# ---------- Auth Routes ----------
@app.post("/api/auth/login")
@limiter.limit("10 per minute")
def api_login():
    """Authenticate user and return JWT token."""
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid request body"}), 400
    username = data.get("username", "").strip()
    password = data.get("password", "")
    if not username or not password:
        return jsonify({"error": "Username and password required"}), 400
    user, token_or_error = authenticate_user(username, password)
    if not user:
        return jsonify({"error": token_or_error}), 401
    return jsonify({"user": user, "token": token_or_error})


@app.post("/api/auth/register")
@limiter.limit("5 per minute")
def api_register():
    """Register a new user account."""
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid request body"}), 400
    username = data.get("username", "").strip()
    password = data.get("password", "")
    role = data.get("role", "student")
    org_id = data.get("org_id", "default")
    if not username or not password:
        return jsonify({"error": "Username and password required"}), 400
    if role not in ("student", "teacher", "parent", "trainer", "hr"):
        role = "student"
    user, token_or_error = register_user(username, password, role, org_id)
    if not user:
        return jsonify({"error": token_or_error}), 409
    # Send welcome notification for new users
    try:
        notifications.trigger_welcome(user["id"], display_name=user.get("username", ""))
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    return jsonify({"user": user, "token": token_or_error}), 201


@app.get("/api/auth/me")
def api_me():
    """Get current user info from JWT token."""
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Not authenticated"}), 401
    payload = verify_token(token)
    if not payload:
        return jsonify({"error": "Invalid or expired token"}), 401
    return jsonify({
        "user": {
            "id": payload.get("user_id"),
            "username": payload.get("username"),
            "role": payload.get("role")
        }
    })


@app.post("/api/auth/forgot-password")
@limiter.limit("3 per 10 minutes")
def api_forgot_password():
    """Request a password reset OTP. Returns OTP in response (no email infra yet)."""
    data = request.get_json() or {}
    username = data.get("username", "").strip()
    if not username:
        return jsonify({"error": "Username is required"}), 400
    otp, err = generate_reset_otp(username)
    if err:
        # Always return success to prevent username enumeration
        return jsonify({"message": "If that username exists, a reset code has been sent.", "expires_in": 900}), 200
    # Log the OTP server-side for debugging; NEVER return it in the response.
    logger.info(f"Password reset OTP generated for {username}")
    return jsonify({"message": "If that username exists, a reset code has been sent.", "expires_in": 900}), 200


@app.post("/api/auth/reset-password")
def api_reset_password():
    """Verify OTP and set a new password."""
    data = request.get_json() or {}
    username = data.get("username", "").strip()
    otp = data.get("otp", "").strip()
    new_password = data.get("new_password", "")
    if not username or not otp or not new_password:
        return jsonify({"error": "Username, code, and new password are required"}), 400
    success, err = reset_password_with_otp(username, otp, new_password)
    if success:
        return jsonify({"message": "Password reset successfully. You can now log in."}), 200
    return jsonify({"error": err}), 400


@app.post("/api/auth/change-password")
@require_auth
@limiter.limit("5 per minute")
def api_change_password():
    """Change password for the currently authenticated user (requires old password)."""
    data = request.get_json() or {}
    old_password = data.get("old_password", "")
    new_password = data.get("new_password", "")
    if not old_password or not new_password:
        return jsonify({"error": "Old password and new password are required"}), 400
    username = request.current_user.get("username")
    success, err = change_password(username, old_password, new_password)
    if success:
        return jsonify({"message": "Password changed successfully."}), 200
    return jsonify({"error": err}), 400


@app.post("/api/auth/logout")
def api_logout():
    """Invalidate the caller's JWT token server-side."""
    token = get_token_from_request()
    if token:
        blacklist_token(token)
    return jsonify({"message": "Logged out successfully"}), 200


@app.post("/api/auth/refresh")
@limiter.limit("10 per minute")
@require_auth
def api_refresh_token():
    """Exchange a valid token for a fresh one with extended expiry."""
    from auth import generate_token as _generate_token
    old_token = get_token_from_request()
    user = request.current_user
    new_token = _generate_token(
        user["user_id"], user["username"], user["role"], user.get("org_id", "default")
    )
    blacklist_token(old_token)
    return jsonify({
        "token": new_token,
        "user": {
            "id": user["user_id"],
            "username": user["username"],
            "role": user["role"],
            "org_id": user.get("org_id", "default"),
        },
    })


@app.post("/api/demo/session")
@limiter.limit("20 per hour")
def demo_session():
    """Create a temporary guest session for the live demo (no auth required).
    Returns a short-lived token + a suitable demo game_id."""
    import uuid as _uuid
    from auth import generate_token as _generate_token
    load_bundle()
    guest_id = f"demo_guest_{_uuid.uuid4().hex[:8]}"
    token = _generate_token(guest_id, "Guest", "student", "demo", expiry_hours=2)
    # Pick a rounds-type game tagged demo:true, or fall back to first rounds game
    demo_game_id = None
    for gid, g in GAMES.items():
        if g.get("demo") is True and g.get("game_type", "rounds") == "rounds":
            demo_game_id = gid
            break
    if not demo_game_id:
        for gid, g in GAMES.items():
            if g.get("game_type", "rounds") == "rounds" and g.get("rounds"):
                demo_game_id = gid
                break
    return jsonify({
        "token": token,
        "game_id": demo_game_id or "startup_sprint",
        "user": {
            "user_id": guest_id,
            "display_name": "Guest Player",
            "role": "student",
            "org_id": "demo",
        },
    })


# ---------- Helpers ----------
def compute_score(state: dict, initial_state: dict = None) -> int:
    """Compute a normalised 0-100 score from game resources.

    For every tracked resource the score measures how far the player is between
    the worst possible value (0 for positives, max for negatives) and a
    reasonable ceiling.  The result is clamped to 0-100.
    """
    SKIP = {"round_index", "dimension_scores", "memory_tags", "learning_outcomes"}

    positive_resources = {
        "money_inr", "cash_inr", "funds", "reputation", "team_trust", "team_morale",
        "trust", "confidence", "experience", "innovation", "energy",
        "customers", "customer_love", "market_share", "deals_won", "negotiation_score",
        "altitude", "supplies", "health", "water_quality", "community_support",
        "volunteers", "wildlife_health", "awareness", "relationship_score",
        "learning_points", "ethics_meter",
    }
    negative_resources = {"stress"}
    # Higher weight for these resources
    weight = {
        "reputation": 1.5, "team_trust": 1.5, "trust": 1.5, "confidence": 1.5,
        "ethics_meter": 1.5, "learning_points": 2.0,
    }

    init = initial_state or {}
    total_weight = 0.0
    weighted_pct = 0.0

    def _num(v, default=0):
        """Extract numeric value from plain number or rich state dict like {value: 100, label: '...'}."""
        if isinstance(v, (int, float)):
            return float(v)
        if isinstance(v, dict):
            return float(v.get("value", default))
        return float(default)

    for key, value in state.items():
        if key in SKIP:
            continue
        # Extract numeric value (handles both plain numbers and rich state dicts)
        try:
            val = _num(value)
        except (TypeError, ValueError):
            continue
        w = weight.get(key, 1.0)

        if key in positive_resources:
            # Ceiling = max(initial * 3, 100) so there's always headroom
            init_val = _num(init.get(key, 0))
            ceiling = max(init_val * 3, 100) if init_val > 0 else max(val * 1.5, 100)
            pct = min(val / ceiling, 1.0) if ceiling > 0 else 0.0
            weighted_pct += pct * w
            total_weight += w
        elif key in negative_resources:
            # Lower stress = better. Ceiling = max(initial*2, 100)
            init_val = _num(init.get(key, 50), 50)
            ceiling = max(init_val * 2, 100)
            pct = max(0.0, 1.0 - val / ceiling) if ceiling > 0 else 1.0
            weighted_pct += pct * w
            total_weight += w

    if total_weight == 0:
        return 50  # neutral fallback

    raw = (weighted_pct / total_weight) * 100
    return max(0, min(100, int(round(raw))))


def compute_badges(final_state: dict):
    """Award badges based on final state thresholds - dynamic for any game."""
    badges = []

    def _v(key, default=0):
        """Get numeric value from state, handling rich dict format."""
        val = final_state.get(key, default)
        if isinstance(val, dict):
            return val.get("value", default)
        if isinstance(val, (int, float)):
            return val
        return default

    # Check for various positive achievements
    if _v("reputation") >= 35:
        badges.append("🌟 Reputation Star")
    if _v("team_trust") >= 45 or _v("trust") >= 45:
        badges.append("🤝 Team Captain")
    if _v("stress", 100) <= 55:
        badges.append("🧘 Calm Under Pressure")

    # Money badges (check both cash_inr and money_inr)
    cash = max(_v("money_inr"), _v("cash_inr"), _v("funds"))
    if cash >= 300:
        badges.append("💰 Money Mind")
    if cash >= 450 and _v("reputation") >= 40:
        badges.append("🚀 Growth Hero")

    # Ethics badge
    if _v("ethics_meter") >= 75:
        badges.append("⚖️ Ethical Leader")

    # Learning badge
    if _v("learning_points") >= 10:
        badges.append("📚 Reflective Learner")

    # Customer love badge
    if _v("customer_love") >= 60:
        badges.append("❤️ Customer Champion")

    # Balanced leadership
    if _v("team_trust") >= 50 and _v("stress", 100) <= 40:
        badges.append("💎 Balanced Leader")

    # Market leader
    if _v("market_share") >= 50:
        badges.append("📊 Market Leader")

    # New badges for different game types
    if _v("altitude") >= 8000:
        badges.append("🏔️ Summit Champion")
    if _v("water_quality") >= 80:
        badges.append("🌊 Environmental Hero")
    if _v("deals_won") >= 5:
        badges.append("🤝 Negotiation Master")
    if _v("customers") >= 100:
        badges.append("📈 Growth Hacker")
    if _v("innovation") >= 80:
        badges.append("💡 Innovation Champion")
    
    return badges[:6]


