def _derive_category(game_type):
    """Derive a category from game_type if not explicitly set."""
    return CATEGORY_MAP.get(game_type, "Other")


def _parse_duration(val) -> int:
    """Extract numeric minutes from values like '45-55 minutes', '30', 50, etc."""
    if isinstance(val, (int, float)):
        return int(val)
    if isinstance(val, str):
        import re
        nums = re.findall(r'\d+', val)
        if nums:
            return int(nums[0])
    return 0


def _derive_game_category(game: dict) -> str:
    """Returns 'chance', 'skill', or 'mixed' based on game structure."""
    if game.get("game_category_override"):
        return game["game_category_override"]
    gt = game.get("game_type", "rounds")
    has_random = bool(game.get("random_events") or game.get("reward_schedule") == "variable")
    pure_skill = {"chess_strategy", "go_territory", "reversi", "strategy_grid",
                  "tower_defense", "puzzle_match", "debate", "negotiation",
                  "ai_arena", "story_branching"}
    if gt in pure_skill:
        return "skill"
    # trump_card, card, card_board: luck in draw + skill in choices → mixed
    if gt in {"card_board", "trump_card", "card"} or has_random:
        return "mixed"
    # board games with scoring weights = mixed; without = chance
    if gt == "board":
        return "mixed" if game.get("dimension_scoring_weights") else "chance"
    # minigame with time pressure has luck element → mixed
    if gt == "minigame":
        return "mixed"
    return "skill"


