@app.get("/api/daily-challenge")
def api_daily_challenge():
    """Return today's daily challenge game (same for all users in an org)."""
    load_bundle()
    import daily_challenge as _dc
    org_id = None
    try:
        token = get_token_from_request()
        payload = verify_token(token) if token else None
        org_id = payload.get("org_id") if payload else None
    except Exception:
        pass
    # Only pick from visible, public games — also respect game_visibility.json (admin hides)
    _hidden_ids = get_hidden_games()
    _hidden_types = get_hidden_game_types()
    _visible_games = {gid: g for gid, g in GAMES.items()
                      if g.get("visible") is not False
                      and g.get("game_type", "rounds") in _PUBLIC_GAME_TYPES
                      and gid not in _hidden_ids
                      and g.get("game_type", "rounds") not in _hidden_types}
    game = _dc.get_daily_challenge(_visible_games, org_id=org_id)
    if not game:
        return jsonify({"challenge": None})
    # Ensure estimated_duration_minutes is present for frontend
    if "estimated_duration_minutes" not in game:
        game["estimated_duration_minutes"] = game.get("duration_minutes") or _parse_duration(game.get("estimated_duration", 0))
    return jsonify({"challenge": game})


