@app.get("/api/profile/level-info")
def api_level_info():
    """Return current level, XP to next, and what game types are unlocked."""
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    payload = verify_token(token)
    if not payload:
        return jsonify({"error": "Invalid token"}), 401
    user_id = payload["user_id"]
    profile = player_profile.get_profile(user_id) or {}
    level = profile.get("level", 1)
    xp = profile.get("xp", 0)
    try:
        with open(os.path.join(os.path.dirname(__file__), "data", "unlock_rules.json")) as f:
            rules = json.load(f)
        gates = rules.get("level_gates", {})
    except Exception:
        gates = {}
    unlocked_types = set()
    for gate_level_str, gate_data in gates.items():
        if level >= int(gate_level_str):
            unlocked_types.update(gate_data.get("unlocked_types", []))
    for gt in profile.get("teacher_early_access", []):
        unlocked_types.add(gt)
    next_gate = None
    for gate_level_str, gate_data in sorted(gates.items(), key=lambda x: int(x[0])):
        if int(gate_level_str) > level:
            next_gate = {"level": int(gate_level_str), **gate_data}
            break
    import math
    next_level = level + 1
    xp_for_next = (next_level ** 2) * 50
    xp_needed = max(0, xp_for_next - xp)
    return jsonify({
        "level": level,
        "xp": xp,
        "xp_to_next_level": xp_needed,
        "unlocked_types": list(unlocked_types),
        "next_unlock": next_gate,
    })


@app.get("/api/profile/baseline-game")
def api_baseline_game():
    """
    Return the appropriate baseline game_id based on user age and persona.

    Selection logic:
      - persona == 'professional' or 'assessor' or 'trainer' → baseline-professional-v1
      - persona == 'student' and age >= 18 → baseline-young-adult-v1
      - persona == 'student' and age < 18 → baseline-teen-v1
      - age >= 26 → baseline-professional-v1
      - age >= 18 → baseline-young-adult-v1
      - age < 18 → baseline-teen-v1
      - fallback (no age, no persona) → soft-skills-baseline-v1
    """
    load_bundle()
    token = get_token_from_request()
    persona_type = None
    age = None

    if token:
        try:
            payload = verify_token(token)
            user_id = payload.get("user_id")
            if user_id:
                profiles = player_profile._load_profiles()
                profile = player_profile._ensure_profile(profiles, user_id)
                age = profile.get("age") or profile.get("persona", {}).get("age")
                persona_type = profile.get("persona", {}).get("type") or profile.get("persona_type")
        except Exception as e:
            logger.debug("baseline-game selection error: %s", e)

    game_id = _select_baseline_game_id(persona_type, age)
    game = GAMES.get(game_id, {})
    return jsonify({
        "game_id": game_id,
        "title": game.get("title", "Soft Skills Baseline"),
        "description": game.get("description", ""),
        "icon": game.get("icon", "🎯"),
        "duration_minutes": game.get("duration_minutes", 15),
        "age_category": game.get("age_category", "All"),
        "coaching_tone": game.get("coaching_tone", "supportive"),
    })


@app.post("/api/teacher/grant-access")
def api_teacher_grant_access():
    """Grant a student (or cohort) early access to a game type."""
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    payload = verify_token(token)
    if not payload:
        return jsonify({"error": "Invalid token"}), 401
    if payload.get("role") not in ("teacher", "school_admin", "admin"):
        return jsonify({"error": "Forbidden"}), 403
    body = request.get_json() or {}
    game_type = body.get("game_type")
    if not game_type:
        return jsonify({"error": "game_type required"}), 400
    target_user_ids = []
    if body.get("student_id"):
        target_user_ids = [body["student_id"]]
    elif body.get("cohort_id"):
        cohort = None
        try:
            cohort = next((c for c in _load_cohorts() if c.get("id") == body["cohort_id"]), None)
        except Exception:
            pass
        target_user_ids = cohort.get("student_ids", []) if cohort else []
    if not target_user_ids:
        return jsonify({"error": "student_id or cohort_id required"}), 400
    updated = 0
    for uid in target_user_ids:
        try:
            p = player_profile.get_profile(uid)
            if p is not None:
                early_access = p.get("teacher_early_access", [])
                if game_type not in early_access:
                    early_access.append(game_type)
                player_profile.update_profile(uid, {"teacher_early_access": early_access})
                updated += 1
        except Exception:
            pass
    return jsonify({"ok": True, "updated": updated, "game_type": game_type})


# ── BASELINE_GAME_ID ──────────────────────────────────────────────────────────
BASELINE_GAME_ID = "baseline-assessment"


def _contextual_sort_games(games_list, persona_type, age, baseline_complete, role):
    """Sort and annotate games based on user profile for contextual relevance."""

    # Determine context
    is_teen = (age is not None and age < 18) or (persona_type == "student" and (age is None or age < 18))
    is_young_adult = (age is not None and 18 <= age <= 25) or (persona_type == "student" and age and 18 <= age <= 25)
    is_professional = (age is not None and age >= 26) or persona_type in ("professional", "assessor", "trainer")

    # Score each game for contextual relevance
    def score_game(game):
        score = 0
        title = (game.get("title", "") + " " + game.get("description", "") + " " + game.get("theme", "")).lower()
        cultural_ctx = (game.get("cultural_context", "") or "").lower()
        age_cat = (game.get("age_category", "") or "").lower()

        # Age category matching
        if is_teen and ("school" in age_cat or "13-17" in age_cat or "teen" in age_cat):
            score += 10
        if is_young_adult and ("college" in age_cat or "18-25" in age_cat or "young" in age_cat):
            score += 10
        if is_professional and ("professional" in age_cat or "26+" in age_cat or "workplace" in cultural_ctx):
            score += 10

        # Demote mismatched games
        if is_teen and ("workplace" in cultural_ctx or "corporate" in cultural_ctx or "salary" in title):
            score -= 5
        if is_professional and ("school" in cultural_ctx or "exam" in title or "class" in title):
            score -= 3

        # Baseline games always get highest priority if not complete
        if not baseline_complete and game.get("is_baseline"):
            score += 100

        return score

    # Annotate and sort
    for game in games_list:
        game["_context_score"] = score_game(game)

    return sorted(games_list, key=lambda g: g.get("_context_score", 0), reverse=True)


# Game types visible to all users; unlisted types require admin/dev/trainer/school_admin role
_PUBLIC_GAME_TYPES = {
    'rounds', 'simulation', 'negotiation', 'debate', 'job_interview', 'group_discussion',
    'client_meeting', 'conflict_mediation', 'public_speaking',
    'stakeholder_update', 'ai_discussion',
    'story_branching',
    'mystery_room',
}


@app.get("/api/games")
def games_list():
    """List all available games (excludes hidden games). Annotates locked status if authenticated."""
    load_bundle()
    # Load game quality scores
    _quality = {}
    try:
        import json as _json
        with open(os.path.join(os.path.dirname(__file__), "data", "game_quality.json")) as _qf:
            _quality = _json.load(_qf)
    except Exception:
        pass
    all_ratings = game_ratings.get_all_avg_ratings()
    hidden = get_hidden_games()
    hidden_types = get_hidden_game_types()

    # Baseline game IDs — hidden from main list once baseline_complete (they still work via direct /play/ link)
    _BASELINE_IDS = {
        "soft-skills-baseline-v1", "baseline-teen-v1",
        "baseline-young-adult-v1", "baseline-professional-v1",
    }

    # Unlock annotations and profile context (optional — only for authenticated users)
    unlock_data = None
    _ctx_persona_type = None
    _ctx_age = None
    _ctx_baseline_complete = False
    _ctx_role = None
    _ctx_user_id = None
    _ctx_assigned_game_ids = []
    _raw_profile = None
    user_payload = None
    try:
        token = get_token_from_request()
        user_payload = verify_token(token) if token else None
        if user_payload:
            _ctx_user_id = user_payload.get("user_id")
            _ctx_role = user_payload.get("role")
            unlock_data = player_profile.check_unlocks(_ctx_user_id)
            # Load raw profile for persona and baseline_complete fields
            try:
                _profiles = player_profile._load_profiles()
                _raw_profile = player_profile._ensure_profile(_profiles, _ctx_user_id)
                _ctx_persona_type = (
                    _raw_profile.get("persona", {}).get("type")
                    or _raw_profile.get("persona_type")
                )
                _raw_age = _raw_profile.get("age") or _raw_profile.get("persona", {}).get("age")
                if _raw_age is not None:
                    try:
                        _ctx_age = int(_raw_age)
                    except (ValueError, TypeError):
                        _ctx_age = None
                _ctx_baseline_complete = bool(_raw_profile.get("baseline_complete", False))
            except Exception as _pe:
                logger.debug("Suppressed profile load in games_list: %s: %s", type(_pe).__name__, _pe)
            # Fetch assigned game IDs for this student
            try:
                _cohort_data = _load_cohorts()
                _user_cohorts = [
                    c.get("id") for c in _cohort_data.get("cohorts", [])
                    if str(_ctx_user_id) in [str(s) for s in c.get("students", [])]
                ]
                if _user_cohorts:
                    _all_assignments = _load_assignments()
                    _ctx_assigned_game_ids = [
                        a.get("game_id") for a in _all_assignments
                        if a.get("cohort_id") in _user_cohorts and a.get("game_id")
                    ]
            except Exception as _ae:
                logger.debug("Suppressed assignment load in games_list: %s: %s", type(_ae).__name__, _ae)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    def _lock_info(g):
        # All games unlocked for all students — progression locks disabled
        return False, ""

    games_out = []
    is_privileged = _ctx_role in ("admin", "dev", "school_admin", "trainer")
    # Resolve viewer's org for feature_flag gating
    _viewer_org_id = (user_payload or {}).get("org_id", "default") if user_payload else "default"
    for g in BUNDLE["games"]:
        if g["game_id"] in hidden:
            continue
        if g.get("game_type", "") in hidden_types:
            continue
        # Hide games marked as not visible or testing from non-privileged users
        if not is_privileged and (g.get("visible") is False or g.get("status") == "testing"):
            continue
        # Non-privileged users only see public game types
        if not is_privileged and g.get("game_type", "rounds") not in _PUBLIC_GAME_TYPES:
            continue
        # Per-org feature flag gating: hide games whose feature_flag is not enabled
        _ff = g.get("feature_flag")
        if _ff and not org_module.get_org_feature(_viewer_org_id, _ff):
            continue
        # Hide baseline games from list once the user has completed their baseline
        if g["game_id"] in _BASELINE_IDS and _ctx_baseline_complete:
            continue
        locked, unlock_hint = _lock_info(g)
        entry = {
            "game_id": g["game_id"],
            "title": g.get("title", ""),
            "theme": g.get("theme", ""),
            "description": g.get("description", ""),
            "icon": g.get("icon", ""),
            "icon_svg_id": g.get("icon_svg_id", ""),
            "game_type": g.get("game_type", "rounds"),
            "category": g.get("category", _derive_category(g.get("game_type", "rounds"))),
            "difficulty": g.get("difficulty", ""),
            "duration_minutes": g.get("duration_minutes", 0),
            "target_audience": g.get("target_audience", ""),
            "round_count": len(g.get("rounds", [])),
            "avg_rating": all_ratings.get(g["game_id"], {}).get("avg_rating", 0),
            "rating_count": all_ratings.get(g["game_id"], {}).get("count", 0),
            "how_to_play": g.get("how_to_play"),
            "learning_objectives": g.get("learning_objectives", []),
            "features": g.get("features", {}),
            "has_storybook": bool(g.get("storybook_pages")),
            "locked": locked,
            "unlock_hint": unlock_hint,
            "nep_stage": _derive_nep_stage(g),
            "nep_competencies": g.get("nep_competencies", []),
            "cultural_context": g.get("cultural_context", ""),
            "player_mode": g.get("player_mode", "solo"),
            "max_players": g.get("max_players", 1),
            "competitive": g.get("competitive", False),
            "tags": g.get("tags", []),
            "dimension_scoring_weights": g.get("dimension_scoring_weights", {}),
            "estimated_duration": g.get("estimated_duration", g.get("duration_minutes", 0)),
            "estimated_duration_minutes": g.get("estimated_duration_minutes") or g.get("duration_minutes") or _parse_duration(g.get("estimated_duration", 0)),
            "target_age": g.get("target_age", g.get("target_audience", "")),
            "grade": g.get("grade", ""),
            "target_grade": g.get("target_grade", g.get("grade", "")),
            "subject": g.get("subject", ""),
            "game_category": _derive_game_category(g),
            "cognitive_framework": _derive_cognitive_framework(g),
            "accessibility_config": _derive_accessibility_config(g),
            "quality_score": _quality.get(g["game_id"], {}).get("score", 50),
            "curated": _quality.get(g["game_id"], {}).get("curated", True),
            "age_category": g.get("age_category", ""),
            "is_baseline": g.get("is_baseline", False),
            "visible": g.get("visible", True),
            "status": g.get("status", "published"),
            "tier": g.get("tier", "standard"),
            "age_band": g.get("age_band", g.get("age_category", "")),
            "domain": g.get("domain", ""),
        }
        # Baseline required gate: student completed profile setup but not yet the baseline assessment
        # (excludes demo accounts and baseline games themselves)
        _is_demo = (_ctx_user_id or "").startswith("demo_") or (user_payload or {}).get("username", "").startswith("demo_")
        if (
            _ctx_role == "student"
            and not _is_demo
            and not g.get("is_baseline", False)
            and _raw_profile is not None
            and _raw_profile.get("profile_setup_complete")
            and not _raw_profile.get("baseline_complete")
        ):
            entry["lock_reason"] = "baseline_required"
        games_out.append(entry)

    # Apply contextual sorting when profile data is available
    if _ctx_persona_type or _ctx_age is not None or _ctx_baseline_complete:
        games_out = _contextual_sort_games(
            games_out,
            _ctx_persona_type,
            _ctx_age,
            _ctx_baseline_complete,
            _ctx_role,
        )

    # Remove internal scoring field before sending response
    for g in games_out:
        g.pop("_context_score", None)

    _meta = dict(BUNDLE.get("meta", {}))
    _meta["assigned_game_ids"] = _ctx_assigned_game_ids

    return jsonify({"meta": _meta, "games": games_out})


@app.get("/api/games/<game_id>")
def games_get(game_id):
    """Get a single game by ID. Non-privileged users cannot access hidden game types."""
    load_bundle()
    game, err = get_game_or_400(game_id)
    if err:
        return err
    # Check if the requesting user has permission to view this game type
    _game_type = game.get("game_type", "rounds")
    if _game_type not in _PUBLIC_GAME_TYPES:
        _caller_role = None
        try:
            _tok = get_token_from_request()
            _pay = verify_token(_tok) if _tok else None
            if _pay:
                _caller_role = _pay.get("role")
        except Exception:
            pass
        if _caller_role not in ("admin", "dev", "school_admin", "trainer"):
            return jsonify({"error": "Game not found"}), 404
    return jsonify(game)


@app.get("/api/games/<game_id>/replay-variants")
def games_replay_variants(game_id):
    """R10 — list replay variants (alternate killer / clue chains) for a game.

    Returns lightweight metadata only (label/summary/seed) — full scene_overrides
    are pulled from RUNS state when a run is started with that variant_seed.
    """
    load_bundle()
    game, err = get_game_or_400(game_id)
    if err:
        return err
    variants = game.get("replay_variants") or []
    cfg = game.get("replay_config") or {}
    return jsonify({
        "enabled": bool(cfg.get("variants_enabled")) and bool(variants),
        "hint": cfg.get("hint", ""),
        "variants": [
            {
                "seed": v.get("seed"),
                "label": v.get("label", ""),
                "summary": v.get("summary", ""),
                "killer_name": v.get("killer_name", ""),
            }
            for v in variants
        ],
    })


@app.post("/api/run/start")
@limiter.limit("30 per minute")
def run_start():
    """Start a new game run."""
    load_bundle()
    payload = request.get_json(silent=True) or {}
    game_id = payload.get("game_id", "startup_sprint")
    game, err = get_game_or_400(game_id)
    if err:
        return err

    # Per-org feature flag gating: refuse run-start when game requires a flag
    # the viewer's org has not enabled.
    _rs_ff = game.get("feature_flag")
    if _rs_ff:
        try:
            _rs_token = get_token_from_request()
            _rs_user = verify_token(_rs_token) if _rs_token else None
            _rs_org_id = (_rs_user or {}).get("org_id", "default") if _rs_user else "default"
        except Exception:
            _rs_org_id = "default"
        if not org_module.get_org_feature(_rs_org_id, _rs_ff):
            return jsonify({"error": "Feature not enabled for your org."}), 403

    run_id = create_run(game_id, game["initial_state"], game)

    # V2 engine: apply mode/persona/legacy overrides inline if provided in run_start payload
    try:
        from engines import v2_engine as _v2
        if _v2.is_v2(game):
            _v2_mode = payload.get("v2_mode_id")
            _v2_persona = payload.get("v2_persona_id")
            _v2_daily = payload.get("v2_daily_challenge_id")
            _v2_token = get_token_from_request()
            _v2_user = verify_token(_v2_token) if _v2_token else None
            _v2_uid = (_v2_user or {}).get("user_id", "") if _v2_user else ""
            _v2_state = RUNS[run_id].get("state")
            if _v2_state is not None:
                _v2_meta = _v2.apply_start_overrides(
                    _v2_state, game,
                    mode_id=_v2_mode, persona_id=_v2_persona, user_id=_v2_uid,
                )
                _v2_prof = _v2.select_scoring_profile_seeded(
                    game, run_id=run_id, mode_id=_v2_mode or "classic",
                )
                if _v2_prof is not None:
                    try:
                        setattr(_v2_state, "_sim_scoring_profile", _v2_prof)
                    except Exception:
                        pass
                RUNS[run_id]["_v2"] = {
                    "mode_id": _v2_mode,
                    "persona_id": _v2_persona,
                    "daily_challenge_id": _v2_daily,
                    "meta": _v2_meta,
                    "scoring_profile": _v2_prof,
                    "rival_state": ((game.get("simulation_config") or {}).get("dynamic_rival") or {}).get("initial_state") or {},
                }
    except Exception as _v2e:
        logger.debug("V2 start hook suppressed: %s", _v2e)

    # Metacognition: prompt predicted score if game enables it
    if game.get("enable_metacognition"):
        RUNS[run_id]["predicted_score_prompt"] = True

    # --- Item 30: Coach Mode ---
    coach_mode = payload.get("coach_mode", False)
    if coach_mode:
        RUNS[run_id]["coach_mode"] = True

    # F5: Assessment IP lock — bind session to requesting IP
    if payload.get("assess_lock_ip"):
        RUNS[run_id]["locked_ip"] = request.remote_addr

    # R10 — replay variant: record which alternate killer/clue chain the player chose.
    # Frontend passes variant_seed (int) when the player clicks "Replay with new killer".
    _variant_seed = payload.get("variant_seed")
    if isinstance(_variant_seed, (int, str)) and str(_variant_seed).strip():
        try:
            _vs = int(_variant_seed)
            _variants = game.get("replay_variants") or []
            _variant = next((v for v in _variants if v.get("seed") == _vs), None)
            if _variant:
                RUNS[run_id]["variant_seed"] = _vs
                RUNS[run_id]["variant_label"] = _variant.get("label", "")
                # Store overrides so any per-round serve can overlay scene_overrides
                RUNS[run_id]["variant_scene_overrides"] = _variant.get("scene_overrides") or {}
        except (ValueError, TypeError):
            pass

    # RL 3B: Track game start for completion rate analytics
    try:
        _gs_file = os.path.join(os.path.dirname(__file__), "data", "game_starts.json")
        try:
            with open(_gs_file) as _f:
                _game_starts = json.load(_f)
        except (FileNotFoundError, json.JSONDecodeError):
            _game_starts = {}
        _game_starts[run_id] = {
            "game_id": game_id,
            "game_type": game.get("game_type", "rounds"),
            "started_at": datetime.now().isoformat(),
            "completed": False,
            "rounds_completed": 0,
            "total_rounds": len(game.get("rounds", [])),
        }
        with open(_gs_file, "w") as _f:
            json.dump(_game_starts, _f)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # RL 3D: Snapshot pre-game dimension scores for skill impact tracking
    try:
        _pre_token = get_token_from_request()
        _pre_user = verify_token(_pre_token) if _pre_token else None
        if _pre_user:
            _pre_profile = player_profile.get_profile(_pre_user["user_id"])
            RUNS[run_id]["pre_game_scores"] = _pre_profile.get("experience_tier") and _pre_profile or {}
            # Store dimension_scores snapshot directly from profiles file
            _profiles_raw = player_profile._load_profiles()
            _p_raw = _profiles_raw.get(_pre_user["user_id"], {})
            RUNS[run_id]["pre_game_dimension_scores"] = _p_raw.get("dimension_scores", {})
            RUNS[run_id]["player_tier"] = _pre_profile.get("experience_tier", {}).get("tier", 0)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Parental controls enforcement (students only)
    try:
        _pc_token = get_token_from_request()
        _pc_user = verify_token(_pc_token) if _pc_token else None
        if _pc_user and _pc_user.get("role") == "student":
            _pc_profile = player_profile.get_profile(_pc_user["user_id"])
            _pc = _pc_profile.get("parental_controls") or {}
            _restricted_types = _pc.get("restricted_game_types") or []
            if _restricted_types and game.get("game_type") in _restricted_types:
                return jsonify({"error": "This game type is restricted by parental controls.", "code": "PARENTAL_RESTRICTED"}), 403
            _time_limit = _pc.get("daily_time_limit_minutes")
            if _time_limit:
                _today = datetime.now().date().isoformat()
                _daily_play = _pc_profile.get("daily_play_minutes") or {}
                _today_minutes = _daily_play.get(_today, 0)
                if _today_minutes >= _time_limit:
                    return jsonify({"error": f"Daily play limit of {_time_limit} minutes reached.", "code": "DAILY_LIMIT_REACHED"}), 403
    except Exception as _pce:
        logger.debug("Suppressed parental controls check: %s", _pce)

    # Growth mindset: detect retry after failure
    try:
        _gm_token = get_token_from_request()
        _gm_user = verify_token(_gm_token) if _gm_token else None
        if _gm_user:
            _prev_runs = [r for r in player_profile.get_skill_history(_gm_user["user_id"]).get("history", [])
                          if r.get("game_id") == game_id or r.get("game_type") == game.get("game_type")]
            if _prev_runs:
                _last_score = _prev_runs[-1].get("mento_score", 100)
                if _last_score < 40:
                    RUNS[run_id]["is_retry_after_failure"] = True
                    RUNS[run_id]["prev_best_score"] = max(s.get("mento_score", 0) for s in _prev_runs)
    except Exception:
        pass

    # AI Arena: initialize game with populated rounds from base_rounds + LLM
    if game.get("game_type") == "ai_arena":
        try:
            from ai_arena_engine import initialize_ai_arena_game, get_variant_offset_for_replay
            # Cross-session memory: offset variant selection for returning players
            variant_offset = 0
            try:
                token = get_token_from_request()
                user_payload = verify_token(token) if token else None
                if user_payload:
                    variant_offset = get_variant_offset_for_replay(game_id, user_payload.get("user_id", ""))
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            initialized_game = initialize_ai_arena_game(game, RUNS[run_id]["state"], variant_offset=variant_offset)
            RUNS[run_id]["initialized_game"] = initialized_game
            # Persist initialized_game to disk immediately so it survives restarts
            update_run(run_id, RUNS[run_id])
            game = initialized_game  # Return initialized version to frontend
        except Exception as e:
            logger.info(f"[AI Arena] Initialization error: {e}")
            # Fallback: copy base_rounds to rounds if initialization fails
            if not game.get("rounds") and game.get("base_rounds"):
                game["rounds"] = [r for r in game["base_rounds"] if not r.get("ai_generatable")]

    # Mystery Room: initialise escape-room state
    if game.get("game_type") == "mystery_room":
        RUNS[run_id] = _ESCAPE_ROOM_ENGINE.start(RUNS[run_id], game)

    # Feature 5: Track active session for live cohort monitoring
    try:
        _act_file = os.path.join(os.path.dirname(__file__), "data", "active_sessions.json")
        try:
            with open(_act_file) as _af:
                _act_sessions = json.load(_af)
        except (FileNotFoundError, json.JSONDecodeError):
            _act_sessions = {}
        _act_token = get_token_from_request()
        _act_user = verify_token(_act_token) if _act_token else None
        if _act_user:
            _act_sessions[run_id] = {
                "user_id": _act_user.get("user_id", ""),
                "game_id": game_id,
                "game_title": game.get("title", game_id),
                "run_id": run_id,
                "started_at": datetime.now().isoformat(),
                "last_seen": datetime.now().isoformat(),
            }
            with open(_act_file, "w") as _af:
                json.dump(_act_sessions, _af)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Adaptive engine: suggest difficulty and generate variant for authenticated users
    adaptive_info = {}
    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith("Bearer "):
        token = auth_header[7:]
        user = verify_token(token)
        if user:
            try:
                from engines.adaptive_game_engine import suggest_difficulty, generate_game_variant, analyze_play_style
                user_id = user.get("user_id") or user.get("username", "")
                diff_suggestion = suggest_difficulty(user_id, game_id)
                variant = generate_game_variant(game_id, user_id)
                play_style = analyze_play_style(user_id)
                adaptive_info = {
                    "difficulty_suggestion": diff_suggestion,
                    "variant_overrides": variant,
                    "play_style": play_style,
                }
            except Exception as e:
                logger.info(f"[Adaptive] Non-critical error at game start: {e}")
    state_obj = RUNS[run_id]["state"]
    # ── Initialize simulation engine for simulation-type games ──
    if game.get("simulation_config"):
        try:
            from engines.simulation_tick_engine import SimulationTickEngine
            _sim_init_engine = SimulationTickEngine(game["simulation_config"])
            _sim_init_engine.initialize_simulation(state_obj)
            # Populate KPI values from actual state resources
            for _kpi_def in (game["simulation_config"].get("kpi_definitions") or game["simulation_config"].get("kpis", [])):
                _kpi_id = _kpi_def.get("id")
                _resource_key = _kpi_def.get("resource")
                if _kpi_id and _resource_key and hasattr(state_obj, 'sim_kpis'):
                    _res_val = getattr(state_obj, _resource_key, None)
                    if isinstance(_res_val, (int, float)):
                        state_obj.sim_kpis[_kpi_id]["value"] = _res_val
                    # Also set prefix/unit from KPI definition
                    if _kpi_def.get("prefix"):
                        state_obj.sim_kpis[_kpi_id]["prefix"] = _kpi_def["prefix"]
                    if _kpi_def.get("unit"):
                        state_obj.sim_kpis[_kpi_id]["unit"] = _kpi_def["unit"]
                    # Set initial status from thresholds
                    _thresholds = _kpi_def.get("status_thresholds", {})
                    _val = state_obj.sim_kpis[_kpi_id].get("value", 0)
                    _inverse = _kpi_def.get("inverse", False)  # inverse: higher = worse
                    if _inverse:
                        # For inverse KPIs (like expenses): higher values are bad
                        if _thresholds.get("critical") is not None and _val >= _thresholds["critical"]:
                            state_obj.sim_kpis[_kpi_id]["status"] = "critical"
                        elif _thresholds.get("warning") is not None and _val >= _thresholds["warning"]:
                            state_obj.sim_kpis[_kpi_id]["status"] = "warning"
                        elif _thresholds.get("good") is not None and _val <= _thresholds["good"]:
                            state_obj.sim_kpis[_kpi_id]["status"] = "strong"
                        else:
                            state_obj.sim_kpis[_kpi_id]["status"] = "steady"
                    else:
                        if _thresholds.get("critical") is not None and _val <= _thresholds["critical"]:
                            state_obj.sim_kpis[_kpi_id]["status"] = "critical"
                        elif _thresholds.get("warning") is not None and _val <= _thresholds["warning"]:
                            state_obj.sim_kpis[_kpi_id]["status"] = "warning"
                        elif _thresholds.get("good") is not None and _val >= _thresholds["good"]:
                            state_obj.sim_kpis[_kpi_id]["status"] = "strong"
                        else:
                            state_obj.sim_kpis[_kpi_id]["status"] = "steady"
            update_run(run_id, RUNS[run_id])
        except Exception as _sim_init_err:
            logger.warning(f"Simulation init at start error: {_sim_init_err}")
    # Item 30: propagate coach_mode flag for build_round_payload
    if RUNS[run_id].get("coach_mode"):
        game["_coach_mode"] = True
    round_payload = build_round_payload(game, state_obj) if game.get("rounds") and state_obj.round_index < len(game["rounds"]) else None
    # R11: overlay variant scene text if this run has an active replay variant
    round_payload = _apply_variant_overlay(round_payload, RUNS[run_id])

    # Free-tier demo tracking — students with no org get 5 free games, then soft-prompt
    demo_info = {}
    try:
        _demo_token = get_token_from_request()
        _demo_user = verify_token(_demo_token) if _demo_token else None
        if _demo_user and _demo_user.get("role") == "student" and _demo_user.get("org_id", "default") == "default":
            _uid = _demo_user.get("user_id", "")
            _profiles = player_profile._load_profiles()
            _p = _profiles.setdefault(_uid, {})
            _played = _p.get("free_games_played", 0) + 1
            _p["free_games_played"] = _played
            player_profile._save_profiles(_profiles)
            _limit = 5
            demo_info = {
                "is_free_tier": True,
                "games_played": _played,
                "games_limit": _limit,
                "limit_reached": _played >= _limit,
            }
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    _start_player_profile = None
    try:
        if _pre_user:
            _start_player_profile = {
                "user_id": _pre_user.get("user_id", ""),
                "display_name": _pre_profile.get("display_name", ""),
                "avatar": _pre_profile.get("avatar", ""),
                "avatar_url": _pre_profile.get("avatar_url", ""),
                "avatar_frame": _pre_profile.get("avatar_frame", "default"),
                "level": _pre_profile.get("level", 0),
            }
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Strip hidden resources from initial state sent to client
    _start_state_dict = state_to_dict(state_obj)
    if game.get("simulation_config", {}).get("hidden_resources"):
        try:
            from engines.simulation_tick_engine import SimulationTickEngine
            _start_sim = SimulationTickEngine(game["simulation_config"])
            _start_state_dict = _start_sim.strip_hidden_from_state(_start_state_dict)
        except Exception:
            pass

    # ── Legibility layer: annotate initial round choices + payload ──
    _start_ux_legibility = None
    if game.get("simulation_config"):
        try:
            if round_payload and round_payload.get("choices"):
                annotate_choices_with_dynamic_cost(
                    round_payload["choices"],
                    getattr(state_obj, "money", getattr(state_obj, "cash", 0)),
                )
        except Exception as _ann_err:
            logger.debug("annotate_choices_with_dynamic_cost (start) failed: %s", _ann_err)
        try:
            _start_ux_legibility = build_ux_payload(
                state_obj, game, None, round_payload, None,
                getattr(state_obj, "round_index", 0),
            )
        except Exception as _ux_err:
            logger.debug("UX enrichment (start) error: %s", _ux_err)
        # Executive subsystems on start — same dormant-when-unconfigured pattern.
        _start_ux_executive = None
        try:
            _start_ux_executive = _build_executive_payload(state_obj, game, round_payload)
        except Exception as _ex_err:
            logger.debug("Executive UX (start) error: %s", _ex_err)
    else:
        _start_ux_executive = None

    return jsonify({
        "run_id": run_id,
        "game_id": game_id,
        "game_title": game.get("title", ""),
        "game_data": game,
        "round": round_payload,
        "state": _start_state_dict,
        "adaptive": adaptive_info,
        "coach_mode": bool(RUNS[run_id].get("coach_mode")),
        "demo_info": demo_info,
        "player_profile": _start_player_profile,
        "predicted_score_prompt": RUNS[run_id].get("predicted_score_prompt", False),
        "ux_legibility": _start_ux_legibility,
        "ux_executive": _start_ux_executive,
    })


@app.get("/api/run/<run_id>/state")
def run_state(run_id):
    """Get current state of a run."""
    try:
        r = get_run(run_id)
    except (KeyError, Exception) as e:
        err_name = type(e).__name__
        if err_name in ("SessionNotFoundError", "SessionExpiredError", "KeyError"):
            return jsonify({"error": f"Run not found: {run_id}. The session may have expired. Please start a new game."}), 404
        logger.error(f"Unexpected error getting run: {str(e)}")
        return jsonify({"error": "Internal error"}), 500

    try:
        game_id = r["game_id"]
        game, err = get_game_or_400(game_id)
        if err:
            return err
        game = get_effective_game(r, game)
        # Item 30: propagate coach_mode
        if r.get("coach_mode"):
            game["_coach_mode"] = True

        state_obj = r["state"]
        total = len(game.get("rounds", []))
        cur = state_obj.round_index + 1

        st = state_to_dict(state_obj)

        # Calculate Mento Score
        mento_score_result = {}
        try:
            # Get achievements and competitors for scoring
            achievements_data = r.get("achievements", [])
            competitors_data = r.get("competitors", [])
            run_log = r.get("log", [])
            
            # Check if multiplayer (for future integration)
            multiplayer_active = False  # Will be set from session/game config
            total_players = 1  # Will be from active sessions count
            
            mento_score_result = calculate_mento_score(
                state=state_obj,
                game_config=game,
                run_log=run_log,
                achievements=achievements_data,
                competitors=competitors_data,
                multiplayer_active=multiplayer_active,
                total_players=total_players
            )
            logger.info(f"Mento Score calculated: {mento_score_result['score']}")
        except Exception as score_err:
            logger.warning(f"Failed to calculate Mento Score: {score_err}")
            import traceback
            traceback.print_exc()
            # Provide fallback score
            mento_score_result = {
                "score": 50.0,
                "breakdown": {},
                "rank": "C (Average)",
                "percentile": 50
            }
        
        # Build round payload then apply variant_mode choice shuffle before returning
        _round_payload = build_round_payload(game, state_obj) if game.get("rounds") and state_obj.round_index < len(game["rounds"]) else None
        # R11: overlay variant scene text if this run has an active replay variant
        _round_payload = _apply_variant_overlay(_round_payload, r)
        # --- Variant mode: shuffle choices for replay variability ---
        # If the run was started with variant_mode: true in its metadata, shuffle
        # the choices array so replays see them in a different order each time.
        if _round_payload and r.get("metadata", {}).get("variant_mode"):
            try:
                import random as _rnd_vm
                _choices = _round_payload.get("choices", [])
                if len(_choices) > 1:
                    _rnd_vm.shuffle(_choices)
                    _round_payload["choices"] = _choices
            except Exception as _vm_err:
                logger.warning(f"variant_mode shuffle failed: {_vm_err}")
        return jsonify(
            {
                "run_id": run_id,
                "game_id": game_id,
                "game_title": game.get("title", ""),
                "game_data": {
                    "glossary": game.get("glossary", {}),
                    "layout_config": game.get("layout_config", {}),  # Include layout config!
                    "choice_placement_override": game.get("choice_placement_override", "round")
                },
                "round_index": state_obj.round_index,
                "progress": {"current": cur, "total": total},
                "score": compute_score(st),
                "mento_score": mento_score_result,  # NEW: Mento Score with breakdown
                "round": _round_payload,
                "state": st,
                "log_count": len(r["log"]),
            }
        )
    except Exception as e:
        logger.error(f"Error building state response: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": "Error building game state"}), 500


def _get_round_mode(round_index: int, total_rounds: int, difficulty_curve: dict = None) -> str:
    """Return tutorial/core/mastery based on position in the game.
    If difficulty_curve is provided, use its phase definitions; otherwise fall back to hardcoded ranges."""
    if difficulty_curve and difficulty_curve.get("phases"):
        round_num = round_index + 1  # 0-indexed → 1-indexed for JSON ranges
        for phase in difficulty_curve["phases"]:
            rng = phase.get("rounds", [1, total_rounds])
            if len(rng) >= 2 and rng[0] <= round_num <= rng[1]:
                return phase.get("name", "core")
        return "core"
    # Legacy fallback
    if round_index <= 1:
        return "tutorial"
    if total_rounds > 0 and round_index >= total_rounds - 2:
        return "mastery"
    return "core"


def _get_difficulty_phase(round_index: int, total_rounds: int, difficulty_curve: dict = None) -> dict:
    """Return full difficulty phase details for the current round.
    Returns {name, hints_visible, timer_seconds, max_choices, delta_multiplier}."""
    mode = _get_round_mode(round_index, total_rounds, difficulty_curve)
    # Defaults per mode
    defaults = {
        "tutorial": {"hints_visible": True, "timer_seconds": None, "max_choices": 3, "delta_multiplier": 1.25},
        "core":     {"hints_visible": False, "timer_seconds": 60, "max_choices": 4, "delta_multiplier": 1.0},
        "mastery":  {"hints_visible": False, "timer_seconds": 45, "max_choices": 5, "delta_multiplier": 0.9},
    }
    result = {"name": mode, **defaults.get(mode, defaults["core"])}
    # Override from difficulty_curve phases if present
    if difficulty_curve and difficulty_curve.get("phases"):
        round_num = round_index + 1
        for phase in difficulty_curve["phases"]:
            rng = phase.get("rounds", [1, total_rounds])
            if len(rng) >= 2 and rng[0] <= round_num <= rng[1]:
                if "hints_visible" in phase:
                    result["hints_visible"] = phase["hints_visible"]
                if "timer_seconds" in phase:
                    result["timer_seconds"] = phase["timer_seconds"]
                if "max_choices" in phase:
                    result["max_choices"] = phase["max_choices"]
                if "delta_multiplier" in phase:
                    result["delta_multiplier"] = phase["delta_multiplier"]
                break
    return result

MODE_DELTA_MULT = {"tutorial": 1.25, "core": 1.0, "mastery": 0.9}


def _mid_game_difficulty(r, round_index, total_rounds):
    """Returns 'ease', 'challenge', or None based on player performance."""
    if total_rounds < 4:
        return None
    state = r.get("state", {})
    resources = state.get("resources", {}) if isinstance(state, dict) else {}
    if not resources:
        # Also try to extract numeric values directly from the state dict
        if isinstance(state, dict):
            resources = {k: v for k, v in state.items()
                        if isinstance(v, (int, float)) and k not in ("round_index", "total_rounds", "game_over")}
    if not resources:
        return None
    # Get numeric resources
    numeric_vals = [v for v in resources.values() if isinstance(v, (int, float))]
    if not numeric_vals:
        return None
    avg_resource = sum(numeric_vals) / len(numeric_vals)
    if round_index >= total_rounds // 2 and avg_resource < 30:
        return "ease"
    # Check last 3 rounds for consistent high performance
    history = r.get("round_history", [])
    if len(history) >= 3:
        last_3 = history[-3:]
        all_high = all(
            sum(v for v in rh.get("resources_after", {}).values() if isinstance(v, (int, float))) /
            max(1, len([v for v in rh.get("resources_after", {}).values() if isinstance(v, (int, float))])) > 80
            for rh in last_3
            if rh.get("resources_after")
        )
        if all_high:
            return "challenge"
    return None


@app.post("/api/run/<run_id>/choose")
@limiter.limit("120 per minute")
def run_choose(run_id):
    """Process a choice and advance the game."""
    try:
        r = get_run(run_id)
    except (KeyError, SessionNotFoundError, SessionExpiredError):
        return jsonify({"error": "Session not found"}), 404
    except StorageIOErr:
        return jsonify({"error": "Session storage error — please start a new game"}), 500

    _run_lock = _get_run_lock(run_id)
    _lock_acquired = _run_lock.acquire(timeout=10)

    try:
        # Re-fetch run inside lock to get latest state
        try:
            r = get_run(run_id)
        except (KeyError, SessionNotFoundError, SessionExpiredError):
            return jsonify({"error": "Session not found"}), 404
        except StorageIOErr:
            return jsonify({"error": "Session storage error — please start a new game"}), 500

        payload = request.get_json(silent=True) or {}

        # Idempotency: return cached outcome if request_id already seen
        _req_id = payload.get("request_id") or payload.get("metadata", {}).get("request_id")
        if _req_id:
            _seen_ids = r.get("_last_request_ids", [])
            if _req_id in _seen_ids:
                _cached = r.get("_last_outcome")
                if _cached:
                    return jsonify(_cached)

    finally:
        if _lock_acquired:
            _run_lock.release()

    payload = request.get_json(silent=True) or {}
    # Sanitize choice_id: must be a non-empty string, max 200 chars, no control chars
    choice_id = str(payload.get("choice_id") or "").strip()[:200]
    # Sanitize choice_ids list
    _raw_choice_ids = payload.get("choice_ids")
    if isinstance(_raw_choice_ids, list):
        choice_ids = [str(c).strip()[:200] for c in _raw_choice_ids if isinstance(c, (str, int))]
    else:
        choice_ids = None
    reflection = (payload.get("reflection") or "").strip()
    free_text = (payload.get("free_text") or "").strip()
    time_to_decide = payload.get("time_to_decide")  # ms from frontend
    _reconsideration = payload.get("reconsideration", {})
    _engagement_signals = payload.get("engagement_signals", {})
    _req_id = payload.get("request_id") or payload.get("metadata", {}).get("request_id")
    metadata = payload.get("metadata", {})

    # Record time-on-decision for behavioral analytics
    choice_time_ms = payload.get("choice_time_ms") or (metadata.get("choice_time_ms") if metadata else None)
    if choice_time_ms and isinstance(choice_time_ms, (int, float)):
        choice_times = r.setdefault("choice_times_ms", [])
        choice_times.append(int(choice_time_ms))

    # F5: Enforce IP lock for assessment sessions
    if r.get("locked_ip") and r["locked_ip"] != request.remote_addr:
        return jsonify({"error": "Assessment session locked to a different device. Please continue on your original device."}), 403

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    game = get_effective_game(r, game)
    # Item 30: propagate coach_mode
    if r.get("coach_mode"):
        game["_coach_mode"] = True

    if game.get("type") == "mystery_room" or game.get("game_type") == "mystery_room":
        try:
            r, deltas = _ESCAPE_ROOM_ENGINE.handle_action(r, game, payload)
        except ValueError as e:
            return jsonify({"error": str(e)}), 400
        # log skill tags into existing aggregator
        for tag in deltas.get("skill_tags", []):
            r.setdefault("skill_tag_history", []).append(tag)
        # Analytics: log mystery_room action
        try:
            _mr_user_id = None
            try:
                _mr_token = get_token_from_request()
                _mr_user = verify_token(_mr_token) if _mr_token else None
                if _mr_user:
                    _mr_user_id = _mr_user.get("user_id")
            except Exception:
                _mr_user_id = None
            _log_mystery_event(
                game.get("game_id") or game.get("id") or r.get("game_id"),
                payload.get("action"),
                {
                    "run_id": run_id,
                    "user_id": _mr_user_id,
                    "target": payload.get("target"),
                    "puzzle_id": payload.get("puzzle_id"),
                    "choice": payload.get("choice"),
                    "events": deltas.get("events", []),
                },
            )
        except Exception as _mr_e:
            logger.debug("Suppressed mystery analytics: %s: %s", type(_mr_e).__name__, _mr_e)
        update_run(run_id, r)
        return jsonify({
            "state": r,
            "events": deltas.get("events", []),
            "climax_unlocked": _ESCAPE_ROOM_ENGINE.gating_status(r, game),
        })

    state_obj = r["state"]
    if not game.get("rounds"):
        return jsonify({"error": f"Game type '{game.get('game_type')}' does not use the /choose endpoint"}), 400
    # Issue 16: reject choices on already-completed game sessions
    if r.get("completed"):
        return jsonify({"error": "Game session already completed", "code": 409}), 409
    if state_obj.round_index >= len(game["rounds"]):
        return jsonify({"error": "Game already ended", "code": 409}), 409
    prev_round = game["rounds"][state_obj.round_index]

    # Resource-gated choice validation: reject if requires condition not met
    _chosen = None
    for _c in prev_round.get("choices", []):
        if _c.get("id") == choice_id:
            _chosen = _c
            break
    if _chosen and _chosen.get("requires"):
        try:
            from engines.simulation_tick_engine import _check_condition
            _ctx = {k: v for k, v in state_to_dict(state_obj).items() if isinstance(v, (int, float))}
            if not _check_condition(_chosen["requires"], _ctx):
                return jsonify({"error": "Choice requirements not met", "lock_reason": _chosen["requires"].get("label", "Resource requirement not met")}), 403
        except Exception as _req_err:
            logger.warning(f"Requires validation error: {_req_err}")

    # Stash player-provided forecast response (from ForecastModal) on state
    # so the exec_effects.forecast_capture dispatcher can read it. One-shot:
    # cleared inside the dispatcher after recording.
    try:
        _forecast_response = payload.get("forecast_response")
        if isinstance(_forecast_response, dict):
            state_obj._forecast_response = _forecast_response
    except Exception:
        pass

    # Mark inbox event as answered (if this choice was triggered by an inbox interrupt).
    # `state._inbox_seen` is the source of truth read by build_inbox_payload.
    try:
        _inbox_event_id = payload.get("inbox_event_id")
        if _inbox_event_id:
            seen = getattr(state_obj, "_inbox_seen", None)
            if not isinstance(seen, set):
                seen = set()
            seen.add(str(_inbox_event_id)[:200])
            state_obj._inbox_seen = seen
    except Exception:
        pass

    # Determine stress rule: per-game stress_event or global
    stress_event = game.get("stress_event") or GLOBAL_STRESS_EVENT

    # Debug logging
    logger.debug("============ PROCESSING CHOICE ============")
    logger.debug(f"Choice ID requested: {choice_id}")
    if isinstance(choice_ids, list):
        logger.debug(f"Choice IDs requested: {choice_ids}")
    logger.debug(f"Current round_index in state: {state_obj.round_index}")
    logger.debug(f"Game has {len(game['rounds'])} total rounds")
    logger.debug(f"State object: {state_obj}")
    if state_obj.round_index < len(game["rounds"]):
        current_round = game["rounds"][state_obj.round_index]
        available_choices = current_round.get("choices", [])
        if not available_choices and current_round.get("tabs"):
            available_choices = []
            for tab in current_round.get("tabs", []):
                available_choices.extend(tab.get("choices", []))
        logger.debug(f"Round at index {state_obj.round_index}:")
        logger.debug(f"- Round ID: {current_round.get('id')}")
        logger.debug(f"- Round Title: {current_round.get('title')}")
        logger.debug(f"- Available choice IDs: {[c.get('id') for c in available_choices]}")
        logger.debug(f"- User trying to select: {choice_ids if isinstance(choice_ids, list) else choice_id}")
        logger.debug(f"- Match? {choice_id in [c.get('id') for c in available_choices]}")
    else:
        logger.error(f"round_index {state_obj.round_index} is out of bounds!")
    logger.debug(f"===========================================\n")
    # --- Round index repair ---
    # If the choice_id doesn't belong to the current round, search all rounds
    # This can happen if a dynamic round was inserted and indices shifted
    target_cid = choice_id
    if isinstance(choice_ids, list) and choice_ids:
        target_cid = choice_ids[0]
    if target_cid and state_obj.round_index < len(game["rounds"]):
        current_choices = game["rounds"][state_obj.round_index].get("choices", [])
        if game["rounds"][state_obj.round_index].get("tabs"):
            current_choices = []
            for tab in game["rounds"][state_obj.round_index].get("tabs", []):
                current_choices.extend(tab.get("choices", []))
        current_choice_ids = [c.get("id") for c in current_choices]
        if target_cid not in current_choice_ids:
            # Choice not found in current round - search all rounds for it
            logger.warning(f"Choice '{target_cid}' not in current round {state_obj.round_index}. Searching all rounds...")
            found_idx = None
            for idx, rnd in enumerate(game["rounds"]):
                all_ch = rnd.get("choices", [])
                if rnd.get("tabs"):
                    all_ch = []
                    for tab in rnd.get("tabs", []):
                        all_ch.extend(tab.get("choices", []))
                if target_cid in [c.get("id") for c in all_ch]:
                    found_idx = idx
                    break
            if found_idx is not None and found_idx != state_obj.round_index:
                logger.warning(f"Found choice '{target_cid}' in round {found_idx} (was at {state_obj.round_index}). Correcting round_index.")
                state_obj.round_index = found_idx
                prev_round = game["rounds"][state_obj.round_index]
            else:
                logger.error(f"Choice '{target_cid}' not found in any round!")
    # Apply deterministic choice + events (engine)
    # Detect input_type from the current round — defaults to multiple_choice
    _input_type = prev_round.get("input_type", "multiple_choice")
    try:
        if _input_type in ("structured_form", "slider_rating", "checklist") and free_text:
            # ── Tier 2 widget path: structured input + LLM eval ──────
            _structured = payload.get("structured_response", {})
            _rubric = prev_round.get("evaluation_rubric", {})
            _dims = (
                prev_round.get("scoring_dimensions")
                or list(_rubric.keys())
                or ["strategic_thinking", "risk_tolerance", "delayed_gratification",
                    "adaptability", "resilience", "empathy"]
            )
            _max_delta = int(prev_round.get("max_delta_per_dimension", 12))
            _situation = prev_round.get("situation") or prev_round.get("story") or prev_round.get("title", "")

            # Apply direct_deltas (sliders/checklist) — re-validate from round config
            _validated_deltas = {}
            if _input_type == "slider_rating":
                _sv = _structured.get("slider_values", {})
                for s_cfg in prev_round.get("sliders", []):
                    v = max(s_cfg.get("min", 1), min(s_cfg.get("max", 5), int(_sv.get(s_cfg["key"], 0))))
                    for res, mult in (s_cfg.get("resource_map") or {}).items():
                        _validated_deltas[res] = _validated_deltas.get(res, 0) + v * mult
            elif _input_type == "checklist":
                _ck = set(_structured.get("checked_items", []))
                for item_cfg in prev_round.get("items", []):
                    if item_cfg["key"] in _ck:
                        dim = item_cfg.get("dimension", "resilience")
                        _validated_deltas[dim] = _validated_deltas.get(dim, 0) + item_cfg.get("delta", 2)

            # Apply validated direct deltas to state
            for resource, delta_val in _validated_deltas.items():
                if hasattr(state_obj, resource):
                    setattr(state_obj, resource, getattr(state_obj, resource, 0) + delta_val)
                elif hasattr(state_obj, 'state') and isinstance(state_obj.state, dict):
                    state_obj.state[resource] = state_obj.state.get(resource, 0) + delta_val

            # LLM evaluate the free_text portion
            eval_result = evaluate_free_text_response(
                situation=_situation,
                player_text=free_text,
                scoring_dimensions=_dims,
                evaluation_rubric=_rubric,
                max_delta=_max_delta,
            )

            # Honesty penalty for slider_rating
            if _input_type == "slider_rating":
                _honesty = prev_round.get("honesty_check", {})
                if _honesty.get("enabled"):
                    _sv = _structured.get("slider_values", {})
                    _avg_slider = sum(_sv.values()) / max(len(_sv), 1)
                    _q_threshold = _honesty.get("quality_threshold", 4)
                    _a_threshold = _honesty.get("avg_rating_threshold", 4)
                    if eval_result.get("quality_score", 10) < _q_threshold and _avg_slider > _a_threshold:
                        _penalty = _honesty.get("penalty_multiplier", 0.5)
                        for resource, delta_val in _validated_deltas.items():
                            _reduction = delta_val - int(delta_val * _penalty)
                            if hasattr(state_obj, resource):
                                setattr(state_obj, resource, getattr(state_obj, resource, 0) - _reduction)
                            elif hasattr(state_obj, 'state') and isinstance(state_obj.state, dict):
                                state_obj.state[resource] = state_obj.state.get(resource, 0) - _reduction
                        eval_result["honesty_penalty_applied"] = True

            state_obj, outcome = apply_free_text_response(
                game, state_obj, free_text, eval_result, time_to_decide=time_to_decide
            )
            outcome["free_text_eval"] = eval_result
            outcome["structured_response"] = _structured
            outcome["validated_deltas"] = _validated_deltas

        elif _input_type == "drawing_canvas":
            # ── Drawing canvas path: Vision API eval ──────
            _widget_data = payload.get("widget_data", {})
            _drawing_id = _widget_data.get("drawing_id")
            if _drawing_id:
                import os as _os
                _draw_dir = _os.path.join("game_sessions", run_id, "drawings")
                _image_path = _os.path.join(_draw_dir, f"{_drawing_id}.png")
                _rubric = prev_round.get("evaluation_rubric") or {}
                _sw_props = prev_round.get("scene_widget", {}).get("props", {})
                if not _rubric:
                    _rubric = _sw_props.get("evaluation_rubric", {})
                _dims = (
                    prev_round.get("scoring_dimensions")
                    or _sw_props.get("scoring_dimensions")
                    or list(_rubric.keys())
                    or ["creativity", "strategic_thinking"]
                )
                _max_delta = _sw_props.get("max_delta", 10)
                _situation = prev_round.get("situation") or prev_round.get("story") or prev_round.get("title", "")
                if _os.path.exists(_image_path):
                    eval_result = evaluate_drawing(
                        situation=_situation,
                        image_path=_image_path,
                        evaluation_rubric=_rubric,
                        scoring_dimensions=_dims,
                        max_delta=_max_delta,
                    )
                else:
                    eval_result = {
                        "dimension_scores": {d: 5 for d in _dims},
                        "dimension_deltas": {d: _max_delta // 2 for d in _dims},
                        "feedback": "Drawing received. Keep practicing your visual thinking!",
                        "quality_score": 5,
                        "skill_tags": _dims[:2],
                        "matched_label": "Visual Thinker",
                        "sentiment_valence": 0.3,
                        "emotional_markers": [],
                        "engagement_level": "medium",
                    }
                state_obj, outcome = apply_free_text_response(
                    game, state_obj, f"[Drawing: {_drawing_id}]", eval_result, time_to_decide=time_to_decide
                )
                outcome["free_text_eval"] = eval_result
                outcome["drawing_eval"] = eval_result
                outcome["widget_data"] = {k: v for k, v in _widget_data.items() if k != "image_base64"}
            else:
                state_obj, outcome = apply_choice(game, state_obj, choice_id, stress_event=stress_event, time_to_decide=time_to_decide)

        elif _input_type == "free_text" and free_text:
            # ── Free-text path: LLM evaluates the response ──────────────────
            _rubric = prev_round.get("evaluation_rubric", {})
            _dims = (
                prev_round.get("scoring_dimensions")
                or list(_rubric.keys())
                or ["strategic_thinking", "risk_tolerance", "delayed_gratification",
                    "adaptability", "resilience", "empathy"]
            )
            _max_delta = int(prev_round.get("max_delta_per_dimension", 12))
            _situation = prev_round.get("situation") or prev_round.get("story") or prev_round.get("title", "")
            eval_result = evaluate_free_text_response(
                situation=_situation,
                player_text=free_text,
                scoring_dimensions=_dims,
                evaluation_rubric=_rubric,
                max_delta=_max_delta,
            )
            state_obj, outcome = apply_free_text_response(
                game, state_obj, free_text, eval_result, time_to_decide=time_to_decide
            )
            outcome["free_text_eval"] = eval_result
        elif _input_type == "hybrid" and free_text and (choice_id or (isinstance(choice_ids, list) and choice_ids)):
            # ── Hybrid path: apply choice normally, then LLM adjusts dimensions ──
            if isinstance(choice_ids, list) and choice_ids:
                state_obj, outcome = apply_choice(game, state_obj, choice_ids, stress_event=stress_event, time_to_decide=time_to_decide)
            else:
                state_obj, outcome = apply_choice(game, state_obj, choice_id, stress_event=stress_event, time_to_decide=time_to_decide)
            # Small LLM adjustment for reasoning quality (capped at ±4)
            _rubric = prev_round.get("evaluation_rubric", {})
            _dims = (
                prev_round.get("scoring_dimensions")
                or list(_rubric.keys())
                or ["strategic_thinking", "adaptability", "empathy"]
            )
            _situation = prev_round.get("situation") or prev_round.get("story") or prev_round.get("title", "")
            try:
                eval_result = evaluate_free_text_response(
                    situation=_situation,
                    player_text=free_text,
                    scoring_dimensions=_dims,
                    evaluation_rubric=_rubric,
                    max_delta=4,  # small adjustment for reasoning
                )
                from core.effects import apply_delta as _apply_delta
                state_obj = _apply_delta(state_obj, eval_result.get("dimension_deltas", {}))
                outcome["free_text_eval"] = eval_result
                outcome["hybrid_reasoning_feedback"] = eval_result.get("feedback", "")
            except Exception as _he:
                logger.warning(f"Hybrid free-text eval failed: {_he}")
        elif isinstance(choice_ids, list) and choice_ids:
            state_obj, outcome = apply_choice(game, state_obj, choice_ids, stress_event=stress_event, time_to_decide=time_to_decide)
        else:
            state_obj, outcome = apply_choice(game, state_obj, choice_id, stress_event=stress_event, time_to_decide=time_to_decide)

        # ── Widget data from scene widgets (brainstorm_board) ──
        _widget_data_bb = payload.get("widget_data", {})
        if _widget_data_bb.get("widget_type") == "brainstorm_board" and _input_type != "drawing_canvas":
            _sw_props = prev_round.get("scene_widget", {}).get("props", {})
            _tiers = _sw_props.get("scoring_tiers", [])
            _idea_count = int(_widget_data_bb.get("idea_count", 0))
            _tier_delta = {}
            for tier in _tiers:
                if _idea_count >= tier.get("min_count", 0):
                    _tier_delta = tier.get("delta", {})
                    break
            for resource, delta_val in _tier_delta.items():
                if hasattr(state_obj, resource):
                    setattr(state_obj, resource, getattr(state_obj, resource, 0) + delta_val)
                elif hasattr(state_obj, 'state') and isinstance(state_obj.state, dict):
                    state_obj.state[resource] = state_obj.state.get(resource, 0) + delta_val
            outcome.setdefault("widget_data", {}).update({
                "widget_type": "brainstorm_board",
                "idea_count": _idea_count,
                "best_idea": _widget_data_bb.get("best_idea", ""),
                "ideas": _widget_data_bb.get("ideas", [])[:20],
                "validated_tier_delta": _tier_delta,
            })

    except ValueError as e:
        import traceback
        logger.error(f"apply_choice failed: {str(e)}")
        traceback.print_exc()
        return jsonify({"error": "Failed to process choice"}), 500
    except Exception as e:
        import traceback
        logger.error(f"Unexpected error in apply_choice: {str(e)}")
        traceback.print_exc()
        return jsonify({"error": "Failed to process choice"}), 500

    # Attach reflection if present
    if reflection:
        outcome["reflection"] = reflection
        # Spec #F — LLM evaluation of the player's reflection text.
        # Best-effort: failures must never block the choice response.
        try:
            from llm import evaluate_free_text_response
            # Use the chosen choice's label or the round prompt as the situation context.
            _refl_round = (game.get("rounds") or [])[max(0, state_obj.round_index - 1)] if game.get("rounds") else {}
            _situation = (_refl_round.get("reflection_prompt")
                          or _refl_round.get("scenario")
                          or _refl_round.get("prompt")
                          or "Reflection on a recent decision.")
            _dims = ["strategic_thinking", "empathy", "delayed_gratification", "adaptability"]
            _eval = evaluate_free_text_response(
                situation=str(_situation)[:600],
                player_text=reflection[:1000],
                scoring_dimensions=_dims,
                max_delta=6,
            )
            if isinstance(_eval, dict):
                outcome["reflection_evaluation"] = {
                    "feedback": _eval.get("feedback"),
                    "quality_score": _eval.get("quality_score"),
                    "matched_label": _eval.get("matched_label"),
                    "skill_tags": _eval.get("skill_tags", []),
                    "dimension_deltas": _eval.get("dimension_deltas", {}),
                }
                # Apply small dimension deltas (already capped at max_delta=6) to dimension_scores.
                dim_scores = getattr(state_obj, "dimension_scores", None)
                if isinstance(dim_scores, dict):
                    for _dim, _delta in (_eval.get("dimension_deltas") or {}).items():
                        if isinstance(_delta, (int, float)) and _dim in dim_scores:
                            dim_scores[_dim] = max(0, min(100, dim_scores[_dim] + int(_delta)))
        except Exception as _refl_err:
            logger.warning(f"Reflection LLM eval failed (non-fatal): {_refl_err}")

    # ── Simulation tick processing ────────────────────────────────
    # For simulation games, process between-round state evolution after each choice
    _sim_tick_result = None
    _sim_dashboard = None
    _sim_engine = None
    _pre_snapshot = None
    if game.get("simulation_config"):
        try:
            from engines.simulation_tick_engine import SimulationTickEngine
            _sim_engine = SimulationTickEngine(game["simulation_config"])
            # Initialize if not yet initialized (e.g. loaded from disk)
            if not hasattr(state_obj, 'sim_tick'):
                _sim_engine.initialize_simulation(state_obj)
            # Capture pre-choice metric snapshot for transition screen delta bullets
            try:
                _pre_snapshot = snapshot_state(state_obj)
            except Exception:
                _pre_snapshot = None
            # Anti-cheat: process flags, delayed effects, noise, momentum, patterns
            if _chosen:
                _choice_idx = next((i for i, c in enumerate(prev_round.get("choices", [])) if c.get("id") == choice_id), 0)
                _sim_engine.process_choice_anticheat(state_obj, _chosen, _choice_idx, prev_round)
            # Dual-action bonus: if sequence of required ids completed this round, boost metrics
            try:
                _da = getattr(state_obj, '_sim_dual_actions', {}) or {}
                _da_rules = (prev_round or {}).get("dual_action_bonuses") or []
                for _rule in _da_rules:
                    _key = _rule.get("key")
                    _seq = _rule.get("require_ids") or []
                    if _key and _seq and _key in _da:
                        if all(_id in _da[_key] for _id in _seq):
                            for _res, _delta in (_rule.get("apply") or {}).items():
                                setattr(state_obj, _res, getattr(state_obj, _res, 0) + _delta)
            except Exception:
                pass
            _sim_tick_result = _sim_engine.process_tick(state_obj, state_obj.round_index)
            _sim_dashboard = _sim_engine.get_dashboard_data(state_obj)
            logger.info(f"[Simulation] Tick {state_obj.sim_tick} processed. Events: {len(_sim_tick_result.get('events_triggered', []))}")
        except Exception as _sim_err:
            # Spec #1/#32 — promote silent failures to ERROR with full context.
            # Was previously WARNING with stacktrace going to stderr only,
            # which masked the V2 'sim_tick=1, round_index=4' bug for hours.
            logger.error(
                "Simulation tick processing FAILED — game=%s run=%s round_index=%s sim_tick=%s err=%s",
                game.get("game_id"), run_id, getattr(state_obj, "round_index", None),
                getattr(state_obj, "sim_tick", None), _sim_err,
                exc_info=True,
            )

    # Process competitors (deterministic - before LLM layer)
    # NOTE: Skip for AI Arena games — they use their own competitor chat system
    competitor_actions = []
    game_type = game.get("game_type", "rounds")
    if game_type != "ai_arena" and hasattr(state_obj, 'competitor_states') and state_obj.competitor_states:
        market_config = game.get("market_config")
        resource_metadata = game.get("resource_metadata", {})
        
        # Calculate market shares for all participants
        market_shares = process_market_dynamics(state_obj, state_obj.competitor_states, market_config)
        
        # Store market history
        if hasattr(state_obj, 'market_history'):
            state_obj.market_history.append({
                "round": state_obj.round_index,
                "shares": market_shares
            })
        
        # Helper to get competitor attribute (works for both objects and dicts)
        def _comp_attr(comp, key, default=None):
            if isinstance(comp, dict):
                return comp.get(key, default)
            return getattr(comp, key, default)

        # Process each active competitor
        for competitor in state_obj.competitor_states:
            if not _comp_attr(competitor, 'is_active', True):
                continue

            # Get personality config if defined
            competitors_config = game.get("competitors", [])
            comp_id = _comp_attr(competitor, 'competitor_id', '')
            comp_config = next((c for c in competitors_config if c["id"] == comp_id), {})
            personality_config = comp_config.get("personality_config", {})

            # Evaluate competitor's decision
            decision = evaluate_competitor_decisions(
                competitor, state_obj, market_shares,
                personality_config, state_obj.round_index
            )

            # Apply decision to competitor state
            market_multiplier = market_shares.get(comp_id, {}).get("demand_multiplier", 0.5)
            apply_competitor_decision(competitor, decision, market_multiplier)

            # Apply resource decay if configured
            if resource_metadata:
                apply_decay_rules(competitor, resource_metadata)

            # Generate personality-appropriate flavor text
            personality = str(_comp_attr(competitor, 'personality_type', 'balanced'))
            comp_name = str(_comp_attr(competitor, 'name', 'Competitor'))
            flavor_templates = {
                "aggressive": f"{comp_name} went all-in with an aggressive move!",
                "balanced": f"{comp_name} made a measured, balanced decision.",
                "quality_focused": f"{comp_name} focused on quality over quantity.",
                "follower": f"{comp_name} followed the market trend carefully.",
                "conservative": f"{comp_name} played it safe this round.",
            }
            flavor_text = flavor_templates.get(personality, f"{comp_name} made their move.")
            decision_summary = ", ".join(f"{k}: {v}" for k, v in decision.items() if k not in ("round_index",))

            # Record action for display (ensure all values are JSON serializable)
            competitor_actions.append({
                "id": str(comp_id),
                "name": comp_name,
                "personality_type": personality,
                "decision": {k: (int(v) if isinstance(v, (int, float)) else bool(v) if isinstance(v, bool) else str(v))
                           for k, v in decision.items()},
                "market_share": float(market_shares.get(comp_id, {}).get("market_share", 0)),
                "is_active": bool(_comp_attr(competitor, 'is_active', True)),
                "flavor_text": flavor_text,
                "decision_summary": decision_summary,
                "resources": {
                    "cash_inr": int(_comp_attr(competitor, 'cash_inr', 0)),
                    "profit": int(_comp_attr(competitor, 'profit', 0)),
                    "reputation": int(_comp_attr(competitor, 'reputation', 50)),
                    "customer_satisfaction": int(_comp_attr(competitor, 'customer_satisfaction', 50)),
                    "cups_sold": int(_comp_attr(competitor, 'cups_sold', 0))
                }
            })
        
        # Apply decay to player resources as well
        if resource_metadata:
            apply_decay_rules(state_obj, resource_metadata)
        
        # Add competitor data to outcome (ensure JSON serializable)
        outcome["competitor_actions"] = competitor_actions
        outcome["market_shares"] = {k: {
            "market_share": float(v["market_share"]),
            "demand_multiplier": float(v["demand_multiplier"])
        } for k, v in market_shares.items()}
    
    # LLM layer (optional) for Mira + Competitor
    # Ensure all data is JSON serializable before passing to LLM
    llm_context = {
        "round_title": outcome["round_title"],
        "goal": outcome["goal"],
        "choice": outcome["choice"],
        "events": outcome["events"],
        "state_after_events": make_json_serializable(outcome["state_after_events"]),
        "competitor_name": outcome.get("competitor_name", prev_round.get("competitor_name", "Competitor")),
        "competitor_actions": competitor_actions if competitor_actions else None,
        "market_shares": outcome.get("market_shares")
    }
    llm_bits = generate_mira_and_competitor(llm_context)
    outcome["mira"] = llm_bits.get("mira", "")
    outcome["mira_question"] = llm_bits.get("question", "")
    outcome["competitor_reaction"] = llm_bits.get("competitor", "")

    # Compute score after events
    score_after = compute_score(outcome["state_after_events"])
    outcome["score_after"] = score_after

    # --- Per-choice Mento Coins reward/penalty ---
    round_coins = None
    try:
        token = get_token_from_request()
        user_payload = verify_token(token) if token else None
        if user_payload:
            # Determine coin delta from choice quality
            # Good choices earn 5-15 coins, mediocre earn 1-3, bad choices lose 3-10
            choice_data = outcome.get("choice", {})
            events = outcome.get("events", [])
            score_before = outcome.get("score_before", 0)

            # Calculate net resource change as a quality signal
            state_before = outcome.get("state_before_events", {})
            state_after = outcome.get("state_after_events", {})
            net_change = 0
            resource_count = 0
            for key in state_after:
                if key in ("round_index",):
                    continue
                after_val = state_after[key] if isinstance(state_after[key], (int, float)) else (state_after[key].get("value", 0) if isinstance(state_after[key], dict) else 0)
                before_val = state_before.get(key, 0) if isinstance(state_before.get(key, 0), (int, float)) else (state_before.get(key, {}).get("value", 0) if isinstance(state_before.get(key, 0), dict) else 0)
                if isinstance(after_val, (int, float)) and isinstance(before_val, (int, float)):
                    net_change += (after_val - before_val)
                    resource_count += 1

            # Assign coins based on net resource change
            if net_change > 15:
                coins = 15  # Excellent choice
            elif net_change > 5:
                coins = 10  # Good choice
            elif net_change > 0:
                coins = 5   # Decent choice
            elif net_change == 0:
                coins = 2   # Neutral
            elif net_change > -5:
                coins = -3  # Poor choice
            elif net_change > -15:
                coins = -5  # Bad choice
            else:
                coins = -10 # Terrible choice

            round_coins = wallet.credit_round_coins(
                user_id=user_payload["user_id"],
                game_id=game_id,
                game_title=game.get("title", game_id),
                round_title=prev_round.get("title", f"Round {state_obj.round_index}"),
                coins=coins,
                reason=f"{'Earned' if coins >= 0 else 'Lost'} coins for choice in {prev_round.get('title', 'round')}",
            )
    except Exception as coin_err:
        logger.warning(f"Per-choice coin credit failed: {coin_err}")
    # Generate round takeaway (game-specific, deterministic) and store per-round
    try:
        takeaway = generate_round_takeaway(prev_round, outcome, game=game)
    except Exception as e:
        logger.warning(f"Failed to generate takeaway: {e}")
        takeaway = {
            "roundId": str(outcome.get("round_id") or prev_round.get("id") or "unknown_round"),
            "takeawayTitle": "Next round focus",
            "takeawayPoints": [
                "Keep the round goal in mind and pick the option that best supports it.",
                "Watch one key resource and avoid draining it too fast."
            ]
        }
    outcome["takeaway"] = takeaway

    # --- Skill callout: identify the soft skill exercised by this choice ---
    try:
        from engines.dimension_utils import infer_skill_tags_from_deltas, build_skill_callout
        actual_cid_sc = choice_ids[0] if isinstance(choice_ids, list) and choice_ids else choice_id
        # Find the chosen choice object for its deltas
        chosen_obj = {}
        for ch in prev_round.get("choices", []):
            if ch.get("id") == actual_cid_sc:
                chosen_obj = ch
                break
        if not chosen_obj:
            for tab in prev_round.get("tabs", []):
                for ch in tab.get("choices", []):
                    if ch.get("id") == actual_cid_sc:
                        chosen_obj = ch
                        break
        choice_deltas = chosen_obj.get("delta", chosen_obj.get("deltas", {}))
        inferred_tags = chosen_obj.get("skill_tags") or infer_skill_tags_from_deltas(
            choice_deltas, chosen_obj.get("label", "")
        )
        if inferred_tags:
            net_val = sum(v for v in (choice_deltas or {}).values() if isinstance(v, (int, float)))
            callout = build_skill_callout(inferred_tags[0], net_val)
            if callout:
                outcome["skill_callout"] = callout
    except Exception as sc_err:
        logger.warning(f"Skill callout generation failed: {sc_err}")
    # --- Item 6: Post-Choice Reflection Prompt ---
    # If the chosen choice has a reflection_prompt, include it (max 3 per game)
    try:
        reflection_count = r.get("reflection_prompt_count", 0)
        max_reflections = game.get("max_reflections", 3)
        if reflection_count < max_reflections:
            actual_cid_rp = choice_ids[0] if isinstance(choice_ids, list) and choice_ids else choice_id
            rp_choice = {}
            for ch in prev_round.get("choices", []):
                if ch.get("id") == actual_cid_rp:
                    rp_choice = ch
                    break
            if not rp_choice:
                for tab in prev_round.get("tabs", []):
                    for ch in tab.get("choices", []):
                        if ch.get("id") == actual_cid_rp:
                            rp_choice = ch
                            break
            rp_text = rp_choice.get("reflection_prompt") or (
                prev_round.get("reflection_prompt") if rp_choice.get("is_pivotal") else None
            )
            if rp_text:
                outcome["post_choice_reflection"] = {
                    "prompt": rp_text,
                    "choice_label": rp_choice.get("label", ""),
                    "round_title": prev_round.get("title", ""),
                }
                r["reflection_prompt_count"] = reflection_count + 1
    except Exception as rp_err:
        logger.warning(f"Post-choice reflection prompt failed: {rp_err}")
    # --- Item 7: Teachable Moment Card ---
    # If the chosen choice leads to a negative outcome, show a teachable moment
    try:
        actual_cid_tm = choice_ids[0] if isinstance(choice_ids, list) and choice_ids else choice_id
        tm_choice = {}
        for ch in prev_round.get("choices", []):
            if ch.get("id") == actual_cid_tm:
                tm_choice = ch
                break
        if not tm_choice:
            for tab in prev_round.get("tabs", []):
                for ch in tab.get("choices", []):
                    if ch.get("id") == actual_cid_tm:
                        tm_choice = ch
                        break
        # Check for explicit teachable_moment in game JSON
        explicit_tm = tm_choice.get("teachable_moment")
        if explicit_tm:
            outcome["teachable_moment"] = explicit_tm
        else:
            # Auto-generate if outcome is significantly negative
            tm_deltas = tm_choice.get("delta", tm_choice.get("deltas", {}))
            tm_net = sum(v for v in (tm_deltas or {}).values() if isinstance(v, (int, float)))
            if tm_net < -10:  # Significantly negative outcome
                from engines.dimension_utils import infer_skill_tags_from_deltas, build_teachable_moment
                tm_tags = infer_skill_tags_from_deltas(tm_deltas, tm_choice.get("label", ""))
                if tm_tags:
                    tm_card = build_teachable_moment(tm_tags[0], tm_choice.get("label", ""), tm_net)
                    if tm_card:
                        outcome["teachable_moment"] = tm_card
    except Exception as tm_err:
        logger.warning(f"Teachable moment generation failed: {tm_err}")
    # --- Item 8: Mid-Game Checkpoint ---
    # At 25%, 50%, 75% progress, include a checkpoint in the response
    try:
        total_rounds = len(game.get("rounds", []))
        current_index = state_obj.round_index  # 0-based, this is the round we just completed
        if total_rounds > 0:
            progress_pct = round((current_index / total_rounds) * 100)
            # Determine checkpoint intervals based on game length
            if total_rounds < 8:
                checkpoint_intervals = game.get("checkpoint_intervals", [50])
            else:
                checkpoint_intervals = game.get("checkpoint_intervals", [25, 50, 75])
            # Check if we just crossed a checkpoint threshold
            prev_progress = round(((current_index - 1) / total_rounds) * 100) if current_index > 0 else 0
            triggered_checkpoints = r.get("triggered_checkpoints", [])
            for threshold in checkpoint_intervals:
                if prev_progress < threshold <= progress_pct and threshold not in triggered_checkpoints:
                    from engines.dimension_utils import build_checkpoint_message
                    # Get dimension scores if available
                    dim_scores = None
                    if hasattr(state_obj, 'dimension_scores'):
                        dim_scores = state_obj.dimension_scores
                    elif hasattr(state_obj, 'to_dict'):
                        sd = state_obj.to_dict()
                        dim_scores = sd.get("dimension_scores")
                    checkpoint_data = build_checkpoint_message(progress_pct, dim_scores)
                    # Add resource summary from current state
                    state_dict = state_to_dict(state_obj)
                    resource_summary = {}
                    initial_state = game.get("initial_state", {})
                    for k, v in state_dict.items():
                        if k in ("round_index",):
                            continue
                        if isinstance(v, (int, float)):
                            init_val = initial_state.get(k, v)
                            if isinstance(init_val, dict):
                                init_val = init_val.get("value", v)
                            if isinstance(init_val, (int, float)) and init_val != 0:
                                change = v - init_val
                                pct_change = round((change / abs(init_val)) * 100) if init_val != 0 else 0
                                resource_summary[k] = {"current": round(v), "change": round(change), "pct_change": pct_change}
                    checkpoint_data["round_number"] = current_index
                    checkpoint_data["total_rounds"] = total_rounds
                    checkpoint_data["resource_summary"] = resource_summary
                    checkpoint_data["choices_made"] = current_index
                    outcome["halftime_checkpoint"] = checkpoint_data
                    triggered_checkpoints.append(threshold)
                    r["triggered_checkpoints"] = triggered_checkpoints
                    break  # Only one checkpoint per round
    except Exception as cp_err:
        logger.warning(f"Mid-game checkpoint generation failed: {cp_err}")
    # --- Social Stats: record choice distribution ---
    try:
        from storage import record_choice_stat, get_choice_stats
        actual_cid_for_stats = choice_ids[0] if isinstance(choice_ids, list) and choice_ids else choice_id
        record_choice_stat(game_id, state_obj.round_index, actual_cid_for_stats)
        social_stats = get_choice_stats(game_id, state_obj.round_index)
        if social_stats:
            outcome["social_stats"] = social_stats
    except Exception as social_err:
        logger.warning(f"Social stats error: {social_err}")
    # --- Expert pick for this round (if defined in game JSON) ---
    _expert_pick = prev_round.get("expert_pick")
    if _expert_pick:
        outcome["expert_pick"] = _expert_pick
    # --- RL 3C: Choice dominance signal (persistent choice_stats.json) ---
    try:
        _cstats_file = os.path.join(os.path.dirname(__file__), "data", "choice_stats.json")
        try:
            with open(_cstats_file) as _f:
                _cstats = json.load(_f)
        except (FileNotFoundError, json.JSONDecodeError):
            _cstats = {}
        _actual_cid_rl = choice_ids[0] if isinstance(choice_ids, list) and choice_ids else choice_id
        _round_id_rl = prev_round.get("id", str(state_obj.round_index))
        _cstats.setdefault(game_id, {}).setdefault(_round_id_rl, {})
        _cstats[game_id][_round_id_rl][_actual_cid_rl] = _cstats[game_id][_round_id_rl].get(_actual_cid_rl, 0) + 1
        with open(_cstats_file, "w") as _f:
            json.dump(_cstats, _f)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # --- RL 3B: Update rounds_completed in game_starts ---
    try:
        _gs_file = os.path.join(os.path.dirname(__file__), "data", "game_starts.json")
        try:
            with open(_gs_file) as _f:
                _game_starts = json.load(_f)
        except (FileNotFoundError, json.JSONDecodeError):
            _game_starts = {}
        if run_id in _game_starts:
            _game_starts[run_id]["rounds_completed"] = int(state_obj.round_index)
            with open(_gs_file, "w") as _f:
                json.dump(_game_starts, _f)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Feature 5: Update last_seen for active session tracking
    try:
        _act_file_ch = os.path.join(os.path.dirname(__file__), "data", "active_sessions.json")
        try:
            with open(_act_file_ch) as _af_ch:
                _act_ch = json.load(_af_ch)
        except (FileNotFoundError, json.JSONDecodeError):
            _act_ch = {}
        if run_id in _act_ch:
            _act_ch[run_id]["last_seen"] = datetime.now().isoformat()
            with open(_act_file_ch, "w") as _af_ch:
                json.dump(_act_ch, _af_ch)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Serialize outcome before storing and returning
    serialized_outcome = make_json_serializable(outcome)

    # Store serialized outcome in run log
    r["log"].append(serialized_outcome)

    # Store reconsideration + engagement signals in latest choice_history entry
    try:
        if state_obj.choice_history:
            _last_ch = state_obj.choice_history[-1]
            if _reconsideration:
                _last_ch["changed_selection"] = _reconsideration.get("changed_selection", False)
                _last_ch["num_selection_changes"] = _reconsideration.get("num_selection_changes", 0)
                _last_ch["hover_durations"] = _reconsideration.get("hover_durations", [])
            if _engagement_signals:
                _last_ch["engagement_signals"] = _engagement_signals
    except Exception as _sig_err:
        logger.debug("Suppressed reconsideration signal storage: %s", _sig_err)

    # Index takeaways by round id (helps report building and quick lookups)
    try:
        r.setdefault("round_takeaways", {})[takeaway["roundId"]] = takeaway
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Are we done? (if we just completed last round)
    # Use both ID match and index bounds check for robustness (dynamic rounds can shift indices)
    # Note: state_obj.round_index may have been corrected by round_index repair above,
    # so use the CURRENT value, not the original one used to set prev_round.
    _last_round_id = game["rounds"][-1]["id"]
    _at_or_past_last = state_obj.round_index >= len(game["rounds"]) - 1
    _prev_is_last = prev_round["id"] == _last_round_id
    done = _prev_is_last or _at_or_past_last

    # Early-exit: if simulation engine triggered an early termination (e.g. R8 option 3)
    _early_exit_info = getattr(state_obj, '_sim_early_exit', None)
    if _early_exit_info and _early_exit_info.get("triggered") and not done:
        done = True
        logger.info(f"[EARLY-EXIT] game={game_id} round={prev_round.get('id')} reason={_early_exit_info.get('ending_id')}")

    # Safety net 1: if more rounds have been played than exist in the game, force game-over
    _rounds_played = len(r.get("log", []))
    _total_game_rounds = len(game.get("rounds", []))
    if _rounds_played >= _total_game_rounds and not done:
        logger.warning(f"[SAFETY-1] Game {game_id}: {_rounds_played} rounds played >= {_total_game_rounds} total. Forcing done=True.")
        done = True

    # Safety net 2: if current round_index equals the index of the LAST round being played
    # (handles case where prev_round was set before round_index correction)
    _current_round_id = game["rounds"][min(state_obj.round_index, len(game["rounds"])-1)]["id"]
    if _current_round_id == _last_round_id and not done:
        logger.warning(f"[SAFETY-2] Game {game_id}: current_round_id matches last_round_id. Forcing done=True.")
        done = True

    # --- P1a: Early game over from game_over_conditions (rounds.py evaluated this) ---
    _early_go = outcome.get("early_game_over")
    if _early_go:
        done = True
        state_obj.game_over = True

    # --- AI Arena advanced features (crisis, interdependencies, news, dynamic rounds) ---
    crisis_event_data = None
    interdependency_effects = []
    news_items = []
    npc_relationship_changes = []
    adaptive_info = None

    if game.get("game_type") == "ai_arena":
        try:
            from ai_arena_engine import (
                evaluate_crisis_events, apply_interdependencies,
                update_npc_relationships, generate_news_events,
                maybe_generate_live_round
            )
            state_dict = state_to_dict(state_obj)

            # 1) Interdependencies
            if game.get("interdependencies"):
                state_dict, interdependency_effects = apply_interdependencies(game, state_dict)
                # Write back any changes to state_obj
                for k, v in state_dict.items():
                    if k not in ("round_index", "total_rounds", "game_over", "game_id", "run_id"):
                        if hasattr(state_obj, k):
                            setattr(state_obj, k, v)

            # 2) NPC relationships
            # Get the actual choice from the round data
            actual_cid = choice_ids[0] if isinstance(choice_ids, list) and choice_ids else choice_id
            actual_choice_obj = {}
            try:
                cur_rnd = game["rounds"][state_obj.round_index] if state_obj.round_index < len(game["rounds"]) else prev_round
                for ch in cur_rnd.get("choices", []):
                    if ch.get("id") == actual_cid:
                        actual_choice_obj = ch
                        break
                if not actual_choice_obj:
                    for tab in cur_rnd.get("tabs", []):
                        for ch in tab.get("choices", []):
                            if ch.get("id") == actual_cid:
                                actual_choice_obj = ch
                                break
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            if actual_choice_obj.get("npc_deltas"):
                state_dict, npc_relationship_changes = update_npc_relationships(state_dict, actual_choice_obj)

            # 3) Crisis events
            if game.get("crisis_events"):
                crisis_event_data = evaluate_crisis_events(game, state_dict, state_obj.round_index)

            # 4) News ticker
            news_items = generate_news_events(game, state_dict, state_obj.round_index)

            # 5) Adaptive difficulty — compute and store for response (Feature 1: cross-session baseline)
            try:
                from ai_arena_engine import get_adaptive_difficulty
                import player_profile as _pp_adapt
                _adapt_tok = get_token_from_request()
                _adapt_usr = verify_token(_adapt_tok) if _adapt_tok else None
                _adapt_baseline = _pp_adapt.get_adaptive_summary(_adapt_usr["user_id"]) if _adapt_usr else None
                adaptive_info = get_adaptive_difficulty(
                    game, state_dict, state_obj.round_index,
                    baseline_scores=_adapt_baseline.get("avg_scores") if _adapt_baseline else None,
                )
            except Exception:
                adaptive_info = None

        except Exception as arena_err:
            logger.warning(f"AI Arena advanced features error: {arena_err}")
        # --- AI Arena: Update dimension scores incrementally after each choice ---
        try:
            arena_dim_scores = _compute_ai_arena_dimension_scores(
                r["log"],  # includes the entry just appended
                initial_state=game.get("initial_state", {}),
                game=game,
            )
            state_obj.dimension_scores = arena_dim_scores
            for sid, sv in arena_dim_scores.items():
                setattr(state_obj, sid, sv)
        except Exception as dim_err:
            logger.warning(f"AI Arena dimension score update failed: {dim_err}")
    # Feature 1: Cross-session adaptive difficulty for non-ai_arena games
    if game.get("game_type") != "ai_arena":
        try:
            _f1_token = get_token_from_request()
            _f1_user = verify_token(_f1_token) if _f1_token else None
            if _f1_user:
                import player_profile as _pp_f1
                _f1_summary = _pp_f1.get_adaptive_summary(_f1_user["user_id"])
                if _f1_summary.get("has_history"):
                    adaptive_info = {"calibrated": True, "has_history": True, "avg_scores": _f1_summary.get("avg_scores", {})}
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    if not done:
        # Check for live dynamic round injection (AI Arena)
        if game.get("game_type") == "ai_arena":
            try:
                from ai_arena_engine import maybe_generate_live_round
                state_dict = state_to_dict(state_obj)
                choice_hist = getattr(state_obj, 'choice_history', [])
                live_round = maybe_generate_live_round(game, state_dict, choice_hist, state_obj.round_index)
                if live_round:
                    # Insert after current position
                    insert_idx = state_obj.round_index + 1
                    game["rounds"].insert(insert_idx, live_round)
                    logger.info(f"Inserted dynamic round '{live_round.get('id')}' at index {insert_idx}. Total rounds now: {len(game['rounds'])}")
                    # Ensure initialized_game is updated with the new rounds
                    if "initialized_game" not in r:
                        import copy
                        r["initialized_game"] = copy.deepcopy(game)
                    r["initialized_game"]["rounds"] = list(game["rounds"])  # Store a copy of the list
                    # Immediately persist to disk so it's not lost
                    try:
                        update_run(run_id, r)
                        logger.info(f"Persisted dynamic round to disk for session {run_id}")
                    except Exception as save_err:
                        logger.warning(f"Failed to persist dynamic round: {save_err}")
            except Exception as dyn_err:
                logger.warning(f"Live dynamic round generation error: {dyn_err}")
        next_round(state_obj, game)

        # Re-check done after next_round (conditional branching may skip past the end)
        if state_obj.round_index >= len(game["rounds"]):
            done = True

        # Apply competitive adaptations if game has adaptive rules and competitors
        if game.get("adaptive_rules") and hasattr(state_obj, 'competitor_states') and state_obj.competitor_states:
            adaptive_engine = create_adaptive_engine(game)
            adaptations = adaptive_engine.evaluate_and_adapt(state_obj, state_obj.round_index)
            apply_competitive_adaptations(state_obj, adaptations)
    else:
        # Game completed - mark as completed and save to leaderboard
        r["completed"] = True  # Prevents re-processing choices on already-finished games
        try:
            # Get user_id from session or request
            user_id = session.get("username") or request.headers.get("X-User-ID") or run_id[:8]
            r["run_id"] = run_id  # Ensure run_id is in the data
            save_final_score(game_id, user_id, r, game)
        except Exception as e:
            logger.warning(f"Failed to save leaderboard entry: {e}")
            # Don't fail the request if leaderboard save fails

    # Select best ending for AI Arena games with endings configured
    ending_data = None
    if done and game.get("endings"):
        try:
            from core.endings import select_best_ending
            ending_data = select_best_ending(state_obj, game["endings"])
        except Exception as end_err:
            logger.warning(f"Failed to select ending: {end_err}")
    # Cross-session memory: save player history on game completion (Item 28: all variability games)
    _save_history = (
        game.get("game_type") == "ai_arena"
        or (game.get("game_type") == "rounds" and game.get("features", {}).get("variability"))
    )
    if done and _save_history:
        try:
            from ai_arena_engine import update_player_history
            token = get_token_from_request()
            user_payload = verify_token(token) if token else None
            if user_payload:
                ending_id = ending_data.get("id") if ending_data else None
                update_player_history(
                    game_id, user_payload["user_id"],
                    r.get("log", []), ending_id
                )
                logger.info(f"Updated cross-session history for user {user_payload['user_id']} on game {game_id}")
        except Exception as hist_err:
            logger.warning(f"Cross-session memory update failed: {hist_err}")
    # Persist changes to disk
    update_run(run_id, r)

    # --- Item 29: Peer Benchmarking ---
    peer_benchmark = None
    try:
        round_id = prev_round.get("id", "")
        actual_cid_pb = choice_ids[0] if isinstance(choice_ids, list) and choice_ids else choice_id
        if round_id and actual_cid_pb:
            peer_benchmark = _update_and_get_peer_benchmark(game_id, round_id, actual_cid_pb, prev_round)
    except Exception as pb_err:
        logger.warning(f"Peer benchmarking failed: {pb_err}")
    # Build response
    # Include updated state + next round payload so frontend can advance UI
    try:
        next_round_data = build_round_payload(game, state_obj) if not done else None
        # R11: overlay variant scene text if this run has an active replay variant
        if next_round_data is not None:
            next_round_data = _apply_variant_overlay(next_round_data, RUNS.get(run_id) or {})
    except Exception as rnd_err:
        import traceback
        logger.warning(f"build_round_payload failed: {rnd_err}")
        traceback.print_exc()
        next_round_data = None
        done = True  # Treat as game over if we can't build the next round

    # Progressive difficulty: determine round_mode for the NEXT round
    _total_rnd = len(game.get("rounds", []))
    _next_idx = int(state_obj.round_index)
    _difficulty_curve = game.get("difficulty_curve")
    _round_mode = _get_round_mode(_next_idx, _total_rnd, _difficulty_curve)
    # Only return full difficulty_phase when game explicitly defines difficulty_curve
    _difficulty_phase = _get_difficulty_phase(_next_idx, _total_rnd, _difficulty_curve) if _difficulty_curve else None

    # Fix 4: Check if a checkpoint quiz should trigger before the next round
    _checkpoint_required = None
    try:
        checkpoints = game.get("checkpoints", [])
        _completed_round_num = _next_idx  # 0-indexed next = just-completed round number
        for cp in checkpoints:
            after_round = cp.get("after_round", 0)
            if after_round == _completed_round_num and not done:
                # Check if already passed
                cp_results = r.get("checkpoint_results", {})
                cp_key = f"cp_{after_round}"
                if cp_key not in cp_results or not cp_results[cp_key].get("passed"):
                    _checkpoint_required = cp
                    break
    except Exception as _cp_err:
        logger.debug("Checkpoint detection failed: %s", _cp_err)

    # Feature 1: Inject calibration info into next round payload for frontend chip
    if next_round_data and adaptive_info and adaptive_info.get("calibrated"):
        next_round_data["adaptive_difficulty"] = {"calibrated": True}

    # --- Round 13: Mid-game coaching nudge ---
    # Track consecutive negative-outcome choices; signal frontend when streak hits 3
    coaching_needed = False
    try:
        _score_delta = serialized_outcome.get("delta", 0) if isinstance(serialized_outcome, dict) else 0
        if _score_delta < 0:
            r["low_dim_streak"] = r.get("low_dim_streak", 0) + 1
        else:
            r["low_dim_streak"] = 0
        if r.get("low_dim_streak", 0) >= 3 and not done:
            coaching_needed = True
            r["low_dim_streak"] = 0  # Reset after triggering
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # --- Round 13: Generic adaptive difficulty for all game types ---
    generic_adapt_result = None
    try:
        if game.get("game_type") in ("rounds", "board", "strategy", "story_branching", "minigame", "card"):
            from adaptive_engine import GenericAdaptiveEngine
            _dim_scores = getattr(state_obj, "dimension_scores", {}) or {}
            _dim_avg = sum(_dim_scores.values()) / len(_dim_scores) if _dim_scores else 50.0
            _adapt_metrics = {
                "score": getattr(state_obj, "score", 0),
                "time_spent": time_to_decide or 0,
                "consecutive_errors": r.get("low_dim_streak", 0),
                "dimension_avg": _dim_avg,
            }
            _adapt_engine = GenericAdaptiveEngine(game.get("adaptive_config", {}))
            _raw = _adapt_engine.evaluate(_adapt_metrics)
            # Normalise keys to match frontend expectations
            generic_adapt_result = {
                "hint": _raw.get("hint") or (_raw.get("show_hint") and "Take your time with this one 💡") or None,
                "difficulty_adjustment": _raw.get("difficulty") or "none",
                "triggered_rules": _raw.get("triggered_rules", []),
            } if _raw else None
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Mid-game adaptive difficulty hint
    try:
        _total_rounds_dh = len(game.get("rounds", [])) or 10
        _round_idx_dh = r["log"][-1].get("round_index", 0) if r["log"] else 0
        _diff_hint = _mid_game_difficulty(r, _round_idx_dh, _total_rounds_dh)
        if _diff_hint:
            r["difficulty_hint"] = _diff_hint
            update_run(run_id, r)
    except Exception:
        pass

    # --- Fix 1: Skill Introduction Cards ---
    # Detect new skill dimensions the student encounters for the first time
    _new_skills_introduced = []
    _skill_explanation = None
    try:
        token = get_token_from_request()
        _user_payload = verify_token(token) if token else None
        _uid = _user_payload["user_id"] if _user_payload else None
        if _uid:
            # Collect skill_tags from the chosen choice
            _choice_skill_tags = []
            if _chosen and isinstance(_chosen.get("skill_tags"), list):
                _choice_skill_tags = _chosen["skill_tags"]
            # Also check dimension_scoring_weights from the game
            _dim_weights = game.get("dimension_scoring_weights", {})
            _all_round_skills = list(set(_choice_skill_tags + list(_dim_weights.keys())))
            if _all_round_skills:
                import player_profile as _pp_skill_intro
                _newly = _pp_skill_intro.mark_skills_introduced(_uid, _all_round_skills)
                if _newly:
                    # Load skill definitions to send rich data
                    _sd_path = os.path.join(os.path.dirname(__file__), "config", "skill_definitions.json")
                    try:
                        with open(_sd_path) as _sf:
                            _sd = json.load(_sf).get("skills", {})
                    except Exception:
                        _sd = {}
                    for _sk in _newly:
                        _def = _sd.get(_sk, {})
                        _new_skills_introduced.append({
                            "id": _sk,
                            "name": _def.get("name", _sk.replace("_", " ").title()),
                            "emoji": _def.get("emoji", "📊"),
                            "color": _def.get("color", "#6366F1"),
                            "tagline": _def.get("tagline", ""),
                            "definition": _def.get("definition", ""),
                            "example": _def.get("example", ""),
                            "how_to_improve": _def.get("how_to_improve", ""),
                        })
            # Fix 2: Pass through skill_explanation from the chosen choice
            if _chosen and isinstance(_chosen.get("skill_explanation"), dict):
                _skill_explanation = _chosen["skill_explanation"]
    except Exception as _ski_err:
        logger.debug("Skill intro detection: %s", _ski_err)

    # Fix 5: Widget Challenge Mode — validate numeric challenge answer
    _challenge_result = None
    try:
        _challenge_answer = payload.get("challenge_answer")
        if _challenge_answer is not None and prev_round:
            _challenge_cfg = prev_round.get("challenge")
            if _challenge_cfg and _challenge_cfg.get("type") == "numeric":
                try:
                    _submitted = float(_challenge_answer)
                    _expected = float(_challenge_cfg["correct_answer"])
                    _tolerance = float(_challenge_cfg.get("tolerance", 0.5))
                    _is_correct = abs(_submitted - _expected) <= _tolerance
                    _challenge_result = {
                        "correct": _is_correct,
                        "submitted": _submitted,
                        "expected": _expected,
                        "feedback": "Correct! Well done!" if _is_correct else f"Not quite. The answer is {_expected} {_challenge_cfg.get('unit', '')}.",
                        "points": _challenge_cfg.get("points", 10) if _is_correct else 0,
                    }
                    if _is_correct:
                        try:
                            user_payload = verify_token(get_token_from_request())
                            if user_payload:
                                player_profile.award_xp(user_payload["user_id"], _challenge_cfg.get("points", 10), f"challenge_{game_id}")
                        except Exception:
                            pass
                except (ValueError, TypeError):
                    pass
    except Exception as _ch_err:
        logger.debug("Challenge validation: %s", _ch_err)

    # Fix 9: Widget answer validation (non-MCQ answers from interactive widgets)
    _widget_answer_result = None
    try:
        _widget_answer = payload.get("widget_answer")
        if _widget_answer is not None and prev_round:
            _wa_cfg = prev_round.get("widget_answer")
            if _wa_cfg:
                from engines.widget_validation_engine import validate_widget_answer
                _widget_answer_result = validate_widget_answer(_wa_cfg, _widget_answer)
                if _widget_answer_result and _widget_answer_result.get("correct"):
                    try:
                        user_payload = verify_token(get_token_from_request())
                        if user_payload:
                            player_profile.award_xp(user_payload["user_id"], 10, f"widget_{game_id}")
                    except Exception:
                        pass
    except Exception as _wa_err:
        logger.debug("Widget answer validation: %s", _wa_err)

    # Log game-over decisions at debug level
    if done:
        logger.info(f"[GAME-OVER] game={game_id} round_index={state_obj.round_index} total_rounds={len(game.get('rounds',[]))} log_len={len(r.get('log',[]))}")

    # ── Strip hidden resources from client state ─────────────────
    _client_state = state_to_dict(state_obj)
    if _sim_engine and game.get("simulation_config", {}).get("hidden_resources"):
        _client_state = _sim_engine.strip_hidden_from_state(_client_state)

    # ── Apply conditional option replacement on next round ──────
    if _sim_engine and next_round_data and next_round_data.get("choices"):
        try:
            _modified_choices = _sim_engine.get_modified_choices(state_obj, next_round_data)
            next_round_data["choices"] = _modified_choices
        except Exception:
            pass  # fall back to original choices

    # ── Annotate dynamic-cost choices for next round (Fix 3) ────
    if _sim_engine and next_round_data and next_round_data.get("choices"):
        try:
            annotate_choices_with_dynamic_cost(
                next_round_data["choices"],
                getattr(state_obj, "money", getattr(state_obj, "cash", 0)),
            )
        except Exception as _ann_err:
            logger.debug("annotate_choices_with_dynamic_cost failed: %s", _ann_err)

    # ── Resolve dynamic_intros[] against state (#7) ─────────────
    # Each intro: {"condition": {...}, "text": "..."} — pick first match.
    if _sim_engine and next_round_data and isinstance(next_round_data.get("dynamic_intros"), list):
        try:
            from engines.simulation_tick_engine import _check_condition as _intro_check
            _intro_ctx = state_to_dict(state_obj)
            _intro_ctx["_flags"] = getattr(state_obj, "flags", {}) or {}
            for _intro in next_round_data["dynamic_intros"]:
                if not isinstance(_intro, dict):
                    continue
                _cond = _intro.get("condition") or _intro.get("when") or {}
                if _intro_check(_cond, _intro_ctx):
                    _text = _intro.get("text") or _intro.get("intro_text")
                    if _text:
                        next_round_data["dynamic_intro"] = _text
                    break
        except Exception as _intro_err:
            logger.debug("dynamic_intro resolution failed: %s", _intro_err)

    # ── Build legibility payload (Summer Sports League UX) ──────
    _ux_legibility = None
    _ux_executive = None
    if _sim_engine:
        try:
            _ux_legibility = build_ux_payload(
                state_obj,
                game,
                _chosen,
                next_round_data,
                _pre_snapshot,
                state_obj.round_index,
            )
            # build_ux_payload mutates state_obj.ledger_history; persist it now
            # so the Money Diary's week list survives refreshes/resumes.
            # (The update_run at line ~3365 ran BEFORE this and would miss it.)
            try:
                update_run(run_id, r)
            except Exception as _save_err:
                logger.debug("persist ledger_history skipped: %s", _save_err)
        except Exception as _ux_err:
            logger.warning(f"UX enrichment error: {_ux_err}")
        # Executive subsystems — only emits non-null sub-payloads if game declares
        # the matching simulation_config blocks. Existing 96 SEL games unaffected.
        try:
            _ux_executive = _build_executive_payload(state_obj, game, next_round_data)
            # Multiplayer role slicing: if this run is part of a multiplayer match
            # and the player has a role, filter the payload to that role's view.
            try:
                mp_role = (request.args.get("mp_role") or
                           getattr(state_obj, "_mp_role", None))
                if mp_role:
                    from engines.executive_ux import slice_payload_for_role
                    _ux_executive = slice_payload_for_role(_ux_executive, mp_role)
            except Exception as _slice_err:
                logger.debug(f"mp role slicing skipped: {_slice_err}")
        except Exception as _exec_err:
            logger.warning(f"Executive UX error: {_exec_err}")

    response_data = {
        "outcome": serialized_outcome,
        "takeaway": takeaway,
        "next_round_index": _next_idx,
        "done": bool(done),
        # Frontend compatibility
        "game_over": bool(done),
        "state": _client_state,
        "round": next_round_data,
        "round_coins": round_coins,  # Per-choice coin reward/penalty
        # Progressive difficulty
        "round_mode": _round_mode,
        "hints_visible": _difficulty_phase.get("hints_visible", _round_mode == "tutorial") if _difficulty_phase else (_round_mode == "tutorial"),
        "difficulty_phase": _difficulty_phase,
        # Fix 4: Checkpoint quiz gate
        "checkpoint_required": _checkpoint_required,
        # AI Arena advanced features
        "crisis_event": crisis_event_data,
        "interdependency_effects": interdependency_effects if interdependency_effects else None,
        "news_items": news_items if news_items else None,
        "npc_relationship_changes": npc_relationship_changes if npc_relationship_changes else None,
        "ending": ending_data,
        "adaptive": adaptive_info if adaptive_info else None,
        "peer_benchmark": peer_benchmark,
        "early_game_over": _early_go,
        "coaching_needed": coaching_needed,
        "adapt_result": generic_adapt_result,
        "difficulty_hint": r.get("difficulty_hint"),
        # Simulation game data
        "tick_result": _sim_tick_result if _sim_tick_result else None,
        "simulation_dashboard": _sim_dashboard if _sim_dashboard else None,
        "ux_legibility": _ux_legibility,
        "ux_executive": _ux_executive,
        # Cause-effect visibility: previews of delayed effects this choice queued
        "delayed_previews": (
            list(getattr(state_obj, "_last_choice_delayed_previews", []) or [])
            if hasattr(state_obj, "_last_choice_delayed_previews") else None
        ),
        # Fix 1+2: Skill teaching
        "new_skills_introduced": _new_skills_introduced if _new_skills_introduced else None,
        "skill_explanation": _skill_explanation,
        # Fix 5: Challenge result
        "challenge_result": _challenge_result,
        # Fix 9: Widget answer result
        "widget_answer_result": _widget_answer_result,
    }

    # Inject exogenous market shock + org scaling friction (when configured on this game).
    # Engines are no-ops if simulation_config.market_shocks/org_scaling are absent.
    try:
        _sim_cfg = game.get("simulation_config") or {}
        if _sim_cfg.get("market_shocks", {}).get("enabled"):
            from engines.market_shock_engine import maybe_inject_shock as _mis
            _state_dict_for_shock = state_to_dict(state_obj)
            _shock = _mis(_state_dict_for_shock, int(state_obj.round_index), _sim_cfg)
            if _shock:
                # Persist shock log on run state object so it survives in the run record
                _fired = list(getattr(state_obj, "_market_shocks_fired", []) or [])
                _fired.append({"id": _shock.get("id"), "round": int(state_obj.round_index)})
                try:
                    setattr(state_obj, "_market_shocks_fired", _fired)
                except Exception:
                    pass
                response_data["market_shock"] = _shock
        if _sim_cfg.get("org_scaling"):
            from engines.org_scaling_engine import (
                compute_team_health as _cth,
                maybe_trigger_friction as _mtf,
            )
            _state_for_org = state_to_dict(state_obj)
            response_data["team_health"] = _cth(_state_for_org)
            _prev_hc = int(getattr(state_obj, "_prev_headcount", _state_for_org.get("headcount", 1)) or 1)
            _new_hc = int(_state_for_org.get("headcount", _prev_hc) or _prev_hc)
            if _new_hc != _prev_hc:
                _friction = _mtf(_state_for_org, _prev_hc, _new_hc)
                if _friction:
                    response_data["org_friction"] = _friction
                try:
                    setattr(state_obj, "_prev_headcount", _new_hc)
                except Exception:
                    pass
    except Exception as _shock_err:
        logger.debug("shock/org-scaling injection failed: %s", _shock_err)

    # Store for idempotency
    if _req_id:
        _seen_ids = r.get("_last_request_ids", [])
        _seen_ids.append(_req_id)
        r["_last_request_ids"] = _seen_ids[-10:]  # keep last 10
        r["_last_outcome"] = response_data
        update_run(run_id, r)

    return jsonify(response_data)


@app.route("/api/run/<run_id>/upload-drawing", methods=["POST"])
def upload_drawing(run_id):
    """Upload a drawing PNG from the canvas widget."""
    import base64

    state_obj = _RUNS.get(run_id)
    if not state_obj:
        return jsonify({"error": "Run not found"}), 404

    data = request.get_json(force=True)
    image_b64 = data.get("image_base64", "")
    round_id = (data.get("round_id") or "drawing").strip()[:100]

    if "," in image_b64:
        image_b64 = image_b64.split(",", 1)[1]

    try:
        image_bytes = base64.b64decode(image_b64)
    except Exception:
        return jsonify({"error": "Invalid base64 image"}), 400

    if not image_bytes[:8] == b'\x89PNG\r\n\x1a\n':
        return jsonify({"error": "Invalid PNG format"}), 400

    if len(image_bytes) > 2 * 1024 * 1024:
        return jsonify({"error": "Image too large (max 2MB)"}), 400

    draw_dir = os.path.join("game_sessions", run_id, "drawings")
    os.makedirs(draw_dir, exist_ok=True)
    image_path = os.path.join(draw_dir, f"{round_id}.png")

    with open(image_path, "wb") as f:
        f.write(image_bytes)

    logger.info(f"Drawing uploaded: run={run_id}, round={round_id}, size={len(image_bytes)} bytes")

    return jsonify({
        "drawing_id": round_id,
        "status": "uploaded",
        "size_bytes": len(image_bytes),
    })


# ───────── Reflection scoring channel (Task 12 — P0 plan) ─────────
@app.route("/api/run/<run_id>/reflection", methods=["POST"])
def api_submit_reflection(run_id):
    """Grade a player's reflection rationale and attach the signal to the run.

    Body: { round_id?: str, choice_id?: str, rationale: str, dimension_focus?: list[str] }
    Returns: { ok: True, score: int, dim_signals: dict[dim, int -10..+10],
               strengths: list[str], improvements: list[str] }
    """
    payload = request.get_json(silent=True) or {}
    rationale = (payload.get("rationale") or "").strip()
    if not rationale:
        return jsonify({"error": "rationale_required"}), 400

    try:
        run = get_run(run_id)
    except (KeyError, SessionNotFoundError, SessionExpiredError):
        return jsonify({"error": "run_not_found"}), 404
    if not run:
        return jsonify({"error": "run_not_found"}), 404

    # Determine focus dimensions: payload > game-level focus_dimensions > default pair
    focus = payload.get("dimension_focus")
    if not focus:
        focus = ((run.get("game") or {}).get("focus_dimensions")
                 or ["empathy", "strategic_thinking"])

    import llm  # late import to allow monkeypatch on llm.grade_reflection_text in tests
    graded = llm.grade_reflection_text(rationale, dimension_focus=focus)

    reflections = run.setdefault("reflections", [])
    reflections.append({
        "round_id": payload.get("round_id"),
        "choice_id": payload.get("choice_id"),
        "rationale": rationale[:2000],   # cap stored size
        "graded": graded,
        "ts": int(time.time()),
    })

    # Mirror dim_signals onto state so aggregate_behavioral_signals can pick them up
    state = run.get("state")
    if isinstance(state, dict):
        rs = state.setdefault("reflection_signals", {})
        for dim, delta in (graded.get("dim_signals") or {}).items():
            try:
                rs[dim] = max(-10, min(10, int(rs.get(dim, 0)) + int(delta)))
            except (TypeError, ValueError):
                continue

    try:
        update_run(run_id, run)
    except Exception as e:
        logger.warning("update_run failed in reflection endpoint: %s", e)

    return jsonify({
        "ok": True,
        "score": graded.get("score", 0),
        "dim_signals": graded.get("dim_signals", {}),
        "strengths": graded.get("strengths", []),
        "improvements": graded.get("improvements", []),
    })


# ───────── Inbox interrupt endpoint (timed event responses) ─────────
@app.post("/api/run/<run_id>/inbox")
@limiter.limit("60 per minute")
def run_inbox_event(run_id):
    """Apply an inbox event's choice without advancing the round.

    Body: { event_id: str, choice_id: str }
    Inbox events are declared per-round under `inbox_events` and their `choices`
    carry their own `exec_effects` (executive effects only — no calc/delta).
    """
    try:
        r = get_run(run_id)
    except (KeyError, SessionNotFoundError, SessionExpiredError):
        return jsonify({"error": "Session not found"}), 404
    body = request.get_json(silent=True) or {}
    event_id = str(body.get("event_id") or "").strip()[:200]
    choice_id = str(body.get("choice_id") or "").strip()[:200]
    if not event_id or not choice_id:
        return jsonify({"error": "event_id and choice_id are required"}), 400

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    game = get_effective_game(r, game)
    state_obj = r["state"]
    if not game.get("rounds"):
        return jsonify({"error": "Game type does not support inbox"}), 400
    if state_obj.round_index >= len(game["rounds"]):
        return jsonify({"error": "Game ended"}), 409

    current_round = game["rounds"][state_obj.round_index]
    events = current_round.get("inbox_events") or []
    event = next((e for e in events if e.get("id") == event_id), None)
    if not event:
        return jsonify({"error": "Inbox event not found in current round"}), 404
    choice = next((c for c in (event.get("choices") or []) if c.get("id") == choice_id), None)
    if not choice:
        return jsonify({"error": "Inbox choice not found"}), 404

    # Apply exec_effects only (no round advance, no calc/delta cascade)
    applied_actions = []
    try:
        ee = choice.get("exec_effects")
        if ee and isinstance(ee, dict):
            from core.exec_effects import apply_exec_effects
            applied_actions = apply_exec_effects(state_obj, game, ee)
    except Exception as _e:
        logger.warning(f"inbox exec_effects failed: {_e}")

    # Mark as answered
    seen = getattr(state_obj, "_inbox_seen", None)
    if not isinstance(seen, set):
        seen = set()
    seen.add(event_id)
    state_obj._inbox_seen = seen

    # Persist
    try:
        save_run(run_id, r)
    except Exception:
        pass

    # Return updated executive payload + applied actions
    try:
        from engines.executive_ux import build_executive_payload
        ux = build_executive_payload(state_obj, game, current_round)
    except Exception:
        ux = None

    return jsonify({
        "ok": True,
        "event_id": event_id,
        "choice_id": choice_id,
        "applied": applied_actions,
        "ux_executive": ux,
    })


# ───────── Fix 4: Checkpoint Quiz Endpoint ─────────
@app.post("/api/run/<run_id>/checkpoint")
@limiter.limit("30 per minute")
def run_checkpoint(run_id):
    """Score a checkpoint quiz and return pass/fail. Max 3 retries before auto-pass."""
    try:
        r = get_run(run_id)
    except (KeyError, SessionNotFoundError):
        return _api_error("Run not found", 404)
    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err

    body = request.get_json(silent=True) or {}
    after_round = body.get("after_round")
    answers = body.get("answers", {})  # {question_id: selected_choice_id}

    if after_round is None:
        return _api_error("after_round is required")

    # Find the checkpoint definition
    checkpoints = game.get("checkpoints", [])
    cp = None
    for c in checkpoints:
        if c.get("after_round") == after_round:
            cp = c
            break
    if not cp:
        return _api_error(f"No checkpoint defined after round {after_round}", 404)

    # Score the answers
    questions = cp.get("questions", [])
    total = len(questions)
    correct = 0
    results = []
    for q in questions:
        qid = q.get("id", "")
        submitted = answers.get(qid)
        correct_id = None
        for ch in q.get("choices", []):
            if ch.get("correct"):
                correct_id = ch.get("id")
                break
        is_correct = submitted == correct_id
        if is_correct:
            correct += 1
        results.append({
            "question_id": qid,
            "submitted": submitted,
            "correct_answer": correct_id,
            "is_correct": is_correct,
            "explanation": q.get("explanation", ""),
        })

    score = correct / total if total > 0 else 0
    passing_score = cp.get("passing_score", 0.6)
    passed = score >= passing_score

    # Track attempts
    cp_key = f"cp_{after_round}"
    if "checkpoint_results" not in r:
        r["checkpoint_results"] = {}
    prev = r["checkpoint_results"].get(cp_key, {})
    attempts = prev.get("attempts", 0) + 1

    # Auto-pass after 3 retries
    if not passed and attempts >= 3:
        passed = True

    r["checkpoint_results"][cp_key] = {
        "passed": passed,
        "score": round(score, 2),
        "attempts": attempts,
        "correct": correct,
        "total": total,
    }
    update_run(run_id, r)

    return jsonify({
        "passed": passed,
        "score": round(score, 2),
        "correct": correct,
        "total": total,
        "attempts": attempts,
        "auto_passed": not (score >= passing_score) and passed,
        "results": results,
        "review_summary": cp.get("review_summary", ""),
        "passing_score": passing_score,
    })


@app.get("/api/run/<run_id>/market")
def run_market_state(run_id):
    """Get current market state for competitive gameplay."""
    try:
        r = get_run(run_id)
    except KeyError as e:
        return jsonify({"error": "Resource not found"}), 404
    
    state_obj = r["state"]
    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    
    # Check if game has competitive mode
    if not hasattr(state_obj, 'competitor_states') or not state_obj.competitor_states:
        return jsonify({
            "competitive_mode": False,
            "message": "This game does not have competitive gameplay enabled"
        })
    
    # Calculate current market shares
    market_config = game.get("market_config")
    market_shares = process_market_dynamics(state_obj, state_obj.competitor_states, market_config)
    
    # Helper to get competitor attribute (works for both objects and dicts)
    def _comp_attr(comp, key, default=None):
        if isinstance(comp, dict):
            return comp.get(key, default)
        return getattr(comp, key, default)

    # Build competitor summaries
    competitors_summary = []
    for competitor in state_obj.competitor_states:
        comp_id = _comp_attr(competitor, 'competitor_id', '')
        comp_state = {
            "id": comp_id,
            "name": _comp_attr(competitor, 'name', ''),
            "personality_type": _comp_attr(competitor, 'personality_type', 'balanced'),
            "is_active": _comp_attr(competitor, 'is_active', True),
            "market_share": market_shares.get(comp_id, {}).get("market_share", 0),
            "resources": {}
        }

        # Add key resources if they exist
        for resource in ['cash_inr', 'profit', 'reputation', 'customer_satisfaction', 'cups_sold']:
            val = _comp_attr(competitor, resource, None)
            if val is not None:
                comp_state["resources"][resource] = val
        
        competitors_summary.append(comp_state)
    
    # Player market share
    player_market_share = market_shares.get("player", {}).get("market_share", 100)
    
    return jsonify({
        "competitive_mode": True,
        "player_market_share": player_market_share,
        "competitors": competitors_summary,
        "market_history": getattr(state_obj, 'market_history', []),
        "total_market_size": market_config.get("total_market_size", 100) if market_config else 100
    })


def _compute_psychological_summary(game, final_state):
    """Shared helper: compute psychological_focus_summary from game config and final state."""
    def _fmt(skill_id):
        return (skill_id or "").replace("_", " ").strip().title()

    def _safe(v, default=0):
        try:
            return int(v) if v is not None else default
        except Exception:
            return default

    try:
        framework_skills = (
            (game.get("psychological_framework") or {}).get("core_skills")
            if isinstance(game.get("psychological_framework"), dict)
            else []
        ) or []
        framework_map = {s.get("id"): s for s in framework_skills if isinstance(s, dict) and s.get("id")}

        focus_counts = {}
        for rnd in game.get("rounds", []) or []:
            if not isinstance(rnd, dict):
                continue
            pf = rnd.get("psychological_focus") or {}
            if not isinstance(pf, dict):
                continue
            for sid in pf.get("primary_skills") or []:
                if isinstance(sid, str) and sid:
                    focus_counts[sid] = focus_counts.get(sid, 0) + 1

        initial_state_cfg = game.get("initial_state") or {}
        psych_skill_ids = []
        if isinstance(initial_state_cfg, dict):
            for k, v in initial_state_cfg.items():
                if isinstance(v, dict) and v.get("category") == "psychological":
                    psych_skill_ids.append(k)
        if framework_map:
            psych_skill_ids.extend([k for k in framework_map if k not in psych_skill_ids])
        if focus_counts:
            psych_skill_ids.extend([k for k in focus_counts if k not in psych_skill_ids])

        skills = []
        for sid in psych_skill_ids:
            init_entry = initial_state_cfg.get(sid) if isinstance(initial_state_cfg, dict) else None
            init_val, init_icon, init_label = 0, None, None
            if isinstance(init_entry, dict):
                init_val = _safe(init_entry.get("value"), 0)
                init_icon = init_entry.get("icon")
                init_label = init_entry.get("label")
            elif isinstance(init_entry, (int, float)):
                init_val = _safe(init_entry, 0)
            final_val = _safe(final_state.get(sid), init_val)
            meta = framework_map.get(sid, {}) if framework_map else {}
            skills.append({
                "id": sid,
                "name": meta.get("name") or init_label or _fmt(sid),
                "icon": meta.get("icon") or init_icon or "",
                "focus_count": int(focus_counts.get(sid, 0)),
                "initial": init_val,
                "final": final_val,
                "change": final_val - init_val,
                "min": 0,
                "max": 100,
            })

        skills_sorted = sorted(skills, key=lambda s: (s.get("focus_count", 0), abs(s.get("change", 0))), reverse=True)
        display_skills = skills_sorted[:5]

        focused_pool = [s for s in skills if (s.get("focus_count") or 0) > 0]
        pool = focused_pool if focused_pool else skills
        psychological_score = None
        if pool:
            psychological_score = max(0, min(100, int(round(sum(_safe(s.get("final"), 0) for s in pool) / max(1, len(pool))))))

        if skills or focus_counts:
            return {"psychological_score": psychological_score, "skills": display_skills, "skills_total": len(skills)}
    except Exception as e:
        logger.warning(f"_compute_psychological_summary: {e}")
    return None


# --- Board Game Dimension Score Computation ---
def _compute_board_dimension_scores(board_choices, boss_wins=0, total_turns=0, final_resources=None):
    """Compute psychological dimension scores from board game play data."""
    final_resources = final_resources or {}

    # Count skill tag occurrences from all choices
    tag_counts = {}
    total_positive_deltas = 0
    total_negative_deltas = 0
    risk_choices = 0
    safe_choices = 0

    for choice in board_choices:
        for tag in choice.get("skill_tags", []):
            tag_counts[tag] = tag_counts.get(tag, 0) + 1

        delta = choice.get("delta", {})
        for v in delta.values():
            if isinstance(v, (int, float)):
                if v > 0:
                    total_positive_deltas += v
                else:
                    total_negative_deltas += abs(v)

        # Classify risk: choices with both large positive and negative deltas
        neg = sum(1 for v in delta.values() if isinstance(v, (int, float)) and v < -5)
        pos = sum(1 for v in delta.values() if isinstance(v, (int, float)) and v > 5)
        if neg > 0 and pos > 0:
            risk_choices += 1
        elif neg == 0 and pos > 0:
            safe_choices += 1

    num_choices = max(1, len(board_choices))
    boss_correct = sum(1 for c in board_choices if c.get("choice_type") == "boss" and c.get("correct") is True)
    boss_total = sum(1 for c in board_choices if c.get("choice_type") == "boss")
    boss_accuracy = boss_correct / max(1, boss_total)

    # Compute each dimension (0-100 scale)
    strategic = min(100, 30 + tag_counts.get("strategic_thinking", 0) * 8 + int(boss_accuracy * 25) + min(15, num_choices * 2))
    risk = min(100, 30 + risk_choices * 10 + tag_counts.get("risk_tolerance", 0) * 8 + min(20, int(total_negative_deltas / max(1, total_positive_deltas + total_negative_deltas) * 30)))
    delayed = min(100, 30 + safe_choices * 6 + tag_counts.get("delayed_gratification", 0) * 8 + min(20, total_turns * 2))
    adaptability = min(100, 30 + len(set(c.get("choice_type") for c in board_choices)) * 10 + tag_counts.get("adaptability", 0) * 8 + min(20, num_choices * 3))
    resilience_val = min(100, 30 + boss_wins * 8 + tag_counts.get("resilience", 0) * 8 + min(20, total_turns * 2))

    # Empathy: morale/team-related keys in deltas
    morale_keys = {"team_morale", "crew_morale", "morale", "team_trust", "relationships", "customer_love"}
    morale_choices = sum(1 for c in board_choices if any(k in (c.get("delta") or {}) for k in morale_keys))
    empathy_val = min(100, 30 + tag_counts.get("empathy", 0) * 10 + min(30, morale_choices * 8))

    scores = {
        "strategic_thinking": strategic,
        "risk_tolerance": risk,
        "delayed_gratification": delayed,
        "adaptability": adaptability,
        "resilience": resilience_val,
        "empathy": empathy_val,
    }
    ethics_count = tag_counts.get("ethical_reasoning", 0)
    if ethics_count > 0:
        scores["ethical_reasoning"] = min(100, 30 + ethics_count * 9)
    creativity_count = tag_counts.get("creativity", 0)
    if creativity_count > 0:
        scores["creativity"] = min(100, 30 + creativity_count * 9)
    return scores


