def _compute_mastery_tiers(dimension_scores: dict) -> dict:
    """Compute mastery tier label and description for each scored dimension."""
    result = {}
    for dim, score in dimension_scores.items():
        for threshold, tier_name, tier_key in _MASTERY_TIERS:
            if score >= threshold:
                label = _DIM_ROLE_LABELS.get(dim, {}).get(tier_key, f"{tier_name} {dim.replace('_',' ').title()}")
                result[dim] = {
                    "score": score,
                    "tier": tier_name,
                    "tier_key": tier_key,
                    "label": label,
                    "description": _MASTERY_DESCRIPTIONS[tier_key],
                }
                break
    return result


