def _get_transfer_activity(dimension_scores: dict) -> dict:
    """Return a real-world transfer activity based on the top scored dimension."""
    import random
    if not dimension_scores:
        return {}
    top_dim = max(dimension_scores, key=lambda d: dimension_scores[d])
    activities = _TRANSFER_ACTIVITIES.get(top_dim, [])
    if not activities:
        return {}
    return {
        "dimension": top_dim,
        "activity": random.choice(activities),
        "dimension_label": top_dim.replace("_", " ").title(),
        "prompt": "Try this in real life this week:"
    }


def _compute_ai_arena_dimension_scores(log_entries, initial_state=None, game=None):
    """Compute dimension scores from AI Arena gameplay log entries.

    Analyzes resource deltas across all choices to infer which soft-skill
    dimensions the player exercised. Also factors in choice variety, crisis
    handling, and overall resource management.
    """
    initial_state = initial_state or {}
    game = game or {}
    from engines.dimension_utils import infer_skill_tags_from_deltas

    # Accumulate per-dimension evidence
    dim_points = {d: 0 for d in ("strategic_thinking", "risk_tolerance", "delayed_gratification",
                                  "adaptability", "resilience", "empathy")}
    tag_counts = {d: 0 for d in dim_points}
    total_positive = 0
    total_negative = 0
    risk_choices = 0
    safe_choices = 0
    unique_round_ids = set()
    crisis_handled = 0

    for entry in log_entries:
        state_before = entry.get("state_before", entry.get("state_before_events", {}))
        state_after = entry.get("state_after_events", entry.get("state_after", {}))
        choice_label = entry.get("choice", {}).get("label", "") if isinstance(entry.get("choice"), dict) else ""
        round_id = entry.get("round_id", "")
        if round_id:
            unique_round_ids.add(round_id)

        # Compute deltas from state changes
        deltas = {}
        for k in state_after:
            if k in ("round_index", "round_title", "game_over", "game_id"):
                continue
            av = state_after[k]
            bv = state_before.get(k, 0)
            if isinstance(av, dict):
                av = av.get("value", 0)
            if isinstance(bv, dict):
                bv = bv.get("value", 0)
            if isinstance(av, (int, float)) and isinstance(bv, (int, float)):
                d = av - bv
                if d != 0:
                    deltas[k] = d

        # Map resource deltas to dimensions
        for resource_key, delta_val in deltas.items():
            resource_lower = resource_key.lower()
            mapped_dim = None
            for rk, dim in _AI_ARENA_RESOURCE_DIMENSION_MAP.items():
                if rk in resource_lower:
                    mapped_dim = dim
                    break
            if mapped_dim:
                dim_points[mapped_dim] += abs(delta_val) * 0.5
            if isinstance(delta_val, (int, float)):
                if delta_val > 0:
                    total_positive += delta_val
                else:
                    total_negative += abs(delta_val)

        # Risk analysis
        neg = sum(1 for v in deltas.values() if isinstance(v, (int, float)) and v < -5)
        pos = sum(1 for v in deltas.values() if isinstance(v, (int, float)) and v > 5)
        if neg > 0 and pos > 0:
            risk_choices += 1
        elif neg == 0 and pos > 0:
            safe_choices += 1

        # Infer skill tags from the choice
        choice_delta = entry.get("choice", {}).get("delta", {}) if isinstance(entry.get("choice"), dict) else {}
        if not choice_delta:
            choice_delta = deltas
        tags = infer_skill_tags_from_deltas(choice_delta, choice_label)
        for t in tags:
            if t in tag_counts:
                tag_counts[t] += 1

        # Check for crisis entries
        for ev in entry.get("events", []):
            if isinstance(ev, str) and "crisis" in ev.lower():
                crisis_handled += 1

    num_choices = max(1, len(log_entries))
    num_unique_rounds = len(unique_round_ids)

    # Compute final 0-100 scores
    strategic = min(100, 30 + int(dim_points["strategic_thinking"]) + tag_counts.get("strategic_thinking", 0) * 6 + min(15, num_choices * 2))
    risk = min(100, 30 + risk_choices * 8 + tag_counts.get("risk_tolerance", 0) * 6 + int(dim_points["risk_tolerance"]))
    delayed = min(100, 30 + safe_choices * 5 + tag_counts.get("delayed_gratification", 0) * 6 + int(dim_points["delayed_gratification"]) + min(10, num_choices))
    adaptability_val = min(100, 30 + min(20, num_unique_rounds * 3) + tag_counts.get("adaptability", 0) * 6 + int(dim_points["adaptability"]))
    resilience_val = min(100, 30 + crisis_handled * 8 + tag_counts.get("resilience", 0) * 6 + int(dim_points["resilience"]) + min(15, num_choices * 2))
    empathy_val = min(100, 30 + tag_counts.get("empathy", 0) * 8 + int(dim_points["empathy"]))

    scores = {
        "strategic_thinking": strategic,
        "risk_tolerance": risk,
        "delayed_gratification": delayed,
        "adaptability": adaptability_val,
        "resilience": resilience_val,
        "empathy": empathy_val,
    }
    ethics_count = tag_counts.get("ethical_reasoning", 0)
    if ethics_count > 0:
        scores["ethical_reasoning"] = min(100, 30 + ethics_count * 9)
    creativity_count = tag_counts.get("creativity", 0)
    if creativity_count > 0:
        scores["creativity"] = min(100, 30 + creativity_count * 9)
    return scores


# --- Negotiation / Debate Dimension Score Computation ---
def _compute_negotiation_dimension_scores(conversation_history, analysis_history, final_state, game_type="negotiation"):
    """Compute dimension scores from negotiation/debate gameplay."""
    num_turns = len([m for m in conversation_history if m.get("speaker") == "student"])

    # Extract scores from analysis history
    empathy_impacts = []
    assertiveness_impacts = []
    relationship_impacts = []

    for a in (analysis_history or []):
        if isinstance(a, dict):
            ei = a.get("empathy_impact", 0)
            ai_val = a.get("assertiveness_impact", 0)
            ri = a.get("relationship_impact", 0)
            empathy_impacts.append(ei.get("value", 0) if isinstance(ei, dict) else (ei if isinstance(ei, (int, float)) else 0))
            assertiveness_impacts.append(ai_val.get("value", 0) if isinstance(ai_val, dict) else (ai_val if isinstance(ai_val, (int, float)) else 0))
            relationship_impacts.append(ri.get("value", 0) if isinstance(ri, dict) else (ri if isinstance(ri, (int, float)) else 0))

    rapport = final_state.get("rapport_score", 50)
    assertiveness = final_state.get("assertiveness_score", 50)
    understanding = final_state.get("understanding_score", 50)

    # Strategic thinking: based on assertiveness + number of turns used effectively
    strategic = min(100, 30 + int(assertiveness * 0.4) + min(20, num_turns * 3))
    # Risk tolerance: high assertiveness = willingness to push
    risk = min(100, 25 + int(assertiveness * 0.5) + sum(1 for a in assertiveness_impacts if a > 3) * 5)
    # Delayed gratification: patience across turns
    delayed = min(100, 30 + min(30, num_turns * 4) + int(rapport * 0.2))
    # Adaptability: variation in approach (different impact types)
    adapt = min(100, 30 + min(25, len(set(round(e) for e in empathy_impacts if e != 0)) * 8) + min(20, num_turns * 3))
    # Resilience: maintained scores despite negative impacts
    neg_impacts = sum(1 for a in relationship_impacts if a < 0)
    resilience_val = min(100, 40 + max(0, num_turns - neg_impacts) * 5 + int(rapport * 0.2))
    # Empathy: relationship + understanding scores
    empathy_val = min(100, 20 + int(rapport * 0.3) + int(understanding * 0.3) + sum(1 for e in empathy_impacts if e > 0) * 5)

    scores = {
        "strategic_thinking": strategic,
        "risk_tolerance": risk,
        "delayed_gratification": delayed,
        "adaptability": adapt,
        "resilience": resilience_val,
        "empathy": empathy_val,
    }
    # Ethics bonus for ethics-focused negotiation/debate game types
    if game_type in ("ethics_debate", "ethical_dilemma"):
        scores["ethical_reasoning"] = min(100, 35 + int(rapport * 0.25) + num_turns * 3)
    return scores


