@app.route("/api/run/<run_id>/card-board/roll", methods=["POST"])
@require_auth
def card_board_roll(run_id):
    """Monopoly mode: roll dice + move player + return tile event (with DALL-E image)."""
    try:
        try:
            run_data = storage.get_run(run_id)
        except Exception:
            return jsonify({"error": "Run not found"}), 404
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        state = _cb_load_state(run_id)
        if not state:
            return jsonify({"error": "Game not initialised"}), 400
        if not game.get("monopoly_mode"):
            return jsonify({"error": "This game does not use monopoly mode"}), 400
        roll, state_after_roll = cb_roll_dice(state)
        new_state, tile_event = cb_move_player(state_after_roll, game, roll)
        # Generate DALL-E image for tile event if not cached
        image_url = None
        if tile_event:
            tile_id = tile_event.get("tile_id")
            if tile_id and new_state.get("image_cache", {}).get(tile_id):
                image_url = new_state["image_cache"][tile_id]
            else:
                prompt = tile_event.get("image_prompt", "")
                if prompt:
                    try:
                        from llm import generate_image
                        image_url = generate_image(prompt)
                        if image_url and tile_id:
                            new_state.setdefault("image_cache", {})[tile_id] = image_url
                    except Exception as _e:
                        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        _cb_save_state(run_id, new_state)
        return jsonify({
            "state": new_state,
            "roll": roll,
            "tile_event": tile_event,
            "image_url": image_url,
        }), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/run/<run_id>/card-board/complete", methods=["POST"])
@require_auth
def card_board_complete(run_id):
    """Finalise a card board game: compute dimension scores, award XP, generate report."""
    try:
        try:
            run_data = storage.get_run(run_id)
        except Exception:
            return jsonify({"error": "Run not found"}), 404
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        state = _cb_load_state(run_id)
        if not state:
            return jsonify({"error": "Game not initialised"}), 400
        skill_dims = cb_compute_skill_dimensions(state, game)
        skill_report = {}
        debrief = {}
        new_badges = []
        xp_earned = 0
        try:
            token = get_token_from_request()
            user_payload = verify_token(token) if token else None
            if user_payload:
                user_id = user_payload["user_id"]
                xp_earned = 80
                award_result = player_profile.award_xp(
                    user_id, xp_earned, "card_board_complete",
                    game_type="card_board",
                    game_title=game.get("title", "Card Board"),
                    dimension_scores=skill_dims,
                )
                new_badges = award_result.get("new_badges", [])
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        # LLM skill report
        try:
            if llm_enabled():
                from llm import generate_skill_report, generate_end_debrief
                choices_made = [
                    e.get("skill_tag", "") for e in state.get("log", [])
                    if e.get("actor") == "player" and e.get("skill_tag")
                ]
                skill_report = generate_skill_report(
                    [{"label": k, "value": v} for k, v in skill_dims.items()],
                    "card_board", choices_made,
                    game.get("title", "Card Board"),
                )
                debrief = generate_end_debrief({
                    "title": game.get("title", "Card Board"),
                    "game_type": "card_board",
                    "won": state.get("winner") == "player",
                    "log": state.get("log", [])[-5:],
                })
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        # Scoring warning
        scoring_warning = None if skill_dims else "No dimension scores recorded."
        # Career suggestions
        career_suggestions = []
        if skill_dims and len([v for v in skill_dims.values() if v > 0]) >= 3:
            try:
                _cf_path = os.path.join(os.path.dirname(__file__), "data", "career_mapping.json")
                with open(_cf_path) as _cf:
                    _careers = json.load(_cf)
                _pd = {k: v / 100.0 for k, v in skill_dims.items() if isinstance(v, (int, float))}
                _cr = []
                for _c in _careers:
                    _req = _c.get("required_dimensions", {})
                    if not _req:
                        continue
                    _tw = sum(_req.values())
                    _ss = sum(min(_pd.get(d, 0) / max(rv, 0.01), 1.0) * rv for d, rv in _req.items())
                    _gaps = [d for d, rv in _req.items() if _pd.get(d, 0) < rv * 0.7]
                    _cr.append({"career": _c["career"], "match_score": round(_ss / max(_tw, 0.01), 3), "gap_dims": _gaps[:2]})
                _cr.sort(key=lambda x: x["match_score"], reverse=True)
                career_suggestions = _cr[:3]
            except Exception as _e:
                logger.debug("Career suggestions failed: %s", _e)
        # Cognitive profile
        _bloom = _BLOOM_MAP.get("card_board", "apply")
        cognitive_profile = {"bloom_level": _bloom, "thinking_style_label": _BLOOM_STYLE_LABELS.get(_bloom, "")}
        return jsonify({
            "skill_dimensions": skill_dims,
            "skill_report": skill_report,
            "debrief": debrief,
            "new_badges": new_badges,
            "xp_earned": xp_earned,
            "state": state,
            "scoring_warning": scoring_warning,
            "career_suggestions": career_suggestions,
            "cognitive_profile": cognitive_profile,
        }), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


