def _tc_load_state(run_id):
    try:
        run_data = storage.get_run(run_id)
        return run_data.get("trump_card_state")
    except Exception:
        return None

def _tc_save_state(run_id, state):
    try:
        run_data = storage.get_run(run_id)
    except Exception:
        return
    run_data["trump_card_state"] = state
    storage.update_run(run_id, run_data)


