# --- Historical Report Storage ---
REPORTS_DIR = os.path.join(os.path.dirname(__file__), "game_sessions", "reports")
os.makedirs(REPORTS_DIR, exist_ok=True)

def _store_historical_report(run_id, run_data, report_core, narrative, wallet_reward):
    """Store a copy of the final report for historical access (persists beyond session expiry)."""
    try:
        report_path = os.path.join(REPORTS_DIR, f"{run_id}.json")
        if os.path.exists(report_path):
            return  # Already stored
        token = get_token_from_request()
        user_payload = verify_token(token) if token else None
        stored = {
            "run_id": run_id,
            "user_id": user_payload["user_id"] if user_payload else None,
            "game_id": run_data.get("game_id", ""),
            "game_title": report_core.get("game", {}).get("title", ""),
            "game_theme": report_core.get("game", {}).get("theme", ""),
            "final_score": report_core.get("final_score"),
            "mento_score": report_core.get("mento_score"),
            "badges": report_core.get("badges", []),
            "psychological_focus_summary": report_core.get("psychological_focus_summary"),
            "nep_tags_seen": report_core.get("nep_tags_seen", []),
            "narrative": narrative,
            "wallet_reward": wallet_reward,
            "final_state": report_core.get("final_state"),
            "round_history": report_core.get("round_history", []),
            "completed_at": run_data.get("last_accessed", ""),
        }
        with open(report_path, "w") as f:
            json.dump(stored, f, indent=2, default=str)
    except Exception as e:
        logger.warning(f"Failed to store historical report for {run_id}: {e}")
def _load_historical_report(run_id):
    """Load a stored report by run_id."""
    report_path = os.path.join(REPORTS_DIR, f"{run_id}.json")
    if not os.path.exists(report_path):
        return None
    with open(report_path, "r") as f:
        return json.load(f)


@app.get("/api/run/<run_id>/report")
def run_report(run_id):
    """Generate final report for completed game."""
    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        # Try loading persisted report (survives server restart)
        _report_file = os.path.join(REPORTS_DIR, f"{run_id}.json")
        if os.path.exists(_report_file):
            try:
                with open(_report_file, "r") as _rf:
                    return jsonify(json.load(_rf))
            except Exception as _load_err:
                logger.debug("Failed to load persisted report: %s", _load_err)
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    game = get_effective_game(r, game)

    # Feature 5: Remove from active sessions on game complete
    try:
        _act_rpt_file = os.path.join(os.path.dirname(__file__), "data", "active_sessions.json")
        try:
            with open(_act_rpt_file) as _arf:
                _act_rpt = json.load(_arf)
        except (FileNotFoundError, json.JSONDecodeError):
            _act_rpt = {}
        if run_id in _act_rpt:
            del _act_rpt[run_id]
            with open(_act_rpt_file, "w") as _arf:
                json.dump(_act_rpt, _arf)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    st_obj = r["state"]
    final_state = state_to_dict(st_obj)

    # Psychological focus summary (deterministic)
    psychological_focus_summary = _compute_psychological_summary(game, final_state)

    badges = compute_badges(final_state)

    # Auto-finalize chess games if not already done
    if game.get("game_type") == "chess_strategy" and not r["log"] and r.get("chess_state"):
        try:
            from engines.chess_strategy_engine import ChessStrategyEngine
            config = game.get("chess_config", {})
            engine = ChessStrategyEngine(config)
            summary = engine.get_game_summary(r["chess_state"])
            for sid, sv in summary["dimension_scores"].items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = summary["dimension_scores"]
            final_state = state_to_dict(st_obj)
            r["log"].append({
                "round_id": "chess_game", "round_title": "Founder's Gambit",
                "choice": {"id": "chess_result", "label": f"{'Victory' if summary['winner']=='player' else 'Defeat'}"},
                "nep_tags": game.get("nep_tags", []),
                "events": [f"Captured {summary['pieces_captured']} pieces", f"Final valuation: ${summary['final_valuation']:,}"],
                "state_before": {"valuation": 1000000}, "state_after_events": {"valuation": summary["final_valuation"]},
            })
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize chess game failed: {e}")
    # Auto-finalize GO games
    if game.get("game_type") == "go_territory" and not r["log"] and r.get("go_state"):
        try:
            from engines.go_territory_engine import GoTerritoryEngine
            config = game.get("go_config", {})
            engine = GoTerritoryEngine(config)
            summary = engine.get_game_summary(r["go_state"])
            for sid, sv in summary.get("dimension_scores", {}).items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = summary.get("dimension_scores", {})
            final_state = state_to_dict(st_obj)
            r["log"].append({"round_id": "go_game", "round_title": game.get("title", "Go"), "choice": {"id": "go_result", "label": f"{'Victory' if summary.get('winner')=='player' else 'Defeat'}"}, "events": [], "state_before": {}, "state_after_events": {}})
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize go game failed: {e}")
    # Auto-finalize Reversi games
    if game.get("game_type") == "reversi" and not r["log"] and r.get("reversi_state"):
        try:
            from engines.reversi_engine import ReversiEngine
            config = game.get("reversi_config", {})
            engine = ReversiEngine(config)
            summary = engine.get_game_summary(r["reversi_state"])
            for sid, sv in summary.get("dimension_scores", {}).items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = summary.get("dimension_scores", {})
            final_state = state_to_dict(st_obj)
            r["log"].append({"round_id": "reversi_game", "round_title": game.get("title", "Reversi"), "choice": {"id": "reversi_result", "label": f"{'Victory' if summary.get('winner')=='player' else 'Defeat'}"}, "events": [], "state_before": {}, "state_after_events": {}})
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize reversi game failed: {e}")
    # Auto-finalize Tower Defense games
    if game.get("game_type") == "tower_defense" and not r["log"] and r.get("td_state"):
        try:
            from engines.tower_defense_engine import TowerDefenseEngine
            config = game.get("td_config", {})
            engine = TowerDefenseEngine(config)
            summary = engine.get_game_summary(r["td_state"])
            for sid, sv in summary.get("dimension_scores", {}).items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = summary.get("dimension_scores", {})
            final_state = state_to_dict(st_obj)
            r["log"].append({"round_id": "td_game", "round_title": game.get("title", "Tower Defense"), "choice": {"id": "td_result", "label": f"{'Victory' if summary.get('winner')=='player' else 'Defeat'}"}, "events": [], "state_before": {}, "state_after_events": {}})
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize tower defense game failed: {e}")
    # Auto-finalize Puzzle Match games
    if game.get("game_type") == "puzzle_match" and not r["log"] and r.get("puzzle_state"):
        try:
            from engines.puzzle_match_engine import PuzzleMatchEngine
            config = game.get("puzzle_config", {})
            engine = PuzzleMatchEngine(config)
            summary = engine.get_game_summary(r["puzzle_state"])
            for sid, sv in summary.get("dimension_scores", {}).items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = summary.get("dimension_scores", {})
            final_state = state_to_dict(st_obj)
            r["log"].append({"round_id": "puzzle_game", "round_title": game.get("title", "Puzzle"), "choice": {"id": "puzzle_result", "label": f"Score: {summary.get('score', 0)}"}, "events": [], "state_before": {}, "state_after_events": {}})
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize puzzle game failed: {e}")
    # Auto-finalize Strategy Grid games
    if game.get("game_type") == "strategy_grid" and not r["log"] and r.get("sg_state"):
        try:
            from engines.strategy_grid_engine import StrategyGridEngine
            config = game.get("strategy_grid_config", {})
            engine = StrategyGridEngine(config)
            summary = engine.get_game_summary(r["sg_state"])
            for sid, sv in summary.get("dimension_scores", {}).items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = summary.get("dimension_scores", {})
            final_state = state_to_dict(st_obj)
            r["log"].append({"round_id": "sg_game", "round_title": game.get("title", "Strategy Grid"), "choice": {"id": "sg_result", "label": f"{'Victory' if summary.get('winner')=='player' else 'Defeat'}"}, "events": [f"Captured {summary.get('player_captures', 0)} pieces", f"Turns: {summary.get('turns_played', 0)}"], "state_before": {}, "state_after_events": {}})
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize strategy grid game failed: {e}")
    # Auto-finalize Board games
    if game.get("game_type") == "board" and r.get("board_state"):
        try:
            board_choices = r.get("board_choices", [])
            board_state = r.get("board_state", {})
            dimension_scores = _compute_board_dimension_scores(
                board_choices,
                board_state.get("boss_wins", 0),
                board_state.get("total_turns", 0),
                board_state.get("final_resources", {}),
            )
            for sid, sv in dimension_scores.items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = dimension_scores
            final_state = state_to_dict(st_obj)
            learned_count = len(board_state.get("learned_terms", []))
            if not r["log"]:
                r["log"].append({
                    "round_id": "board_game",
                    "round_title": game.get("title", "Board Game"),
                    "choice": {"id": "board_result", "label": f"Completed in {board_state.get('total_turns', 0)} turns"},
                    "events": [f"Boss wins: {board_state.get('boss_wins', 0)}", f"Terms learned: {learned_count}"],
                    "state_before": {},
                    "state_after_events": {},
                })
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize board game failed: {e}")
    # Auto-finalize AI Arena games
    if game.get("game_type") == "ai_arena" and r["log"]:
        try:
            dimension_scores = _compute_ai_arena_dimension_scores(
                r["log"],
                initial_state=game.get("initial_state", {}),
                game=game,
            )
            for sid, sv in dimension_scores.items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = dimension_scores
            final_state = state_to_dict(st_obj)
            r_count = len(r["log"])
            logger.info(f"Auto-finalized AI Arena: {r_count} rounds → dimension_scores={dimension_scores}")
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize AI Arena game failed: {e}")
    # Auto-finalize Negotiation games
    if (r.get("game_id") == "negotiation" or game.get("game_type") == "negotiation") and r.get("conversation_history"):
        try:
            dimension_scores = _compute_negotiation_dimension_scores(
                r.get("conversation_history", []),
                r.get("analysis_history", []),
                state_to_dict(st_obj),
                game_type="negotiation",
            )
            for sid, sv in dimension_scores.items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = dimension_scores
            final_state = state_to_dict(st_obj)
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize negotiation game failed: {e}")
    # Auto-finalize Debate games
    if (r.get("game_id") == "debate" or game.get("game_type") == "debate") and r.get("conversation_history"):
        try:
            dimension_scores = _compute_negotiation_dimension_scores(
                r.get("conversation_history", []),
                r.get("round_scores", []),
                state_to_dict(st_obj),
                game_type="debate",
            )
            for sid, sv in dimension_scores.items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = dimension_scores
            final_state = state_to_dict(st_obj)
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize debate game failed: {e}")
    # Auto-finalize Card games
    if game.get("game_type") == "card":
        try:
            from engines.card_engine import CardEngine
            cfg = game.get("card_system", game.get("card_config", {}))
            if cfg:
                card_engine = CardEngine(cfg)
                dimension_scores = card_engine.compute_dimension_scores(st_obj)
                for sid, sv in dimension_scores.items():
                    setattr(st_obj, sid, sv)
                st_obj.dimension_scores = dimension_scores
                final_state = state_to_dict(st_obj)
                if not r["log"]:
                    r["log"].append({
                        "round_id": "card_game",
                        "round_title": game.get("title", "Card Battle"),
                        "choice": {"id": "card_result", "label": "Completed"},
                        "events": [],
                        "state_before": {},
                        "state_after_events": {},
                    })
                storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize card game failed: {e}")
    # Auto-finalize Minigame games
    if game.get("game_type") == "minigame":
        try:
            from minigame_engine import MiniGameEngine
            mg_session = r.get("minigame_state", {})
            if mg_session:
                mg_config = game.get("minigame_config", game.get("minigame", {}))
                mg_engine = MiniGameEngine(mg_config)
                dimension_scores = mg_engine.compute_dimension_scores(mg_session)
                for sid, sv in dimension_scores.items():
                    setattr(st_obj, sid, sv)
                st_obj.dimension_scores = dimension_scores
                final_state = state_to_dict(st_obj)
                if not r["log"]:
                    r["log"].append({
                        "round_id": "minigame",
                        "round_title": game.get("title", "Minigame"),
                        "choice": {"id": "minigame_result", "label": f"Score: {mg_session.get('score', 0)}"},
                        "events": [],
                        "state_before": {},
                        "state_after_events": {},
                    })
                storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize minigame failed: {e}")
    # Auto-finalize Rounds games (A4: wire _compute_rounds_dimension_scores)
    if game.get("game_type") == "rounds" and r["log"]:
        try:
            log_choices = [
                {
                    "choice_id": x.get("choice", {}).get("id"),
                    "skill_tags": x.get("choice", {}).get("skill_tags", []),
                    "risk_level": x.get("choice", {}).get("risk_level", "medium"),
                    "choice_type": x.get("choice", {}).get("choice_type", ""),
                }
                for x in r["log"] if x.get("choice")
            ]
            _rounds_state = dict(final_state)
            if not _rounds_state.get("choice_history"):
                _rounds_state["choice_history"] = log_choices
            if not _rounds_state.get("rounds_completed"):
                _rounds_state["rounds_completed"] = [x.get("round_id") for x in r["log"] if x.get("round_id")]
            _rounds_state["total_rounds"] = max(len(game.get("rounds", [])), len(r["log"]))
            dimension_scores = _canonical_scores(
                _compute_rounds_dimension_scores(_rounds_state, game=game),
                score_version=1,
            )
            for sid, sv in dimension_scores.items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = dimension_scores
            final_state = state_to_dict(st_obj)
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize rounds game failed: {e}")
    # Auto-finalize Story Branching games (A4: use _compute_story_dimension_scores)
    if game.get("game_type") == "story_branching" and r["log"]:
        try:
            ending_type = r.get("ending_type") or final_state.get("ending_type", "standard")
            dimension_scores = _canonical_scores(
                _compute_story_dimension_scores(final_state, ending_type),
                score_version=1,
            )
            for sid, sv in dimension_scores.items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = dimension_scores
            final_state = state_to_dict(st_obj)
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize story branching game failed: {e}")
    # Auto-finalize Simulation games (use same rounds scoring + simulation state)
    if game.get("game_type") == "simulation" and r["log"]:
        try:
            log_choices = [
                {
                    "choice_id": x.get("choice", {}).get("id"),
                    "skill_tags": x.get("choice", {}).get("skill_tags", []),
                    "risk_level": x.get("choice", {}).get("risk_level", "medium"),
                    "choice_type": x.get("choice", {}).get("choice_type", ""),
                }
                for x in r["log"] if x.get("choice")
            ]
            _sim_state = dict(final_state)
            if not _sim_state.get("choice_history"):
                _sim_state["choice_history"] = log_choices
            if not _sim_state.get("rounds_completed"):
                _sim_state["rounds_completed"] = [x.get("round_id") for x in r["log"] if x.get("round_id")]
            _sim_state["total_rounds"] = max(len(game.get("rounds", [])), len(r["log"]))
            dimension_scores = _canonical_scores(
                _compute_rounds_dimension_scores(_sim_state, game=game),
                score_version=1,
            )
            for sid, sv in dimension_scores.items():
                setattr(st_obj, sid, sv)
            st_obj.dimension_scores = dimension_scores
            final_state = state_to_dict(st_obj)
            storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize simulation game failed: {e}")
    # Auto-finalize Strategy (city building) games
    if game.get("game_type") == "strategy":
        try:
            from engines.city_building_engine import CityBuildingEngine
            cfg = game.get("strategy_config", game.get("city_building", {}))
            if cfg:
                city_engine = CityBuildingEngine(cfg)
                dimension_scores = city_engine.compute_dimension_scores(st_obj)
                for sid, sv in dimension_scores.items():
                    setattr(st_obj, sid, sv)
                st_obj.dimension_scores = dimension_scores
                final_state = state_to_dict(st_obj)
                if not r["log"]:
                    r["log"].append({
                        "round_id": "strategy_game",
                        "round_title": game.get("title", "Strategy"),
                        "choice": {"id": "strategy_result", "label": "Completed"},
                        "events": [],
                        "state_before": {},
                        "state_after_events": {},
                    })
                storage.update_run(run_id, r)
        except Exception as e:
            logger.warning(f"Auto-finalize strategy game failed: {e}")
    # Collect deterministic evidence
    nep_tags_seen = sorted({t for x in r["log"] for t in x.get("nep_tags", [])})
    choices = [{"round_id": x.get("round_id", x.get("scene_id", "")), "choice": x.get("choice", {}).get("label", x.get("label", ""))} for x in r["log"]]
    events = [
        {"round_id": x.get("round_id", x.get("scene_id", "")), "events": x.get("events", [])}
        for x in r["log"]
    ]

    # Collect reflections from all rounds
    reflections = [
        {"round_id": x.get("round_id", x.get("scene_id", "")), "reflection": x.get("reflection", "")}
        for x in r["log"] if x.get("reflection")
    ]
    
    # Build detailed round history with videos and stats
    round_history = []
    for idx, log_entry in enumerate(r["log"]):
        # Find matching round definition from game
        round_def = next((rnd for rnd in game.get("rounds", []) if rnd.get("id") == log_entry.get("round_id")), None)
        
        # Get state changes
        state_before = log_entry.get("state_before", {})
        state_after = log_entry.get("state_after_events", {})
        
        # Calculate key stat changes
        stat_changes = {
            "money": {
                "before": state_before.get("money_inr", state_before.get("cash_inr", 0)),
                "after": state_after.get("money_inr", state_after.get("cash_inr", 0)),
                "change": state_after.get("money_inr", state_after.get("cash_inr", 0)) - state_before.get("money_inr", state_before.get("cash_inr", 0))
            },
            "reputation": {
                "before": state_before.get("reputation", 0),
                "after": state_after.get("reputation", 0),
                "change": state_after.get("reputation", 0) - state_before.get("reputation", 0)
            },
            "stress": {
                "before": state_before.get("stress", 0),
                "after": state_after.get("stress", 0),
                "change": state_after.get("stress", 0) - state_before.get("stress", 0)
            },
            "team_trust": {
                "before": state_before.get("team_trust", 0),
                "after": state_after.get("team_trust", 0),
                "change": state_after.get("team_trust", 0) - state_before.get("team_trust", 0)
            }
        }
        
        round_data = {
            "round_number": idx + 1,
            "round_id": log_entry.get("round_id", log_entry.get("scene_id", "")),
            "round_title": log_entry.get("round_title", ""),
            "choice": log_entry.get("choice", {}).get("label", ""),
            "choice_id": log_entry.get("choice", {}).get("id", ""),
            "stat_changes": stat_changes,
            "events": log_entry.get("events", []),
            "reflection": log_entry.get("reflection", ""),
            "takeaway": log_entry.get("takeaway"),
            "media": round_def.get("media", {}) if round_def else {},
            "goal": log_entry.get("goal", "")
        }
        
        round_history.append(round_data)

    # Calculate Mento Score for report
    mento_score_result = {}
    try:
        achievements_data = r.get("achievements", [])
        competitors_data = r.get("competitors", [])
        run_log = r.get("log", [])
        mento_score_result = calculate_mento_score(
            state=st_obj,
            game_config=game,
            run_log=run_log,
            achievements=achievements_data,
            competitors=competitors_data,
            multiplayer_active=False,
            total_players=1
        )
    except Exception as score_err:
        logger.warning(f"Mento Score in report failed: {score_err}")
        mento_score_result = {"score": 50.0, "breakdown": {}, "rank": "C (Average)", "percentile": 50}

    # Extract scalar mento_score for metacognition comparison
    mento_score = mento_score_result.get("score", 50) if isinstance(mento_score_result, dict) else 50

    # Store metacognition delta if predicted score was submitted
    _metacognition_delta = None
    predicted_score = r.get("metacognition_predicted_score")
    if predicted_score is not None:
        metacognition_delta = mento_score - predicted_score
        _metacognition_delta = metacognition_delta
        try:
            _mc_uid = r.get("user_id", "")
            if _mc_uid:
                _mc_profiles = player_profile._load_profiles()
                _mc_prof = _mc_profiles.setdefault(_mc_uid, {})
                _metacal = _mc_prof.get("metacognition_calibration", [])
                _metacal.append({"game_id": r.get("game_id"), "predicted": predicted_score, "actual": mento_score, "delta": metacognition_delta, "timestamp": __import__("datetime").datetime.now().isoformat()})
                _mc_prof["metacognition_calibration"] = _metacal[-20:]  # keep last 20
                player_profile._save_profiles(_mc_profiles)
        except Exception:
            pass

    initial_state = game.get("initial_state", {})

    # --- Normalize dimension scores for Skill Dashboard ---
    normalized_dimensions = None
    try:
        from engines.dimension_utils import normalize_dimension_scores, get_dimension_metadata, adjust_scores_for_timing
        raw_dims = final_state.get("dimension_scores", {})

        # Adjust raw dimension scores based on timing data before normalizing
        try:
            from engines.behavioral_analytics import compute_timing_stats
            choice_hist = st_obj.choice_history if hasattr(st_obj, 'choice_history') else []
            ts = compute_timing_stats(choice_hist)
            if ts and raw_dims:
                raw_dims = adjust_scores_for_timing(raw_dims, ts)
        except Exception as ts_err:
            logger.warning(f"Timing adjustment failed: {ts_err}")
        normalized_dimensions = normalize_dimension_scores(raw_dims)
    except Exception as dim_err:
        logger.warning(f"Dimension normalization failed: {dim_err}")
    # Build a dict version for downstream consumers (mastery_tiers, career, etc.)
    _norm_dims_dict = {}
    if isinstance(normalized_dimensions, list):
        for _nd in normalized_dimensions:
            if isinstance(_nd, dict) and _nd.get("name"):
                _norm_dims_dict[_nd["name"]] = _nd.get("value", 0)
    elif isinstance(normalized_dimensions, dict):
        _norm_dims_dict = normalized_dimensions
    # --- Mento Score Breakdown (expanded with category labels) ---
    mento_breakdown = None
    try:
        if mento_score_result.get("breakdown") and mento_score_result.get("weights"):
            _category_labels = {
                "resource_optimization": "Resource Management",
                "decision_quality": "Decision Quality",
                "speed_efficiency": "Speed & Efficiency",
                "achievement_progress": "Achievement Progress",
                "learning_engagement": "Learning Engagement",
                "competitive_performance": "Competitive Performance",
                "risk_management": "Risk Management",
            }
            mento_breakdown = []
            for cat_key, cat_score in mento_score_result["breakdown"].items():
                weight = mento_score_result["weights"].get(cat_key, 0)
                mento_breakdown.append({
                    "category": _category_labels.get(cat_key, cat_key.replace("_", " ").title()),
                    "key": cat_key,
                    "weight": round(weight, 2),
                    "score": round(cat_score, 1),
                    "contribution": round(cat_score * weight, 1),
                })
            mento_breakdown.sort(key=lambda x: x["contribution"], reverse=True)
    except Exception as mb_err:
        logger.warning(f"Mento breakdown generation failed: {mb_err}")
    # --- LLM Skill Report (personalized) ---
    skill_report = None
    try:
        from llm import llm_enabled
        if llm_enabled() and normalized_dimensions:
            from llm import generate_skill_report
            choices_made_text = [x.get("choice", {}).get("label", "") for x in r.get("log", [])]
            skill_report = generate_skill_report(
                normalized_dimensions,
                game.get("game_type", "rounds"),
                choices_made_text,
                game.get("title", "")
            )
    except Exception as sr_err:
        logger.warning(f"LLM skill report generation failed: {sr_err}")
    # Static fallback if LLM failed but we have dimensions
    if not skill_report and normalized_dimensions:
        try:
            top = normalized_dimensions[0]
            bottom = normalized_dimensions[-1]
            skill_report = {
                "summary_text": (
                    f"Your strongest skill was {top['label']} at {top['value']}%. "
                    f"Consider focusing on {bottom['label']} ({bottom['value']}%) in future games."
                ),
                "strengths": [{"skill": d["label"], "score": d["value"]} for d in normalized_dimensions[:2]],
                "growth_area": {"skill": bottom["label"], "suggestion": f"Try games that challenge your {bottom['label'].lower()}."},
            }
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # --- LLM End Debrief ---
    debrief = None
    try:
        from llm import llm_enabled
        if llm_enabled():
            from llm import generate_end_debrief
            debrief = generate_end_debrief({
                "game_type": game.get("game_type", "rounds"),
                "title": game.get("title", ""),
                "choices": [x.get("choice", {}).get("label", "") for x in r.get("log", [])],
                "dimension_scores": normalized_dimensions,
                "result": "completed",
            })
    except Exception as db_err:
        logger.warning(f"LLM debrief generation failed: {db_err}")
    # Build decision journal for board games
    decision_journal = None
    concept_mastery_report = None
    if game.get("game_type") == "board":
        board_choices = r.get("board_choices", [])
        if board_choices:
            decision_journal = []
            for bc in board_choices:
                entry = {
                    "turn": bc.get("turn", 0),
                    "type": bc.get("choice_type", "event"),
                    "choice": bc.get("choice_label", ""),
                    "outcome_delta": bc.get("delta", {}),
                    "skill_tags": bc.get("skill_tags", []),
                }
                if bc.get("choice_type") == "boss":
                    entry["correct"] = bc.get("correct")
                decision_journal.append(entry)
        # Concept mastery
        raw_mastery = r.get("concept_mastery", {})
        if raw_mastery:
            concept_mastery_report = {
                term: {
                    "encounters": data["encounters"],
                    "mastery_pct": round(data["positive_outcomes"] / max(1, data["encounters"]) * 100),
                }
                for term, data in raw_mastery.items()
            }

    # --- Mento Chat Psychological Analysis ---
    mento_chat_analysis = None
    try:
        from llm import analyze_mento_chat
        _chat_log = r.get("mento_chat_log", [])
        if _chat_log:
            _raw_dims = final_state.get("dimension_scores", {}) if isinstance(final_state, dict) else {}
            mento_chat_analysis = analyze_mento_chat(
                _chat_log,
                _raw_dims,
                game.get("title", ""),
                game.get("game_type", "rounds"),
            )
    except Exception as _ca_err:
        logger.warning(f"Mento chat analysis failed: {_ca_err}")

    report_core = {
        "game": {"game_id": game_id, "title": game.get("title", ""), "theme": game.get("theme", "")},
        "final_state": final_state,
        "final_score": compute_score(final_state, initial_state),
        "mento_score": mento_score_result,
        "mento_breakdown": mento_breakdown,
        "badges": badges,
        "psychological_focus_summary": psychological_focus_summary,
        "choices": choices,
        "events": events,
        "reflections": reflections,
        "nep_tags_seen": nep_tags_seen,
        "round_history": round_history,
        "dimension_scores": normalized_dimensions,
        "skill_report": skill_report,
        "debrief": debrief,
        "decision_journal": decision_journal,
        "concept_mastery": concept_mastery_report,
        "board_learned_terms": r.get("board_learned_terms"),
        "mento_chat_analysis": mento_chat_analysis,
        "metacognition_delta": _metacognition_delta,
        "mastery_tiers": _compute_mastery_tiers(_norm_dims_dict),
        "transfer_activity": _get_transfer_activity(_norm_dims_dict),
    }

    # Surface scoring failures to frontend
    if not report_core.get("dimension_scores"):
        report_core["scoring_warning"] = "Dimension scores could not be computed for this session."

    # ── Anti-cheat: reveal hidden metrics in post-game report ──────
    if game.get("simulation_config", {}).get("hidden_resources"):
        try:
            from engines.simulation_tick_engine import SimulationTickEngine
            _report_sim_engine = SimulationTickEngine(game["simulation_config"])
            report_core["hidden_metrics"] = _report_sim_engine.get_hidden_metrics_for_report(st_obj)
            _anti_cheat_score = _report_sim_engine.compute_final_score(st_obj)
            if _anti_cheat_score:
                report_core["anti_cheat_score"] = _anti_cheat_score
            # ── simulation_final: grade/title + choice_history + flags for MentoReport ──
            _ch_hist = getattr(st_obj, '_sim_choice_history', []) or []
            _flags = getattr(st_obj, '_sim_flags', {}) or {}
            _early = getattr(st_obj, '_sim_early_exit', None)
            report_core["simulation_final"] = {
                "grade": (_anti_cheat_score or {}).get("grade"),
                "title": (_anti_cheat_score or {}).get("title"),
                "score": (_anti_cheat_score or {}).get("score"),
                "profile_name": (_anti_cheat_score or {}).get("profile_name"),
                "momentum": (_anti_cheat_score or {}).get("momentum"),
                "choice_history": _ch_hist,
                "flags_set": _flags,
                "early_exit": _early,
            }
        except Exception as _acs_err:
            logger.debug("Anti-cheat score computation failed: %s", _acs_err)

    # Career suggestions (top 3 matches based on dimension scores)
    if _norm_dims_dict and len([v for v in _norm_dims_dict.values() if v > 0]) >= 3:
        try:
            _career_file = os.path.join(os.path.dirname(__file__), "data", "career_mapping.json")
            with open(_career_file) as _cf:
                _careers = json.load(_cf)
            _player_dims = {k: v / 100.0 for k, v in _norm_dims_dict.items() if isinstance(v, (int, float))}
            _career_results = []
            for _career in _careers:
                _req = _career.get("required_dimensions", {})
                if not _req:
                    continue
                _tw = sum(_req.values())
                _ss = sum(min(_player_dims.get(d, 0) / max(rv, 0.01), 1.0) * rv for d, rv in _req.items())
                _match = round(_ss / max(_tw, 0.01), 3)
                _gaps = [d for d, rv in _req.items() if _player_dims.get(d, 0) < rv * 0.7]
                _career_results.append({"career": _career["career"], "match_score": _match, "gap_dims": _gaps[:2]})
            _career_results.sort(key=lambda x: x["match_score"], reverse=True)
            report_core["career_suggestions"] = _career_results[:3]
        except Exception as _career_err:
            logger.debug("Career suggestions failed: %s", _career_err)

    # Cognitive profile from game type
    try:
        _bloom = _BLOOM_MAP.get(game.get("game_type", "rounds"), "understand")
        _top_dim = max(_norm_dims_dict, key=_norm_dims_dict.get) if _norm_dims_dict else None
        _style_label = _BLOOM_STYLE_LABELS.get(_bloom, "")
        report_core["cognitive_profile"] = {
            "bloom_level": _bloom,
            "top_dimension": _top_dim,
            "thinking_style_label": _style_label,
        }
    except Exception:
        pass

    # --- DNA Card: shareable decision profile ---
    dna_card = None
    try:
        dimension_scores = final_state.get("dimension_scores", {})
        memory_tags = final_state.get("memory_tags", [])
        choice_history = final_state.get("choice_history", []) if isinstance(final_state.get("choice_history"), list) else []

        # Determine archetype from top dimension
        archetype_map = {
            "strategic_thinking": ("The Strategist", "chess"),
            "risk_tolerance": ("The Daredevil", "fire"),
            "delayed_gratification": ("The Patient Planner", "hourglass"),
            "impulse_control": ("The Steady Hand", "shield"),
            "resilience": ("The Comeback Kid", "muscle"),
            "emotional_regulation": ("The Cool Head", "brain"),
            "growth_mindset": ("The Explorer", "seedling"),
            "self_awareness": ("The Reflector", "mirror"),
            "empathy": ("The Empath", "heart"),
            "leadership": ("The Leader", "crown"),
        }
        sorted_dims = sorted(dimension_scores.items(), key=lambda x: x[1], reverse=True) if dimension_scores else []
        top_dim = sorted_dims[0][0] if sorted_dims else "strategic_thinking"
        archetype_name, archetype_icon = archetype_map.get(top_dim, ("The Adventurer", "star"))

        # Top 3 traits
        top_traits = []
        for dim_key, dim_val in sorted_dims[:3]:
            label = dim_key.replace("_", " ").title()
            top_traits.append({"id": dim_key, "label": label, "score": dim_val})

        # Decision style from memory tags
        tag_count = len(memory_tags)
        if tag_count > 6:
            decision_style = "Diverse Explorer"
        elif tag_count > 3:
            decision_style = "Balanced Thinker"
        else:
            decision_style = "Focused Specialist"

        # Signature stat: highest resource change from initial
        initial_state_vals = game.get("initial_state", {})
        max_growth_key, max_growth_pct = "", 0
        for key, init_val in initial_state_vals.items():
            if isinstance(init_val, (int, float)) and init_val > 0:
                final_val = final_state.get(key, init_val)
                if isinstance(final_val, (int, float)):
                    pct = ((final_val - init_val) / init_val) * 100
                    if abs(pct) > abs(max_growth_pct):
                        max_growth_key = key
                        max_growth_pct = pct

        dna_card = {
            "archetype_name": archetype_name,
            "archetype_icon": archetype_icon,
            "top_traits": top_traits,
            "decision_style": decision_style,
            "signature_stat": {
                "resource": max_growth_key.replace("_", " ").title(),
                "change_pct": round(max_growth_pct, 1),
            },
            "total_decisions": len(choice_history),
            "game_title": game.get("title", ""),
        }
    except Exception as dna_err:
        logger.warning(f"DNA card generation failed: {dna_err}")
    if dna_card:
        report_core["dna_card"] = dna_card

    # --- Behavioral Analytics & Growth Curve Recording ---
    try:
        from engines.behavioral_analytics import analyze_session_behavior, record_dimension_snapshot
        choice_hist = st_obj.choice_history if hasattr(st_obj, 'choice_history') else []
        resource_traj = st_obj.resource_trajectory if hasattr(st_obj, 'resource_trajectory') else []

        behavioral_profile = analyze_session_behavior(
            choice_history=choice_hist,
            resource_trajectory=resource_traj,
            game=game,
            run_id=run_id,
            user_id=r.get("user_id", "anonymous"),
        )
        report_core["behavioral_indicators"] = behavioral_profile.get("behavioral_indicators")
        report_core["timing_stats"] = behavioral_profile.get("timing_stats")

        # Record growth curve snapshot
        if normalized_dimensions:
            token = get_token_from_request()
            user_payload = verify_token(token) if token else None
            if user_payload:
                # Convert list-of-dicts to dict for growth curve storage
                dim_scores_dict = {}
                if isinstance(normalized_dimensions, list):
                    for d in normalized_dimensions:
                        key = d.get("name", d.get("id", ""))
                        if key:
                            dim_scores_dict[key] = d.get("value", 0)
                elif isinstance(normalized_dimensions, dict):
                    dim_scores_dict = normalized_dimensions
                record_dimension_snapshot(
                    user_id=user_payload["user_id"],
                    game_id=game_id,
                    run_id=run_id,
                    dimension_scores=dim_scores_dict,
                )
    except Exception as ba_err:
        logger.warning(f"Behavioral analytics failed: {ba_err}")

    # --- Accumulate normalized dimension scores into player profile ---
    if normalized_dimensions:
        try:
            token = get_token_from_request()
            user_payload = verify_token(token) if token else None
            if user_payload:
                player_profile.update_dimension_scores(
                    user_id=user_payload["user_id"],
                    game_id=game_id,
                    dimension_scores=normalized_dimensions,
                )
                # Also update NEP progression
                try:
                    player_profile.update_nep_progression(
                        user_id=user_payload["user_id"],
                        game_id=game_id,
                        dimension_scores={d["name"]: d["value"] for d in normalized_dimensions} if isinstance(normalized_dimensions, list) else normalized_dimensions,
                    )
                except Exception as nep_err:
                    logger.debug("Failed to update NEP progression: %s", nep_err)
        except Exception as ds_err:
            logger.debug("Failed to update dimension scores: %s", ds_err)

    # --- Idempotent rewards: only credit wallet/XP once per run ---
    already_rewarded = r.get("rewards_credited", False)
    wallet_reward = r.get("cached_wallet_reward")
    xp_reward = r.get("cached_xp_reward")
    # Must be defined outside the `if not already_rewarded:` branch — referenced later
    # for the baseline-completed modal trigger, even when /report is hit again for an
    # already-finalized run.
    _just_completed_baseline = False

    if not already_rewarded:
        # Credit global wallet coins based on Mento Score rank
        wallet_reward = None
        try:
            token = get_token_from_request()
            user_payload = verify_token(token) if token else None
            if user_payload:
                rank_str = mento_score_result.get("rank", "F")
                rank_letter = rank_str.strip()[0].upper() if rank_str else "F"
                total_achievements = len(game.get("achievements", []))
                earned_achievements = len(badges) if badges else 0
                wallet_reward = wallet.credit_game_completion(
                    user_id=user_payload["user_id"],
                    game_id=game_id,
                    game_title=game.get("title", game_id),
                    mento_rank=rank_letter,
                    achievement_count=earned_achievements,
                    total_achievements=total_achievements,
                )
        except Exception as wallet_err:
            logger.warning(f"Wallet credit failed: {wallet_err}")
        # Award XP to player profile
        xp_reward = None
        try:
            token = get_token_from_request()
            user_payload = verify_token(token) if token else None
            if user_payload:
                _ms = report_core.get("mento_score", {})
                final_score = (_ms.get("score") or _ms.get("total") or 50) if isinstance(_ms, dict) else 50
                xp_amount = int(round(max(25, final_score)))
                psych_scores = None
                if psychological_focus_summary and psychological_focus_summary.get("skills"):
                    psych_scores = {
                        s["id"]: {"final": s["final"], "name": s.get("name", ""), "icon": s.get("icon", "")}
                        for s in psychological_focus_summary["skills"]
                    }
                # Build a plain dict of dimension scores for XP and profile storage
                dim_scores_for_xp = _norm_dims_dict if _norm_dims_dict else (final_state.get("dimension_scores") if isinstance(final_state.get("dimension_scores"), dict) else None)
                xp_reward = player_profile.award_xp(
                    user_id=user_payload["user_id"],
                    xp_amount=xp_amount,
                    reason="game_completion",
                    game_type=game.get("game_type", "rounds"),
                    game_title=game.get("title", game_id),
                    score=final_score,
                    psychological_scores=psych_scores,
                    dimension_scores=dim_scores_for_xp,
                )
                # Store baseline scores if this is the baseline assessment (atomic write)
                if game.get("is_baseline") and dim_scores_for_xp:
                    try:
                        player_profile.complete_baseline(user_payload["user_id"], dim_scores_for_xp)
                        _just_completed_baseline = True
                    except Exception as bl_err:
                        logger.warning(f"Baseline completion store failed: {bl_err}")
                # Store wellbeing check result if this is a PHQ-9 or GAD-7 survey
                if game.get("is_wellbeing_survey") and game.get("survey_type"):
                    try:
                        _survey_type = game["survey_type"]
                        _scoring_bands = game.get("scoring_bands", [])
                        _score_key = f"{_survey_type}_score"
                        _raw_total = 0
                        for _ch in r["log"]:
                            _choice_obj = _ch.get("choice", {})
                            _delta = _choice_obj.get("delta") or {}
                            _raw_total += int(_delta.get(_score_key, 0))
                        _severity = "unknown"
                        _color = "gray"
                        for _band in _scoring_bands:
                            if _band.get("min", 0) <= _raw_total <= _band.get("max", 999):
                                _severity = _band["severity"]
                                _color = _band.get("color", "gray")
                                break
                        from datetime import datetime as _dt
                        player_profile.store_wellbeing_check(user_payload["user_id"], {
                            "survey": _survey_type,
                            "raw_score": _raw_total,
                            "severity": _severity,
                            "color": _color,
                            "timestamp": _dt.now().isoformat(),
                        })
                    except Exception as _wb_err:
                        logger.warning(f"Wellbeing check store failed: {_wb_err}")
                # Record research instrument (TEIQue-SF pre/post) completion
                if game.get("is_research_instrument") and user_payload:
                    try:
                        _profiles = player_profile._load_profiles()
                        _rp = player_profile._ensure_profile(_profiles, user_payload["user_id"])
                        if _rp.get("research_cohort"):
                            # Compute score totals from the run log
                            _ri_scores = {}
                            for _ch in r["log"]:
                                _choice_obj = _ch.get("choice", {})
                                _delta = _choice_obj.get("delta") or {}
                                for _dk, _dv in _delta.items():
                                    if _dk.endswith("_score") and isinstance(_dv, (int, float)):
                                        _ri_scores[_dk] = _ri_scores.get(_dk, 0) + int(_dv)
                            from datetime import datetime as _ri_dt
                            if not _rp.get("research_pre_test_complete"):
                                _rp["research_pre_test_complete"] = True
                                _rp["research_pre_test_scores"] = _ri_scores
                                _rp["research_pre_test_date"] = _ri_dt.now().isoformat()
                                _rp["research_pre_test_games"] = _rp.get("games_completed", 0)
                            else:
                                _rp["research_post_test_complete"] = True
                                _rp["research_post_test_scores"] = _ri_scores
                                _rp["research_post_test_date"] = _ri_dt.now().isoformat()
                            player_profile._save_profiles(_profiles)
                    except Exception as _ri_err:
                        logger.debug("Research instrument save: %s", _ri_err)
                # Trigger game-complete notification
                try:
                    notifications.trigger_game_complete(
                        user_id=user_payload["user_id"],
                        game_title=game.get("title", game_id),
                        xp_earned=xp_reward.get("xp_earned", 0),
                        streak_days=xp_reward.get("streak_days", 0),
                    )
                except Exception as _e:
                    logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
                # Trigger level-up notification if the player levelled up
                try:
                    if xp_reward.get("level_up"):
                        notifications.trigger_level_up(
                            user_id=user_payload["user_id"],
                            new_level=xp_reward.get("new_level", 0),
                        )
                except Exception as _e:
                    logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
                # Trigger achievement notifications for each newly earned badge
                try:
                    for badge in xp_reward.get("new_badges", []):
                        notifications.trigger_achievement(
                            user_id=user_payload["user_id"],
                            badge_name=badge.get("name", ""),
                            badge_icon=badge.get("icon", ""),
                            xp_reward=badge.get("xp_reward", 0),
                        )
                except Exception as _e:
                    logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        except Exception as xp_err:
            logger.warning(f"XP award failed: {xp_err}")
        # Growth mindset: track improvement after retry
        try:
            if r.get("is_retry_after_failure"):
                from datetime import datetime as _dt_gm
                _actual_score = report_core.get("mento_score", 0) or 0
                if isinstance(_actual_score, dict):
                    _actual_score = _actual_score.get("total", 0) or 0
                _prev_best = r.get("prev_best_score", 0)
                if _actual_score > _prev_best and user_payload:
                    _profiles_d = player_profile._load_profiles()
                    _uid_gm = user_payload["user_id"]
                    if _uid_gm in _profiles_d:
                        _prof_gm = _profiles_d[_uid_gm]
                        _prof_gm["growth_mindset_retries"] = _prof_gm.get("growth_mindset_retries", 0) + 1
                        _prof_gm["growth_mindset_delta"] = _prof_gm.get("growth_mindset_delta", [])
                        _prof_gm["growth_mindset_delta"].append({
                            "game_id": game_id, "prev": _prev_best, "new": _actual_score,
                            "delta": _actual_score - _prev_best, "ts": _dt_gm.now().isoformat()
                        })
                        _prof_gm["growth_mindset_delta"] = _prof_gm["growth_mindset_delta"][-20:]
                        player_profile._save_profiles(_profiles_d)
        except Exception as _gm_err:
            logger.debug("Growth mindset tracking: %s", _gm_err)
        # A1: Record coaching tip outcome for RL bandit learning
        try:
            from llm import record_coaching_tip_outcome
            _tip_id = r.get("_coaching_tip_id")
            if _tip_id:
                _dim_scores = final_state.get("dimension_scores", {})
                if _dim_scores:
                    _weakest = min(_dim_scores, key=_dim_scores.get)
                    _avg = sum(_dim_scores.values()) / max(1, len(_dim_scores))
                    record_coaching_tip_outcome(_tip_id, game.get("game_type", "rounds"), _weakest, _avg - 50)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        # RL 3B: Mark game as completed in game_starts.json
        try:
            _gs_file = os.path.join(os.path.dirname(__file__), "data", "game_starts.json")
            try:
                with open(_gs_file) as _f:
                    _game_starts = json.load(_f)
            except (FileNotFoundError, json.JSONDecodeError):
                _game_starts = {}
            if run_id in _game_starts:
                _game_starts[run_id]["completed"] = True
                _game_starts[run_id]["finished_at"] = datetime.now().isoformat()
                with open(_gs_file, "w") as _f:
                    json.dump(_game_starts, _f)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        # RL 3D: Track skill impact by game type
        try:
            _pre_dim = r.get("pre_game_dimension_scores", {})
            _post_dim = report_core.get("dimension_scores") or final_state.get("dimension_scores") or {}
            if _pre_dim and _post_dim:
                _si_file = os.path.join(os.path.dirname(__file__), "data", "skill_impact.json")
                try:
                    with open(_si_file) as _f:
                        _si = json.load(_f)
                except (FileNotFoundError, json.JSONDecodeError):
                    _si = {}
                _gtype = game.get("game_type", "rounds")
                _si.setdefault(_gtype, {})
                for _dim, _post_val in _post_dim.items():
                    if isinstance(_post_val, (int, float)) and _dim in _pre_dim:
                        _delta = _post_val - _pre_dim.get(_dim, _post_val)
                        entry = _si[_gtype].setdefault(_dim, {"total_delta": 0, "count": 0, "avg_delta": 0})
                        entry["total_delta"] += _delta
                        entry["count"] += 1
                        entry["avg_delta"] = round(entry["total_delta"] / entry["count"], 2)
                with open(_si_file, "w") as _f:
                    json.dump(_si, _f)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        # Spaced Repetition: schedule reviews for weak dimensions (score < 65)
        try:
            import spaced_repetition as _sr
            _sr_user_id = user_payload["user_id"] if user_payload else None
            _sr_dim_scores = report_core.get("dimension_scores") or final_state.get("dimension_scores") or {}
            if _sr_user_id and _sr_dim_scores:
                for _sr_dim, _sr_val in _sr_dim_scores.items():
                    if isinstance(_sr_val, (int, float)) and _sr_val < 65:
                        _sr.schedule_review(_sr_user_id, game_id, _sr_dim, int(_sr_val))
        except Exception as _sr_err:
            logger.warning(f"Spaced repetition schedule_review failed: {_sr_err}")
        # Store metacognition delta if predicted score exists
        try:
            _predicted = r.get("predicted_score")
            _actual_ms = report_core.get("mento_score")
            if isinstance(_actual_ms, dict):
                _actual_ms = _actual_ms.get("total")
            if _predicted is not None and _actual_ms is not None and user_payload:
                from datetime import datetime as _dt_mc
                _mc_delta = round(float(_actual_ms) - float(_predicted), 1)
                _profiles_d2 = player_profile._load_profiles()
                _uid2 = user_payload["user_id"]
                if _uid2 in _profiles_d2:
                    _p2 = _profiles_d2[_uid2]
                    _p2.setdefault("metacognition_history", []).append({
                        "game_id": game_id, "predicted": _predicted, "actual": _actual_ms,
                        "delta": _mc_delta, "ts": _dt_mc.now().isoformat()
                    })
                    _p2["metacognition_history"] = _p2["metacognition_history"][-50:]
                    player_profile._save_profiles(_profiles_d2)
        except Exception as _mc_err:
            logger.debug("Metacognition store: %s", _mc_err)
        # Mark rewards as credited so repeat calls don't double-award
        r["rewards_credited"] = True
        r["cached_wallet_reward"] = wallet_reward
        r["cached_xp_reward"] = xp_reward
        try:
            update_run(run_id, r)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # LLM narrative — cache to avoid repeat LLM calls
    cached_narrative = r.get("cached_narrative")
    if cached_narrative:
        narrative = cached_narrative
    else:
        narrative = generate_final_report(report_core)
        if not narrative.get("badges"):
            narrative["badges"] = badges
        r["cached_narrative"] = narrative
        try:
            update_run(run_id, r)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Store report for historical access
    _store_historical_report(run_id, r, report_core, narrative, wallet_reward)

    # Notify linked parents when child completes a game
    try:
        _child_uid = (user_payload or {}).get("user_id") or r.get("user_id")
        if _child_uid:
            _fl = _load_family_links()
            _parent_ids = [lnk["parent_id"] for lnk in _fl.get("links", []) if lnk.get("child_id") == _child_uid]
            _gs = int(report_core.get("final_score", 0))
            _gtitle = game.get("title", "a game")
            _child_display = next((lnk.get("child_display_name", _child_uid) for lnk in _fl.get("links", []) if lnk.get("child_id") == _child_uid), _child_uid)
            for _pid in _parent_ids:
                notifications.create_notification(
                    _pid, "game_complete",
                    title=f"{_child_display} completed {_gtitle}",
                    body=f"They scored {_gs}/100. Tap to see their progress.",
                    action_url="/parent-dashboard", icon="🎮"
                )
            # Also record batch assessment run if ?b= param present
            _batch_id = request.args.get("b")
            if _batch_id:
                _record_assessment_run(_batch_id, run_id, final_state.get("dimension_scores", {}), _gs)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Course progress: mark game item complete in any enrolled courses
    try:
        _course_uid = (user_payload or {}).get("user_id") or r.get("user_id")
        if _course_uid:
            _course_score = int(report_core.get("final_score", 0) or 0)
            _check_course_progress_on_game_complete(_course_uid, game_id, run_id, _course_score)
    except Exception as _ce2:
        logger.debug("Course progress hook: %s", _ce2)

    # Peer percentile: surface the player's rank among all players for this game
    try:
        if user_payload and final_score is not None:
            _rank_data = get_user_rank(game_id, user_payload["user_id"])
            if _rank_data and _rank_data.get("found") and report_core.get("mento_score") is not None:
                if isinstance(report_core["mento_score"], dict):
                    report_core["mento_score"]["percentile"] = _rank_data.get("percentile")
                else:
                    result_mento_score_val = report_core["mento_score"]
                    report_core["mento_score"] = {"score": result_mento_score_val, "percentile": _rank_data.get("percentile")}
            result_percentile = _rank_data.get("percentile")
        else:
            result_percentile = None
    except Exception:
        result_percentile = None

    # Behavioral analytics: decision speed, cognitive load, session sentiment
    try:
        import player_profile as _pp_report
        _report_uid = (user_payload or {}).get("user_id") if user_payload else None
        if not _report_uid:
            _rpt_tok = get_token_from_request()
            _rpt_usr = verify_token(_rpt_tok) if _rpt_tok else None
            _report_uid = (_rpt_usr or {}).get("user_id")
        if _report_uid:
            _ch_all = getattr(r.get("state"), "choice_history", []) or []
            _decision_speed = _pp_report.compute_decision_speed_profile(_ch_all)
            if not _decision_speed.get("insufficient_data"):
                result_behavioural = {"decision_speed_profile": _decision_speed}
            else:
                result_behavioural = {}
        else:
            result_behavioural = {}
    except Exception as _beh_err:
        logger.debug("Suppressed behavioral analytics: %s", _beh_err)
        result_behavioural = {}

    try:
        _run_log = r.get("log", [])
        if _run_log:
            from behavioral_indicators import _compute_session_cognitive_load
            _cog = _compute_session_cognitive_load(_run_log)
            if _cog:
                result_behavioural["cognitive_load"] = _cog
    except Exception as _cog_err:
        logger.debug("Suppressed cognitive load: %s", _cog_err)

    try:
        _ch_for_sent = getattr(r.get("state"), "choice_history", []) or []
        _sent_vals = [c.get("sentiment_valence") for c in _ch_for_sent if c.get("sentiment_valence") is not None]
        _emo_markers = [m for c in _ch_for_sent for m in (c.get("emotional_markers") or [])]
        if _sent_vals:
            from statistics import mean as _mean
            _sent_avg = round(_mean(_sent_vals), 2)
            _sent_trend = (
                "declining" if len(_sent_vals) > 2 and _sent_vals[-1] < _sent_vals[0] - 0.3
                else "stable"
            )
            _dominant = max(set(_emo_markers), key=_emo_markers.count) if _emo_markers else None
            result_behavioural["session_sentiment"] = {
                "avg_valence": _sent_avg,
                "trend": _sent_trend,
                "dominant_emotion": _dominant,
                "n": len(_sent_vals),
            }
    except Exception as _sent_err:
        logger.debug("Suppressed session sentiment: %s", _sent_err)

    # Compute decision style from choice times
    _choice_times = r.get("choice_times_ms", [])
    _decision_style = None
    _decision_style_description = None
    _avg_choice_time_ms = None
    if len(_choice_times) >= 3:
        _avg_choice_time_ms = round(sum(_choice_times) / len(_choice_times))
        if _avg_choice_time_ms < 5000:
            _decision_style = "Quick Decider"
            _decision_style_description = "You make fast, intuitive decisions. This reflects confidence and pattern recognition — hallmarks of experienced leaders."
        elif _avg_choice_time_ms < 15000:
            _decision_style = "Balanced Thinker"
            _decision_style_description = "You balance speed with reflection — considering options without overthinking. This is the sweet spot for high-stakes decisions."
        else:
            _decision_style = "Careful Deliberator"
            _decision_style_description = "You take time to weigh decisions thoroughly. This reflects conscientiousness and reduces impulsive errors in complex situations."
    if _decision_style:
        report_core["decision_style"] = _decision_style
        report_core["decision_style_description"] = _decision_style_description
        report_core["avg_choice_time_ms"] = _avg_choice_time_ms

    result = {"report_core": report_core, "narrative": narrative, "mentoPercentile": result_percentile}
    # Surface final executive snapshot for exec-tier post-game section (dormant for non-exec games).
    try:
        from engines.executive_ux import build_executive_payload as _bep_for_report
        _final_ux_exec = _bep_for_report(st_obj, game, None)
        if _final_ux_exec:
            result["ux_executive"] = _final_ux_exec
            # Also include the per-round actions log if present
            _eal = getattr(st_obj, "_exec_actions_log", None)
            if _eal:
                result["exec_actions_log"] = list(_eal)
    except Exception as _ex_err:
        logger.debug("Executive UX (report) error: %s", _ex_err)
    if result_behavioural:
        result.update(result_behavioural)
    if wallet_reward:
        result["wallet_reward"] = wallet_reward
    if xp_reward:
        result["xp_reward"] = xp_reward
        if xp_reward.get("newly_unlocked"):
            result["newly_unlocked"] = xp_reward["newly_unlocked"]
        if xp_reward.get("experience_tier"):
            result["experience_tier"] = xp_reward["experience_tier"]
    if _just_completed_baseline:
        result["just_completed_baseline"] = True

    # Adaptive: track engagement and provide recommendations
    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith("Bearer "):
        token = auth_header[7:]
        user = verify_token(token)
        if user:
            from engines.adaptive_game_engine import track_engagement, recommend_next_game, analyze_play_style
            _uid = user.get("user_id") or user.get("username", "")
            _engagement, _recommendations, _play_style = {}, [], {}
            try:
                _engagement = track_engagement(_uid, run_id)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            try:
                _recommendations = recommend_next_game(_uid, count=3)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            try:
                _play_style = analyze_play_style(_uid)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            result["adaptive"] = {
                "engagement": _engagement,
                "recommended_next": _recommendations,
                "play_style": _play_style,
            }

    # Next game recommendation based on weakest dimension
    _next_game_rec = None
    try:
        _dim_scores_rec = report_core.get("dimension_scores", {})
        if _dim_scores_rec and user_payload:
            _rec_uid = user_payload["user_id"]
            _rec_profile = player_profile.get_profile(_rec_uid) or {}
            _rec_level = _rec_profile.get("level", 1)
            _rec_unlocked = _get_unlocked_game_types_for_level(_rec_level)
            for gt in _rec_profile.get("teacher_early_access", []):
                _rec_unlocked.add(gt)
            _rec_recent = {e.get("game_id") for e in _rec_profile.get("game_history", [])[-10:] if e.get("game_id")}
            _ALL_DIMS_REC = ["strategic_thinking", "risk_tolerance", "delayed_gratification",
                             "adaptability", "resilience", "empathy", "ethical_reasoning", "creativity"]
            _rec_weakest = min(_ALL_DIMS_REC, key=lambda d: _dim_scores_rec.get(d, 100))
            for _rec_gid, _rec_g in GAMES.items():
                if _rec_gid in _rec_recent or _rec_gid == game_id:
                    continue
                if _rec_g.get("visible") is False:
                    continue
                if _rec_g.get("game_type") not in _PUBLIC_GAME_TYPES:
                    continue
                if _rec_g.get("dimension_scoring_weights", {}).get(_rec_weakest, 0) >= 0.25:
                    _next_game_rec = {
                        "game_id": _rec_gid,
                        "title": _rec_g.get("title", _rec_gid),
                        "reason": f"Your weakest area is {_rec_weakest.replace('_', ' ')} — this targets it directly.",
                    }
                    break
    except Exception as _rec_e:
        logger.debug(f"next_game_rec failed: {_rec_e}")
    report_core["next_recommended_game"] = _next_game_rec

    # Meta-debrief: compare player to high-score / low-score cohorts
    try:
        from engines.meta_debrief_engine import build_debrief as _build_debrief
        _is_story = (game.get("game_type") == "story_branching")
        if _is_story:
            # For story games, treat each scene as a "round" so the engine
            # can match canonical_choices keyed by scene_id.
            _md_rounds = []
            _scenes = (game.get("story_intro") or {}).get("scenes") or []
            for _sc in _scenes:
                _sid = _sc.get("scene_id") or _sc.get("id")
                if not _sid:
                    continue
                _r = dict(_sc)
                _r["id"] = _sid
                # surface expert_pick.choice_id at the top level for engine
                _ep = _sc.get("expert_pick")
                if isinstance(_ep, dict):
                    _r["expert_pick"] = _ep.get("choice_id")
                _md_rounds.append(_r)
        else:
            _md_rounds = game.get("rounds", []) or []
        _md_history = []
        for _entry in (r.get("log") or []):
            # rounds-type uses round_id; story-type uses scene_id
            _rid = (_entry.get("round_id") or _entry.get("round")
                    or _entry.get("scene_id") or _entry.get("id"))
            _ch = _entry.get("choice")
            if isinstance(_ch, dict):
                _cid = _ch.get("id") or _ch.get("choice_id")
            else:
                _cid = _ch
            # Story log entries have choice_id directly on the entry, not under .choice
            if not _cid:
                _cid = _entry.get("choice_id")
            if _rid and _cid:
                _md_history.append({"round_id": _rid, "choice_id": _cid})
        _md_score = float(report_core.get("mento_score") or report_core.get("final_score") or 0)
        _md_cfg = game.get("simulation_config") or {}
        _debrief = _build_debrief(rounds=_md_rounds, choice_history=_md_history,
                                  final_score=_md_score, config=_md_cfg)
        if _debrief:
            result["meta_debrief"] = _debrief
        # Story-game canonical match score: % of scenes where the player picked
        # the same canonical choice as the curated high-score path.
        if _is_story:
            _canon = ((_md_cfg.get("meta_debrief") or {})
                      .get("cohorts", {}).get("high_score", {})
                      .get("canonical_choices") or {})
            if _canon:
                _player_map = {h["round_id"]: h["choice_id"] for h in _md_history}
                _matches, _total = 0, 0
                _diffs = []
                for _sid, _ccid in _canon.items():
                    if _sid in _player_map:
                        _total += 1
                        if _player_map[_sid] == _ccid:
                            _matches += 1
                        else:
                            _diffs.append({"scene_id": _sid,
                                           "expert_choice": _ccid,
                                           "player_choice": _player_map[_sid]})
                if _total > 0:
                    _cm = {
                        "matches": _matches,
                        "total": _total,
                        "percent": round(100.0 * _matches / _total, 1),
                        "divergences": _diffs[:5],
                    }
                    result["canonical_match"] = _cm
                    # Persist on the run so /api/leaderboard/story-paths can read it cheaply
                    try:
                        r["canonical_match"] = _cm
                        update_run(run_id, r)
                    except Exception:
                        pass
    except Exception as _md_err:
        logger.debug("meta_debrief failed: %s", _md_err)

    # Surface market shocks fired during the run + org scaling snapshot (when present)
    try:
        _shocks_fired = (final_state or {}).get("market_shocks_fired") or []
        if _shocks_fired:
            result["market_shocks_fired"] = list(_shocks_fired)
        _org_log = (final_state or {}).get("org_friction_log") or []
        if _org_log:
            result["org_friction_log"] = list(_org_log)
        # Final team_health snapshot if org_scaling is configured for this game
        if (game.get("simulation_config") or {}).get("org_scaling") and final_state.get("headcount"):
            from engines.org_scaling_engine import compute_team_health as _cth
            result["team_health_final"] = _cth(final_state)
    except Exception as _os_err:
        logger.debug("scaling snapshot failed: %s", _os_err)

    # mystery_room: surface escape-room-specific fields
    if game.get("game_type") == "mystery_room":
        try:
            report_core["outcome_label"] = r.get("outcome_label")
            report_core["knowledge_score"] = r.get("knowledge_score", 0)
            report_core["evidence_collected"] = r.get("evidence_collected", [])
            report_core["evidence_board_state"] = r.get("evidence_board_state", {})
            report_core["fingerprint"] = _ESCAPE_ROOM_ENGINE.compute_fingerprint(r)
            report_core["hints_used"] = r.get("hints_used", {})
            epilogues = game.get("epilogues", {})
            report_core["epilogue"] = epilogues.get(r.get("outcome_label", ""), None)
        except Exception as _mr_err:
            logger.warning("mystery_room report block failed: %s", _mr_err)

    # Mark run as completed and persist full report to disk (survives restart)
    try:
        r["completed"] = True
        update_run(run_id, r)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    try:
        _full_report_file = os.path.join(REPORTS_DIR, f"{run_id}.json")
        # Include top-level identifying fields so /api/profile/reports can find this report
        _persist = dict(result)
        _persist.setdefault("run_id", run_id)
        _persist.setdefault("game_id", game_id)
        _persist.setdefault("user_id", (user_payload or {}).get("user_id"))
        _persist.setdefault("game_title", game.get("title", ""))
        _persist.setdefault("game_theme", game.get("theme", ""))
        _persist.setdefault("completed_at", r.get("last_accessed", ""))
        # Surface report_core fields for /api/profile/reports listing
        _persist.setdefault("mento_score", report_core.get("mento_score"))
        _persist.setdefault("final_score", report_core.get("final_score"))
        _persist.setdefault("badges", report_core.get("badges", []))
        with open(_full_report_file, "w") as _rf:
            json.dump(_persist, _rf, default=str)
    except Exception as _e:
        logger.debug("Failed to persist full report: %s", _e)

    return jsonify(result)


@app.get("/api/run/<run_id>/report-cards")
def run_report_cards(run_id):
    """Generate parent and teacher report cards for completed game (deterministic)."""
    try:
        r = get_run(run_id)
    except KeyError as e:
        return jsonify({"error": "Resource not found"}), 404

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err

    st_obj = r["state"]
    final_state = state_to_dict(st_obj)

    # Collect gameplay evidence for deterministic analysis
    nep_tags_seen = sorted({t for x in r["log"] for t in x.get("nep_tags", [])})
    choices_made = [
        {
            "round_id": x["round_id"],
            "round_title": x["round_title"],
            "choice": x["choice"]["label"]
        }
        for x in r["log"]
    ]
    
    # Analyze from dimension scores (universal, works for all game types)
    dim_scores = {}
    raw_dims = final_state.get("dimension_scores", {})
    if isinstance(raw_dims, dict):
        dim_scores = raw_dims
    elif isinstance(raw_dims, list):
        for d in raw_dims:
            if isinstance(d, dict) and d.get("name"):
                dim_scores[d["name"]] = d.get("value", 50)

    strengths = []
    growth_areas = []
    DIM_LABELS = {
        "strategic_thinking": "Strategic Thinking",
        "risk_tolerance": "Risk Tolerance",
        "delayed_gratification": "Patience & Long-term Thinking",
        "adaptability": "Adaptability",
        "resilience": "Resilience",
        "empathy": "Empathy & EQ",
        "ethical_reasoning": "Ethical Reasoning",
        "creativity": "Creative Thinking",
    }
    for dim, score in sorted(dim_scores.items(), key=lambda x: -x[1]):
        label = DIM_LABELS.get(dim, dim.replace("_", " ").title())
        if score >= 65:
            strengths.append(f"Strong {label} ({score}/100)")
        elif score < 45:
            growth_areas.append(f"{label} needs development ({score}/100)")

    # Extract learning_points (used in both paths)
    learning_points = final_state.get("learning_points", 0)

    # Fallback: if no dimension scores, use legacy state-based analysis
    if not dim_scores:
        ethics = final_state.get("ethics_meter", final_state.get("reputation", 50))
        if ethics >= 75:
            strengths.append("Ethical reasoning")
        elif ethics < 50:
            growth_areas.append("Ethical awareness")
        stress = final_state.get("stress", 50)
        if stress <= 40:
            strengths.append("Emotional resilience")
        elif stress >= 75:
            growth_areas.append("Stress management")
        team_trust = final_state.get("team_trust", 50)
        if team_trust >= 70:
            strengths.append("Collaboration")
        elif team_trust < 50:
            growth_areas.append("Teamwork skills")
        if learning_points >= 5:
            strengths.append("Critical thinking")

    # Default growth areas if none identified
    if not growth_areas:
        growth_areas = ["Risk assessment", "Strategic planning"]
    
    # Build context for LLM
    context = {
        "student_name": game.get("player_profile", {}).get("name", "Student"),
        "game_title": game.get("title", "Startup Sprint"),
        "simulation_theme": game.get("theme", "Entrepreneurship"),
        "final_state": final_state,
        "choices_made": choices_made,
        "strengths": strengths[:5],  # Top 5
        "growth_areas": growth_areas[:3],  # Top 3
        "nep_skills": nep_tags_seen,
        "total_rounds": len(r["log"]),
        "learning_points": learning_points
    }
    
    # Generate deterministic report cards using LLM
    report_cards = generate_report_cards(context)

    # Psychological summary for Skill Profile tab
    psych_summary = _compute_psychological_summary(game, final_state)

    return jsonify({
        "student_name": context["student_name"],
        "game_title": context["game_title"],
        "report_cards": report_cards,
        "psychological_focus_summary": psych_summary,
    })


@app.get("/api/run/<run_id>/certificate")
def run_certificate(run_id):
    """Return an HTML certificate of completion for a game run."""
    from certificate import generate_certificate_html
    fmt = request.args.get("format", "html")
    r = None
    try:
        r = get_run(run_id)
    except Exception:
        pass
    if r is None:
        # Try loading persisted report to reconstruct certificate data
        _report_file = os.path.join(REPORTS_DIR, f"{run_id}.json")
        if os.path.exists(_report_file):
            try:
                with open(_report_file, "r") as _rf:
                    _stored = json.load(_rf)
                _rc = _stored.get("report_core", _stored)
                _game_info = _rc.get("game", {})
                _final_score = _rc.get("final_score", 50)
                ranks = [(90, "S"), (80, "A"), (65, "B"), (50, "C"), (35, "D")]
                _rank = next((rk for threshold, rk in ranks if _final_score >= threshold), "F")
                _player_name = "Player"
                try:
                    token = get_token_from_request()
                    user = verify_token(token) if token else None
                    if user:
                        prof = player_profile.get_profile(user["user_id"])
                        _player_name = prof.get("display_name") or user.get("username", "Player")
                except Exception:
                    pass
                from datetime import datetime as _dt_cert2
                _completion_date = _stored.get("completed_at", _dt_cert2.now().strftime("%B %d, %Y"))
                html = generate_certificate_html(
                    player_name=_player_name,
                    game_title=_game_info.get("title", _game_info.get("game_id", "")),
                    game_theme=_game_info.get("theme", "Soft Skills"),
                    mento_score=_final_score,
                    mento_rank=_rank,
                    badges=_rc.get("badges", []),
                    completion_date=_completion_date,
                    run_id=run_id,
                )
                if fmt == "json":
                    return jsonify({"html": html})
                from flask import Response
                return Response(html, mimetype="text/html; charset=utf-8")
            except Exception as _e:
                logger.debug("Certificate from persisted report failed: %s", _e)
        return jsonify({"error": "Run not found"}), 404
    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    st_obj = r["state"]
    final_score = compute_score(state_to_dict(st_obj), game.get("initial_state", {}))
    # Determine rank
    ranks = [(90, "S"), (80, "A"), (65, "B"), (50, "C"), (35, "D")]
    rank = next((rk for threshold, rk in ranks if final_score >= threshold), "F")
    # Player name
    player_name = "Player"
    try:
        token = get_token_from_request()
        user = verify_token(token) if token else None
        if user:
            prof = player_profile.get_profile(user["user_id"])
            player_name = prof.get("display_name") or user.get("username", "Player")
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    badges = r.get("badges_earned", [])
    from datetime import datetime as _dt_cert
    completion_date = r.get("completed_at", _dt_cert.now().strftime("%B %d, %Y"))
    if isinstance(completion_date, str) and "T" in completion_date:
        try:
            completion_date = _dt_cert.fromisoformat(completion_date.split("T")[0]).strftime("%B %d, %Y")
        except Exception:
            pass
    html = generate_certificate_html(
        player_name=player_name,
        game_title=game.get("title", game_id),
        game_theme=game.get("theme", game.get("category", "Soft Skills")),
        mento_score=final_score,
        mento_rank=rank,
        badges=badges,
        completion_date=completion_date,
        run_id=run_id,
    )
    if fmt == "json":
        return jsonify({"html": html})
    from flask import Response
    return Response(html, mimetype="text/html; charset=utf-8")


@app.get("/api/run/<run_id>/rubric")
def run_rubric(run_id):
    """Return an academic rubric HTML mapping student scores to grading levels."""
    fmt = request.args.get("format", "html")
    r = None
    try:
        r = get_run(run_id)
    except Exception:
        pass
    if r is None:
        # Try loading persisted report to reconstruct rubric data
        _report_file = os.path.join(REPORTS_DIR, f"{run_id}.json")
        if os.path.exists(_report_file):
            try:
                with open(_report_file, "r") as _rf:
                    _stored = json.load(_rf)
                _rc = _stored.get("report_core", _stored)
                _dim_scores = _rc.get("final_state", {}).get("dimension_scores", {}) or {}
                _game_info = _rc.get("game", {})
                # Build a minimal fake run object to continue the rubric logic below
                class _FakeState:
                    pass
                _fake_st = _FakeState()
                for k, v in _dim_scores.items():
                    setattr(_fake_st, k, v)
                r = {
                    "game_id": _game_info.get("game_id", ""),
                    "state": _fake_st,
                }
            except Exception as _e:
                logger.debug("Rubric from persisted report failed: %s", _e)
                return jsonify({"error": "Run not found"}), 404
        else:
            return jsonify({"error": "Run not found"}), 404
    game_id = r["game_id"]
    game, _ = get_game_or_400(game_id)
    st_obj = r["state"]
    dim_scores = state_to_dict(st_obj).get("dimension_scores", {}) or {}
    # Player name
    player_name = "Student"
    try:
        token = get_token_from_request()
        user = verify_token(token) if token else None
        if user:
            prof = player_profile.get_profile(user["user_id"])
            player_name = prof.get("display_name") or user.get("username", "Student")
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    DIMS_INFO = [
        ("strategic_thinking", "Strategic Thinking",
         "Consistently identifies long-term patterns, plans multiple steps ahead, and optimises resources proactively.",
         "Demonstrates awareness of consequences beyond the immediate round and makes reasoned resource decisions.",
         "Reacts to immediate events with limited forward planning; shows some awareness of trade-offs.",
         "Responds to events without evident planning; resources managed reactively."),
        ("risk_tolerance", "Risk Tolerance",
         "Confidently takes calculated risks with clear reasoning; recovers quickly from setbacks.",
         "Willing to take moderate risks when evidence supports it; manages uncertainty adequately.",
         "Takes some risks but mostly defaults to safe options; limited comfort with uncertainty.",
         "Avoids risk consistently; choices show low tolerance for ambiguity."),
        ("delayed_gratification", "Delayed Gratification",
         "Consistently prioritises long-term investment over short-term gain; demonstrates exceptional patience.",
         "Often chooses options with future payoffs even at short-term cost.",
         "Sometimes sacrifices immediate gains for future benefit; inconsistent application.",
         "Consistently prefers immediate rewards; rarely invests in long-term outcomes."),
        ("adaptability", "Adaptability",
         "Thrives under changing conditions; adjusts strategy swiftly and effectively with each new development.",
         "Adjusts approach when conditions change; shows flexibility in most situations.",
         "Adapts when necessary but may struggle with rapid or multiple simultaneous changes.",
         "Struggles to adjust when circumstances change; tends to apply the same approach repeatedly."),
        ("resilience", "Resilience",
         "Maintains high performance after setbacks; uses failures as learning opportunities.",
         "Recovers from setbacks within a round or two; keeps team morale stable.",
         "Shows some recovery after difficulty; occasional loss of momentum after setbacks.",
         "Setbacks significantly disrupt performance; limited bounce-back observed."),
        ("empathy", "Empathy",
         "Consistently considers stakeholder perspectives; choices reflect strong awareness of team and community impact.",
         "Regularly accounts for others' needs; shows genuine consideration of stakeholder wellbeing.",
         "Sometimes considers others' perspectives; awareness of impact present but inconsistent.",
         "Choices rarely account for others' perspectives or team wellbeing."),
        ("ethical_reasoning", "Ethical Reasoning",
         "Articulates principled rationale for decisions; consistently chooses integrity even at cost.",
         "Generally makes ethically sound choices; demonstrates awareness of moral dimensions.",
         "Shows some ethical awareness; occasional tension between ethics and convenience.",
         "Ethical considerations rarely evident in decision-making."),
        ("creativity", "Creativity",
         "Regularly selects innovative approaches; combines ideas from different domains to create novel solutions.",
         "Often explores less obvious options; demonstrates creative problem-solving.",
         "Occasionally tries creative approaches; primarily stays within conventional choices.",
         "Mostly selects conventional options; limited evidence of creative thinking."),
    ]

    def level_for(score):
        if score is None: return None
        if score >= 85: return 0  # Exemplary
        if score >= 65: return 1  # Proficient
        if score >= 40: return 2  # Developing
        return 3                  # Beginning

    LEVEL_LABELS = ["Exemplary (85-100)", "Proficient (65-84)", "Developing (40-64)", "Beginning (0-39)"]
    LEVEL_COLORS = ["#4CAF50", "#2196F3", "#FF9800", "#F44336"]
    LEVEL_BG    = ["#E8F5E9", "#E3F2FD", "#FFF3E0", "#FFEBEE"]

    rows_html = ""
    for dim_key, dim_label, exem, prof, dev, beg in DIMS_INFO:
        score = dim_scores.get(dim_key)
        lvl = level_for(score)
        cells = [exem, prof, dev, beg]
        score_badge = f'<span style="font-weight:700;color:{LEVEL_COLORS[lvl] if lvl is not None else "#999"}">{int(score) if score is not None else "—"}/100</span>'
        row_cells = ""
        for i, (label, txt, color, bg) in enumerate(zip(LEVEL_LABELS, cells, LEVEL_COLORS, LEVEL_BG)):
            highlight = 'border:2px solid ' + color + ';' if i == lvl else ''
            row_cells += f'<td style="padding:8px 10px;background:{bg if i==lvl else "#fff"};{highlight}border-radius:4px;font-size:12px;vertical-align:top">{txt}</td>'
        rows_html += f"""
        <tr>
          <td style="padding:8px 10px;font-weight:600;font-size:13px;white-space:nowrap;vertical-align:middle">{dim_label}<br>{score_badge}</td>
          {row_cells}
        </tr>"""

    html = f"""<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Academic Rubric — {game.get('title',game_id)}</title>
<style>
  body{{font-family:'Segoe UI',sans-serif;margin:0;padding:24px;color:#2d3047;background:#f9f9f9}}
  h1{{font-size:22px;margin-bottom:4px}}
  .meta{{color:#666;font-size:13px;margin-bottom:20px}}
  table{{border-collapse:collapse;width:100%;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 1px 6px rgba(0,0,0,.08)}}
  th{{background:#2d3047;color:#fff;padding:10px 12px;font-size:12px;text-align:left;white-space:nowrap}}
  tr:nth-child(even){{background:#fafafa}}
  .legend{{margin-top:16px;font-size:12px;color:#666}}
  @media print{{body{{padding:12px}}}}
</style>
</head>
<body>
<h1>Academic Skills Rubric</h1>
<div class="meta">
  <strong>Student:</strong> {player_name} &nbsp;|&nbsp;
  <strong>Activity:</strong> {game.get('title',game_id)} &nbsp;|&nbsp;
  <strong>Date:</strong> {__import__('datetime').datetime.now().strftime('%B %d, %Y')}
</div>
<table>
<thead>
  <tr>
    <th style="min-width:140px">Skill Dimension</th>
    {''.join(f'<th style="background:{c};min-width:160px">{l}</th>' for l,c in zip(LEVEL_LABELS,LEVEL_COLORS))}
  </tr>
</thead>
<tbody>{rows_html}</tbody>
</table>
<div class="legend">
  ℹ️ Highlighted cells show the student's demonstrated level. Scores are based on in-game decision patterns across dimensions mapped to Goleman, Dweck, and CASEL frameworks.<br>
  Use browser File → Print → Save as PDF to export this rubric.
</div>
</body></html>"""

    if fmt == "json":
        return jsonify({"html": html})
    from flask import Response
    return Response(html, mimetype="text/html; charset=utf-8")


@app.get("/api/profile/skill-passport")
def api_skill_passport():
    """Generate a beautiful Skill Passport PDF (HTML) for the authenticated user."""
    token = get_token_from_request() or request.args.get("token")
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    payload = verify_token(token)
    if not payload:
        return jsonify({"error": "Invalid token"}), 401

    user_id = payload["user_id"]
    username = payload.get("username", "Student")
    profile = player_profile.get_profile(user_id)

    # Get dimension averages
    avg_dims = {}
    ps = profile.get("psychological_scores", {})
    for dim, data in ps.items():
        if isinstance(data, dict) and data.get("count", 0) > 0:
            avg_dims[dim] = round(data["total"] / data["count"], 1)

