@app.get("/api/impact-stats")
def api_impact_stats():
    """Public endpoint: aggregate platform impact metrics."""
    try:
        all_profiles = player_profile._load_profiles()
        # Filter to actual profile dicts (skip metadata strings)
        profiles = {k: v for k, v in all_profiles.items() if isinstance(v, dict)}
        total_users = len(profiles)
        total_games_played = sum(p.get("games_completed", 0) for p in profiles.values())
        total_decisions = sum(
            sum(len(h.get("choices", [])) for h in p.get("history", []))
            for p in profiles.values()
        ) + total_games_played * 8  # estimate 8 choices per game

        # Aggregate dimension improvements
        improved_count = 0
        for p in profiles.values():
            ps = p.get("psychological_scores", {})
            if any(d.get("count", 0) >= 3 for d in ps.values() if isinstance(d, dict)):
                improved_count += 1

        avg_empathy_improvement = 0
        empathy_users = 0
        for p in profiles.values():
            ps = p.get("psychological_scores", {})
            emp = ps.get("empathy", {})
            if isinstance(emp, dict) and emp.get("count", 0) >= 2:
                avg_score = emp["total"] / emp["count"]
                if avg_score > 50:
                    avg_empathy_improvement += (avg_score - 50)
                    empathy_users += 1

        return jsonify({
            "total_users": total_users,
            "total_games_played": total_games_played,
            "total_decisions": total_decisions,
            "total_game_titles": len(GAMES),
            "students_improved": improved_count,
            "avg_empathy_lift": round(avg_empathy_improvement / max(1, empathy_users), 1),
            "dimensions_tracked": 8,
            "nep_aligned_games": sum(1 for g in GAMES.values() if g.get("nep_competencies")),
        })
    except Exception as e:
        logger.error(f"Impact stats error: {e}")
        return jsonify({"total_users": 0, "total_games_played": 0, "total_decisions": 0})


@app.get("/api/family/children/<child_id>/assignments")
@require_auth
def family_child_assignments(child_id):
    """Parent endpoint: return assignments for a linked child."""
    parent_id = request.current_user.get("user_id")
    # Verify parent link
    links_data = _load_family_links()
    link = next((l for l in links_data.get("links", []) if l.get("parent_id") == parent_id and l.get("child_id") == child_id), None)
    if not link:
        return jsonify({"error": "Child not linked to this account"}), 403
    # Load assignments filtered to this child
    try:
        _asgn_file = os.path.join(os.path.dirname(__file__), "data", "assignments.json")
        with open(_asgn_file) as _f:
            _asgn_data = json.load(_f)
        assignments = _asgn_data if isinstance(_asgn_data, list) else _asgn_data.get("assignments", [])
        child_assignments = [a for a in assignments if child_id in (a.get("students") or [])]
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        child_assignments = []
    return jsonify({"assignments": child_assignments})


# ---------- Uploads ----------
@app.get("/uploads/<path:path>")
def serve_uploads(path):
    """Serve uploaded files (with path traversal protection)."""
    upload_folder = os.getenv("UPLOAD_FOLDER", "uploads")
    uploads_path = os.path.realpath(os.path.join(os.path.dirname(__file__), "..", upload_folder))
    # Resolve the requested file path and ensure it stays within uploads directory
    requested = os.path.realpath(os.path.join(uploads_path, path))
    if not requested.startswith(uploads_path + os.sep) and requested != uploads_path:
        return jsonify({"error": "Forbidden"}), 403
    return send_from_directory(uploads_path, path)


# ---------- Analytics ----------
@app.get("/api/analytics/overview")
@require_admin_or_school_admin
def analytics_overview():
    """Get real analytics overview from leaderboard and session data."""
    from game_storage import list_all_games, load_game
    from storage import get_leaderboard
    from auth import _load_users

    game_ids = list_all_games()
    total_plays = 0
    unique_users = set()
    total_score_sum = 0
    per_game_stats = []

    for gid in game_ids:
        game_data = load_game(gid)
        try:
            lb = get_leaderboard(gid, limit=10000)
        except Exception:
            lb = {"entries": []}
        entries = lb.get("entries", [])
        game_plays = len(entries)
        total_plays += game_plays

        for entry in entries:
            unique_users.add(entry.get("user_id", ""))
            total_score_sum += entry.get("achievement_score", 0)

        per_game_stats.append({
            "game_id": gid,
            "title": game_data.get("title", gid) if game_data else gid,
            "total_plays": game_plays,
            "avg_score": round(
                sum(e.get("achievement_score", 0) for e in entries) / max(len(entries), 1), 1
            ),
            "rounds_count": len(game_data.get("rounds", [])) if game_data else 0,
        })

    users = _load_users()
    user_count = len([u for u in users if u.get("role") != "admin"])

    return jsonify({
        "total_plays": total_plays,
        "total_users": user_count or len(unique_users),
        "average_score": round(total_score_sum / max(total_plays, 1), 1),
        "completion_rate": 100 if total_plays > 0 else 0,
        "total_games": len(game_ids),
        "per_game_stats": sorted(per_game_stats, key=lambda x: x["total_plays"], reverse=True),
    })


@app.get("/api/analytics/game/<game_id>")
@require_admin
def game_analytics(game_id):
    """Get analytics for a specific game."""
    from game_storage import load_game
    from storage import get_leaderboard

    game_data = load_game(game_id)
    if not game_data:
        return jsonify({"error": "Game not found"}), 404

    try:
        lb = get_leaderboard(game_id, limit=10000)
    except Exception:
        lb = {"entries": []}
    entries = lb.get("entries", [])

    score_ranges = {"0-20": 0, "21-40": 0, "41-60": 0, "61-80": 0, "81-100": 0}
    for entry in entries:
        score = entry.get("achievement_score", 0)
        if score <= 20:
            score_ranges["0-20"] += 1
        elif score <= 40:
            score_ranges["21-40"] += 1
        elif score <= 60:
            score_ranges["41-60"] += 1
        elif score <= 80:
            score_ranges["61-80"] += 1
        else:
            score_ranges["81-100"] += 1

    return jsonify({
        "game_id": game_id,
        "title": game_data.get("title", game_id),
        "total_plays": len(entries),
        "avg_score": round(
            sum(e.get("achievement_score", 0) for e in entries) / max(len(entries), 1), 1
        ),
        "top_score": max((e.get("achievement_score", 0) for e in entries), default=0),
        "score_distribution": score_ranges,
        "rounds_count": len(game_data.get("rounds", [])),
    })


@app.post("/api/admin/generate-story")
@require_admin
def admin_generate_story():
    """Use LLM to generate story/narrative content for a round."""
    try:
        payload = request.get_json(silent=True) or {}
        round_theme = payload.get('theme', 'business challenge')
        target_age = payload.get('age', '10-14')
        tone = payload.get('tone', 'educational and fun')

        if not llm_enabled():
            return jsonify({"error": "LLM not enabled"}), 400

        prompt = f"""Create an engaging story scenario for a business simulation game for students aged {target_age}.

Theme: {round_theme}
Tone: {tone}

Generate a JSON with:
{{
  "title": "Scenario title (5-8 words)",
  "story": "Narrative description (2-3 sentences, vivid and engaging)",
  "goal": "What the student needs to achieve (1 sentence)",
  "setting": "Where this takes place (1 sentence)",
  "challenge": "The main problem/opportunity (1 sentence)"
}}

Make it educational, age-appropriate, and exciting!"""

        story_data = llm_call(
            system_prompt="You are a creative educational content writer. Return ONLY valid JSON.",
            user_prompt=prompt,
            temperature=0.8,
            max_tokens=300,
            purpose="admin_generate_story",
            fallback={"error": "Story generation failed"},
        )
        return jsonify(story_data)

    except Exception as e:
        logger.info(f"Story generation error: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


# ---------- AI Proxy Endpoints ----------
@app.post("/api/ai/generate-image")
@require_admin
def ai_generate_image():
    """Proxy DALL-E 3 image generation through the backend."""
    try:
        from llm import llm_enabled, _client

        if not llm_enabled():
            return jsonify({"error": "AI features are not enabled"}), 400

        payload = request.get_json(silent=True)
        if not payload:
            return jsonify({"error": "Invalid request body"}), 400
        prompt = payload.get("prompt", "")
        size = payload.get("size", "1024x1024")
        style = payload.get("style", "vivid")

        if not prompt:
            return jsonify({"error": "prompt is required"}), 400

        client = _client()
        resp = client.images.generate(
            model="dall-e-3",
            prompt=prompt,
            n=1,
            size=size,
            style=style,
        )

        image_url = resp.data[0].url
        try:
            from cost_tracker import log_cost
            log_cost("image", "dall-e-3", purpose="image_generate", size=size)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        return jsonify({"image_url": image_url})

    except Exception as e:
        logger.info(f"Image generation error: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


# ---------- Story Image Generation (DALL-E 3 + Mento Mascot) ----------

@app.get("/api/games/<game_id>/rounds/<round_id>/story-image")
def get_story_image(game_id, round_id):
    """On-demand story image generation for a specific round. No auth required."""
    from game_storage import load_game
    from services.story_image_service import check_cached, generate_story_image, get_pollinations_fallback

    # Check cache first (fast path)
    cached_url = check_cached(game_id, round_id)
    if cached_url:
        return jsonify({"image_url": cached_url, "cached": True})

    # Load game and find round
    game = load_game(game_id)
    if not game:
        return jsonify({"error": "Game not found"}), 404

    target_round = None
    for idx, rnd in enumerate(game.get("rounds", [])):
        # Match by id, round_id, or index-based key (round_1, round_2, etc.)
        rnd_id = str(rnd.get("id", ""))
        rnd_round_id = str(rnd.get("round_id", ""))
        rnd_index_key = f"round_{idx + 1}"
        if str(round_id) in (rnd_id, rnd_round_id, rnd_index_key):
            target_round = rnd
            break

    if not target_round:
        return jsonify({"error": "Round not found"}), 404

    image_prompt = target_round.get("image_prompt", "") or target_round.get("ai_image_prompt", "")
    scene_hint = target_round.get("scene_hint")

    if not image_prompt and not scene_hint:
        # Derive from any available text: scenario/situation/story/title
        ai_cfg = game.get("ai_image_config", {})
        if ai_cfg.get("generate_on_first_play") is not False:
            text = (
                target_round.get("scenario") or
                target_round.get("situation") or
                target_round.get("story") or
                target_round.get("title") or
                ""
            ).strip()
            if text:
                style = ai_cfg.get("style", "educational illustration, vibrant colors, soft lighting")
                image_prompt = f"{text[:180]} — {style}"
        if not image_prompt and not scene_hint:
            return jsonify({"error": "No image prompt could be derived for this round"}), 404

    # Pass game-level image config for style-aware generation
    ai_cfg = game.get("ai_image_config", {})
    dalle_style = ai_cfg.get("dalle_style", "vivid")  # vivid or natural
    image_style = ai_cfg.get("image_style", "cartoon")  # cartoon/semi-realistic/realistic/watercolor

    result = generate_story_image(
        game_id=game_id,
        round_id=round_id,
        image_prompt=image_prompt,
        scene_hint=scene_hint,
        style=dalle_style,
        image_style=image_style,
    )
    return jsonify(result)


@app.get("/api/games/<game_id>/scenes/<scene_id>/story-image")
def get_scene_story_image(game_id, scene_id):
    """On-demand story image generation for a story_branching scene. No auth required."""
    from game_storage import load_game
    from services.story_image_service import check_cached, generate_story_image

    cached_url = check_cached(game_id, scene_id)
    if cached_url:
        return jsonify({"image_url": cached_url, "cached": True})

    game = load_game(game_id)
    if not game:
        return jsonify({"error": "Game not found"}), 404

    scene_map = _build_story_scene_map(game)
    scene = scene_map.get(scene_id)
    if not scene:
        return jsonify({"error": "Scene not found"}), 404

    image_prompt = scene.get("image_prompt", "")
    if not image_prompt:
        return jsonify({"error": "No image_prompt for this scene"}), 404

    result = generate_story_image(
        game_id=game_id,
        round_id=scene_id,
        image_prompt=image_prompt,
    )
    return jsonify(result)


@app.post("/api/admin/games/<game_id>/rounds/<round_id>/regenerate-image")
@require_admin
def admin_regenerate_story_image(game_id, round_id):
    """Admin: regenerate a specific round's story image (force overwrite cache)."""
    from game_storage import load_game
    from services.story_image_service import generate_story_image

    game = load_game(game_id)
    if not game:
        return jsonify({"error": "Game not found"}), 404

    target_round = None
    for rnd in game.get("rounds", []):
        if str(rnd.get("id")) == str(round_id):
            target_round = rnd
            break

    if not target_round:
        return jsonify({"error": "Round not found"}), 404

    image_prompt = target_round.get("image_prompt", "")
    scene_hint = target_round.get("scene_hint")

    result = generate_story_image(
        game_id=game_id,
        round_id=round_id,
        image_prompt=image_prompt,
        scene_hint=scene_hint,
        force=True,
    )
    return jsonify(result)


# Background job tracking for board story generation
_board_story_jobs = {}  # job_id -> { status, game_id, progress, result, error }

def _run_board_story_generation(job_id, game_id, generate_images, overwrite):
    """Background worker for board story generation."""
    import copy
    try:
        from game_storage import load_game, save_game

        _board_story_jobs[job_id]["status"] = "generating_stories"
        _board_story_jobs[job_id]["progress"] = "Loading game data..."

        game = load_game(game_id)
        if not game:
            _board_story_jobs[job_id]["status"] = "failed"
            _board_story_jobs[job_id]["error"] = "Game not found"
            return

        board_config = game.get("board_config", {})
        tiles = board_config.get("tiles", [])
        existing_events = game.get("events", {})
        glossary = game.get("glossary", {})

        event_tiles = []
        for idx, tile in enumerate(tiles):
            event_id = tile.get("event_id")
            if not event_id:
                continue
            existing = existing_events.get(event_id, {})
            if existing.get("ai_generated") and not overwrite:
                continue
            event_tiles.append({
                "event_id": event_id,
                "tile_type": tile.get("type", "event"),
                "tile_label": tile.get("label", ""),
                "position_index": idx,
            })

        if not event_tiles:
            _board_story_jobs[job_id]["status"] = "completed"
            _board_story_jobs[job_id]["result"] = {
                "message": "All tiles already have AI stories.",
                "generated": 0, "images_generated": 0,
            }
            return

        _board_story_jobs[job_id]["progress"] = f"Generating stories for {len(event_tiles)} tiles..."
        _board_story_jobs[job_id]["total_tiles"] = len(event_tiles)

        game_title = game.get("title", "Board Game")
        game_theme = game.get("theme", game.get("description", ""))

        generated_events = generate_board_narrative_batch(
            game_title=game_title,
            game_theme=game_theme,
            tiles_info=event_tiles,
            existing_events=existing_events,
            glossary_terms=list(glossary.keys()),
        )

        if not generated_events:
            _board_story_jobs[job_id]["status"] = "failed"
            _board_story_jobs[job_id]["error"] = "AI story generation returned no results"
            return

        _board_story_jobs[job_id]["stories_generated"] = len(generated_events)
        _board_story_jobs[job_id]["progress"] = f"Generated {len(generated_events)} stories. Starting image generation..."

        # Merge into events
        for event_id, event_data in generated_events.items():
            original = existing_events.get(event_id, {})
            event_data["original_event"] = {
                "title": original.get("title", ""),
                "description": original.get("description", ""),
            }
            existing_events[event_id] = event_data

        # Generate images
        images_generated = 0
        images_failed = 0
        if generate_images:
            _board_story_jobs[job_id]["status"] = "generating_images"
            try:
                from services.story_image_service import generate_story_image
                total = len(generated_events)
                for i, (event_id, event_data) in enumerate(generated_events.items()):
                    _board_story_jobs[job_id]["progress"] = f"Generating image {i+1}/{total}: {event_id}"
                    try:
                        image_prompt = (
                            f"{game_title}: {event_data.get('title', '')} - "
                            f"{event_data.get('story', '')[:120]}"
                        )
                        result = generate_story_image(game_id, event_id, image_prompt=image_prompt, force=True)
                        if isinstance(result, dict) and result.get("image_url"):
                            event_data["image_url"] = result["image_url"]
                            existing_events[event_id] = event_data
                            images_generated += 1
                        elif isinstance(result, dict) and result.get("fallback_url"):
                            event_data["image_url"] = result["fallback_url"]
                            existing_events[event_id] = event_data
                            images_generated += 1
                        else:
                            images_failed += 1
                    except Exception as img_err:
                        logger.info(f"[BoardStory] Image failed for {event_id}: {img_err}")
                        images_failed += 1
            except ImportError:
                logger.info("[BoardStory] story_image_service not available")
        # Save
        _board_story_jobs[job_id]["progress"] = "Saving game data..."
        game["events"] = existing_events
        if "board_config" not in game:
            game["board_config"] = {}
        game["board_config"]["ai_stories_enabled"] = True
        save_game(game)
        GAMES[game_id] = game

        _board_story_jobs[job_id]["status"] = "completed"
        _board_story_jobs[job_id]["result"] = {
            "message": f"Generated {len(generated_events)} stories with {images_generated} images",
            "generated": len(generated_events),
            "images_generated": images_generated,
            "images_failed": images_failed,
            "event_ids": list(generated_events.keys()),
        }
    except Exception as e:
        _board_story_jobs[job_id]["status"] = "failed"
        _board_story_jobs[job_id]["error"] = str(e)
        import traceback
        traceback.print_exc()


@app.post("/api/admin/games/<game_id>/generate-board-stories")
@require_admin
def admin_batch_generate_board_stories(game_id):
    """Admin: kick off background batch-generation of AI narrative + images for board game tiles.

    Returns a job_id immediately. Poll /api/admin/board-story-job/<job_id> for progress.
    """
    import threading, uuid
    from game_storage import load_game

    game = load_game(game_id)
    if not game:
        return jsonify({"error": "Game not found"}), 404
    if game.get("game_type") != "board":
        return jsonify({"error": "Not a board game"}), 400

    # Check for already running job for this game
    for jid, job in _board_story_jobs.items():
        if job.get("game_id") == game_id and job.get("status") in ("generating_stories", "generating_images"):
            return jsonify({"job_id": jid, "status": job["status"], "progress": job.get("progress", ""),
                            "message": "Generation already in progress"}), 200

    data = request.get_json(silent=True) or {}
    generate_images = data.get("generate_images", True)
    overwrite = data.get("overwrite", False)

    job_id = str(uuid.uuid4())[:8]
    _board_story_jobs[job_id] = {
        "status": "starting",
        "game_id": game_id,
        "progress": "Starting...",
        "result": None,
        "error": None,
    }

    thread = threading.Thread(
        target=_run_board_story_generation,
        args=(job_id, game_id, generate_images, overwrite),
        daemon=True,
    )
    thread.start()

    return jsonify({"job_id": job_id, "status": "starting", "message": "Generation started in background"})


@app.get("/api/admin/board-story-job/<job_id>")
@require_admin
def admin_board_story_job_status(job_id):
    """Check progress of a board story generation job."""
    job = _board_story_jobs.get(job_id)
    if not job:
        return jsonify({"error": "Job not found"}), 404
    return jsonify(job)


def _run_scenario_image_generation(job_id, game_type, generate_images, overwrite):
    """Background worker for negotiation/debate storybook image generation."""
    try:
        from game_storage import (
            load_negotiation_game, save_negotiation_game,
            load_debate_scenarios, save_debate_scenarios,
            load_investor_pitch, save_investor_pitch,
            load_session_game as _load_sess, save_session_game as _save_sess,
        )

        _board_story_jobs[job_id]["status"] = "generating_images"
        _board_story_jobs[job_id]["progress"] = f"Loading {game_type} scenarios..."

        if game_type == "negotiation":
            game_data = load_negotiation_game()
            file_key = "negotiation_game"
        elif game_type == "pitch":
            game_data = load_investor_pitch()
            file_key = "investor_pitch_game"
        elif game_type in VALID_SESSION_TYPES:
            game_data = _load_sess(game_type)
            file_key = "session_game"
        else:
            game_data = load_debate_scenarios()
            file_key = "debate_game"

        if not game_data:
            _board_story_jobs[job_id]["status"] = "failed"
            _board_story_jobs[job_id]["error"] = f"{game_type} game data not found"
            return

        scenarios = game_data.get("scenarios", [])
        if not scenarios:
            _board_story_jobs[job_id]["status"] = "failed"
            _board_story_jobs[job_id]["error"] = "No scenarios found"
            return

        # Count total pages that need images
        pages_to_process = []
        for s_idx, scenario in enumerate(scenarios):
            for p_idx, page in enumerate(scenario.get("storybook_pages", [])):
                if page.get("image_url") and not overwrite:
                    continue
                if not page.get("image_prompt"):
                    continue
                pages_to_process.append((s_idx, p_idx, scenario["scenario_id"], page))

        if not pages_to_process:
            _board_story_jobs[job_id]["status"] = "completed"
            _board_story_jobs[job_id]["result"] = {
                "message": "All storybook pages already have images.",
                "images_generated": 0, "images_failed": 0,
            }
            return

        total = len(pages_to_process)
        _board_story_jobs[job_id]["total_tiles"] = total
        _board_story_jobs[job_id]["progress"] = f"Generating images for {total} storybook pages..."

        images_generated = 0
        images_failed = 0

        if generate_images:
            try:
                from services.story_image_service import generate_story_image
                for i, (s_idx, p_idx, scenario_id, page) in enumerate(pages_to_process):
                    _board_story_jobs[job_id]["progress"] = f"Image {i+1}/{total}: {scenario_id} page {p_idx+1}"
                    try:
                        game_id_for_cache = f"{game_type}_{scenario_id}"
                        round_id_for_cache = f"storybook_p{p_idx}"
                        result = generate_story_image(
                            game_id_for_cache, round_id_for_cache,
                            image_prompt=page["image_prompt"],
                            force=overwrite,
                        )
                        url = None
                        if isinstance(result, dict):
                            url = result.get("image_url") or result.get("fallback_url")
                        if url:
                            scenarios[s_idx]["storybook_pages"][p_idx]["image_url"] = url
                            images_generated += 1
                        else:
                            images_failed += 1
                    except Exception as img_err:
                        logger.info(f"[ScenarioImg] Image failed for {scenario_id} p{p_idx}: {img_err}")
                        images_failed += 1
            except ImportError:
                logger.info("[ScenarioImg] story_image_service not available")
        # Save back — must re-wrap with file key since save writes raw JSON
        _board_story_jobs[job_id]["progress"] = "Saving scenario data..."
        game_data["scenarios"] = scenarios
        file_data = {file_key: game_data}

        if game_type == "negotiation":
            save_negotiation_game(file_data, create_backup=True)
        elif game_type == "pitch":
            save_investor_pitch(file_data, create_backup=True)
        elif game_type in VALID_SESSION_TYPES:
            _save_sess(game_type, {"session_game": game_data}, create_backup=True)
        else:
            save_debate_scenarios(file_data, create_backup=True)

        # Reload into memory
        global NEGOTIATION_GAME, DEBATE_GAME, INVESTOR_PITCH_GAME, SESSION_GAMES
        if game_type == "negotiation":
            NEGOTIATION_GAME = game_data
        elif game_type == "pitch":
            INVESTOR_PITCH_GAME = game_data
        elif game_type in VALID_SESSION_TYPES:
            SESSION_GAMES[game_type] = game_data
        else:
            DEBATE_GAME = game_data

        _board_story_jobs[job_id]["status"] = "completed"
        _board_story_jobs[job_id]["result"] = {
            "message": f"Generated {images_generated} images for {game_type} storybook pages",
            "images_generated": images_generated,
            "images_failed": images_failed,
            "total_pages": total,
        }
    except Exception as e:
        _board_story_jobs[job_id]["status"] = "failed"
        _board_story_jobs[job_id]["error"] = str(e)
        import traceback
        traceback.print_exc()


@app.post("/api/admin/generate-scenario-stories")
@require_admin
def admin_batch_generate_scenario_images():
    """Admin: kick off background DALL-E image generation for negotiation/debate storybook pages.

    Returns a job_id immediately. Poll /api/admin/board-story-job/<job_id> for progress.
    """
    import threading, uuid

    data = request.get_json(silent=True) or {}
    game_type = data.get("game_type", "")
    valid_types = {"negotiation", "debate", "pitch"} | VALID_SESSION_TYPES
    if game_type not in valid_types:
        return jsonify({"error": f"game_type must be one of: {', '.join(sorted(valid_types))}"}), 400

    generate_images = data.get("generate_images", True)
    overwrite = data.get("overwrite", False)

    # Check for already running job
    for jid, job in _board_story_jobs.items():
        if job.get("game_type") == game_type and job.get("status") in ("generating_images",):
            return jsonify({"job_id": jid, "status": job["status"], "progress": job.get("progress", ""),
                            "message": "Generation already in progress"}), 200

    job_id = str(uuid.uuid4())[:8]
    _board_story_jobs[job_id] = {
        "status": "starting",
        "game_type": game_type,
        "progress": "Starting...",
        "result": None,
        "error": None,
    }

    thread = threading.Thread(
        target=_run_scenario_image_generation,
        args=(job_id, game_type, generate_images, overwrite),
        daemon=True,
    )
    thread.start()

    return jsonify({"job_id": job_id, "status": "starting", "message": f"Image generation started for {game_type}"})


@app.get("/api/featured-scenario")
def get_featured_scenario():
    """Get the featured scenario of the day (rotates daily)."""
    from datetime import date

    all_scenarios = []

    if NEGOTIATION_GAME:
        for s in NEGOTIATION_GAME.get("scenarios", []):
            first_image = None
            for p in s.get("storybook_pages", []):
                if p.get("image_url"):
                    first_image = p["image_url"]
                    break
            all_scenarios.append({
                "game_type": "negotiation",
                "scenario_id": s["scenario_id"],
                "title": s["title"],
                "description": s["description"],
                "difficulty": s.get("difficulty", "beginner"),
                "image_url": first_image,
            })

    if DEBATE_GAME:
        for s in DEBATE_GAME.get("scenarios", []):
            first_image = None
            for p in s.get("storybook_pages", []):
                if p.get("image_url"):
                    first_image = p["image_url"]
                    break
            all_scenarios.append({
                "game_type": "debate",
                "scenario_id": s["scenario_id"],
                "title": s["title"],
                "description": s["description"],
                "difficulty": s.get("difficulty", "beginner"),
                "image_url": first_image,
            })

    if INVESTOR_PITCH_GAME:
        for s in INVESTOR_PITCH_GAME.get("scenarios", []):
            first_image = None
            for p in s.get("storybook_pages", []):
                if p.get("image_url"):
                    first_image = p["image_url"]
                    break
            all_scenarios.append({
                "game_type": "pitch",
                "scenario_id": s["scenario_id"],
                "title": s["title"],
                "description": s["description"],
                "difficulty": s.get("difficulty", "beginner"),
                "image_url": first_image,
            })

    # Add session game scenarios
    for gt, gd in SESSION_GAMES.items():
        for s in gd.get("scenarios", []):
            first_image = None
            for p in s.get("storybook_pages", []):
                if p.get("image_url"):
                    first_image = p["image_url"]
                    break
            all_scenarios.append({
                "game_type": gt,
                "scenario_id": s["scenario_id"],
                "title": s["title"],
                "description": s["description"],
                "difficulty": s.get("difficulty", "beginner"),
                "image_url": first_image,
            })

    if not all_scenarios:
        return jsonify({"featured": None})

    day_index = date.today().toordinal() % len(all_scenarios)
    return jsonify({"featured": all_scenarios[day_index], "total_scenarios": len(all_scenarios)})


