@app.post("/api/admin/layout-templates")
@require_admin
def save_layout_template():
    """Save or update a layout template."""
    try:
        payload = request.get_json(silent=True)
        if not payload:
            return jsonify({"error": "Invalid request body"}), 400
        raw_template = payload.get('template')
        
        if not raw_template:
            return jsonify({"error": "Invalid template data"}), 400

        new_template = _normalize_layout_template(raw_template)

        if not new_template or not new_template.get('id') or not new_template.get('layout_type'):
            return jsonify({"error": "Invalid template data"}), 400
        
        templates = load_layout_templates()
        
        # Check if template exists (update) or is new (create)
        existing_index = next((i for i, t in enumerate(templates) if t['id'] == new_template['id']), None)
        
        if existing_index is not None:
            templates[existing_index] = new_template
        else:
            templates.append(new_template)
        
        save_layout_templates(templates)
        return jsonify({"success": True, "message": "Template saved"})
    
    except Exception as e:
        logger.info(f"Error saving layout template: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


