@require_admin
def delete_layout_template(template_id):
    """Delete a layout template."""
    try:
        # Prevent deletion of default templates
        if template_id in ['classic', 'minimal', 'journey']:
            return jsonify({"error": "Cannot delete default templates"}), 400
        
        templates = load_layout_templates()
        templates = [t for t in templates if t['id'] != template_id]
        save_layout_templates(templates)
        
        return jsonify({"success": True, "message": "Template deleted"})
    
    except Exception as e:
        logger.info(f"Error deleting layout template: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


@app.post("/api/voice/ask-mento")
@limiter.limit("20 per minute")
def voice_ask_mento():
    """Voice-powered conversation with Coach Mento AI Agent."""
    try:
        from llm import coach_mento_agent, llm_enabled
        
        payload = request.get_json(silent=True)
        if not payload:
            return jsonify({"error": "Invalid request body"}), 400
        question = payload.get('question', '')
        game_context = payload.get('game_context', None)
        
        if not question:
            return jsonify({"error": "No question provided"}), 400
        
        # Use AI agent with full context (with timeout to prevent locks)
        import signal
        
        def timeout_handler(signum, frame):
            raise TimeoutError("LLM request timed out")
        
        # Set 10 second timeout
        signal.signal(signal.SIGALRM, timeout_handler)
        signal.alarm(10)
        
        try:
            result = coach_mento_agent(question, game_context)
            signal.alarm(0)  # Cancel alarm
        except TimeoutError:
            signal.alarm(0)
            raise Exception("Request timeout")

        # A1: Persist tip_id for RL bandit outcome recording at /report
        _tip_id = result.pop("_tip_id", None)
        _voice_run_id = (game_context or {}).get("run_id") if game_context else None
        if _tip_id and _voice_run_id:
            try:
                _r = RUNS.get(_voice_run_id) or get_run(_voice_run_id)
                if _r:
                    _r["_coaching_tip_id"] = _tip_id
                    update_run(_voice_run_id, _r)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        return jsonify(result)
        
    except Exception as e:
        logger.info(f"Voice LLM error: {e}")
        return jsonify({
            "response": "I'm Coach Mento, and I'm here to guide you! What would you like to explore?",
            "action": None,
            "action_params": {}
        })


