@require_admin
def admin_generate_concepts():
    """AI-generate structured concepts for a discussion topic."""
    data = request.get_json(force=True)
    topic = data.get("topic", "").strip()
    count = min(data.get("count", 6), 10)
    if not topic:
        return jsonify({"error": "topic is required"}), 400
    try:
        from llm import llm_call
        result = llm_call(
            system_prompt="Generate structured learning concepts for an educational discussion game. Return JSON.",
            user_prompt=f'Generate {count} key concepts for the topic: "{topic}". Return JSON: {{"concepts": [{{"id": "snake_case_id", "title": "Short Title", "definition": "1-2 sentence definition", "formula": "Formula if applicable, else empty string"}}]}}',
            temperature=0.5,
            max_tokens=800,
            purpose="admin_generate_concepts",
        )
        return jsonify(result if isinstance(result, dict) and "concepts" in result else {"concepts": []})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


