@app.get("/api/admin/users")
@require_admin_or_school_admin
def admin_list_users():
    """List users. school_admin sees only their org's users; admin sees all."""
    import math as _math
    page = max(1, int(request.args.get("page", 1)))
    per_page = min(200, max(1, int(request.args.get("per_page", 50))))
    from auth import _load_users
    users = _load_users()
    # Scope to org for school_admin
    caller = request.current_user
    if caller.get("role") == "school_admin":
        org_id = caller.get("org_id", "default")
        users = [u for u in users if u.get("org_id", "default") == org_id]
    safe_users = []
    for u in users:
        safe_users.append({
            "id": u.get("id"),
            "username": u.get("username"),
            "role": u.get("role", "student"),
            "org_id": u.get("org_id", "default"),
            "created_at": u.get("created_at", "")
        })
    total = len(safe_users)
    start = (page - 1) * per_page
    safe_users_page = safe_users[start:start + per_page]
    return jsonify({"users": safe_users_page, "total": total, "page": page, "per_page": per_page, "pages": _math.ceil(total / per_page) if total else 1})


@app.delete("/api/admin/users/<user_id>")
@require_admin
def admin_delete_user(user_id):
    """Delete a user by id (admin only). Cannot delete self."""
    if user_id == request.current_user.get("user_id"):
        return jsonify({"error": "Cannot delete your own account"}), 400
    from auth import _load_users, _save_users
    users = _load_users()
    original_len = len(users)
    users = [u for u in users if u.get("id") != user_id]
    if len(users) == original_len:
        return jsonify({"error": "User not found"}), 404
    _save_users(users)
    return jsonify({"message": f"User {user_id} deleted"})


@app.put("/api/admin/users/<user_id>/role")
@require_admin
def admin_update_user_role(user_id):
    """Update a user's role (admin only)."""
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid request body"}), 400
    new_role = data.get("role", "").strip()
    if new_role not in ("student", "teacher", "parent", "admin", "trainer", "school_admin", "hr"):
        return jsonify({"error": "Invalid role"}), 400
    from auth import _load_users, _save_users
    users = _load_users()
    user = next((u for u in users if u.get("id") == user_id), None)
    if not user:
        return jsonify({"error": "User not found"}), 404
    user["role"] = new_role
    _save_users(users)
    return jsonify({"message": f"User {user_id} role updated to {new_role}", "user": {"id": user["id"], "username": user["username"], "role": new_role}})


