@app.get("/<path:path>")
@nocache
def serve_static(path):
    """Serve static files from frontend, fallback to index.html for SPA routes."""
    import os as _os
    # Return proper 404 for unmatched API paths
    if path.startswith("api/"):
        return jsonify({"error": "Endpoint not found", "path": f"/{path}"}), 404
    static_file = _os.path.join(FRONTEND_DIR, path)
    if _os.path.isfile(static_file):
        return send_from_directory(FRONTEND_DIR, path)
    # SPA fallback: return index.html for client-side routes
    return send_from_directory(FRONTEND_DIR, "index.html")


@app.post("/api/character/dialogue")
def character_dialogue():
    """Handle interactive dialogue with competitor characters."""
    payload = request.get_json(silent=True) or {}

    character_id = payload.get("character_id", "")
    user_message = payload.get("user_message", "")
    round_num = payload.get("round", 1)
    char_context = payload.get("character_context", {})
    conversation_history = payload.get("conversation_history", [])
    game_state = payload.get("game_state", {})

    if not llm_enabled():
        fallback_responses = {
            "riya": "That's interesting! My cupcakes are doing well so far. Competition is tough though!",
            "arjun": "I'm analyzing the market data. Numbers don't lie! How's your ROI looking?",
            "meera": "Each product tells a story. What story are you telling with your business?",
            "mento": "Great question! What do YOU think is the best approach here?"
        }
        return jsonify({
            "response": fallback_responses.get(character_id, "Interesting point!"),
            "mood": "neutral",
            "relationship_change": 0
        })

    personality = char_context.get("personality", "")
    backstory = char_context.get("backstory", "")
    current_story = char_context.get("current_story", "")
    mood = char_context.get("mood", "neutral")

    system_prompt = f"""You are {character_id.title()}, a character in an entrepreneurship game.

Your Profile:
- Personality: {personality}
- Backstory: {backstory}
- Current mood: {mood}
- What you're doing this round: {current_story}

Current game context:
- Round: {round_num}
- User's stats: {game_state}

Guidelines:
1. Stay in character - respond as {character_id.title()} would
2. Reference your current business decisions and strategy
3. Be friendly but competitive
4. Ask questions to engage the user
5. Show personality through your responses
6. Keep responses concise (2-3 sentences)
7. React to user's game state (congratulate if doing well, empathize if struggling)
8. Build continuity - remember previous conversations

Mood affects your tone:
- happy: Enthusiastic, energetic
- worried: Concerned, cautious
- competitive: Driven, ambitious
- neutral: Balanced, thoughtful
"""

    conv_history = []
    for msg in conversation_history[-5:]:
        role = "user" if msg["role"] == "user" else "assistant"
        conv_history.append({"role": role, "content": msg["content"]})

    response_text = llm_call(
        system_prompt=system_prompt,
        user_prompt=user_message,
        response_json=False,
        temperature=0.8,
        max_tokens=150,
        conversation_history=conv_history,
        purpose="character_dialogue",
        fallback="I'm thinking about my strategy... What's yours?",
    )

    # Analyze sentiment to update mood and relationship
    mood_update = mood
    relationship_change = 0
    positive_words = ["great", "awesome", "nice", "good", "love", "excellent"]
    negative_words = ["bad", "terrible", "hate", "awful", "poor"]
    user_lower = user_message.lower()
    if any(word in user_lower for word in positive_words):
        relationship_change = 5
        mood_update = "happy"
    elif any(word in user_lower for word in negative_words):
        relationship_change = -3
        mood_update = "worried"

    return jsonify({
        "response": response_text,
        "mood": mood_update,
        "relationship_change": relationship_change
    })



