@app.post("/api/negotiation/start")
def negotiation_start():
    """Start a negotiation scenario (curated or custom)."""
    payload = request.get_json(silent=True) or {}
    scenario_id = payload.get("scenario_id", "")
    custom_negotiation = payload.get("custom_negotiation")

    if not NEGOTIATION_GAME:
        return jsonify({"error": "Negotiation game not found"}), 404

    if custom_negotiation:
        # Custom scenario from generate-context
        scenario = {
            "scenario_id": "custom_negotiation",
            "title": custom_negotiation.get("title", "Your Negotiation"),
            "description": custom_negotiation.get("description", ""),
            "setting": custom_negotiation.get("setting", "A professional meeting room."),
            "cultural_context": custom_negotiation.get("cultural_context", "Indian professional context"),
            "your_objective": custom_negotiation.get("your_objective", "Reach a good agreement."),
            "your_batna": custom_negotiation.get("your_batna", "Walk away if terms are bad."),
            "other_party": custom_negotiation.get("other_party", {"name": "AI", "role": "Counterpart", "personality": "Firm but fair", "objective": "Best deal", "avatar_emoji": "🤝"}),
            "conversation_turns": custom_negotiation.get("conversation_turns", 8),
            "phases": custom_negotiation.get("phases", ["Opening", "Exploration", "Bargaining", "Closing"]),
            "coaching_tips": [],
            "storybook_pages": [],
        }
    else:
        scenario = next((s for s in NEGOTIATION_GAME["scenarios"] if s["scenario_id"] == scenario_id), None)
        if not scenario:
            return jsonify({"error": "Invalid scenario_id"}), 400

    # Create run with negotiation-specific state
    initial_state = NEGOTIATION_GAME["initial_state"].copy()
    run_id = create_run("negotiation", initial_state)

    # Store scenario_id in run metadata
    r = get_run(run_id)
    r["scenario_id"] = scenario.get("scenario_id", "custom_negotiation")
    r["conversation_history"] = []
    r["current_turn"] = 0

    # Persist changes
    update_run(run_id, r)

    # Generate an AI greeting using the LLM
    other_party = scenario.get("other_party", {})
    ai_greeting = None
    try:
        greeting_result = negotiation_ai_response(
            user_message="[The student has just arrived. Greet them and open the negotiation naturally, staying in character.]",
            scenario_data=scenario,
            conversation_history=[],
            current_turn=0,
            state=initial_state,
            scores_history=[],
            coaching_tone=game.get("coaching_tone", "supportive")
        )
        ai_greeting = greeting_result.get("response", "")
        if ai_greeting:
            r["conversation_history"] = [{
                "turn": 0,
                "speaker": other_party.get("name", "AI"),
                "message": ai_greeting
            }]
            update_run(run_id, r)
    except Exception as e:
        logger.warning(f"Failed to generate negotiation greeting: {e}")
    return jsonify({
        "run_id": run_id,
        "scenario": {
            "scenario_id": scenario.get("scenario_id", "custom_negotiation"),
            "title": scenario["title"],
            "description": scenario.get("description", ""),
            "setting": scenario.get("setting", ""),
            "cultural_context": scenario.get("cultural_context", ""),
            "your_objective": scenario.get("your_objective", ""),
            "your_batna": scenario.get("your_batna", ""),
            "other_party_name": other_party.get("name", ""),
            "other_party": other_party,
            "conversation_turns": scenario.get("conversation_turns", 8),
            "phases": scenario.get("phases", []),
            "coaching_tips": scenario.get("coaching_tips", []),
            "storybook_pages": scenario.get("storybook_pages", [])
        },
        "initial_state": initial_state,
        "ai_greeting": ai_greeting
    })


@app.post("/api/negotiation/<run_id>/message")
def negotiation_message(run_id):
    """Send a message in the negotiation and get AI response."""
    try:
        r = get_run(run_id)
    except KeyError as e:
        return jsonify({"error": "Resource not found"}), 404
    
    payload = request.get_json(silent=True) or {}
    user_message = payload.get("message", "").strip()
    
    if not user_message:
        return jsonify({"error": "Message cannot be empty"}), 400
    
    if not NEGOTIATION_GAME:
        return jsonify({"error": "Negotiation game not found"}), 404
    
    # Get scenario
    scenario_id = r.get("scenario_id", "")
    scenario = next((s for s in NEGOTIATION_GAME["scenarios"] if s["scenario_id"] == scenario_id), None)
    if not scenario:
        return jsonify({"error": "Scenario not found"}), 404
    
    # Get current state
    state_obj = r["state"]
    current_state = state_to_dict(state_obj)
    
    # Increment turn
    r["current_turn"] = r.get("current_turn", 0) + 1
    current_turn = r["current_turn"]
    
    # Add user message to history
    conversation_history = r.get("conversation_history", [])
    conversation_history.append({
        "turn": current_turn,
        "speaker": "student",
        "message": user_message
    })
    
    # Build scores history from previous analysis results
    neg_scores_history = r.get("analysis_history", [])

    # P3a: Check for scripted responses first (pre-authored dialogue → no LLM cost)
    # JSON format in scenario: "scripted_responses": {"turn_1": {"response": "...", "tone": "..."}, "keywords": {"price": {"response": "..."}}}
    scripted_responses = scenario.get("scripted_responses", {})
    _scripted_reply = None
    if scripted_responses:
        _turn_key = f"turn_{current_turn}"
        if _turn_key in scripted_responses:
            _scripted_reply = scripted_responses[_turn_key]
        elif "keywords" in scripted_responses:
            _msg_lower = user_message.lower()
            for kw, kw_resp in scripted_responses["keywords"].items():
                if kw.lower() in _msg_lower:
                    _scripted_reply = kw_resp
                    break

    if _scripted_reply:
        ai_result = {
            "response": _scripted_reply.get("response", ""),
            "analysis": _scripted_reply.get("analysis", {"relationship_impact": 0, "assertiveness_impact": 0, "empathy_impact": 0}),
            "scripted": True,
        }
    else:
        # Get AI response
        _neg_difficulty = scenario.get("difficulty", r.get("difficulty", "intermediate"))
        ai_result = negotiation_ai_response(
            user_message=user_message,
            scenario_data=scenario,
            conversation_history=conversation_history,
            current_turn=current_turn,
            state=current_state,
            scores_history=neg_scores_history,
            difficulty=_neg_difficulty,
            coaching_tone=game.get("coaching_tone", "supportive")
        )
    
    # Add AI response to history
    conversation_history.append({
        "turn": current_turn,
        "speaker": scenario["other_party"]["name"],
        "message": ai_result["response"]
    })
    
    r["conversation_history"] = conversation_history
    
    # Update state based on analysis (handle both old int and new dict format)
    analysis = ai_result.get("analysis", {})
    def _impact_val(v):
        """Extract numeric value from impact score (int or {value, confidence} dict)."""
        if isinstance(v, dict):
            return v.get("value", 0)
        return v if isinstance(v, (int, float)) else 0

    state_obj.rapport_score = max(0, min(100,
        getattr(state_obj, 'rapport_score', 50) + _impact_val(analysis.get("relationship_impact", 0))))
    state_obj.assertiveness_score = max(0, min(100,
        getattr(state_obj, 'assertiveness_score', 50) + _impact_val(analysis.get("assertiveness_impact", 0))))
    state_obj.understanding_score = max(0, min(100,
        getattr(state_obj, 'understanding_score', 50) + _impact_val(analysis.get("empathy_impact", 0))))

    # Store analysis history for adaptive tier computation
    analysis_history = r.get("analysis_history", [])
    analysis_history.append(analysis)
    r["analysis_history"] = analysis_history
    
    # ── Judge LLM: evaluate turn for phase advancement and agreement ──
    max_turns = scenario.get("conversation_turns", 6)
    phases = scenario.get("phases", ["Opening", "Exploration", "Bargaining", "Closing"])
    current_phase_idx = r.get("phase_index", 0)
    agreement_reached = False  # Only the judge can declare agreement, not the main LLM
    judge_feedback = None

    # Minimum turns before agreement can be detected (at least 75% of turns)
    min_turns_for_agreement = max(4, int(max_turns * 0.75))

    if llm_enabled() and current_turn >= 2:
        try:
            last_exchanges = conversation_history[-6:] if len(conversation_history) >= 6 else conversation_history
            exchange_text = "\n".join(f"{m['speaker']}: {m['message']}" for m in last_exchanges)
            judge_system = "You are a negotiation judge. Evaluate the student's negotiation progress and return a JSON response."
            judge_user = f"""Evaluate this negotiation conversation:

SCENARIO: {scenario.get('title', '')}
STUDENT OBJECTIVE: {scenario.get('your_objective', '')}
CURRENT PHASE: {phases[min(current_phase_idx, len(phases)-1)]} (phase {current_phase_idx+1} of {len(phases)})
TURN: {current_turn}/{max_turns}

RECENT CONVERSATION:
{exchange_text}

Return JSON with these fields:
{{
  "advance_phase": true or false,
  "agreement_reached": true or false,
  "phase_reason": "brief reason for your phase decision",
  "coaching_tip": "one specific actionable tip for the student"
}}

PHASE ADVANCEMENT RULES:
- Opening → Exploration: Student has introduced the topic and stated what they want. Advance after 1-2 turns.
- Exploration → Bargaining: Both parties have shared their needs or constraints (schedules, preferences). Advance after 2-3 turns.
- Bargaining → Closing: Concrete proposals with specific details (times, dates, locations) are being discussed. Advance after 4-5 turns.
- Advance the phase whenever the above criteria are met. Do NOT keep the phase stuck on "Opening" for the entire conversation.
- Only advance ONE phase at a time.

AGREEMENT RULES (be very strict):
- agreement_reached = true ONLY when BOTH parties have EXPLICITLY agreed on specific terms
- Saying "that sounds reasonable" or "I can consider that" is NOT agreement
- Agreement requires BOTH sides stating clear commitments (e.g., "Ok, let's do Monday and Wednesday at 5:30")
- If in doubt, set agreement_reached = false
- Turn {current_turn}/{max_turns}: {"Agreement CANNOT be reached yet — too early in the negotiation." if current_turn < min_turns_for_agreement else "Agreement is possible if both parties explicitly commit."}"""

            judge_result = llm_call(
                system_prompt=judge_system,
                user_prompt=judge_user,
                temperature=0.2,
                max_tokens=250,
                purpose="negotiation_judge",
                fallback={},
            )

            if judge_result.get("advance_phase") is True and current_phase_idx < len(phases) - 1:
                current_phase_idx += 1
                r["phase_index"] = current_phase_idx

            # Only allow agreement after minimum turns
            if judge_result.get("agreement_reached") is True and current_turn >= min_turns_for_agreement:
                agreement_reached = True

            judge_feedback = judge_result.get("coaching_tip", "")
        except Exception as e:
            import traceback
            logger.warning(f"Judge LLM error: {e}")
            traceback.print_exc()

    # Determine current phase name
    current_phase_name = phases[min(current_phase_idx, len(phases) - 1)]

    # Check if negotiation is complete
    is_complete = current_turn >= max_turns or agreement_reached

    # Persist changes
    update_run(run_id, r)

    neg_msg_resp = {
        "ai_response": ai_result["response"],
        "analysis": analysis,
        "phase": current_phase_name,
        "phase_index": current_phase_idx,
        "total_phases": len(phases),
        "phases": phases,
        "negotiation_progress": ai_result.get("negotiation_progress", int((current_turn / max_turns) * 100)),
        "current_turn": current_turn,
        "max_turns": max_turns,
        "is_complete": is_complete,
        "agreement_reached": agreement_reached,
        "updated_state": state_to_dict(state_obj),
        "coaching_tip": judge_feedback or analysis.get("feedback", ""),
    }
    if ai_result.get("detailed_guidance"):
        neg_msg_resp["detailed_guidance"] = ai_result["detailed_guidance"]
    # AI tactic detection data
    if ai_result.get("ai_tactic_used"):
        neg_msg_resp["ai_tactic_used"] = ai_result["ai_tactic_used"]
        neg_msg_resp["ai_tactic_label"] = ai_result.get("ai_tactic_label", "")
        neg_msg_resp["ai_tactic_tip"] = ai_result.get("ai_tactic_tip", "")
    return jsonify(neg_msg_resp)


@app.get("/api/negotiation/<run_id>/outcome")
def negotiation_outcome(run_id):
    """Get final negotiation outcome and evaluation."""
    try:
        r = get_run(run_id)
    except KeyError as e:
        return jsonify({"error": "Resource not found"}), 404
    
    if not NEGOTIATION_GAME:
        return jsonify({"error": "Negotiation game not found"}), 404
    
    # Get scenario
    scenario_id = r.get("scenario_id", "")
    scenario = next((s for s in NEGOTIATION_GAME["scenarios"] if s["scenario_id"] == scenario_id), None)
    if not scenario:
        return jsonify({"error": "Scenario not found"}), 404
    
    # Get final state
    state_obj = r["state"]
    final_state = state_to_dict(state_obj)
    
    # Get conversation history
    conversation_history = r.get("conversation_history", [])
    
    # Evaluate outcome
    evaluation = evaluate_negotiation_outcome(
        scenario_data=scenario,
        conversation_history=conversation_history,
        final_state=final_state
    )
    
    # Calculate final score (handle both old int and new dict format)
    scores = evaluation.get("scores", {})
    overall_v = scores.get("overall", 50)
    final_score = overall_v.get("score", 50) if isinstance(overall_v, dict) else overall_v
    rel_v = scores.get("relationship", 50)
    rel_score = rel_v.get("score", 50) if isinstance(rel_v, dict) else rel_v

    # Update state with final scores
    state_obj.learning_points = state_obj.learning_points + (final_score // 10)
    if rel_score >= 70:
        state_obj.successful_negotiations = state_obj.successful_negotiations + 1
    
    # Persist changes
    update_run(run_id, r)

    # Award XP for negotiation
    try:
        token = get_token_from_request()
        user_payload = verify_token(token) if token else None
        if user_payload:
            xp_amount = int(round(max(25, final_score)))
            player_profile.award_negotiation_xp(
                user_id=user_payload["user_id"],
                xp_amount=xp_amount,
                scenario_title=scenario["title"],
            )
    except Exception as xp_err:
        logger.warning(f"Negotiation XP award failed: {xp_err}")
    # Generate metacognitive reflection
    reflection = generate_metacognitive_reflection(
        game_type="negotiation",
        scenario_data=scenario,
        conversation_history=conversation_history,
        evaluation=evaluation
    )

    # Compute dimension scores for negotiation
    neg_dimension_scores = None
    try:
        neg_dimension_scores = _compute_negotiation_dimension_scores(
            conversation_history,
            r.get("analysis_history", []),
            state_to_dict(state_obj),
            game_type="negotiation",
        )
        state_obj.dimension_scores = neg_dimension_scores
        for sid, sv in neg_dimension_scores.items():
            setattr(state_obj, sid, sv)
        update_run(run_id, r)
    except Exception as dim_err:
        logger.warning(f"Negotiation dimension score computation failed: {dim_err}")
    return jsonify({
        "scenario_title": scenario["title"],
        "evaluation": evaluation,
        "reflection": reflection,
        "final_state": state_to_dict(state_obj),
        "final_score": final_score,
        "conversation_history": conversation_history,
        "badges": compute_badges(state_to_dict(state_obj)),
        "dimension_scores": neg_dimension_scores,
    })


