# INVESTOR PITCH API
# ============================================

def _select_investor_panel(investor_pool, scenario=None, difficulty="intermediate", recommended_ids=None):
    """Select 3 investors from the pool based on scenario preferences and difficulty."""
    import random

    if not investor_pool or len(investor_pool) < 3:
        return investor_pool[:3] if investor_pool else []

    pool = list(investor_pool)

    # If recommended_ids provided (from LLM for custom pitch), use those
    if recommended_ids:
        selected = [inv for inv in pool if inv["id"] in recommended_ids]
        if len(selected) >= 3:
            return selected[:3]
        # Pad with random
        remaining = [inv for inv in pool if inv["id"] not in recommended_ids]
        random.shuffle(remaining)
        selected.extend(remaining[:3 - len(selected)])
        return selected[:3]

    # Use scenario preferences
    preferred = set(scenario.get("preferred_investor_types", [])) if scenario else set()
    avoid = set(scenario.get("avoid_investor_types", [])) if scenario else set()
    pool = [inv for inv in pool if inv["id"] not in avoid]

    # Difficulty-based weights: beginner = more friendly, advanced = more tough
    if difficulty == "beginner":
        # Sort by friendly_weight desc, pick from top
        pool.sort(key=lambda x: x.get("friendly_weight", 3), reverse=True)
    elif difficulty == "advanced":
        pool.sort(key=lambda x: x.get("difficulty_weight", 3), reverse=True)
    else:
        random.shuffle(pool)

    # Prioritize preferred types
    preferred_investors = [inv for inv in pool if inv["id"] in preferred]
    other_investors = [inv for inv in pool if inv["id"] not in preferred]

    selected = []
    # Take preferred first
    for inv in preferred_investors:
        if len(selected) < 3:
            selected.append(inv)
    # Fill remaining
    for inv in other_investors:
        if len(selected) < 3:
            selected.append(inv)

    # Add randomness — swap one investor randomly to ensure surprise factor
    if len(pool) > 3 and len(selected) == 3:
        swap_idx = random.randint(0, 2)
        remaining = [inv for inv in pool if inv not in selected]
        if remaining:
            selected[swap_idx] = random.choice(remaining)

    return selected[:3]


@app.get("/api/pitch/scenarios")
def pitch_scenarios():
    """Get all investor pitch scenarios and investor pool summary."""
    if not INVESTOR_PITCH_GAME:
        return jsonify({"error": "Investor pitch game not configured"}), 404

    scenarios_out = []
    for s in INVESTOR_PITCH_GAME.get("scenarios", []):
        scenarios_out.append({
            "scenario_id": s["scenario_id"],
            "title": s["title"],
            "description": s["description"],
            "difficulty": s.get("difficulty", "intermediate"),
            "industry": s.get("industry", ""),
            "setting": s.get("setting", ""),
            "conversation_turns": s.get("conversation_turns", 10),
            "storybook_pages": s.get("storybook_pages", []),
            "predefined_metrics": s.get("predefined_metrics", {}),
            "preferred_investor_types": s.get("preferred_investor_types", []),
        })

    # Investor pool summary (safe subset for display)
    pool_summary = []
    for inv in INVESTOR_PITCH_GAME.get("investor_pool", []):
        pool_summary.append({
            "id": inv["id"],
            "name": inv["name"],
            "archetype": inv["archetype"],
            "focus": inv.get("focus", ""),
            "avatar_emoji": inv.get("avatar_emoji", "💼"),
        })

    return jsonify({
        "game_title": INVESTOR_PITCH_GAME.get("title", ""),
        "description": INVESTOR_PITCH_GAME.get("description", ""),
        "scenarios": scenarios_out,
        "investor_pool": pool_summary,
        "help_content": INVESTOR_PITCH_GAME.get("help_content", {}),
        "scoring_rubric": INVESTOR_PITCH_GAME.get("scoring_rubric", {}),
        "pitch_phases": INVESTOR_PITCH_GAME.get("pitch_phases", []),
    })


@app.post("/api/pitch/generate-context")
@require_auth
def pitch_generate_context():
    """Generate pitch context for 'Pitch Your Own Idea' mode. Requires login."""
    if not INVESTOR_PITCH_GAME:
        return jsonify({"error": "Investor pitch game not configured"}), 404

    payload = request.get_json(silent=True) or {}
    idea_description = payload.get("idea_description", "").strip()
    difficulty = payload.get("difficulty", "intermediate")

    if not idea_description or len(idea_description) < 10:
        return jsonify({"error": "Please describe your idea in at least 10 characters"}), 400

    investor_pool = INVESTOR_PITCH_GAME.get("investor_pool", [])
    context = generate_pitch_context(idea_description, investor_pool)

    # Select investors based on LLM recommendation
    recommended_ids = context.get("recommended_investor_ids", [])
    active_investors = _select_investor_panel(investor_pool, difficulty=difficulty, recommended_ids=recommended_ids)

    return jsonify({
        "generated_context": context,
        "active_investors": [
            {
                "id": inv["id"],
                "name": inv["name"],
                "archetype": inv["archetype"],
                "focus": inv.get("focus", ""),
                "avatar_emoji": inv.get("avatar_emoji", "💼"),
                "voice": inv.get("voice", "nova"),
            }
            for inv in active_investors
        ],
    })


@app.post("/api/pitch/start")
def pitch_start():
    """Start an investor pitch session."""
    if not INVESTOR_PITCH_GAME:
        return jsonify({"error": "Investor pitch game not configured"}), 404

    payload = request.get_json(silent=True) or {}
    scenario_id = payload.get("scenario_id", "")
    custom_pitch = payload.get("custom_pitch")  # For "Pitch Your Own"

    investor_pool = INVESTOR_PITCH_GAME.get("investor_pool", [])

    if custom_pitch:
        # Pitch Your Own mode
        scenario = {
            "scenario_id": "custom_pitch",
            "title": custom_pitch.get("pitch_title", "Your Pitch"),
            "description": custom_pitch.get("key_context", ""),
            "industry": custom_pitch.get("industry", "General"),
            "difficulty": payload.get("difficulty", "intermediate"),
            "setting": custom_pitch.get("setting", "A modern conference room. Three investors are ready to hear your idea."),
            "pitch_topic": custom_pitch.get("pitch_title", ""),
            "predefined_metrics": {},
            "conversation_turns": 10,
            "pitch_phases": INVESTOR_PITCH_GAME.get("pitch_phases", ["Elevator Pitch", "Deep Dive Q&A", "Objection Round", "The Ask"]),
            "scoring_rubric": INVESTOR_PITCH_GAME.get("scoring_rubric", {}),
            "coaching_tips": ["Be clear about the problem you're solving", "Support claims with data"],
            "learning_objectives": ["Practice articulating your idea", "Handle tough investor questions"],
            "storybook_pages": [],
            "preferred_investor_types": [],
            "avoid_investor_types": [],
        }
        active_investor_ids = [inv["id"] for inv in (custom_pitch.get("active_investors") or [])]
        active_investors = _select_investor_panel(
            investor_pool, scenario,
            difficulty=scenario["difficulty"],
            recommended_ids=active_investor_ids if active_investor_ids else None
        )
    else:
        scenario = next((s for s in INVESTOR_PITCH_GAME.get("scenarios", []) if s["scenario_id"] == scenario_id), None)
        if not scenario:
            return jsonify({"error": "Scenario not found"}), 404
        active_investors = _select_investor_panel(
            investor_pool, scenario, difficulty=scenario.get("difficulty", "intermediate")
        )

    initial_state = INVESTOR_PITCH_GAME.get("initial_state", {}).copy()
    initial_state["pitch_score"] = 0
    initial_state["panel_confidence"] = 50

    run_id = create_run("pitch", initial_state)
    r = get_run(run_id)
    r["scenario_id"] = scenario.get("scenario_id", "custom_pitch")
    r["conversation_history"] = []
    r["current_turn"] = 0
    r["analysis_history"] = []
    r["active_investor_ids"] = [inv["id"] for inv in active_investors]
    r["active_investors"] = [
        {
            "id": inv["id"],
            "name": inv["name"],
            "archetype": inv["archetype"],
            "focus": inv.get("focus", ""),
            "personality": inv.get("personality", ""),
            "tough_question_style": inv.get("tough_question_style", ""),
            "avatar_emoji": inv.get("avatar_emoji", "💼"),
            "voice": inv.get("voice", "nova"),
        }
        for inv in active_investors
    ]

    # Generate panel greeting
    investor_names = ", ".join([inv["name"] for inv in active_investors])
    greeting_prompt = f"The pitch session is starting. Welcome the pitcher briefly (1-2 sentences). You are {active_investors[0]['name']}, the lead investor. Introduce the panel: {investor_names}. Ask the pitcher to begin their elevator pitch."

    ai_greeting = pitch_panel_response(
        user_message=greeting_prompt,
        scenario_data=scenario,
        conversation_history=[],
        current_turn=0,
        state=initial_state,
        active_investors=active_investors,
    )

    greeting_msg = ai_greeting.get("response", f"{active_investors[0]['name']}: Welcome. You have the floor. Tell us about your idea.")
    r["conversation_history"].append({
        "turn": 0,
        "speaker": ai_greeting.get("speaker_name", active_investors[0]["name"]),
        "speaker_investor_id": ai_greeting.get("speaker_investor_id", active_investors[0]["id"]),
        "message": greeting_msg,
    })
    update_run(run_id, r)

    return jsonify({
        "run_id": run_id,
        "scenario": {
            "scenario_id": scenario.get("scenario_id"),
            "title": scenario["title"],
            "description": scenario.get("description", ""),
            "industry": scenario.get("industry", ""),
            "setting": scenario.get("setting", ""),
            "pitch_topic": scenario.get("pitch_topic", ""),
            "predefined_metrics": scenario.get("predefined_metrics", {}),
            "conversation_turns": scenario.get("conversation_turns", 10),
            "pitch_phases": scenario.get("pitch_phases", INVESTOR_PITCH_GAME.get("pitch_phases", [])),
            "coaching_tips": scenario.get("coaching_tips", []),
            "storybook_pages": scenario.get("storybook_pages", []),
        },
        "active_investors": r["active_investors"],
        "initial_state": initial_state,
        "ai_greeting": greeting_msg,
        "speaker_investor_id": ai_greeting.get("speaker_investor_id", active_investors[0]["id"]),
        "speaker_name": ai_greeting.get("speaker_name", active_investors[0]["name"]),
    })


@app.post("/api/pitch/<run_id>/message")
def pitch_message(run_id):
    """Process a pitch turn."""
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Run not found"}), 404

    payload = request.get_json(silent=True) or {}
    user_message = payload.get("message", "").strip()
    if not user_message:
        return jsonify({"error": "Message is required"}), 400

    scenario_id = r.get("scenario_id", "")
    scenario = None
    if INVESTOR_PITCH_GAME and scenario_id != "custom_pitch":
        scenario = next((s for s in INVESTOR_PITCH_GAME.get("scenarios", []) if s["scenario_id"] == scenario_id), None)

    if not scenario:
        # Custom pitch or fallback
        scenario = {
            "scenario_id": scenario_id,
            "title": "Your Pitch",
            "description": "",
            "industry": "",
            "conversation_turns": 10,
            "pitch_phases": INVESTOR_PITCH_GAME.get("pitch_phases", ["Elevator Pitch", "Deep Dive Q&A", "Objection Round", "The Ask"]) if INVESTOR_PITCH_GAME else [],
            "scoring_rubric": INVESTOR_PITCH_GAME.get("scoring_rubric", {}) if INVESTOR_PITCH_GAME else {},
        }

    conversation_history = r.get("conversation_history", [])
    current_turn = r.get("current_turn", 0) + 1
    r["current_turn"] = current_turn

    state_obj = r.get("state", {})
    if hasattr(state_obj, '__dict__'):
        state = {k: v for k, v in state_obj.__dict__.items() if not k.startswith('_')}
    elif isinstance(state_obj, dict):
        state = state_obj
    else:
        state = {"pitch_score": 0, "panel_confidence": 50}

    # Append user message
    conversation_history.append({
        "turn": current_turn,
        "speaker": "student",
        "message": user_message,
    })

    # Get active investors
    active_investors = r.get("active_investors", [])
    scores_history = r.get("analysis_history", [])

    ai_result = pitch_panel_response(
        user_message=user_message,
        scenario_data=scenario,
        conversation_history=conversation_history,
        current_turn=current_turn,
        state=state,
        active_investors=active_investors,
        scores_history=scores_history,
    )

    # Append AI response
    ai_response = ai_result.get("response", "Interesting. Tell me more.")
    conversation_history.append({
        "turn": current_turn,
        "speaker": ai_result.get("speaker_name", "Investor"),
        "speaker_investor_id": ai_result.get("speaker_investor_id", ""),
        "message": ai_response,
    })
    r["conversation_history"] = conversation_history

    # Update state
    analysis = ai_result.get("analysis", {})
    for key in ["relationship_impact", "assertiveness_impact", "empathy_impact"]:
        impact = analysis.get(key, 0)
        if isinstance(impact, dict):
            impact = impact.get("value", 0)
        if isinstance(impact, (int, float)):
            if key == "relationship_impact":
                state["panel_confidence"] = max(0, min(100, state.get("panel_confidence", 50) + impact))
            state["pitch_score"] = max(0, state.get("pitch_score", 0) + max(0, impact))

    # Store analysis history
    if "analysis_history" not in r:
        r["analysis_history"] = []
    r["analysis_history"].append(analysis)

    # Update investor sentiments on run
    investor_sentiments = ai_result.get("investor_sentiments", {})
    r["investor_sentiments"] = investor_sentiments

    if hasattr(state_obj, '__dict__'):
        for k, v in state.items():
            setattr(state_obj, k, v)
    else:
        r["state"] = state

    max_turns = scenario.get("conversation_turns", 10)
    is_complete = current_turn >= max_turns

    update_run(run_id, r)

    return jsonify({
        "ai_response": ai_response,
        "speaker_investor_id": ai_result.get("speaker_investor_id", ""),
        "speaker_name": ai_result.get("speaker_name", ""),
        "analysis": analysis,
        "phase": ai_result.get("phase", ""),
        "pitch_progress": ai_result.get("pitch_progress", 0),
        "current_turn": current_turn,
        "max_turns": max_turns,
        "is_complete": is_complete,
        "investor_sentiments": investor_sentiments,
        "updated_state": state,
    })


@app.get("/api/pitch/<run_id>/outcome")
def pitch_outcome(run_id):
    """Evaluate the pitch performance."""
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Run not found"}), 404

    scenario_id = r.get("scenario_id", "")
    scenario = None
    if INVESTOR_PITCH_GAME and scenario_id != "custom_pitch":
        scenario = next((s for s in INVESTOR_PITCH_GAME.get("scenarios", []) if s["scenario_id"] == scenario_id), None)

    if not scenario:
        scenario = {
            "scenario_id": scenario_id,
            "title": "Your Pitch",
            "difficulty": "intermediate",
            "industry": "",
            "scoring_rubric": INVESTOR_PITCH_GAME.get("scoring_rubric", {}) if INVESTOR_PITCH_GAME else {},
        }

    conversation_history = r.get("conversation_history", [])
    active_investors = r.get("active_investors", [])

    state_obj = r.get("state", {})
    if hasattr(state_obj, '__dict__'):
        final_state = {k: v for k, v in state_obj.__dict__.items() if not k.startswith('_')}
    elif isinstance(state_obj, dict):
        final_state = state_obj
    else:
        final_state = {}

    evaluation = evaluate_pitch_outcome(
        scenario_data=scenario,
        conversation_history=conversation_history,
        final_state=final_state,
        active_investors=active_investors,
    )

    # Compute final score
    final_score = 50
    if "scores" in evaluation and "overall" in evaluation["scores"]:
        overall = evaluation["scores"]["overall"]
        if isinstance(overall, dict):
            final_score = overall.get("score", 50)
        elif isinstance(overall, (int, float)):
            final_score = overall

    # Generate reflection
    reflection = None
    try:
        reflection = generate_metacognitive_reflection(
            game_type="pitch",
            scenario_data=scenario,
            conversation_history=conversation_history,
            evaluation=evaluation
        )
    except Exception as ref_err:
        logger.warning(f"Pitch reflection failed: {ref_err}")
    # Award XP if authenticated
    try:
        token = get_token_from_request()
        if token:
            payload_data = verify_token(token)
            if payload_data and "user_id" in payload_data:
                player_profile.award_negotiation_xp(
                    payload_data["user_id"],
                    scenario_title=f"pitch:{scenario.get('title', '')}",
                    final_score=final_score,
                )
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Compute dimension scores (reuse negotiation pattern)
    dimension_scores = None
    try:
        dimension_scores = _compute_negotiation_dimension_scores(
            conversation_history,
            r.get("analysis_history", []),
            final_state,
            game_type="pitch",
        )
    except Exception as dim_err:
        logger.warning(f"Pitch dimension score computation failed: {dim_err}")
    update_run(run_id, r)

    return jsonify({
        "scenario_title": scenario.get("title", "Your Pitch"),
        "evaluation": evaluation,
        "reflection": reflection,
        "final_state": final_state,
        "final_score": final_score,
        "conversation_history": conversation_history,
        "active_investors": active_investors,
        "dimension_scores": dimension_scores,
    })


