@app.post("/api/session/<game_type>/<run_id>/message")
def session_message(game_type, run_id):
    """Process a turn in a session game."""
    if game_type not in VALID_SESSION_TYPES:
        return jsonify({"error": f"Invalid game type: {game_type}"}), 400
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Run not found"}), 404

    payload = request.get_json(silent=True) or {}
    user_message = payload.get("message", "").strip()
    if not user_message:
        return jsonify({"error": "Message is required"}), 400

    game_data = SESSION_GAMES.get(game_type)
    scenario_id = r.get("scenario_id", "")
    scenario = None
    if game_data and scenario_id != "custom_session":
        scenario = next((s for s in game_data.get("scenarios", []) if s["scenario_id"] == scenario_id), None)
    if not scenario:
        scenario = {
            "scenario_id": scenario_id,
            "title": "Your Session",
            "description": "",
            "industry": "",
            "conversation_turns": 10,
            "session_phases": game_data.get("session_phases", []) if game_data else [],
            "scoring_rubric": game_data.get("scoring_rubric", {}) if game_data else {},
        }

    conversation_history = r.get("conversation_history", [])
    current_turn = r.get("current_turn", 0) + 1
    r["current_turn"] = current_turn

    state_obj = r.get("state", {})
    if hasattr(state_obj, '__dict__'):
        state = {k: v for k, v in state_obj.__dict__.items() if not k.startswith('_')}
    elif isinstance(state_obj, dict):
        state = state_obj
    else:
        state = {"performance_score": 0}

    conversation_history.append({"turn": current_turn, "speaker": "student", "message": user_message})

    active_personas = r.get("active_personas", [])
    scores_history = r.get("analysis_history", [])

    ai_result = session_panel_response(
        user_message=user_message,
        game_type=game_type,
        scenario_data=scenario,
        conversation_history=conversation_history,
        current_turn=current_turn,
        state=state,
        active_personas=active_personas,
        scores_history=scores_history,
    )

    ai_response = ai_result.get("response", "Interesting. Tell me more.")
    conversation_history.append({
        "turn": current_turn,
        "speaker": ai_result.get("speaker_name", "AI"),
        "speaker_persona_id": ai_result.get("speaker_persona_id", ""),
        "message": ai_response,
    })
    r["conversation_history"] = conversation_history

    analysis = ai_result.get("analysis", {})
    for key in ["relationship_impact", "assertiveness_impact", "empathy_impact"]:
        impact = analysis.get(key, 0)
        if isinstance(impact, dict):
            impact = impact.get("value", 0)
        if isinstance(impact, (int, float)):
            state["performance_score"] = max(0, state.get("performance_score", 0) + max(0, impact))
            state_keys = list(state.keys())
            if len(state_keys) > 1 and key == "relationship_impact":
                second_key = state_keys[1]
                cur_val = state.get(second_key, 50)
                if isinstance(cur_val, (int, float)):
                    state[second_key] = max(0, min(100, cur_val + impact))

    if "analysis_history" not in r:
        r["analysis_history"] = []
    r["analysis_history"].append(analysis)

    persona_sentiments = ai_result.get("persona_sentiments", {})
    r["persona_sentiments"] = persona_sentiments

    if hasattr(state_obj, '__dict__'):
        for k, v in state.items():
            setattr(state_obj, k, v)
    else:
        r["state"] = state

    max_turns = scenario.get("conversation_turns", 10)
    is_complete = current_turn >= max_turns
    update_run(run_id, r)

    resp_data = {
        "ai_response": ai_response,
        "speaker_persona_id": ai_result.get("speaker_persona_id", ""),
        "speaker_name": ai_result.get("speaker_name", ""),
        "analysis": analysis,
        "phase": ai_result.get("phase", ""),
        "session_progress": ai_result.get("session_progress", 0),
        "current_turn": current_turn,
        "max_turns": max_turns,
        "is_complete": is_complete,
        "persona_sentiments": persona_sentiments,
        "updated_state": state,
    }

    # AI Discussion: pass chart_data and math_problem from LLM response
    if game_type == "ai_discussion":
        if ai_result.get("chart_data"):
            resp_data["chart_data"] = ai_result["chart_data"]
        if ai_result.get("math_problem"):
            resp_data["math_problem"] = ai_result["math_problem"]

    return jsonify(resp_data)


@app.get("/api/session/<game_type>/<run_id>/outcome")
def session_outcome(game_type, run_id):
    """Evaluate session performance."""
    if game_type not in VALID_SESSION_TYPES:
        return jsonify({"error": f"Invalid game type: {game_type}"}), 400
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Run not found"}), 404

    game_data = SESSION_GAMES.get(game_type)
    scenario_id = r.get("scenario_id", "")
    scenario = None
    if game_data and scenario_id != "custom_session":
        scenario = next((s for s in game_data.get("scenarios", []) if s["scenario_id"] == scenario_id), None)
    if not scenario:
        scenario = {
            "scenario_id": scenario_id,
            "title": "Your Session",
            "difficulty": "intermediate",
            "industry": "",
            "scoring_rubric": game_data.get("scoring_rubric", {}) if game_data else {},
        }

    conversation_history = r.get("conversation_history", [])
    active_personas = r.get("active_personas", [])

    state_obj = r.get("state", {})
    if hasattr(state_obj, '__dict__'):
        final_state = {k: v for k, v in state_obj.__dict__.items() if not k.startswith('_')}
    elif isinstance(state_obj, dict):
        final_state = state_obj
    else:
        final_state = {}

    evaluation = evaluate_session_outcome(
        game_type=game_type,
        scenario_data=scenario,
        conversation_history=conversation_history,
        final_state=final_state,
        active_personas=active_personas,
    )

    final_score = 50
    if "scores" in evaluation and "overall" in evaluation["scores"]:
        overall = evaluation["scores"]["overall"]
        if isinstance(overall, dict):
            final_score = overall.get("score", 50)
        elif isinstance(overall, (int, float)):
            final_score = overall

    reflection = None
    try:
        reflection = generate_metacognitive_reflection(
            game_type=game_type,
            scenario_data=scenario,
            conversation_history=conversation_history,
            evaluation=evaluation
        )
    except Exception as ref_err:
        logger.warning(f"{game_type} reflection failed: {ref_err}")
    try:
        token = get_token_from_request()
        if token:
            payload_data = verify_token(token)
            if payload_data and "user_id" in payload_data:
                player_profile.award_negotiation_xp(
                    payload_data["user_id"],
                    scenario_title=f"{game_type}:{scenario.get('title', '')}",
                    final_score=final_score,
                )
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    dimension_scores = None
    try:
        dimension_scores = _compute_negotiation_dimension_scores(
            conversation_history,
            r.get("analysis_history", []),
            final_state,
            game_type=game_type,
        )
    except Exception as dim_err:
        logger.warning(f"{game_type} dimension score computation failed: {dim_err}")
    update_run(run_id, r)

    return jsonify({
        "scenario_title": scenario.get("title", "Your Session"),
        "evaluation": evaluation,
        "reflection": reflection,
        "final_state": final_state,
        "final_score": final_score,
        "conversation_history": conversation_history,
        "active_personas": active_personas,
        "dimension_scores": dimension_scores,
    })


