@app.post("/api/run/<run_id>/scene-update")
def get_scene_update_api(run_id):
    """Generate dynamic scene update after player choice using AI."""
    try:
        from dynamic_scene_ai import get_scene_update
        
        r = get_run(run_id)
        payload = request.get_json(silent=True) or {}
        choice_id = payload.get("choice_id", "")
        
        game_id = r["game_id"]
        game, err = get_game_or_400(game_id)
        if err:
            return err
        game = get_effective_game(r, game)

        state_obj = r["state"]
        current_round = game["rounds"][state_obj.round_index]

        # Find the choice
        choice = next((c for c in current_round.get("choices", []) if c["id"] == choice_id), None)
        if not choice:
            return jsonify({"error": "Choice not found"}), 404

        # Generate scene update using AI
        scene_update = get_scene_update(current_round, choice, state_to_dict(state_obj))
        
        return jsonify({
            "scene_update": scene_update,
            "round_id": current_round["id"]
        })
    except Exception as e:
        logger.info(f"Error generating scene update: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


