@app.post("/api/run/<run_id>/interaction")
def handle_interaction(run_id):
    """Generate AI response for clicking on objects/characters."""
    try:
        r = get_run(run_id)
        payload = request.get_json(silent=True) or {}

        target_name = payload.get("target_name", "")
        target_type = payload.get("target_type", "character")
        target_description = payload.get("target_description", "")

        game_id = r["game_id"]
        game, err = get_game_or_400(game_id)
        if err:
            return err
        game = get_effective_game(r, game)

        state_obj = r["state"]
        current_round = game["rounds"][state_obj.round_index]

        # Generate AI interaction
        prompt = f"""Player clicked on: {target_name} ({target_type})
Description: {target_description}

Context:
- Round: {current_round.get('title')}
- Story: {current_round.get('story', '')[:300]}
- State: Stress {state_to_dict(state_obj).get('stress', 50)}

Generate a brief interaction response (1-2 sentences) and visual effect.

Output JSON:
{{
  "message": "What happens when clicked",
  "visual_effect": "sparkle/glow/none"
}}"""

        interaction = llm_call(
            system_prompt="Output only valid JSON.",
            user_prompt=prompt,
            temperature=0.7,
            max_tokens=150,
            purpose="scene_interaction",
            fallback={"message": f"You interacted with {target_name}.", "visual_effect": "sparkle"},
        )

        return jsonify({"interaction": interaction})
        
    except Exception as e:
        logger.info(f"Error generating interaction: {e}")
        # Fallback
        return jsonify({
            "interaction": {
                "message": f"You interacted with {payload.get('target_name', 'something')}.",
                "visual_effect": "sparkle"
            }
        })


@app.post("/api/character-chat")
def character_chat():
    """
    AI-powered character dialogue system.
    Characters respond based on their personality, game context, and conversation history.
    """
    try:
        payload = request.json
        character_name = payload.get("character_name", "Character")
        character_description = payload.get("character_description", "")
        environment = payload.get("environment", {})
        conversation_history = payload.get("conversation_history", [])
        round_context = payload.get("round_context", "")
        
        # Build conversation context
        history_text = ""
        if conversation_history:
            recent = conversation_history[-3:]  # Last 3 exchanges
            for entry in recent:
                if "user" in entry:
                    history_text += f"\nPlayer: {entry['user']}"
                elif "message" in entry:
                    history_text += f"\n{character_name}: {entry['message']}"
        
        # Create personality-based prompt
        prompt = f"""You are {character_name}, a character in an educational game.

Character Info:
- Name: {character_name}
- Description: {character_description}
- Current Location: {environment.get('setting', 'unknown')}
- Context: {round_context}

Conversation History:{history_text}

Generate a short, friendly response (1-2 sentences) that:
1. Matches the character's personality
2. Is appropriate for kids/teens
3. Relates to the game scenario
4. Encourages learning and growth
5. Is conversational and natural

Respond as {character_name} would, staying in character.
Keep it brief, friendly, and educational.

Output ONLY the character's dialogue (no JSON, no quotes, just the text)."""

        message = llm_call(
            system_prompt=f"You are {character_name}. Respond naturally and briefly.",
            user_prompt=prompt,
            response_json=False,
            temperature=0.8,
            max_tokens=100,
            purpose="character_chat",
            fallback="Hey! Great to meet you!",
        )

        # Remove any quotes if present
        if message.startswith('"') and message.endswith('"'):
            message = message[1:-1]
        if message.startswith("'") and message.endswith("'"):
            message = message[1:-1]

        return jsonify({"message": message})

    except Exception as e:
        logger.info(f"Error in character chat: {e}")
        fallback_responses = [
            "Hey! Great to meet you!",
            "I'm here to help if you need anything!",
            "This is quite an adventure, isn't it?",
            "What do you think we should do?",
            "I'm learning so much from this experience!"
        ]
        import random
        return jsonify({"message": random.choice(fallback_responses)})


@app.post("/api/mento/chat")
@limiter.limit("20 per minute")
def mento_chat():
    """
    Coach Mento AI chat with full game context awareness.
    Mento can answer questions, provide guidance, and react to game state.
    """
    try:
        payload = request.json
        message = payload.get("message", "")
        game_context = payload.get("game_context", {})
        
        if not message:
            return jsonify({"error": "Message is required"}), 400
        
        # Get run data if available for richer context
        run_id = game_context.get("run_id")
        if run_id and run_id in RUNS:
            run = RUNS[run_id]
            game = GAMES.get(run["game_id"])
            if game:
                game = get_effective_game(run, game)

            # Enrich context with current round data
            state_obj = run.get("state")
            ri = state_obj.round_index if hasattr(state_obj, "round_index") else (state_obj.get("round_index", 0) if isinstance(state_obj, dict) else 0)
            if game and ri < len(game.get("rounds", [])):
                current_round = game["rounds"][ri]
                game_context["round_title"] = current_round.get("title", "")
                game_context["goal"] = current_round.get("goal", "")
                _s = run.get("state", {})
                game_context["state"] = vars(_s) if hasattr(_s, "__dict__") else (_s if isinstance(_s, dict) else {})
                game_context["choices"] = current_round.get("choices", [])
                game_context["game_title"] = game.get("title", "")
        
        # Call LLM agent
        response_data = coach_mento_agent(message, game_context)

        # A1: Persist tip_id for RL bandit outcome recording at /report
        _tip_id = response_data.pop("_tip_id", None)
        if run_id:
            try:
                _r = RUNS.get(run_id) or get_run(run_id)
                if _r:
                    if _tip_id:
                        _r["_coaching_tip_id"] = _tip_id
                    # A2: Append this chat turn to per-run chat log for later analysis
                    _log = _r.setdefault("mento_chat_log", [])
                    _log.append({
                        "user": message,
                        "mento": response_data.get("response", ""),
                        "round_index": game_context.get("round_index", 0),
                    })
                    update_run(run_id, _r)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        return jsonify(response_data)

    except Exception as e:
        logger.info(f"Error in Mento chat: {e}")
        return jsonify({
            "response": "I'm here to help! What would you like to know?",
            "action": None,
            "action_params": {}
        })


