@app.route("/api/craft", methods=["POST"])
def api_craft():
    """
    Craft an item using the crafting engine.
    POST body: {run_id, recipe_id}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        recipe_id = data.get("recipe_id")
        
        if not run_id or not recipe_id:
            return jsonify({"error": "Missing run_id or recipe_id"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        # Check if game has crafting config
        crafting_config = game.get("crafting", {})
        recipes = crafting_config.get("recipes", [])
        if not recipes:
            return jsonify({"error": "Game does not support crafting"}), 400
        
        # Get current state
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        
        # Initialize crafting engine
        crafting_engine = CraftingEngine(crafting_config)
        
        # Check if can craft
        can_craft, reason = crafting_engine.can_craft(recipe_id, state)
        if not can_craft:
            return jsonify({"error": f"Cannot craft: {reason}", "success": False}), 400
        
        # Craft the item
        new_state, result = crafting_engine.craft(recipe_id, state)
        
        # Update run
        run_data["state"] = new_state.__dict__
        update_run(run_id, run_data)
        
        return jsonify({
            "success": True,
            "message": result,
            "new_state": new_state.__dict__,
            "crafted_item": recipe_id
        })
        
    except Exception as e:
        logger.error(f"Crafting failed: {e}")
        return jsonify({"error": "An internal error occurred", "success": False}), 500


@app.route("/api/research", methods=["POST"])
def api_research():
    """
    Research a technology using the tech tree engine.
    POST body: {run_id, tech_id}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        tech_id = data.get("tech_id")
        
        if not run_id or not tech_id:
            return jsonify({"error": "Missing run_id or tech_id"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        # Check if game has tech tree
        tech_tree = game.get("tech_tree") or game.get("techTree") or {}
        if not tech_tree or not tech_tree.get("nodes"):
            return jsonify({"error": "Game does not support tech tree"}), 400
        
        # Get current state
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        
        # Initialize tech tree engine
        tech_tree_engine = TechTreeEngine(tech_tree)
        
        # Check if can research
        if not tech_tree_engine.can_research(tech_id, state):
            return jsonify({"error": "Cannot research: prerequisites not met or insufficient resources", "success": False}), 400
        
        # Research the tech
        new_state, result = tech_tree_engine.research(tech_id, state)
        
        # Update run
        run_data["state"] = new_state.__dict__
        update_run(run_id, run_data)
        
        return jsonify({
            "success": True,
            "message": result,
            "new_state": new_state.__dict__,
            "researched_tech": tech_id
        })
        
    except Exception as e:
        logger.error(f"Research failed: {e}")
        return jsonify({"error": "An internal error occurred", "success": False}), 500


