@app.route("/api/procedural/generate-round", methods=["POST"])
def api_generate_round():
    """
    Generate a round from template.
    POST body: {run_id, template_id}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        template_id = data.get("template_id")
        
        if not run_id or not template_id:
            return jsonify({"error": "Missing run_id or template_id"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        # Check if game has procedural config
        procedural = game.get("procedural", {})
        templates = procedural.get("templates", [])
        
        template = next((t for t in templates if t.get("id") == template_id), None)
        if not template:
            return jsonify({"error": "Template not found"}), 404
        
        # Get current state
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        
        # Create context from state
        context = {
            "round_num": state.round_index + 1,
            "day_num": state.round_index + 1,
            **state.__dict__
        }
        
        # Initialize RNG with run ID for determinism
        rng = RNGEngine(run_id + "_" + str(state.round_index))
        
        # Generate round
        generated_round = TemplateEngine.generate_round(template, context, rng)
        
        return jsonify({
            "success": True,
            "round": generated_round
        })
        
    except Exception as e:
        logger.error(f"Round generation failed: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


@app.route("/api/procedural/roll-loot", methods=["POST"])
def api_roll_loot():
    """
    Roll loot from table.
    POST body: {run_id, table_id}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        table_id = data.get("table_id")
        
        if not run_id or not table_id:
            return jsonify({"error": "Missing run_id or table_id"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        # Get loot tables
        procedural = game.get("procedural", {})
        loot_tables = procedural.get("loot_tables", [])
        
        table = next((t for t in loot_tables if t.get("id") == table_id), None)
        if not table:
            return jsonify({"error": "Loot table not found"}), 404
        
        # Initialize RNG
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        rng = RNGEngine(run_id + "_loot_" + str(state.round_index))
        
        # Roll loot
        items = table.get("items", [])
        weights = {item["id"]: item.get("weight", 1) for item in items}
        
        selected_id = rng.weighted_choice(weights)
        selected_item = next(i for i in items if i["id"] == selected_id)
        
        # Roll quantity
        min_qty = selected_item.get("min_qty", 1)
        max_qty = selected_item.get("max_qty", 1)
        quantity = rng.randint(min_qty, max_qty)
        
        # Add to state
        current_qty = getattr(state, selected_id, 0)
        setattr(state, selected_id, current_qty + quantity)
        
        # Update run
        run_data["state"] = state.__dict__
        update_run(run_id, run_data)
        
        return jsonify({
            "success": True,
            "loot": {
                "item_id": selected_id,
                "quantity": quantity,
                "rarity": selected_item.get("rarity", "common")
            },
            "new_state": state.__dict__
        })
        
    except Exception as e:
        logger.error(f"Loot roll failed: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


@app.route("/api/procedural/trigger-event", methods=["POST"])
def api_trigger_event():
    """
    Trigger random event from pool.
    POST body: {run_id, pool_id}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        pool_id = data.get("pool_id")
        
        if not run_id or not pool_id:
            return jsonify({"error": "Missing run_id or pool_id"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        # Get event pools
        procedural = game.get("procedural", {})
        event_pools = procedural.get("event_pools", [])
        
        pool = next((p for p in event_pools if p.get("id") == pool_id), None)
        if not pool:
            return jsonify({"error": "Event pool not found"}), 404
        
        # Initialize RNG
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        rng = RNGEngine(run_id + "_event_" + str(state.round_index))
        
        # Select event
        events = pool.get("events", [])
        weights = {event["id"]: event.get("weight", 1) for event in events}
        
        selected_id = rng.weighted_choice(weights)
        selected_event = next(e for e in events if e["id"] == selected_id)
        
        # Apply event effects (delta)
        delta = selected_event.get("delta", {})
        for resource, change in delta.items():
            current = getattr(state, resource, 0)
            setattr(state, resource, current + change)
        
        # Update run
        run_data["state"] = state.__dict__
        update_run(run_id, run_data)
        
        return jsonify({
            "success": True,
            "event": {
                "id": selected_id,
                "title": selected_event.get("title", ""),
                "story": selected_event.get("story", ""),
                "delta": delta
            },
            "new_state": state.__dict__
        })
        
    except Exception as e:
        logger.error(f"Event trigger failed: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


