@app.route("/api/dialogue/start", methods=["POST"])
def api_dialogue_start():
    """
    Start a conversation.
    POST body: {run_id, conversation_id}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        conversation_id = data.get("conversation_id")
        
        if not run_id or not conversation_id:
            return jsonify({"error": "Missing run_id or conversation_id"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        # Check if game has dialogue config
        dialogue_config = game.get("dialogue", {})
        if not dialogue_config:
            return jsonify({"error": "Game does not support dialogue"}), 400
        
        # Get current state
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        
        # Initialize dialogue engine
        dialogue_engine = DialogueEngine(dialogue_config)
        
        # Start conversation
        node_data, new_state = dialogue_engine.start_conversation(conversation_id, state)
        
        # Get NPC info
        npc_id = node_data.get("npc_id")
        npc_info = {}
        if npc_id:
            npc = dialogue_engine.npcs.get(npc_id, {})
            npc_info = {
                "name": npc.get("name", "Unknown"),
                "avatar": npc.get("avatar", ""),
                "relationship": dialogue_engine.get_npc_relationship(npc_id, new_state),
                "relationship_status": dialogue_engine.get_relationship_status(npc_id, new_state)
            }
        
        # Update run
        run_data["state"] = new_state.__dict__
        update_run(run_id, run_data)
        
        return jsonify({
            "success": True,
            "node": node_data,
            "npc_info": npc_info,
            "new_state": new_state.__dict__
        })
        
    except Exception as e:
        logger.error(f"Dialogue start failed: {e}")
        return jsonify({"error": "An internal error occurred", "success": False}), 500


@app.route("/api/dialogue/respond", methods=["POST"])
def api_dialogue_respond():
    """
    Choose a dialogue response.
    POST body: {run_id, conversation_id, node_id, response_id}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        conversation_id = data.get("conversation_id")
        node_id = data.get("node_id")
        response_id = data.get("response_id")
        
        if not all([run_id, conversation_id, node_id, response_id]):
            return jsonify({"error": "Missing required parameters"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        dialogue_config = game.get("dialogue", {})
        if not dialogue_config:
            return jsonify({"error": "Game does not support dialogue"}), 400
        
        # Get current state
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        
        # Initialize dialogue engine
        dialogue_engine = DialogueEngine(dialogue_config)
        
        # Choose response
        next_node_data, new_state, result = dialogue_engine.choose_response(
            conversation_id, node_id, response_id, state
        )
        
        # Get NPC info
        conv = dialogue_engine.conversations.get(conversation_id, {})
        npc_id = conv.get("npc_id")
        npc_info = {}
        if npc_id:
            npc = dialogue_engine.npcs.get(npc_id, {})
            npc_info = {
                "name": npc.get("name", "Unknown"),
                "avatar": npc.get("avatar", ""),
                "relationship": dialogue_engine.get_npc_relationship(npc_id, new_state),
                "relationship_status": dialogue_engine.get_relationship_status(npc_id, new_state)
            }
        
        # Update run
        run_data["state"] = new_state.__dict__
        update_run(run_id, run_data)
        
        return jsonify({
            "success": True,
            "next_node": next_node_data,
            "npc_info": npc_info,
            "new_state": new_state.__dict__,
            "message": result
        })
        
    except Exception as e:
        logger.error(f"Dialogue respond failed: {e}")
        return jsonify({"error": "An internal error occurred", "success": False}), 500


