@app.route("/api/rpg/combat/action", methods=["POST"])
def api_rpg_combat_action():
    """
    Execute a combat action.
    POST body: {run_id, actor_id, action: {type, target_id, skill_id?, item_id?}}
    """
    try:
        data = request.json
        run_id = data.get("run_id")
        actor_id = data.get("actor_id")
        action = data.get("action", {})
        
        if not run_id or not actor_id or not action:
            return jsonify({"error": "Missing required fields"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        rpg_config = game.get("rpg", {})
        if not rpg_config:
            return jsonify({"error": "Game does not have RPG system"}), 400
        
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        
        combat_state = getattr(state, 'active_combat', None)
        if not combat_state or not combat_state.get("active"):
            return jsonify({"error": "No active combat"}), 400
        
        rpg_engine = RPGEngine(rpg_config)
        
        # Execute action
        combat_state = rpg_engine.execute_action(combat_state, actor_id, action)
        
        # Check if combat ended
        combat_result = rpg_engine.check_combat_end(combat_state)
        
        if combat_result:
            combat_state["active"] = False
            combat_state["result"] = combat_result
            
            # Award experience on victory
            if combat_result == "victory":
                exp_per_enemy = 50
                total_exp = len(combat_state["enemies"]) * exp_per_enemy
                
                for char in combat_state["party"]:
                    if char["current_hp"] > 0:
                        state, leveled_up = rpg_engine.gain_exp(state, char["id"], total_exp // len([c for c in combat_state["party"] if c["current_hp"] > 0]))
                        if leveled_up:
                            combat_state["log"].append(f"{char['name']} leveled up!")
        else:
            # Advance turn
            combat_state["current_turn"] = (combat_state["current_turn"] + 1) % len(combat_state["turn_order"])
            if combat_state["current_turn"] == 0:
                combat_state["round"] += 1
            
            # Auto-execute enemy turns
            current_turn_id = combat_state["turn_order"][combat_state["current_turn"]]
            is_enemy = any(e["id"] == current_turn_id for e in combat_state["enemies"])
            
            while is_enemy and not rpg_engine.check_combat_end(combat_state):
                enemy = next(e for e in combat_state["enemies"] if e["id"] == current_turn_id)
                enemy_char = rpg_engine.Character(enemy)
                
                if enemy_char.is_alive():
                    party_chars = [rpg_engine.Character(c) for c in combat_state["party"]]
                    enemy_action = rpg_engine.get_enemy_action(enemy_char, party_chars)
                    combat_state = rpg_engine.execute_action(combat_state, current_turn_id, enemy_action)
                
                # Check combat end after enemy action
                combat_result = rpg_engine.check_combat_end(combat_state)
                if combat_result:
                    combat_state["active"] = False
                    combat_state["result"] = combat_result
                    break
                
                # Advance to next turn
                combat_state["current_turn"] = (combat_state["current_turn"] + 1) % len(combat_state["turn_order"])
                if combat_state["current_turn"] == 0:
                    combat_state["round"] += 1
                
                current_turn_id = combat_state["turn_order"][combat_state["current_turn"]]
                is_enemy = any(e["id"] == current_turn_id for e in combat_state["enemies"])
        
        # Update state
        state.active_combat = combat_state
        
        # Update party HP/MP from combat
        party = rpg_engine.get_party(state)
        for i, char in enumerate(party):
            combat_char = next((c for c in combat_state["party"] if c["id"] == char.id), None)
            if combat_char:
                char.current_hp = combat_char["current_hp"]
                char.current_mp = combat_char["current_mp"]
        state = rpg_engine.save_party(state, party)
        
        # Save updated state
        run_data["state"] = state.__dict__
        update_run(run_id, run_data)
        
        return jsonify({
            "success": True,
            "combat_state": combat_state,
            "combat_ended": combat_result is not None,
            "result": combat_result
        })
        
    except Exception as e:
        logger.error(f"Failed to execute combat action: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": "An internal error occurred"}), 500


@app.route("/api/rpg/party", methods=["GET"])
def api_rpg_get_party():
    """
    Get current party state.
    Query params: run_id
    """
    try:
        run_id = request.args.get("run_id")
        if not run_id:
            return jsonify({"error": "Missing run_id"}), 400
        
        run_data = get_run(run_id)
        if not run_data:
            return jsonify({"error": "Run not found"}), 404
        
        game_id = run_data.get("game_id")
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        
        rpg_config = game.get("rpg", {})
        if not rpg_config:
            return jsonify({"party": []})
        
        state_dict = run_data.get("state", {})
        state = RunState(**state_dict)
        
        rpg_engine = RPGEngine(rpg_config)
        party = rpg_engine.get_party(state)
        
        return jsonify({
            "party": [char.to_dict() for char in party]
        })
        
    except Exception as e:
        logger.error(f"Failed to get party: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


