@app.post("/api/audio/negotiation/start")
def api_audio_negotiation_start():
    """Start an audio-based negotiation game."""
    try:
        data = request.json
        game_id = data.get("game_id")
        if not game_id:
            return jsonify({"error": "Missing game_id"}), 400

        game, err = get_game_or_400(game_id)
        if err:
            return err

        if not is_audio_negotiation_game(game):
            return jsonify({"error": "Game does not support audio negotiation"}), 400

        audio_engine = create_audio_negotiation_engine(game)
        if not audio_engine or not audio_engine.is_enabled():
            return jsonify({"error": "Audio negotiation not configured. Check OPENAI_API_KEY and LLM_ENABLED."}), 500

        initial_state = {
            "rapport_score": 50,
            "understanding_score": 50,
            "assertiveness_score": 50,
            "current_round": 0,
            "conversation_history": [],
            "rounds_completed": []
        }
        run_id = create_run(game_id, initial_state, game)
        first_round = audio_engine.get_round_config(0)

        return jsonify({
            "success": True,
            "run_id": run_id,
            "game_id": game_id,
            "game_title": game.get("title", ""),
            "total_rounds": audio_engine.get_total_rounds(),
            "current_round": 0,
            "round_objective": first_round.get("objective", ""),
            "ai_persona": first_round.get("ai_persona", {}),
            "state": initial_state,
            "audio_config": {
                "stt_provider": audio_engine.stt_provider.value,
                "tts_provider": audio_engine.tts_provider.value,
                "voice_settings": audio_engine.voice_settings
            }
        })
    except Exception as e:
        logger.error(f"Failed to start audio negotiation: {e}")
        import traceback; traceback.print_exc()
        return jsonify({"error": "An internal error occurred"}), 500


@app.post("/api/audio/transcribe")
def api_audio_transcribe():
    """Transcribe audio to text using configured STT provider.
    run_id is optional — if absent or game has no audio engine, falls back to direct OpenAI Whisper."""
    try:
        run_id = request.form.get("run_id")
        if "audio" not in request.files:
            return jsonify({"error": "No audio file provided"}), 400

        audio_file = request.files["audio"]
        audio_format = request.form.get("format", "webm")

        # Try game-specific audio engine if run_id provided
        audio_engine = None
        if run_id:
            try:
                r = get_run(run_id)
                game_id = r["game_id"]
                game, err = get_game_or_400(game_id)
                if not err:
                    audio_engine = create_audio_negotiation_engine(game)
                    if audio_engine and not audio_engine.is_enabled():
                        audio_engine = None
            except (KeyError, Exception):
                pass  # Fall through to direct Whisper

        if audio_engine:
            transcription = audio_engine.transcribe_audio(audio_file, audio_format)
            return jsonify({"success": True, "transcription": transcription})

        # Fallback: direct OpenAI Whisper
        api_key = os.environ.get("OPENAI_API_KEY", "")
        if not api_key:
            return jsonify({"error": "Transcription not available — no API key configured"}), 503
        try:
            from openai import OpenAI as _OpenAI
            client = _OpenAI(api_key=api_key)
            # Read audio bytes and create a file-like object with correct name
            audio_bytes = audio_file.read()
            import io
            ext = "webm" if audio_format == "webm" else audio_format
            audio_buf = io.BytesIO(audio_bytes)
            audio_buf.name = f"recording.{ext}"
            result = client.audio.transcriptions.create(
                model="whisper-1",
                file=audio_buf,
                language="en",
            )
            transcription = result.text or ""
            try:
                from cost_tracker import log_cost
                audio_dur = len(audio_bytes) / 32000  # rough estimate: ~32KB/sec for compressed audio
                log_cost("stt", "whisper-1", purpose="audio_transcribe", duration_seconds=audio_dur)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            return jsonify({"success": True, "transcription": transcription})
        except Exception as whisper_err:
            logger.warning(f"Direct Whisper transcription failed: {whisper_err}")
            return jsonify({"error": "Transcription failed"}), 500
    except Exception as e:
        logger.error(f"Transcription failed: {e}")
        import traceback; traceback.print_exc()
        return jsonify({"error": "An internal error occurred"}), 500


@app.post("/api/audio/speak")
def api_audio_speak():
    """Convert text to speech. Returns audio/mpeg binary.
    run_id is optional — if absent or game has no audio engine, falls back to direct OpenAI TTS."""
    try:
        data = request.json
        text = data.get("text")
        run_id = data.get("run_id")
        voice_id = data.get("voice_id")
        if not text:
            return jsonify({"error": "Missing text"}), 400

        # Explicit voice_id override (used by investor pitch per-investor voices)
        VALID_VOICES = {"alloy", "echo", "fable", "onyx", "nova", "shimmer"}
        if voice_id and voice_id in VALID_VOICES:
            api_key = os.environ.get("OPENAI_API_KEY", "")
            if not api_key:
                return jsonify({"error": "TTS not available", "use_browser_tts": True}), 503
            try:
                from openai import OpenAI as _OpenAI
                client = _OpenAI(api_key=api_key)
                tts_response = client.audio.speech.create(
                    model="tts-1", voice=voice_id, input=text[:4096]
                )
                audio_bytes = tts_response.content
                try:
                    from cost_tracker import log_cost
                    log_cost("tts", "tts-1", purpose="audio_speak_voice", characters=len(text[:4096]))
                except Exception as _e:
                    logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
                response = make_response(audio_bytes)
                response.headers["Content-Type"] = "audio/mpeg"
                response.headers["Content-Disposition"] = "attachment; filename=speech.mp3"
                return response
            except Exception as tts_err:
                logger.warning(f"voice_id TTS failed: {tts_err}")
                return jsonify({"error": "TTS not available", "use_browser_tts": True}), 503

        audio_engine = None
        # Try game-specific audio engine if run_id provided
        if run_id:
            try:
                r = get_run(run_id)
                game_id = r["game_id"]
                game, err = get_game_or_400(game_id)
                if not err:
                    audio_engine = create_audio_negotiation_engine(game)
                    if audio_engine and not audio_engine.is_enabled():
                        audio_engine = None
            except (KeyError, Exception):
                pass  # Fall through to direct TTS

        # Use game audio engine if available
        if audio_engine:
            audio_bytes = audio_engine.synthesize_speech(text)
        else:
            # Fallback: direct OpenAI TTS
            api_key = os.environ.get("OPENAI_API_KEY", "")
            if not api_key:
                return jsonify({"error": "TTS not available", "use_browser_tts": True}), 503
            try:
                from openai import OpenAI as _OpenAI
                client = _OpenAI(api_key=api_key)
                tts_response = client.audio.speech.create(
                    model="tts-1",
                    voice="nova",
                    input=text[:4096],
                )
                audio_bytes = tts_response.content
                try:
                    from cost_tracker import log_cost
                    log_cost("tts", "tts-1", purpose="audio_speak_default", characters=len(text[:4096]))
                except Exception as _e:
                    logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            except Exception as tts_err:
                logger.warning(f"Direct TTS fallback failed: {tts_err}")
                return jsonify({"error": "TTS not available", "use_browser_tts": True}), 503

        response = make_response(audio_bytes)
        response.headers["Content-Type"] = "audio/mpeg"
        response.headers["Content-Disposition"] = "attachment; filename=speech.mp3"
        return response
    except Exception as e:
        logger.error(f"TTS failed: {e}")
        import traceback; traceback.print_exc()
        return jsonify({"error": "An internal error occurred"}), 500


@app.post("/api/audio/negotiation/turn")
def api_audio_negotiation_turn():
    """Process a conversation turn in audio negotiation."""
    try:
        data = request.json
        run_id = data.get("run_id")
        user_message = data.get("user_message")
        if not run_id or not user_message:
            return jsonify({"error": "Missing run_id or user_message"}), 400

        try:
            r = get_run(run_id)
        except KeyError as e:
            return jsonify({"error": "Resource not found"}), 404

        game_id = r["game_id"]
        game, err = get_game_or_400(game_id)
        if err:
            return err

        audio_engine = create_audio_negotiation_engine(game)
        if not audio_engine or not audio_engine.is_enabled():
            return jsonify({"error": "Audio engine not configured"}), 500

        state_obj = r.get("state")
        current_state = state_obj if isinstance(state_obj, dict) else state_to_dict(state_obj)
        current_round = current_state.get("current_round", 0)
        conversation_history = current_state.get("conversation_history", [])

        round_config = audio_engine.get_round_config(current_round)
        if not round_config:
            return jsonify({"error": "Invalid round"}), 400

        result = audio_engine.process_conversation_turn(
            user_message=user_message,
            round_config=round_config,
            conversation_history=conversation_history,
            current_state=current_state
        )

        conversation_history.append({"speaker": "student", "message": user_message, "turn": len(conversation_history)})
        conversation_history.append({"speaker": "ai", "message": result["ai_response"], "turn": len(conversation_history), "assessment": result["assessment"]})

        updated_state = result["updated_state"]
        updated_state["conversation_history"] = conversation_history
        updated_state["current_round"] = current_round

        if result["should_progress"]:
            round_evaluation = audio_engine.evaluate_round_completion(
                round_config=round_config,
                conversation_history=conversation_history,
                final_state=updated_state
            )
            updated_state.setdefault("rounds_completed", []).append({
                "round_index": current_round,
                "round_id": round_config.get("id"),
                "evaluation": round_evaluation,
                "conversation_count": len(conversation_history)
            })

            next_round_index = current_round + 1
            if next_round_index < audio_engine.get_total_rounds():
                updated_state["current_round"] = next_round_index
                updated_state["conversation_history"] = []
                next_round_config = audio_engine.get_round_config(next_round_index)
                r["state"] = updated_state
                update_run(run_id, r)
                return jsonify({
                    "success": True, "ai_response": result["ai_response"],
                    "assessment": result["assessment"], "phase": result["phase"],
                    "round_completed": True, "round_evaluation": round_evaluation,
                    "next_round": {"round_index": next_round_index, "objective": next_round_config.get("objective", ""), "ai_persona": next_round_config.get("ai_persona", {})},
                    "state": updated_state
                })
            else:
                updated_state["game_completed"] = True
                r["state"] = updated_state
                update_run(run_id, r)
                return jsonify({
                    "success": True, "ai_response": result["ai_response"],
                    "assessment": result["assessment"],
                    "round_completed": True, "round_evaluation": round_evaluation,
                    "game_completed": True, "final_state": updated_state,
                    "rounds_completed": updated_state.get("rounds_completed", [])
                })

        r["state"] = updated_state
        update_run(run_id, r)
        return jsonify({
            "success": True, "ai_response": result["ai_response"],
            "assessment": result["assessment"], "phase": result["phase"],
            "negotiation_progress": result.get("negotiation_progress", 0),
            "round_completed": False, "state": updated_state
        })
    except Exception as e:
        logger.error(f"Conversation turn failed: {e}")
        import traceback; traceback.print_exc()
        return jsonify({"error": "An internal error occurred"}), 500


@app.post("/api/audio/negotiation/evaluate")
def api_audio_negotiation_evaluate():
    """Evaluate a completed audio negotiation round."""
    try:
        data = request.json
        run_id = data.get("run_id")
        round_index = data.get("round_index")
        if not run_id:
            return jsonify({"error": "Missing run_id"}), 400

        try:
            r = get_run(run_id)
        except KeyError as e:
            return jsonify({"error": "Resource not found"}), 404

        game_id = r["game_id"]
        game, err = get_game_or_400(game_id)
        if err:
            return err

        audio_engine = create_audio_negotiation_engine(game)
        if not audio_engine or not audio_engine.is_enabled():
            return jsonify({"error": "Audio engine not configured"}), 500

        state_obj = r.get("state")
        current_state = state_obj if isinstance(state_obj, dict) else state_to_dict(state_obj)
        if round_index is None:
            round_index = current_state.get("current_round", 0)

        round_config = audio_engine.get_round_config(round_index)
        if not round_config:
            return jsonify({"error": "Invalid round"}), 400

        conversation_history = current_state.get("conversation_history", [])
        evaluation = audio_engine.evaluate_round_completion(
            round_config=round_config,
            conversation_history=conversation_history,
            final_state=current_state
        )
        return jsonify({"success": True, "evaluation": evaluation})
    except Exception as e:
        logger.error(f"Evaluation failed: {e}")
        import traceback; traceback.print_exc()
        return jsonify({"error": "An internal error occurred"}), 500


# ==================== SAVE / RESUME ====================

@app.route("/api/saves", methods=["GET"])
def list_saved_games():
    """List all in-progress (non-ended) game sessions that can be resumed."""
    try:
        saves = []
        for run_id in storage.list_runs():
            try:
                run_data = storage.get_run(run_id)
            except Exception:
                continue

            state = run_data.get("state")
            if state is None:
                continue

            # Skip completed games
            state_dict = state.to_dict() if hasattr(state, "to_dict") else state
            if state_dict.get("game_over"):
                continue

            game_id = run_data.get("game_id", "")
            game = GAMES.get(game_id, {})
            total_rounds = len(game.get("rounds", []))
            round_index = state_dict.get("round_index", 0)

            # Detect turn/progress for grid-based game types
            game_type = game.get("game_type", "")
            turn_number = None
            sg_state = run_data.get("sg_state")
            if sg_state:
                turn_number = sg_state.get("turn_number")
            elif state_dict.get("turn_number"):
                turn_number = state_dict.get("turn_number")

            saves.append({
                "run_id": run_id,
                "game_id": game_id,
                "game_title": game.get("title", game_id),
                "game_type": game_type,
                "icon": game.get("icon", "🎮"),
                "theme_colors": game.get("theme_colors", {}),
                "round_index": round_index,
                "total_rounds": total_rounds,
                "turn_number": turn_number,
                "created_at": run_data.get("created_at", ""),
                "last_accessed": run_data.get("last_accessed", ""),
            })

        # Sort by most recent first
        saves.sort(key=lambda s: s.get("last_accessed", ""), reverse=True)
        return jsonify({"saves": saves})
    except Exception as e:
        logger.error(f"list_saved_games: {e}")
        return jsonify({"saves": []})


@app.route("/api/run/<run_id>/resume", methods=["POST"])
def resume_game(run_id):
    """Resume an existing game run."""
    try:
        run_data = storage.get_run(run_id)
        state = run_data["state"]
        game_id = run_data["game_id"]
        game, err = get_game_or_400(game_id)
        if err:
            return err

        state_dict = state.to_dict() if hasattr(state, "to_dict") else state
        round_index = state_dict.get("round_index", 0)

        return jsonify({
            "run_id": run_id,
            "game_id": game_id,
            "game": game,
            "state": state_dict,
            "round_index": round_index,
        })
    except Exception as e:
        logger.error(f"resume_game: {e}")
        return jsonify({"error": "Resource not found"}), 404


# ==================== BOARD GAME ENDPOINTS ====================

@app.route('/api/run/<run_id>/roll', methods=['POST'])
def board_roll_dice(run_id):
    """Roll dice for a board game and return new position + tile event."""
    from board_engine import BoardEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    # Load game data from storage using game_id
    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err
    if game_data.get("game_type") != "board":
        return jsonify({"error": "Not a board game"}), 400

    engine = BoardEngine(game_data)
    dice_value = engine.roll_dice()

    # Get or initialize board state
    board_state = run.get("board_state") or {"path_index": 0, "visited": [], "dice_history": []}
    current_index = board_state.get("path_index", 0)
    new_index = engine.calculate_new_position(current_index, dice_value)

    tile = engine.get_tile_by_index(new_index)
    event = engine.get_event_for_tile(tile)
    is_finished = engine.is_finish(new_index)

    board_state["path_index"] = new_index
    board_state["dice_history"].append(dice_value)
    if tile:
        board_state["visited"].append(tile.get("position"))

    run["board_state"] = board_state
    storage.update_run(run_id, run)

    return jsonify({
        "dice_value": dice_value,
        "new_index": new_index,
        "tile": tile,
        "event": event,
        "is_finished": is_finished,
        "board_state": board_state,
    })


@app.route('/api/run/<run_id>/board/log-choice', methods=['POST'])
def board_log_choice(run_id):
    """Log a board game event choice, boss answer, or decision for the run log."""
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    data = request.get_json(silent=True) or {}
    choice_type = data.get("type", "event")
    choice_id = data.get("choice_id", "")
    choice_label = data.get("choice_label", "")
    event_title = data.get("event_title", "")
    delta = data.get("delta", {})
    feedback = data.get("feedback", "")
    correct = data.get("correct")
    turn = data.get("turn", 0)
    path_index = data.get("path_index", 0)
    glossary_terms = data.get("glossary_terms", [])
    reflection = data.get("reflection", "")

    # Infer skill tags from delta + choice text
    from engines.dimension_utils import infer_skill_tags_from_deltas, build_skill_callout
    skill_tags = data.get("skill_tags") or infer_skill_tags_from_deltas(delta, choice_label)

    # Build log entry
    log_entry = {
        "round_id": f"board_turn_{turn}",
        "round_title": event_title,
        "choice": {"id": choice_id, "label": choice_label},
        "choice_type": choice_type,
        "events": [feedback] if feedback else [],
        "nep_tags": [],
        "skill_tags": skill_tags,
        "state_before": {},
        "state_after_events": {},
        "delta": delta,
        "path_index": path_index,
        "correct": correct,
    }
    if reflection:
        log_entry["reflection"] = reflection

    # Accumulate into board_choices for dimension scoring later
    board_choices = run.get("board_choices", [])
    board_choices.append({
        "choice_id": choice_id,
        "choice_label": choice_label,
        "choice_type": choice_type,
        "delta": delta,
        "skill_tags": skill_tags,
        "correct": correct,
        "turn": turn,
        "path_index": path_index,
        "glossary_terms": glossary_terms,
    })
    run["board_choices"] = board_choices

    # Concept mastery tracking
    concept_mastery = run.get("concept_mastery", {})
    for term in glossary_terms:
        if term not in concept_mastery:
            concept_mastery[term] = {"encounters": 0, "positive_outcomes": 0}
        concept_mastery[term]["encounters"] += 1
        net_delta = sum(v for v in delta.values() if isinstance(v, (int, float)))
        if net_delta > 0:
            concept_mastery[term]["positive_outcomes"] += 1
    run["concept_mastery"] = concept_mastery

    run["log"].append(log_entry)
    storage.update_run(run_id, run)

    # Return skill callout for frontend display
    callout = None
    if skill_tags:
        callout = build_skill_callout(skill_tags[0], sum(v for v in delta.values() if isinstance(v, (int, float))))

    return jsonify({"logged": True, "skill_tags": skill_tags, "callout": callout})


@app.route('/api/run/<run_id>/board/generate-tile-story', methods=['POST'])
def board_generate_tile_story(run_id):
    """Generate an AI-powered contextual story for a board game tile."""
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    data = request.get_json(silent=True) or {}
    tile_id = data.get("tile_id", "")
    tile_type = data.get("tile_type", "event")
    tile_label = data.get("tile_label", "")
    fallback_event = data.get("fallback_event")
    generate_image = data.get("generate_image", False)

    # Check cache first
    cached_stories = run.get("generated_tile_stories", {})
    if tile_id and tile_id in cached_stories:
        return jsonify({"story": cached_stories[tile_id], "cached": True, "ai_generated": True})

    # Build context from game data
    game_id = run.get("game_id", "")
    game = GAMES.get(game_id, {})
    game_title = game.get("title", "Board Game")
    game_theme = game.get("theme", game.get("description", "strategy and skills"))

    # Build summary of recent choices from run log
    recent_choices = []
    for entry in (run.get("log") or [])[-5:]:
        ch = entry.get("choice", {})
        if ch.get("label"):
            recent_choices.append(ch["label"])
    choices_summary = "; ".join(recent_choices) if recent_choices else ""

    # Current resources from request (client has current state)
    current_resources = data.get("current_resources", {})

    # Glossary terms from game's board config
    board_config = game.get("board_config", {})
    glossary_terms = list((board_config.get("glossary") or {}).keys())[:5]

    # Generate story via LLM
    story = generate_board_tile_story(
        game_title=game_title,
        game_theme=game_theme,
        tile_type=tile_type,
        tile_label=tile_label,
        previous_choices_summary=choices_summary,
        current_resources=current_resources,
        glossary_terms=glossary_terms,
        fallback_event=fallback_event,
    )

    ai_generated = isinstance(story, dict) and story.get("title") and story != fallback_event

    # Generate image for AI-generated stories
    if generate_image and ai_generated:
        try:
            from services.story_image_service import generate_story_image
            image_prompt = f"{game_title}: {story.get('title', '')} - {story.get('story', '')[:100]}"
            result = generate_story_image(game_id, tile_id, image_prompt=image_prompt)
            if isinstance(result, dict) and result.get("image_url"):
                story["image_url"] = result["image_url"]
            elif isinstance(result, dict) and result.get("fallback_url"):
                story["image_url"] = result["fallback_url"]
        except Exception as e:
            app.logger.warning(f"Board tile image generation failed: {e}")
            pass  # Image generation is optional

    # Cache in run data
    if ai_generated and tile_id:
        if "generated_tile_stories" not in run:
            run["generated_tile_stories"] = {}
        run["generated_tile_stories"][tile_id] = story
        storage.update_run(run_id, run)

    return jsonify({"story": story, "cached": False, "ai_generated": ai_generated})


@app.route('/api/run/<run_id>/board/complete', methods=['POST'])
def board_complete(run_id):
    """Finalize a board game: compute dimension scores, store learned terms."""
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    data = request.get_json(silent=True) or {}
    learned_terms = data.get("learned_terms", [])
    final_resources = data.get("final_resources", {})
    move_history = data.get("move_history", [])
    boss_wins = data.get("boss_wins", 0)
    total_turns = data.get("total_turns", 0)
    achievements = data.get("achievements", [])

    # Store learned terms
    run["board_learned_terms"] = learned_terms

    # Compute dimension scores from accumulated choices
    board_choices = run.get("board_choices", [])
    dimension_scores = _compute_board_dimension_scores(board_choices, boss_wins, total_turns, final_resources)

    # Set dimension scores on the state object
    st_obj = run["state"]
    if hasattr(st_obj, 'dimension_scores'):
        st_obj.dimension_scores = dimension_scores
    else:
        st_obj.dimension_scores = dimension_scores
    for dim, score in dimension_scores.items():
        setattr(st_obj, dim, score)

    run["board_state"] = {
        "completed": True,
        "learned_terms": learned_terms,
        "final_resources": final_resources,
        "move_history": move_history[-20:] if move_history else [],
        "boss_wins": boss_wins,
        "total_turns": total_turns,
        "achievements": achievements,
    }

    storage.update_run(run_id, run)
    try:
        from llm import record_coaching_tip_outcome
        _tip_id = run.get("_coaching_tip_id")
        if _tip_id and dimension_scores:
            _weakest = min(dimension_scores, key=dimension_scores.get)
            _avg = sum(dimension_scores.values()) / max(1, len(dimension_scores))
            record_coaching_tip_outcome(_tip_id, "board", _weakest, _avg - 50)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    return jsonify({"completed": True, "dimension_scores": dimension_scores})


@app.route('/api/cross-game-analysis', methods=['GET'])
def cross_game_analysis():
    """Analyze dimension scores across multiple completed games for a user."""
    import glob as glob_mod
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    user_id = user_payload["user_id"]
    reports_dir = os.path.join(os.path.dirname(__file__), "game_sessions", "reports")

    # Load all reports for this user
    game_reports = []
    for report_path in glob_mod.glob(os.path.join(reports_dir, "*.json")):
        try:
            with open(report_path) as f:
                report = json.load(f)
            if report.get("user_id") == user_id and report.get("report", {}).get("dimension_scores"):
                game_reports.append(report)
        except Exception:
            continue

    if not game_reports:
        return jsonify({"analysis": None, "message": "No completed games with dimension scores found."})

    # Aggregate dimension scores across games
    from engines.dimension_utils import STANDARD_DIMENSIONS
    dim_totals = {}
    dim_counts = {}
    game_summaries = []

    for report in game_reports:
        dims = report.get("report", {}).get("dimension_scores", [])
        game_title = report.get("report", {}).get("game", {}).get("title", "Unknown")
        game_dims = {}
        for d in dims:
            name = d.get("name", "")
            value = d.get("value", 0)
            dim_totals[name] = dim_totals.get(name, 0) + value
            dim_counts[name] = dim_counts.get(name, 0) + 1
            game_dims[name] = value
        game_summaries.append({
            "game_title": game_title,
            "run_id": report.get("run_id"),
            "timestamp": report.get("timestamp"),
            "dimensions": game_dims,
        })

    # Compute averages
    averages = {}
    for dim in dim_totals:
        averages[dim] = round(dim_totals[dim] / max(1, dim_counts[dim]))

    # Identify strengths (top 2) and growth areas (bottom 2)
    sorted_dims = sorted(averages.items(), key=lambda x: x[1], reverse=True)
    strengths = [{"name": d[0], "avg_score": d[1], "label": STANDARD_DIMENSIONS.get(d[0], {}).get("label", d[0].replace("_", " ").title())} for d in sorted_dims[:2]]
    growth_areas = [{"name": d[0], "avg_score": d[1], "label": STANDARD_DIMENSIONS.get(d[0], {}).get("label", d[0].replace("_", " ").title())} for d in sorted_dims[-2:]]

    # Recommendations
    recommendations = []
    for area in growth_areas:
        recs = {
            "risk_tolerance": "Try taking more calculated risks in games. Start with small gambles and observe the outcomes.",
            "strategic_thinking": "Focus on planning ahead. Before each choice, think about the consequences 2-3 steps ahead.",
            "delayed_gratification": "Practice choosing long-term benefits over short-term rewards in your next game.",
            "adaptability": "When things don't go as planned, try a completely different approach instead of repeating the same strategy.",
            "resilience": "After setbacks, keep pushing forward. Remember that recovering from failure is a key life skill.",
            "empathy": "Consider how your choices affect other characters and team members in the game.",
        }
        recommendations.append({
            "dimension": area["name"],
            "label": area["label"],
            "recommendation": recs.get(area["name"], f"Focus on improving your {area['label']} skills."),
        })

    return jsonify({
        "analysis": {
            "total_games": len(game_reports),
            "averages": averages,
            "strengths": strengths,
            "growth_areas": growth_areas,
            "recommendations": recommendations,
            "game_history": game_summaries[-10:],
        }
    })


# ==================== MINI-GAME ENDPOINTS ====================

@app.route('/api/run/<run_id>/minigame/start', methods=['POST'])
def minigame_start(run_id):
    """Start a mini-game session."""
    from minigame_engine import MiniGameEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    # Load game data from storage using game_id
    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err
    if game_data.get("game_type") != "minigame":
        return jsonify({"error": "Not a mini-game"}), 400

    engine = MiniGameEngine(game_data)
    # Item 22: Support challenge_id on start
    challenge_id = (request.json or {}).get("challenge_id") if request.json else None
    session = engine.start_session(challenge_id=challenge_id)

    run["minigame_state"] = session
    storage.update_run(run_id, run)

    return jsonify({"session": session})


@app.route('/api/run/<run_id>/minigame/action', methods=['POST'])
def minigame_action(run_id):
    """Process a mini-game action."""
    from minigame_engine import MiniGameEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    # Load game data from storage using game_id
    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err
    engine = MiniGameEngine(game_data)
    session = run.get("minigame_state", {})

    if session.get("completed"):
        return jsonify({"error": "Game already completed", "session": session}), 400

    action = request.json or {}
    session = engine.process_action(session, action)

    result = None
    if session.get("completed"):
        result = engine.evaluate(session)

        # Item 23: Store dimension scores for cross-minigame pattern analysis
        if result and result.get("dimension_scores"):
            minigame_history = run.get("minigame_dimension_history", [])
            minigame_history.append({
                "game_id": game_id,
                "subtype": session.get("subtype", ""),
                "dimension_scores": result["dimension_scores"],
                "percentage": result.get("percentage", 0),
                "tier": result.get("tier", ""),
                "challenge_result": result.get("challenge_result"),
            })
            run["minigame_dimension_history"] = minigame_history

    run["minigame_state"] = session
    storage.update_run(run_id, run)

    return jsonify({"session": session, "result": result})


@app.route('/api/run/<run_id>/minigame/state', methods=['GET'])
def minigame_state(run_id):
    """Get current mini-game state."""
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404
    return jsonify({"session": run.get("minigame_state", {})})


@app.route('/api/run/<run_id>/minigame/complete', methods=['POST'])
def minigame_complete(run_id):
    """Record minigame completion, compute dimension scores, award XP."""
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    data = request.get_json(silent=True) or {}
    game_subtype = data.get("game_type", "minigame")
    final_score   = int(data.get("final_score", 0))
    won           = bool(data.get("won", False))

    # Record score on state so compute_dimension_scores can use it
    st_obj = run.get("state")
    if st_obj is not None:
        scores = getattr(st_obj, "minigame_scores", {}) or {}
        scores[game_subtype] = scores.get(game_subtype, []) + [final_score]
        st_obj.minigame_scores = scores

        completed = getattr(st_obj, "minigames_completed", []) or []
        if game_subtype not in completed:
            completed.append(game_subtype)
        st_obj.minigames_completed = completed

        # Compute dimensions via MiniGameEngine (standalone engine)
        try:
            from minigame_engine import MiniGameEngine
            game = run.get("game", {})
            session = run.get("minigame_state") or {}
            # Ensure final_score is reflected in session for scoring
            if final_score and not session.get("score"):
                session = dict(session)
                session["score"] = final_score
                session["completed"] = True
            eng = MiniGameEngine(game)
            dimension_scores = eng.compute_dimension_scores(session)
            st_obj.dimension_scores = dimension_scores
            for dim, val in dimension_scores.items():
                setattr(st_obj, dim, val)
        except Exception as e:
            logger.info(f"[minigame/complete] dimension scoring failed: {e}")
            dimension_scores = {}

        storage.update_run(run_id, run)
    else:
        dimension_scores = {}

    # Award XP
    try:
        user_id = run.get("user_id") or get_current_user_id()
        if user_id:
            xp_gain = max(10, int(final_score * 0.5) + (50 if won else 10))
            psych = {k: {"final": v, "name": k.replace("_", " ").title()} for k, v in dimension_scores.items()}
            award_xp(user_id, xp_gain, f"Minigame: {game_subtype}", "minigame", final_score, psych)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # A1: Record coaching tip outcome for RL bandit learning
    try:
        from llm import record_coaching_tip_outcome
        _tip_id = run.get("_coaching_tip_id")
        if _tip_id and dimension_scores:
            _weakest = min(dimension_scores, key=dimension_scores.get)
            _avg = sum(dimension_scores.values()) / max(1, len(dimension_scores))
            record_coaching_tip_outcome(_tip_id, game_subtype, _weakest, _avg - 50)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    return jsonify({"completed": True, "dimension_scores": dimension_scores})


@app.route('/api/minigame/insights', methods=['GET'])
def minigame_cross_insights():
    """
    Item 23: Cross-minigame pattern analysis.
    Aggregates dimension scores across all minigame runs to generate insights.
    Expects ?player_id=... or aggregates all available runs.
    """
    history = []
    try:
        run_ids = storage.list_runs() if hasattr(storage, 'list_runs') else []
        for rid in run_ids:
            run_data = storage.get_run(str(rid))
            if run_data and isinstance(run_data, dict):
                for entry in run_data.get("minigame_dimension_history", []):
                    history.append(entry)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    if not history:
        return jsonify({"insights": None, "message": "No minigame history available"})

    # Aggregate by subtype
    subtype_scores = {}
    for entry in history:
        sub = entry.get("subtype", "unknown")
        if sub not in subtype_scores:
            subtype_scores[sub] = {"scores": [], "count": 0}
        subtype_scores[sub]["scores"].append(entry.get("dimension_scores", {}))
        subtype_scores[sub]["count"] += 1

    # Compute averages per subtype per dimension
    subtype_averages = {}
    all_dims = {}
    for sub, data in subtype_scores.items():
        dims = {}
        for scores in data["scores"]:
            for dim, val in scores.items():
                dims.setdefault(dim, []).append(val)
                all_dims.setdefault(dim, []).append(val)
        subtype_averages[sub] = {
            "count": data["count"],
            "averages": {dim: round(sum(vals) / len(vals)) for dim, vals in dims.items()},
        }

    # Overall averages
    overall = {dim: round(sum(vals) / len(vals)) for dim, vals in all_dims.items()}

    # Find strengths and weaknesses
    if overall:
        sorted_dims = sorted(overall.items(), key=lambda x: x[1], reverse=True)
        strength = sorted_dims[0] if sorted_dims else None
        weakness = sorted_dims[-1] if len(sorted_dims) > 1 else None
    else:
        strength = weakness = None

    # Build insight text
    insight_text = None
    if strength and weakness:
        from engines.dimension_utils import STANDARD_DIMENSIONS
        s_meta = STANDARD_DIMENSIONS.get(strength[0], {})
        w_meta = STANDARD_DIMENSIONS.get(weakness[0], {})
        s_label = s_meta.get("short_label", strength[0].replace("_", " ").title())
        w_label = w_meta.get("short_label", weakness[0].replace("_", " ").title())
        insight_text = f"You excel at {s_label} (avg {strength[1]}%) but could improve {w_label} (avg {weakness[1]}%)."

    return jsonify({
        "total_plays": len(history),
        "subtype_averages": subtype_averages,
        "overall_averages": overall,
        "strength": {"dimension": strength[0], "average": strength[1]} if strength else None,
        "weakness": {"dimension": weakness[0], "average": weakness[1]} if weakness else None,
        "insight": insight_text,
    })


# ==================== STRATEGY GAME LEADERBOARD HELPERS ====================

def _compute_strategy_achievement_score(summary, game_type="chess_strategy"):
    """Generic achievement score (0-1000) for strategy games."""
    score = 0
    won = summary.get("winner") == "player"

    if game_type == "chess_strategy":
        if won: score += 500
        wt = summary.get("win_type", "")
        if wt == "ceo_captured": score += 100
        elif wt == "resource_control": score += 150
        elif wt == "valuation": score += 200
        score += summary.get("pieces_captured", 0) * 30
        score -= summary.get("pieces_lost", 0) * 20
        score += summary.get("resources_controlled", 0) * 50

    elif game_type == "strategy_grid":
        if won: score += 500
        score += summary.get("pieces_captured", 0) * 25
        score -= summary.get("pieces_lost", 0) * 15
        score += summary.get("resources_controlled", 0) * 40
        score += summary.get("turns_played", 0) * 3

    elif game_type == "go_territory":
        if won: score += 500
        ps = summary.get("player_score", 0)
        ais = summary.get("ai_score", 0)
        if ps + ais > 0:
            score += int((ps / max(1, ps + ais)) * 300)
        score += summary.get("player_territory", 0) * 5
        score += summary.get("player_captures", 0) * 20

    elif game_type == "reversi":
        if won: score += 500
        pd = summary.get("player_discs", 0)
        ad = summary.get("ai_discs", 0)
        if pd + ad > 0:
            score += int((pd / max(1, pd + ad)) * 300)
        score += summary.get("corners_controlled", 0) * 50

    elif game_type == "tower_defense":
        if won: score += 500
        score += summary.get("waves_cleared", 0) * 40
        score += summary.get("enemies_killed", 0) * 5
        lives = summary.get("lives_remaining", 0)
        score += lives * 30

    elif game_type == "puzzle_match":
        ps = summary.get("player_score", 0)
        ts = summary.get("target_score", 1)
        ratio = min(1.0, ps / max(1, ts))
        score += int(ratio * 600)
        score += summary.get("max_chain", 0) * 30
        if won: score += 200

    # Add dimension score bonus for all types
    dim = summary.get("dimension_scores", {})
    if dim:
        score += sum(dim.values()) // len(dim)

    return max(0, min(1000, score))

def _compute_strategy_tier(score):
    if score >= 800: return "Legend"
    if score >= 650: return "Master"
    if score >= 500: return "Expert"
    if score >= 350: return "Advanced"
    if score >= 200: return "Intermediate"
    return "Novice"

# ─── Leaderboard population stats cache (Task 8 — P0 plan) ───────────────────
# Per-game-type Z-score normalization uses pop_stats[game_type][dim] = {mean,std}.
# Recomputed daily by _recompute_leaderboard_pop_stats() in _run_scheduler().
_LB_POP_STATS_CACHE = {"loaded_at": 0.0, "mtime": 0.0, "stats": {}}
_LB_POP_STATS_TTL = 300  # 5 min


def _leaderboard_pop_stats_path():
    return os.path.join(os.path.dirname(__file__), "data", "leaderboard_pop_stats.json")


def _load_leaderboard_pop_stats():
    """Load pop stats with mtime+TTL caching. Returns {} on any failure."""
    import time as _time_lb
    try:
        path = _leaderboard_pop_stats_path()
        try:
            mtime = os.path.getmtime(path)
        except OSError:
            mtime = 0.0
        now = _time_lb.time()
        cache = _LB_POP_STATS_CACHE
        # Invalidate when file changes OR after TTL — whichever comes first.
        if (
            cache["stats"]
            and cache["mtime"] == mtime
            and (now - cache["loaded_at"]) < _LB_POP_STATS_TTL
        ):
            return cache["stats"]
        try:
            with open(path, "r") as _f:
                data = json.load(_f)
                if not isinstance(data, dict):
                    data = {}
        except (FileNotFoundError, json.JSONDecodeError):
            data = {}
        cache["stats"] = data
        cache["mtime"] = mtime
        cache["loaded_at"] = now
        return data
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        return {}


def _normalize_entry_for_leaderboard(entry, game_type):
    """Add `score_normalized` (dict) to entry without replacing `score`.

    Source dims come from entry['final_metrics']['dimension_scores'] when
    present, else from entry['dimension_scores']. Falls back silently on
    any error — leaderboard write must never fail because of normalization.
    """
    try:
        from engines.dimension_utils import zscore_normalize_for_leaderboard
        dims = None
        fm = entry.get("final_metrics") or {}
        if isinstance(fm, dict) and isinstance(fm.get("dimension_scores"), dict):
            dims = fm["dimension_scores"]
        elif isinstance(entry.get("dimension_scores"), dict):
            dims = entry["dimension_scores"]
        if not dims:
            return entry
        pop_all = _load_leaderboard_pop_stats() or {}
        pop_for_gt = pop_all.get(game_type) or {}
        entry["score_normalized"] = zscore_normalize_for_leaderboard(dims, pop_for_gt)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    return entry


def _leaderboard_sort_key(entry):
    """Sort key for leaderboard ranking (Task 9 — P0 plan).

    Primary:   ci_low (90% CI lower bound from dimension scoring envelope).
    Secondary: score (legacy back-compat).

    Returns a tuple so that, when used with sorted(..., reverse=True):
      - entries WITH ci_low rank above entries WITHOUT ci_low (when scores equal),
      - within entries with ci_low: sorted by ci_low DESC then score DESC,
      - within legacy entries: sorted by score DESC.
    """
    if not isinstance(entry, dict):
        return (0, 0, 0)
    score = entry.get("score") or entry.get("achievement_score") or 0
    try:
        score = float(score)
    except (TypeError, ValueError):
        score = 0
    ci_low = entry.get("ci_low")
    has_ci = ci_low is not None
    try:
        ci_low_val = float(ci_low) if has_ci else 0
    except (TypeError, ValueError):
        ci_low_val = 0
        has_ci = False
    return (1 if has_ci else 0, ci_low_val, score)


def _attach_ci_to_entry(entry, score_envelope):
    """Attach ci_low/ci_high/ranked_by to a leaderboard entry from the score envelope.

    Envelope shape (from `_compute_*_dimension_scores` helpers):
      {"score_v1": {...}, "score_v2": {...}, "ci": {dim: {"low": int, "high": int}}}

    Aggregate strategy: average `low`/`high` across all dims that report CI.
    Defensive: missing/malformed envelope leaves the entry untouched (sets only
    `ranked_by` = "score" for clarity). Never raises.
    """
    try:
        if not isinstance(entry, dict):
            return entry
        ci = (score_envelope or {}).get("ci") if isinstance(score_envelope, dict) else None
        if not isinstance(ci, dict):
            entry.setdefault("ranked_by", "score")
            return entry
        ci_lows = [
            v.get("low") for v in ci.values()
            if isinstance(v, dict) and isinstance(v.get("low"), (int, float))
        ]
        ci_highs = [
            v.get("high") for v in ci.values()
            if isinstance(v, dict) and isinstance(v.get("high"), (int, float))
        ]
        if ci_lows:
            entry["ci_low"] = int(round(sum(ci_lows) / len(ci_lows)))
            if ci_highs:
                entry["ci_high"] = int(round(sum(ci_highs) / len(ci_highs)))
            entry["ranked_by"] = "ci_low"
        else:
            entry["ranked_by"] = "score"
    except Exception as _e:
        logger.debug("Suppressed %s in _attach_ci_to_entry: %s", type(_e).__name__, _e)
    return entry


def _save_strategy_leaderboard(game_id, game_title, entry):
    """Save score to game-specific leaderboard file."""
    lb_file = os.path.join('game_sessions', f'leaderboard_{game_id}.json')
    try:
        with open(lb_file, 'r') as f:
            lb = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        lb = {"game_id": game_id, "game_title": game_title, "entries": [], "last_updated": ""}
    lb["entries"].append(entry)
    # Task 9 — sort by ci_low primary, score secondary; legacy entries fall back
    # cleanly because _leaderboard_sort_key returns (0, 0, score) when ci_low absent.
    lb["entries"].sort(key=_leaderboard_sort_key, reverse=True)
    lb["entries"] = lb["entries"][:100]
    lb["last_updated"] = entry.get("timestamp", "")
    os.makedirs('game_sessions', exist_ok=True)
    with open(lb_file, 'w') as f:
        json.dump(lb, f, indent=2)

def _submit_strategy_leaderboard(run_id, game_id, game_title, summary, game_type, score_envelope=None):
    """Extract user, compute score, submit to leaderboard. Safe to call from any /complete endpoint.

    Task 9 — `score_envelope` is the optional output of `_compute_*_dimension_scores`
    (shape: {score_v1, score_v2, ci}). When provided, ci_low/ci_high are attached to
    the entry and used for ranking (CI-lower-bound first, score as tiebreaker).
    Legacy callers that pass only `summary` continue to work — entry will rank by
    `score` alone.
    """
    try:
        user_id = None
        auth_header = request.headers.get('Authorization', '')
        if auth_header.startswith('Bearer '):
            try:
                token = auth_header.split(' ')[1]
                payload = jwt.decode(token, JWT_SECRET, algorithms=['HS256'])
                user_id = payload.get('username') or payload.get('sub')
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        if not user_id:
            user_id = request.headers.get('X-User-ID') or run_id[:8]

        ach_score = _compute_strategy_achievement_score(summary, game_type)
        entry = {
            "user_id": user_id,
            "run_id": run_id,
            "timestamp": datetime.now().isoformat(),
            "rounds_completed": summary.get("turns_played", 0),
            "final_metrics": {k: v for k, v in summary.items() if isinstance(v, (int, float)) and k != "dimension_scores"},
            "achievement_score": ach_score,
            "total_points": ach_score,
            "score": ach_score,  # explicit alias for back-compat readers (Task 8)
            "tier": _compute_strategy_tier(ach_score),
            "achievements": [],
            "game_type": game_type,
        }
        # Preserve raw dimension_scores on the entry for analytics + Z-score
        # normalization. Back-compat: legacy readers still use `score`.
        if isinstance(summary.get("dimension_scores"), dict):
            entry["dimension_scores"] = summary["dimension_scores"]
        # Add `score_normalized` (Task 8 — per-game-type Z-score normalization).
        # Defensive: failure here MUST NOT block the write.
        _normalize_entry_for_leaderboard(entry, game_type)
        # Task 9 — attach ci_low/ci_high/ranked_by from score envelope when available.
        # If callers don't yet pass the envelope, this is a no-op (ranked_by="score").
        # TODO: thread `_compute_strategy_dimension_scores(state)` envelope through the
        # six strategy /complete handlers (chess, go, reversi, tower_defense,
        # puzzle_match, strategy_grid) so CI-lower-bound ranking activates for them.
        _attach_ci_to_entry(entry, score_envelope)
        _save_strategy_leaderboard(game_id, game_title, entry)
        logger.info(f"Leaderboard entry saved for {user_id} on {game_id} ({game_type}): score={ach_score}")
    except Exception as e:
        logger.warning(f"Leaderboard save failed for {game_id}: {e}")
# ==================== CHESS STRATEGY (Founder's Gambit) ====================

def _compute_chess_achievement_score(summary):
    """Score: 0-1000 based on chess game performance."""
    score = 0
    if summary.get("winner") == "player":
        score += 500
        wt = summary.get("win_type", "")
        if wt == "ceo_captured": score += 100
        elif wt == "resource_control": score += 150
        elif wt == "valuation": score += 200
    score += summary.get("pieces_captured", 0) * 30
    score -= summary.get("pieces_lost", 0) * 20
    score += summary.get("resources_controlled", 0) * 50
    dim = summary.get("dimension_scores", {})
    if dim:
        score += sum(dim.values()) // len(dim)
    return max(0, min(1000, score))

def _compute_chess_tier(score):
    if score >= 800: return "Legend"
    if score >= 650: return "Master"
    if score >= 500: return "Expert"
    if score >= 350: return "Advanced"
    if score >= 200: return "Intermediate"
    return "Novice"

def _save_chess_leaderboard(game_id, game_title, entry):
    """Save chess score to game-specific leaderboard file."""
    lb_file = os.path.join('game_sessions', f'leaderboard_{game_id}.json')
    try:
        with open(lb_file, 'r') as f:
            lb = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        lb = {"game_id": game_id, "game_title": game_title, "entries": [], "last_updated": ""}
    lb["entries"].append(entry)
    lb["entries"].sort(key=lambda x: (x.get("achievement_score", 0), x.get("total_points", 0)), reverse=True)
    lb["entries"] = lb["entries"][:100]
    lb["last_updated"] = entry.get("timestamp", "")
    os.makedirs('game_sessions', exist_ok=True)
    with open(lb_file, 'w') as f:
        json.dump(lb, f, indent=2)

