@app.route('/api/run/<run_id>/chess/end-turn', methods=['POST'])
def chess_end_turn(run_id):
    """End current turn and get AI move."""
    from engines.chess_strategy_engine import ChessStrategyEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err

    chess_state = run.get("chess_state")
    if not chess_state:
        return jsonify({"error": "Chess game not initialized"}), 400

    config = game_data.get("chess_config", {})
    engine = ChessStrategyEngine(config)

    # End player turn
    turn_info = engine.end_turn(chess_state)

    # AI turn(s) — execute up to max_ap moves
    ai_moves = []
    if chess_state["turn"] == "ai" and not chess_state["game_over"]:
        for _ in range(config.get("max_ap", 2)):
            if chess_state["action_points"] <= 0 or chess_state["game_over"]:
                break
            ai_action = engine.get_ai_move(chess_state)
            if ai_action["action"] == "move":
                result = engine.execute_move(chess_state, ai_action["piece_id"], ai_action["target"])
                ai_moves.append({"type": "move", **result})
            elif ai_action["action"] == "ability":
                result = engine.use_ability(chess_state, ai_action["piece_id"], ability_id=ai_action.get("ability_id"), target=ai_action.get("target"))
                ai_moves.append({"type": "ability", **result})
            else:
                break

        # End AI turn
        if not chess_state["game_over"]:
            engine.end_turn(chess_state)

    run["chess_state"] = chess_state
    storage.update_run(run_id, run)

    return jsonify({
        "turn_info": turn_info,
        "ai_moves": ai_moves,
        "state": chess_state,
    })


