@app.route('/api/run/<run_id>/chess/complete', methods=['POST'])
def chess_complete(run_id):
    """Finalize chess game — store results and dimension scores for report generation."""
    from engines.chess_strategy_engine import ChessStrategyEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404

    chess_state = run.get("chess_state")
    if not chess_state:
        return jsonify({"error": "No chess game data"}), 400

    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err

    config = game_data.get("chess_config", {})
    engine = ChessStrategyEngine(config)
    summary = engine.get_game_summary(chess_state)

    # Store dimension scores into the RunState for psychology reports
    state_obj = run["state"]
    dimension_scores = summary["dimension_scores"]
    for skill_id, score_val in dimension_scores.items():
        setattr(state_obj, skill_id, score_val)
    state_obj.dimension_scores = dimension_scores

    # Create a synthetic log entry so the report endpoint works
    log_entry = {
        "round_id": "chess_game",
        "round_title": "Founder's Gambit",
        "choice": {
            "id": "chess_result",
            "label": f"{'Victory' if summary['winner'] == 'player' else 'Defeat'} — {(summary.get('win_type') or 'game_over').replace('_', ' ').title()}"
        },
        "nep_tags": game_data.get("nep_tags", []),
        "events": [
            f"Captured {summary['pieces_captured']} rival pieces",
            f"Lost {summary['pieces_lost']} pieces",
            f"Controlled {summary['resources_controlled']} resource tiles",
            f"Final valuation: ${summary['final_valuation']:,}",
        ],
        "state_before": {"valuation": 1000000},
        "state_after_events": {"valuation": summary["final_valuation"]},
        "chess_summary": summary,
    }

    # Only add if not already finalized
    if not any(e.get("round_id") == "chess_game" for e in run["log"]):
        run["log"].append(log_entry)

    storage.update_run(run_id, run)
    logger.info(f"Chess game finalized for run {run_id}: {summary['winner']} by {summary['win_type']}")
    try:
        from llm import record_coaching_tip_outcome
        _tip_id = run.get("_coaching_tip_id")
        if _tip_id and dimension_scores:
            _weakest = min(dimension_scores, key=dimension_scores.get)
            _avg = sum(dimension_scores.values()) / max(1, len(dimension_scores))
            record_coaching_tip_outcome(_tip_id, "chess_strategy", _weakest, _avg - 50)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Submit to leaderboard
    _submit_strategy_leaderboard(run_id, game_id, game_data.get("title", game_id), summary, "chess_strategy")

    return jsonify({"success": True, "summary": summary})


