@app.route('/api/run/<run_id>/go/place', methods=['POST'])
def go_place(run_id):
    """Place a stone on the board."""
    from engines.go_territory_engine import GoTerritoryEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404
    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err
    go_state = run.get("go_state")
    if not go_state:
        return jsonify({"error": "Go game not initialized"}), 400
    data = request.json or {}
    position = data.get("position")
    if not position:
        return jsonify({"error": "position required"}), 400
    config = game_data.get("go_config", {})
    engine = GoTerritoryEngine(config)
    result = engine.place_stone(go_state, position)
    ai_result_data = None
    if result.get("success") and not go_state.get("game_over"):
        ai_result = engine.get_ai_move(go_state)
        if ai_result.get("action") == "place":
            ai_place = engine.place_stone(go_state, ai_result["position"])
            ai_result_data = ai_place
        elif ai_result.get("action") == "pass":
            engine.pass_turn(go_state)
            ai_result_data = {"action": "pass"}
    go_state["_valid_moves"] = engine.get_valid_moves(go_state)
    run["go_state"] = go_state
    storage.update_run(run_id, run)
    return jsonify({"result": result, "ai_result": ai_result_data, "state": go_state})


