@app.route('/api/run/<run_id>/reversi/place', methods=['POST'])
def reversi_place(run_id):
    """Place a disc."""
    from engines.reversi_engine import ReversiEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404
    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err
    rev_state = run.get("reversi_state")
    if not rev_state:
        return jsonify({"error": "Reversi game not initialized"}), 400
    data = request.json or {}
    position = data.get("position")
    if not position:
        return jsonify({"error": "position required"}), 400
    config = game_data.get("reversi_config", {})
    engine = ReversiEngine(config)
    result = engine.place_disc(rev_state, position)
    # AI move if it's AI's turn
    if result.get("success") and rev_state.get("turn") == "ai" and not rev_state.get("game_over"):
        ai_action = engine.get_ai_move(rev_state)
        if ai_action.get("action") == "place":
            ai_result = engine.place_disc(rev_state, ai_action["position"])
            result["ai_move"] = ai_result
