@app.route('/api/run/<run_id>/reversi/complete', methods=['POST'])
def reversi_complete(run_id):
    """Finalize Reversi game."""
    from engines.reversi_engine import ReversiEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404
    rev_state = run.get("reversi_state")
    if not rev_state:
        return jsonify({"error": "No reversi game data"}), 400
    game_id = run.get("game_id")
    game_data, err = get_game_or_400(game_id)
    if err:
        return err
    config = game_data.get("reversi_config", {})
    engine = ReversiEngine(config)
    summary = engine.get_game_summary(rev_state)
    state_obj = run["state"]
    dimension_scores = summary.get("dimension_scores", {})
    for skill_id, score_val in dimension_scores.items():
        setattr(state_obj, skill_id, score_val)
    state_obj.dimension_scores = dimension_scores
    log_entry = {
        "round_id": "reversi_game", "round_title": game_data.get("title", "Reversi"),
        "choice": {"id": "reversi_result", "label": f"{'Victory' if summary.get('winner')=='player' else 'Defeat'}"},
        "events": [f"Your discs: {summary.get('player_discs', 0)}", f"AI discs: {summary.get('ai_discs', 0)}"],
        "state_before": {}, "state_after_events": {},
    }
    if not any(e.get("round_id") == "reversi_game" for e in run["log"]):
        run["log"].append(log_entry)
    storage.update_run(run_id, run)
    try:
        from llm import record_coaching_tip_outcome
        _tip_id = run.get("_coaching_tip_id")
        if _tip_id and dimension_scores:
            _weakest = min(dimension_scores, key=dimension_scores.get)
            _avg = sum(dimension_scores.values()) / max(1, len(dimension_scores))
            record_coaching_tip_outcome(_tip_id, "reversi", _weakest, _avg - 50)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    _submit_strategy_leaderboard(run_id, game_id, game_data.get("title", game_id), summary, "reversi")
    return jsonify({"success": True, "summary": summary})


