# ============================================
# DAILY REWARDS SYSTEM
# ============================================

_daily_rewards_config = None
def _get_daily_rewards_config():
    global _daily_rewards_config
    if _daily_rewards_config is None:
        import json as _json
        cfg_path = os.path.join(os.path.dirname(__file__), "config", "daily_rewards_config.json")
        try:
            with open(cfg_path) as f:
                _daily_rewards_config = _json.load(f)
        except Exception:
            _daily_rewards_config = {"rewards": [{"day": 1, "coins": 50}], "streak_bonuses": {}, "reset_on_skip": True}
    return _daily_rewards_config

DAILY_REWARDS_FILE = os.path.join(os.path.dirname(__file__), "game_sessions", "daily_rewards.json")

def _load_daily_rewards():
    try:
        with open(DAILY_REWARDS_FILE, "r") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def _save_daily_rewards(data):
    os.makedirs(os.path.dirname(DAILY_REWARDS_FILE), exist_ok=True)
    with open(DAILY_REWARDS_FILE, "w") as f:
        json.dump(data, f, indent=2, default=str)


@app.get("/api/daily-rewards/status")
@require_auth
def daily_rewards_status():
    """Get current daily reward status: streak, can_claim, schedule."""
    user_id = request.current_user["user_id"]
    config = _get_daily_rewards_config()
    data = _load_daily_rewards()
    user_data = data.get(user_id, {"streak": 0, "total_claims": 0, "last_claim": None, "history": []})

    from datetime import datetime, timedelta
    now = datetime.now()
    can_claim = True
    if user_data.get("last_claim"):
        last = datetime.fromisoformat(user_data["last_claim"])
        if last.date() == now.date():
            can_claim = False

    streak = user_data.get("streak", 0)
    day_index = streak % len(config["rewards"])
    current_reward = config["rewards"][day_index]

    # Build 7-day calendar
    calendar = []
    for i, r in enumerate(config["rewards"]):
        calendar.append({
            "day": r.get("day", i + 1),
            "coins": r["coins"],
            "icon": r.get("icon", "🎁"),
            "label": r.get("label", f"Day {i+1}"),
            "claimed": i < (streak % len(config["rewards"])) or (i == day_index and not can_claim),
            "current": i == day_index and can_claim,
        })

    # Next streak milestone
    next_milestone = None
    for ms_str, bonus in sorted(config.get("streak_bonuses", {}).items(), key=lambda x: int(x[0])):
        if int(ms_str) > streak:
            next_milestone = {"streak": int(ms_str), "coins": bonus.get("coins", 0), "label": bonus.get("label", ""), "icon": bonus.get("icon", "🔥")}
            break

    return jsonify({
        "streak": streak,
        "total_claims": user_data.get("total_claims", 0),
        "can_claim": can_claim,
        "current_reward": current_reward,
        "calendar": calendar,
        "next_milestone": next_milestone,
    })


@app.post("/api/daily-rewards/claim")
@require_auth
def daily_rewards_claim():
    """Claim today's daily reward."""
    user_id = request.current_user["user_id"]
    config = _get_daily_rewards_config()
    data = _load_daily_rewards()
    user_data = data.setdefault(user_id, {"streak": 0, "total_claims": 0, "last_claim": None, "history": []})

    from datetime import datetime, timedelta
    now = datetime.now()

    # Check already claimed
    if user_data.get("last_claim"):
        last = datetime.fromisoformat(user_data["last_claim"])
        if last.date() == now.date():
            return jsonify({"success": False, "error": "Already claimed today"}), 400
        days_diff = (now.date() - last.date()).days
        if days_diff == 1:
            user_data["streak"] += 1
        elif config.get("reset_on_skip", True):
            user_data["streak"] = 1
    else:
        user_data["streak"] = 1

    streak = user_data["streak"]
    day_index = (streak - 1) % len(config["rewards"])
    reward = config["rewards"][day_index]
    coins = reward.get("coins", 50)

    # Check streak bonus
    streak_bonus = 0
    streak_label = None
    bonus_map = config.get("streak_bonuses", {})
    if str(streak) in bonus_map:
        b = bonus_map[str(streak)]
        streak_bonus = b.get("coins", 0)
        streak_label = b.get("label", "")

    total_coins = coins + streak_bonus

    # Credit wallet
    wallet.credit_daily_reward(user_id, total_coins, streak)

    user_data["last_claim"] = now.isoformat()
    user_data["total_claims"] = user_data.get("total_claims", 0) + 1
    user_data["history"] = (user_data.get("history") or [])[-29:] + [{"date": now.isoformat(), "coins": total_coins, "streak": streak}]
    _save_daily_rewards(data)

    return jsonify({
        "success": True,
        "coins": coins,
        "streak_bonus": streak_bonus,
        "streak_label": streak_label,
        "total_coins": total_coins,
        "new_streak": streak,
    })


@app.get("/api/daily-rewards/config")
def daily_rewards_config():
    """Get daily rewards schedule (public)."""
    config = _get_daily_rewards_config()
    return jsonify(config)


