# ---------------------------------------------------------------------------
# Social Engine endpoints
# Backed by backend/data/social_graph.json (same pattern as other data files).
# Falls back to social_engine.py functions if the module is available.
# ---------------------------------------------------------------------------

_SOCIAL_GRAPH_FILE = os.path.join(os.path.dirname(__file__), "data", "social_graph.json")


def _load_social_graph() -> dict:
    """Load the social graph from disk. Returns empty structure on missing/corrupt file."""
    try:
        with open(_SOCIAL_GRAPH_FILE, "r") as _f:
            return json.load(_f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def _save_social_graph(data: dict):
    """Persist social graph to disk."""
    os.makedirs(os.path.dirname(_SOCIAL_GRAPH_FILE), exist_ok=True)
    with open(_SOCIAL_GRAPH_FILE, "w") as _f:
        json.dump(data, _f, indent=2)


def _social_get_user_record(graph: dict, user_id: str) -> dict:
    """Return (creating if necessary) the social record for user_id."""
    return graph.setdefault(user_id, {
        "friends": [],
        "pending_sent": [],
        "pending_received": [],
        "activity": [],
        "challenges": [],
    })


@app.get("/api/social/friends")
def api_social_friends():
    """List confirmed friends for the current user."""
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    user_payload = verify_token(token)
    if not user_payload:
        return jsonify({"error": "Invalid token"}), 401
    try:
        # Try delegating to social_engine module first
        import social_engine as _se
        return jsonify(_se.get_friends(user_payload["user_id"]))
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    try:
        graph = _load_social_graph()
        rec = _social_get_user_record(graph, user_payload["user_id"])
        friends = rec.get("friends", [])
        return jsonify({"friends": friends, "count": len(friends)})
    except Exception as e:
        return jsonify({"friends": [], "count": 0, "error": str(e)})


@app.post("/api/social/friends/request")
def api_social_friend_request():
    """Send a friend request to another user.

    Body: {target_user_id: str}
    """
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    user_payload = verify_token(token)
    if not user_payload:
        return jsonify({"error": "Invalid token"}), 401
    data = request.get_json(silent=True) or {}
    target_user_id = (data.get("target_user_id") or "").strip()
    if not target_user_id:
        return jsonify({"error": "target_user_id is required"}), 400
    user_id = user_payload["user_id"]
    if target_user_id == user_id:
        return jsonify({"error": "Cannot send a friend request to yourself"}), 400
    try:
        import social_engine as _se
        return jsonify(_se.send_friend_request(user_id, target_user_id))
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    try:
        import uuid as _uuid
        from datetime import datetime as _dt
        graph = _load_social_graph()
        sender = _social_get_user_record(graph, user_id)
        receiver = _social_get_user_record(graph, target_user_id)
        # Check not already friends or pending
        if target_user_id in [f.get("user_id") for f in sender.get("friends", [])]:
            return jsonify({"ok": False, "error": "Already friends"}), 400
        if target_user_id in sender.get("pending_sent", []):
            return jsonify({"ok": False, "error": "Request already sent"}), 400
        request_id = str(_uuid.uuid4())[:8]
        req_entry = {
            "request_id": request_id,
            "from_user_id": user_id,
            "to_user_id": target_user_id,
            "sent_at": _dt.now().isoformat(),
        }
        sender.setdefault("pending_sent", []).append(target_user_id)
        receiver.setdefault("pending_received", []).append(req_entry)
        _save_social_graph(graph)
        return jsonify({"ok": True, "request_id": request_id})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


@app.post("/api/social/friends/accept")
def api_social_friend_accept():
    """Accept a friend request.

    Body: {request_id: str}
    """
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    user_payload = verify_token(token)
    if not user_payload:
        return jsonify({"error": "Invalid token"}), 401
    data = request.get_json(silent=True) or {}
    request_id = (data.get("request_id") or "").strip()
    if not request_id:
        return jsonify({"error": "request_id is required"}), 400
    user_id = user_payload["user_id"]
    try:
        import social_engine as _se
        return jsonify(_se.accept_friend_request(user_id, request_id))
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    try:
        from datetime import datetime as _dt
        graph = _load_social_graph()
        rec = _social_get_user_record(graph, user_id)
        pending = rec.get("pending_received", [])
        matched = next((r for r in pending if r.get("request_id") == request_id), None)
        if not matched:
            return jsonify({"ok": False, "error": "Request not found"}), 404
        from_uid = matched["from_user_id"]
        # Remove from pending
        rec["pending_received"] = [r for r in pending if r.get("request_id") != request_id]
        # Add mutual friendship
        friend_entry_self = {"user_id": from_uid, "since": _dt.now().isoformat()}
        friend_entry_other = {"user_id": user_id, "since": _dt.now().isoformat()}
        rec.setdefault("friends", []).append(friend_entry_self)
        sender_rec = _social_get_user_record(graph, from_uid)
        sender_rec.setdefault("friends", []).append(friend_entry_other)
        # Remove from sender's pending_sent
        sender_rec["pending_sent"] = [u for u in sender_rec.get("pending_sent", []) if u != user_id]
        # Record activity for both
        act_entry = {
            "type": "new_friend",
            "user_id": from_uid,
            "other_user_id": user_id,
            "at": _dt.now().isoformat(),
        }
        rec.setdefault("activity", []).insert(0, act_entry)
        sender_rec.setdefault("activity", []).insert(0, {**act_entry, "user_id": user_id, "other_user_id": from_uid})
        _save_social_graph(graph)
        return jsonify({"ok": True, "friend_user_id": from_uid})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


@app.get("/api/social/activity-feed")
def api_social_activity_feed():
    """Return recent activity from the current user's friends."""
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    user_payload = verify_token(token)
    if not user_payload:
        return jsonify({"error": "Invalid token"}), 401
    try:
        import social_engine as _se
        return jsonify(_se.get_activity_feed(user_payload["user_id"]))
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    try:
        graph = _load_social_graph()
        user_id = user_payload["user_id"]
        rec = _social_get_user_record(graph, user_id)
        friend_ids = [f.get("user_id") for f in rec.get("friends", []) if f.get("user_id")]
        feed = []
        for fid in friend_ids:
            friend_rec = graph.get(fid, {})
            for act in friend_rec.get("activity", [])[:10]:
                feed.append({**act, "from_user_id": fid})
        # Sort by timestamp descending
        feed.sort(key=lambda x: x.get("at", ""), reverse=True)
        return jsonify({"activity": feed[:50], "count": len(feed[:50])})
    except Exception as e:
        return jsonify({"activity": [], "count": 0, "error": str(e)})


@app.post("/api/social/challenge")
def api_social_challenge():
    """Challenge a friend to a specific game.

    Body: {friend_id: str, game_id: str}
    """
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    user_payload = verify_token(token)
    if not user_payload:
        return jsonify({"error": "Invalid token"}), 401
    data = request.get_json(silent=True) or {}
    friend_id = (data.get("friend_id") or "").strip()
    game_id = (data.get("game_id") or "").strip()
    if not friend_id or not game_id:
        return jsonify({"error": "friend_id and game_id are required"}), 400
    user_id = user_payload["user_id"]
    try:
        import social_engine as _se
        return jsonify(_se.send_challenge(user_id, friend_id, game_id))
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    try:
        import uuid as _uuid
        from datetime import datetime as _dt
        load_bundle()
        game = GAMES.get(game_id)
        if not game:
            return jsonify({"error": "Game not found"}), 404
        graph = _load_social_graph()
        rec = _social_get_user_record(graph, user_id)
        friend_ids = [f.get("user_id") for f in rec.get("friends", [])]
        if friend_id not in friend_ids:
            return jsonify({"error": "You can only challenge friends"}), 403
        challenge_id = str(_uuid.uuid4())[:8]
        challenge_entry = {
            "challenge_id": challenge_id,
            "from_user_id": user_id,
            "to_user_id": friend_id,
            "game_id": game_id,
            "game_title": game.get("title", game_id),
            "issued_at": _dt.now().isoformat(),
            "status": "pending",
        }
        # Store on both sides
        rec.setdefault("challenges", []).insert(0, challenge_entry)
        friend_rec = _social_get_user_record(graph, friend_id)
        friend_rec.setdefault("challenges", []).insert(0, challenge_entry)
        # Add to friend's activity feed
        friend_rec.setdefault("activity", []).insert(0, {
            "type": "challenge_received",
            "from_user_id": user_id,
            "game_id": game_id,
            "game_title": game.get("title", game_id),
            "challenge_id": challenge_id,
            "at": _dt.now().isoformat(),
        })
        _save_social_graph(graph)
        return jsonify({"ok": True, "challenge_id": challenge_id, "game_title": game.get("title", game_id)})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


