@app.get("/api/profile/reports")
def api_get_report_history():
    """Get all historical reports for the current user."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401
    user_id = user_payload["user_id"]
    reports = []
    try:
        for fname in os.listdir(REPORTS_DIR):
            if not fname.endswith(".json"):
                continue
            fpath = os.path.join(REPORTS_DIR, fname)
            with open(fpath, "r") as f:
                rpt = json.load(f)
            if rpt.get("user_id") == user_id:
                reports.append({
                    "run_id": rpt.get("run_id"),
                    "game_id": rpt.get("game_id"),
                    "game_title": rpt.get("game_title", ""),
                    "game_theme": rpt.get("game_theme", ""),
                    "final_score": rpt.get("final_score"),
                    "mento_score": rpt.get("mento_score"),
                    "badges": rpt.get("badges", []),
                    "wallet_reward": rpt.get("wallet_reward"),
                    "completed_at": rpt.get("completed_at", ""),
                })
    except Exception as e:
        logger.warning(f"Failed to list reports: {e}")
    # Most recent first
    reports.sort(key=lambda r: r.get("completed_at", ""), reverse=True)
    return jsonify({"reports": reports})


