# ============================================
# STORY BRANCHING API
# ============================================

def _build_story_scene_map(game: dict) -> dict:
    """Build scene lookup map from a story_branching game, handling both formats:
    - New: game.story_intro.scenes[] with scene_id/narrative fields
    - Old: game.story.opening + game.story.branches[] with id/text fields
    Returns a dict keyed by scene id, with fields normalized to id/text.
    """
    scene_map = {}
    # New format: story_intro.scenes
    story_intro = game.get("story_intro", {})
    for scene in story_intro.get("scenes", []):
        sid = scene.get("scene_id") or scene.get("id")
        if not sid:
            continue
        normalized = dict(scene)
        if "id" not in normalized:
            normalized["id"] = sid
        if "text" not in normalized and "narrative" in normalized:
            normalized["text"] = normalized["narrative"]
        scene_map[sid] = normalized
    # Old format: story.opening + story.branches (fallback)
    story = game.get("story", {})
    opening = story.get("opening", {})
    if opening.get("id"):
        scene_map[opening["id"]] = opening
    for branch in story.get("branches", []):
        if branch.get("id"):
            scene_map[branch["id"]] = branch
    return scene_map


@app.post("/api/run/<run_id>/branching-choice")
@limiter.limit("60 per minute")
def story_branching_choice(run_id):
    """Process a choice in a story_branching game.
    Body: {"scene_id": "...", "choice_id": "..."}
    Returns: {"next_scene": {...}, "state": {...}, "is_ending": bool, "ending_message": str}
    """
    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    scene_id = payload.get("scene_id", "")
    choice_id = payload.get("choice_id", "")

    if not scene_id or not choice_id:
        return jsonify({"error": "scene_id and choice_id are required"}), 400

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err

    # Build scene lookup — handles both story_intro.scenes and story.opening/branches formats
    scene_map = _build_story_scene_map(game)

    # Find current scene
    scene = scene_map.get(scene_id)
    if not scene:
        return jsonify({"error": f"Scene not found: {scene_id}"}), 404

    # Find the choice
    choice = None
    for c in scene.get("choices", []):
        if c.get("id") == choice_id:
            choice = c
            break
    if not choice:
        return jsonify({"error": f"Choice not found: {choice_id}"}), 404

    # Apply delta to state
    state_obj = r["state"]
    delta = choice.get("delta", {})
    for key, val in delta.items():
        if hasattr(state_obj, key):
            current = getattr(state_obj, key)
            if isinstance(current, dict) and "value" in current:
                current["value"] = max(0, min(100, current.get("value", 0) + val))
            elif isinstance(current, (int, float)):
                setattr(state_obj, key, current + val)
        else:
            # Try dict-style access for RunState
            d = state_to_dict(state_obj)
            if key in d:
                raw = d[key]
                if isinstance(raw, dict) and "value" in raw:
                    raw["value"] = max(0, min(100, raw.get("value", 0) + val))

    # Track memory tags
    if choice.get("memory_tags"):
        if "memory_tags" not in r:
            r["memory_tags"] = []
        r["memory_tags"].extend(choice["memory_tags"])

    # Track choice in log
    r["log"].append({
        "scene_id": scene_id,
        "choice_id": choice_id,
        "label": choice.get("label", ""),
        "delta": delta,
    })

    # Find next scene / chapter
    next_scene_id = choice.get("next_scene", "")
    next_chapter = choice.get("next_chapter", "")  # chapter-unlock flow
    next_scene = scene_map.get(next_scene_id)

    # Determine ending state:
    # - choice.is_ending → always ending
    # - next_scene.is_ending → ending via scene flag
    # - no next_scene AND no next_chapter → default ending
    # - has next_chapter → NOT an ending
    if choice.get("is_ending"):
        is_ending = True
    elif next_chapter:
        is_ending = False
    elif next_scene:
        is_ending = next_scene.get("is_ending", False)
    else:
        is_ending = True  # dead end fallback

    # Resolve ending metadata (can be on choice OR on next_scene)
    ending_type = ""
    ending_message = ""
    if is_ending:
        if next_scene:
            ending_type = next_scene.get("ending_type", "")
            ending_message = next_scene.get("ending_message", "")
        # Fallback to choice-level ending info (used by Red Riding Hood and similar)
        if not ending_type:
            ending_type = choice.get("ending_type", "neutral")
        if not ending_message:
            ending_message = choice.get("ending_message", "")
        state_obj.game_over = True
        r["ending_type"] = ending_type
        r["ending_message"] = ending_message

    # Track current scene for resume
    r["current_scene_id"] = next_scene_id if next_scene else scene_id

    # ── Chapter-level XP/coins award ──────────────────────────────
    # Award partial XP and coins when a chapter completes (next_chapter set)
    # or when the full story ends (is_ending). This ensures students who
    # play a few chapters get recognition on the leaderboard.
    chapter_reward = {}
    if next_chapter or is_ending:
        try:
            token = get_token_from_request()
            user_payload = verify_token(token) if token else None
            if user_payload:
                user_id = user_payload["user_id"]
                # Prevent double-awarding the same chapter
                rewarded = r.setdefault("chapters_rewarded", [])
                chapter_key = next_chapter or f"ending_{ending_type}"
                completed_chapter_id = scene.get("chapter_id", scene_id)

                if completed_chapter_id not in rewarded:
                    rewarded.append(completed_chapter_id)

                    # Compute interim dimension scores from current log
                    log_for_scoring = r.get("log", [])
                    interim_scores = _canonical_scores(
                        _compute_story_dimension_scores(
                            {"log": log_for_scoring, "dimension_scores": state_to_dict(r["state"]).get("dimension_scores", {})},
                            ending_type=ending_type if is_ending else "standard"
                        ),
                        score_version=1,
                    )

                    # XP: 20 per chapter, 40 for final ending
                    chapter_xp = 40 if is_ending else 20
                    xp_result = player_profile.award_xp(
                        user_id=user_id,
                        xp_amount=chapter_xp,
                        reason="chapter_complete" if not is_ending else "story_complete",
                        game_type="story_branching",
                        game_title=game.get("title", game_id),
                        score=chapter_xp,
                        dimension_scores=interim_scores,
                        increment_game_count=is_ending,  # Only count full completions
                    )

                    # Coins: 25 per chapter, 50 for ending
                    chapter_coins = 50 if is_ending else 25
                    try:
                        from wallet import add_coins
                        coin_result = add_coins(user_id, chapter_coins, "chapter_complete",
                                                f"Completed chapter in {game.get('title', game_id)}")
                    except Exception:
                        coin_result = {"earned": chapter_coins}

                    chapter_reward = {
                        "xp_earned": chapter_xp,
                        "coins_earned": chapter_coins,
                        "dimension_scores": interim_scores,
                        "level_up": xp_result.get("level_up", False),
                        "new_level": xp_result.get("new_level", 1),
                        "total_xp": xp_result.get("total_xp", 0),
                    }
        except Exception as e:
            import traceback
            traceback.print_exc()
            pass  # Don't fail the choice response if XP award has an issue

    update_run(run_id, r)

    # Story-game expert pick + counterfactual surfacing (parity with rounds-type sims)
    _expert = scene.get("expert_pick") if isinstance(scene.get("expert_pick"), dict) else None
    _ep_choice_id = _expert.get("choice_id") if _expert else None
    _was_expert_pick = bool(_ep_choice_id) and (choice_id == _ep_choice_id)
    _ep_choice_meta = None
    if _ep_choice_id:
        _ep_choice_meta = next((c for c in scene.get("choices", []) if c.get("id") == _ep_choice_id), None)
    _counterfactual_for_chosen = choice.get("counterfactual_feedback") if not _was_expert_pick else None

    return jsonify({
        "next_scene": next_scene,
        "next_scene_id": next_scene_id,
        "next_chapter": next_chapter,
        "state": state_to_dict(r["state"]),
        "is_ending": is_ending,
        "ending_type": ending_type,
        "ending_message": ending_message,
        "memory_tags": r.get("memory_tags", []),
        "chapter_reward": chapter_reward,
        # Story expert-pick reveal payload — only present when scene declares expert_pick
        "expert_pick": ({
            "choice_id": _ep_choice_id,
            "label": (_ep_choice_meta or {}).get("label", ""),
            "reason": _expert.get("reason", "") if _expert else "",
            "was_expert_pick": _was_expert_pick,
        } if _ep_choice_id else None),
        "counterfactual_for_chosen": _counterfactual_for_chosen,
    })


@app.post("/api/run/<run_id>/story-challenge")
def story_challenge(run_id):
    """Live-LLM 'challenge me on this' beat for story_branching games.

    POST body: { "scene_id": "...", "choice_id": "...", "user_reply": "?",
                 "history": [{"role":"assistant|user","content":"..."}] }
    Returns: { "response", "feedback", "tactics", "tone", "scene_id", "choice_id" }
    """
    from llm import story_challenge_response as _scr

    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    scene_id = (payload.get("scene_id") or "").strip()
    choice_id = (payload.get("choice_id") or "").strip()
    user_reply = (payload.get("user_reply") or "").strip()[:400]
    history = payload.get("history") or []
    if not isinstance(history, list):
        history = []
    history = [h for h in history[-6:] if isinstance(h, dict)]

    if not scene_id or not choice_id:
        return jsonify({"error": "scene_id and choice_id are required"}), 400

    game_id = r.get("game_id")
    game, err = get_game_or_400(game_id)
    if err:
        return err
    if game.get("game_type") != "story_branching":
        return jsonify({"error": "Not a story_branching game"}), 400

    scene_map = _build_scene_map(game)
    scene = scene_map.get(scene_id)
    if not scene:
        return jsonify({"error": f"Scene not found: {scene_id}"}), 404
    choice = next((c for c in scene.get("choices", []) if c.get("id") == choice_id), None)
    if not choice:
        return jsonify({"error": f"Choice not found: {choice_id}"}), 404

    expert = scene.get("expert_pick") if isinstance(scene.get("expert_pick"), dict) else None
    expert_choice_id = (expert or {}).get("choice_id")
    expert_choice = next((c for c in scene.get("choices", []) if c.get("id") == expert_choice_id), None)
    expert_label = (expert_choice or {}).get("label", "")
    expert_reason = (expert or {}).get("reason", "")
    was_expert = bool(expert_choice_id) and (choice_id == expert_choice_id)

    npc_persona = (scene.get("challenge_npc")
                   or (game.get("simulation_config") or {}).get("challenge_npc")
                   or "a thoughtful skeptic mentor pressing the player to defend their reasoning")

    # R3 — per-game persona ladder for escalation on later turns
    persona_ladder = (scene.get("challenge_persona_ladder")
                      or (game.get("simulation_config") or {}).get("challenge_persona_ladder")
                      or None)
    # turn_index = number of prior assistant turns in the conversation history
    turn_index = sum(1 for h in (history or []) if h.get("role") == "assistant")

    out = _scr(
        scene_text=scene.get("text") or scene.get("description") or "",
        chosen_label=choice.get("label", ""),
        chosen_skills=choice.get("skill_tags", []) or [],
        expert_label=expert_label,
        expert_reason=expert_reason,
        was_expert_pick=was_expert,
        npc_persona=npc_persona,
        user_reply=user_reply,
        conversation_history=history,
        turn_index=turn_index,
        persona_ladder=persona_ladder,
    )
    out["scene_id"] = scene_id
    out["choice_id"] = choice_id
    return jsonify(out)


@app.post("/api/run/<run_id>/dissent-juror")
def dissent_juror(run_id):
    """R4 — Live LLM contrarian-juror reaction for ethics-tribunal style rounds.

    POST body: { "round_id": "...", "choice_id": "...",
                 "user_reply"?: "...",
                 "history": [{"role":"assistant|user","content":"..."}] }
    Returns: { "response", "feedback", "tactics", "tone", "round_id", "choice_id" }
    """
    from llm import story_challenge_response as _scr

    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    round_id = (payload.get("round_id") or "").strip()
    choice_id = (payload.get("choice_id") or "").strip()
    user_reply = (payload.get("user_reply") or "").strip()[:400]
    history = payload.get("history") or []
    if not isinstance(history, list):
        history = []
    history = [h for h in history[-6:] if isinstance(h, dict)]

    if not round_id or not choice_id:
        return jsonify({"error": "round_id and choice_id are required"}), 400

    game_id = r.get("game_id")
    game, err = get_game_or_400(game_id)
    if err:
        return err

    rounds = game.get("rounds") or []
    rd = next((x for x in rounds if (x.get("id") or x.get("round_id")) == round_id), None)
    if not rd:
        return jsonify({"error": f"Round not found: {round_id}"}), 404

    dj_cfg = rd.get("dissent_juror") or {}
    if not dj_cfg.get("enabled"):
        return jsonify({"error": "Dissent juror not enabled for this round"}), 400

    choices = rd.get("choices") or []
    choice = next((c for c in choices if c.get("id") == choice_id), None)
    if not choice:
        return jsonify({"error": f"Choice not found: {choice_id}"}), 404

    # The "expert pick" in ethics framing is the dissent verdict — the harder right
    # answer the contrarian juror is defending. Configurable per-round.
    dissent_choice_id = dj_cfg.get("dissent_choice_id") or ""
    dissent_choice = next((c for c in choices if c.get("id") == dissent_choice_id), None)
    dissent_label = (dissent_choice or {}).get("label", dj_cfg.get("dissent_label", ""))
    dissent_reason = dj_cfg.get("dissent_reason", "")
    was_dissent = bool(dissent_choice_id) and (choice_id == dissent_choice_id)

    npc_persona = dj_cfg.get("juror_persona", (
        "a senior contrarian juror — soft-spoken but unwilling to let the panel "
        "rationalise the easy verdict. They lead with the harm the majority is "
        "willing to absorb."
    ))
    persona_ladder = dj_cfg.get("juror_persona_ladder") or None
    turn_index = sum(1 for h in history if h.get("role") == "assistant")

    out = _scr(
        scene_text=rd.get("scenario") or rd.get("story") or rd.get("title") or "",
        chosen_label=choice.get("label", ""),
        chosen_skills=choice.get("skill_tags", []) or [],
        expert_label=dissent_label,
        expert_reason=dissent_reason,
        was_expert_pick=was_dissent,
        npc_persona=npc_persona,
        user_reply=user_reply,
        conversation_history=history,
        turn_index=turn_index,
        persona_ladder=persona_ladder,
    )
    out["round_id"] = round_id
    out["choice_id"] = choice_id
    return jsonify(out)


@app.post("/api/run/<run_id>/investor-react")
def investor_react(run_id):
    """R1 — Live-LLM investor reaction for simulation rounds flagged with
    `live_investor: {...}` (e.g., Series A Founders' Journey q5_term_sheet).

    POST body: { "round_id": "...", "choice_id": "...",
                 "user_message"?: "...",
                 "history": [{"role":"assistant|user","content":"..."}] }
    Returns: { "response", "analysis", "ai_tactic_label", "ai_tactic_tip",
               "round_id", "choice_id" }
    """
    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    round_id = (payload.get("round_id") or "").strip()
    choice_id = (payload.get("choice_id") or "").strip()
    user_message = (payload.get("user_message") or "").strip()[:1000]
    history = payload.get("history") or []
    if not isinstance(history, list):
        history = []
    history = [h for h in history[-8:] if isinstance(h, dict)]

    if not round_id or not choice_id:
        return jsonify({"error": "round_id and choice_id are required"}), 400

    game_id = r.get("game_id")
    game, err = get_game_or_400(game_id)
    if err:
        return err

    rounds = game.get("rounds") or []
    rd = next((x for x in rounds if (x.get("id") or x.get("round_id")) == round_id), None)
    if not rd:
        return jsonify({"error": f"Round not found: {round_id}"}), 404

    li_cfg = rd.get("live_investor") or {}
    if not li_cfg.get("enabled"):
        return jsonify({"error": "Live investor not enabled for this round"}), 400

    choices = rd.get("choices") or []
    choice = next((c for c in choices if c.get("id") == choice_id), None)
    if not choice:
        return jsonify({"error": f"Choice not found: {choice_id}"}), 404

    # Build scenario_data from round + live_investor config
    scenario_data = {
        "title": rd.get("title") or "Investor Negotiation",
        "scenario": rd.get("scenario") or rd.get("story") or "",
        "your_role": li_cfg.get("your_role", "Founder negotiating Series A terms"),
        "opponent_role": li_cfg.get("investor_persona", "Senior partner at a Tier-1 VC firm"),
        "opponent_goals": li_cfg.get("investor_goals", []),
        "opponent_constraints": li_cfg.get("investor_constraints", []),
        "your_goals": li_cfg.get("founder_goals", []),
        "phases": li_cfg.get("phases", ["Opening", "Counter", "Close"]),
        "conversation_turns": li_cfg.get("max_turns", 4),
        "skill_focus": li_cfg.get("skill_focus", ["governance_judgment", "commercial_acumen"]),
        "context_facts": [
            f"Player chose: {choice.get('label', choice_id)}",
            f"Choice rationale (static): {choice.get('feedback', '')}",
        ],
    }

    # First turn: synthesise user_message from the choice if none provided
    if not user_message:
        user_message = (
            f"My position: {choice.get('label', choice_id)}. "
            f"{choice.get('feedback', '')}"
        ).strip()

    current_turn = sum(1 for h in history if h.get("role") == "user")
    state = {
        "relationship_score": 50,
        "assertiveness": 50,
        "empathy": 50,
    }
    difficulty = li_cfg.get("difficulty") or rd.get("difficulty") or "intermediate"

    try:
        out = negotiation_ai_response(
            user_message=user_message,
            scenario_data=scenario_data,
            conversation_history=history,
            current_turn=current_turn,
            state=state,
            scores_history=[],
            difficulty=difficulty,
        )
    except Exception as e:
        return jsonify({"error": f"LLM error: {e}"}), 502

    out["round_id"] = round_id
    out["choice_id"] = choice_id
    return jsonify(out)


@app.post("/api/run/<run_id>/explain")
@limiter.limit("30 per minute")
def mento_explain_round(run_id):
    """R18 — Mento explains contextual coach.

    A small chat affordance for any round: the player asks "why does this matter?"
    or "what did the expert do here?" and Mento answers with the round's
    expert_pick reasoning *without* giving away the answer.

    POST body: {
        "round_id": str,
        "question": str,                # the player question
        "history"?: [{role, content}],   # last few turns
        "kind"?: "why_matter" | "expert_did" | "hint" | "free"   # surface category
    }
    Returns: { response, action?, action_params?, kind, round_id }
    """
    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    round_id = (payload.get("round_id") or "").strip()
    question = (payload.get("question") or "").strip()[:600]
    kind = (payload.get("kind") or "free").strip()
    history = payload.get("history") or []
    if not isinstance(history, list):
        history = []
    history = [h for h in history[-6:] if isinstance(h, dict)]

    game_id = r.get("game_id")
    game, err = get_game_or_400(game_id)
    if err:
        return err

    rounds = game.get("rounds") or []
    rd = None
    if round_id:
        rd = next((x for x in rounds if (x.get("id") or x.get("round_id")) == round_id), None)
    if not rd and rounds:
        # Default to current round
        try:
            idx = int(getattr(r.get("state"), "round_index", 0))
        except Exception:
            idx = 0
        if 0 <= idx < len(rounds):
            rd = rounds[idx]

    # Map "kind" to a canonical question if the player didn't type one
    if not question:
        question = {
            "why_matter": "Why does this round matter? What's the underlying skill being tested?",
            "expert_did": "What does the expert reasoning say here? Don't give me the answer — explain the lens.",
            "hint":       "Without telling me which option to pick, what should I be thinking about?",
        }.get(kind, "Help me understand this round.")

    # Build a redacted round context so the agent can reason about the situation
    # without the model just regurgitating which option is correct.
    redacted_choices = []
    for c in (rd.get("choices") or []) if rd else []:
        redacted_choices.append({
            "label": c.get("label", ""),
            "skill_tags": c.get("skill_tags", []),
            # Deliberately omit feedback / deltas / expert_rationale so Mento
            # cannot just paraphrase the right answer.
        })

    # Mento *can* see the expert rationale and reflection prompt — these are
    # the genuine teaching artefacts.
    expert_signals = []
    for c in (rd.get("choices") or []) if rd else []:
        if c.get("expert_rationale"):
            expert_signals.append(c["expert_rationale"])
    expert_signals = expert_signals[:3]

    game_context = {
        "run_id": run_id,
        "game_id": game_id,
        "game_title": game.get("title", ""),
        "round": {
            "id": rd.get("id") if rd else "",
            "title": rd.get("title", "") if rd else "",
            "story": (rd.get("story") or rd.get("scenario") or "")[:1200] if rd else "",
            "reflection_prompt": rd.get("reflection_prompt", "") if rd else "",
            "coaching_moment": rd.get("coaching_moment", "") if rd else "",
            "choices_redacted": redacted_choices,
            "expert_signals": expert_signals,
        },
        "explain_kind": kind,
        "explain_history": history,
        "explain_directives": (
            "You are Coach Mento. The player is mid-round and asking for help understanding the situation. "
            "Do NOT tell them which option to pick. Do NOT name a specific choice as the right answer. "
            "Instead: name the underlying skill, point at the lens the expert uses, surface the trade-off, "
            "and end with one short reflective question. Stay under 90 words."
        ),
    }

    try:
        from llm import coach_mento_agent
        result = coach_mento_agent(question, game_context)
    except Exception as _e:
        logger.warning(f"R18 mento_explain failed: {_e}")
        # Static fallback — assemble a respectable answer without LLM
        skill = ""
        if rd and rd.get("choices"):
            tags = []
            for c in rd["choices"]:
                tags.extend(c.get("skill_tags") or [])
            if tags:
                skill = max(set(tags), key=tags.count).replace("_", " ")
        rp = (rd.get("reflection_prompt") or "") if rd else ""
        cm = (rd.get("coaching_moment") or "") if rd else ""
        body_parts = []
        if skill:
            body_parts.append(f"This round is mainly about **{skill}**.")
        if cm:
            body_parts.append(cm)
        if rp:
            body_parts.append(f"Ask yourself: {rp}")
        body = " ".join(body_parts) or "Take a breath and walk through what you're optimizing for here — and what each option costs."
        result = {"response": body, "action": None, "action_params": {}}

    # Strip any internal RL bandit id before returning
    result.pop("_tip_id", None)
    result["round_id"] = round_id or (rd.get("id") if rd else "")
    result["kind"] = kind
    return jsonify(result)


@app.post("/api/run/<run_id>/boardroom-debate")
@limiter.limit("20 per minute")
def boardroom_debate(run_id):
    """R12 — Live debate-AI for The Boardroom.

    Wraps debate_ai_response with a per-round persona pulled from the round's
    `live_debate` config. Used for The Boardroom rounds r6 (Marcus NRR
    interrogation) and r8 (Marcus governance ultimatum), but generic enough
    to drive any round that declares a `live_debate` block.

    POST body: {
        "round_id": str,
        "student_argument": str,
        "history"?: [{role: "ai"|"student", content: str}]
    }
    Returns: { "ai_response": {...}, "round_id", "turn_index", "max_turns" }
    """
    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    round_id = (payload.get("round_id") or "").strip()
    student_argument = (payload.get("student_argument") or "").strip()[:1200]
    history = payload.get("history") or []
    if not isinstance(history, list):
        history = []
    history = [h for h in history[-8:] if isinstance(h, dict)]

    if not round_id or not student_argument:
        return jsonify({"error": "round_id and student_argument are required"}), 400

    game_id = r.get("game_id")
    game, err = get_game_or_400(game_id)
    if err:
        return err

    rounds = game.get("rounds") or []
    rd = next((x for x in rounds if (x.get("id") or x.get("round_id")) == round_id), None)
    if not rd:
        return jsonify({"error": f"Round not found: {round_id}"}), 404

    ld_cfg = rd.get("live_debate") or {}
    if not ld_cfg.get("enabled"):
        return jsonify({"error": "Live debate not enabled for this round"}), 400

    persona = ld_cfg.get("persona") or {}
    scenario_data = {
        "topic": rd.get("title", ""),
        "context": (rd.get("story") or "")[:1200],
        "ai_persona": persona,
        "ai_position": ld_cfg.get("ai_position", ""),
        "student_position": ld_cfg.get("student_position", ""),
        "scoring_rubric": ld_cfg.get("scoring_rubric") or {},
    }

    turn_index = sum(1 for h in history if (h.get("role") == "ai")) + 1
    total_rounds = int(ld_cfg.get("max_turns", 3) or 3)
    difficulty = ld_cfg.get("difficulty", "advanced")

    try:
        from llm import debate_ai_response
        result = debate_ai_response(
            student_argument=student_argument,
            scenario_data=scenario_data,
            conversation_history=history,
            current_round=turn_index,
            total_rounds=total_rounds,
            scores_history=[],
            difficulty=difficulty,
        )
    except Exception as _e:
        logger.warning(f"R12 boardroom_debate failed: {_e}")
        # Static fallback so the modal stays usable if the LLM is down
        name = persona.get("name", "Marcus")
        fallback_text = (
            f"{name} watches you for a beat, then says: "
            f"\"That's a fair start — but tighten the mechanism. "
            f"Tell me one specific thing your team will do differently this quarter.\""
        )
        result = {
            "ai_response": fallback_text,
            "tactic": "narrowing_question",
            "score_signal": {"composure": 0, "evidence": 0, "reasoning": 0},
            "turn_complete": turn_index >= total_rounds,
        }

    return jsonify({
        "ai_response": result,
        "round_id": round_id,
        "turn_index": turn_index,
        "max_turns": total_rounds,
        "persona": {"name": persona.get("name", ""), "role": persona.get("role", "")},
    })


