@app.post("/api/run/<run_id>/story-choice")
def ai_arena_story_choice(run_id):
    """Process a choice during the AI Arena story intro phase.
    Body: {"scene_id": "...", "choice_id": "..."}
    Returns: {"next_scene": {...}, "state": {...}, "transitions_to_gameplay": bool}
    """
    from ai_arena_engine import process_story_intro_choice

    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    scene_id = payload.get("scene_id", "")
    choice_id = payload.get("choice_id", "")

    if not scene_id or not choice_id:
        return jsonify({"error": "scene_id and choice_id are required"}), 400

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err

    # Use initialized game if available (has populated rounds)
    active_game = r.get("initialized_game", game)

    result = process_story_intro_choice(active_game, scene_id, choice_id, state_to_dict(r["state"]))

    # Apply state delta
    state_obj = r["state"]
    for key, val in result.get("state_delta", {}).items():
        if hasattr(state_obj, key):
            setattr(state_obj, key, getattr(state_obj, key) + val)
        elif isinstance(state_obj, dict):
            state_obj[key] = state_obj.get(key, 0) + val
        else:
            # Rich format resource
            d = state_to_dict(state_obj)
            if key in d:
                raw = d[key]
                if isinstance(raw, dict) and "value" in raw:
                    raw["value"] = raw.get("value", 0) + val
                else:
                    d[key] = raw + val if isinstance(raw, (int, float)) else val

    # Track memory tags
    if result.get("memory_tag"):
        if "memory_tags" not in r:
            r["memory_tags"] = []
        r["memory_tags"].append(result["memory_tag"])

    # Track story phase completion
    if result.get("transitions_to_gameplay"):
        r["story_intro_complete"] = True

    update_run(run_id, r)

    return jsonify({
        "next_scene": result.get("next_scene"),
        "next_scene_id": result.get("next_scene_id"),
        "transitions_to_gameplay": result.get("transitions_to_gameplay", False),
        "state": state_to_dict(r["state"]),
        "memory_tag": result.get("memory_tag", ""),
    })


@app.post("/api/run/<run_id>/competitor-chat")
def ai_arena_competitor_chat(run_id):
    """Get competitor chat message in context of current game.
    Body: {"competitor_id": "...", "player_last_choice": {...}}
    Returns: {"message": str, "mood": str, "strategy_hint": str}
    """
    from ai_arena_engine import generate_competitor_chat

    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    competitor_id = payload.get("competitor_id", "")
    player_last_choice = payload.get("player_last_choice", {})

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err

    active_game = r.get("initialized_game", game)

    # Find competitor config
    competitor_config = None
    for comp in active_game.get("competitors", []):
        if comp.get("id") == competitor_id:
            competitor_config = comp
            break

    if not competitor_config:
        competitors = active_game.get("competitors", [])
        competitor_config = competitors[0] if competitors else {"name": "Competitor", "personality_type": "balanced"}

    config = active_game.get("ai_arena_config", {})
    result = generate_competitor_chat(
        competitor_config=competitor_config,
        game_state=state_to_dict(r["state"]),
        player_last_choice=player_last_choice,
        round_context={"domain": config.get("domain", "general"), "round_title": payload.get("round_title", "")},
    )

    return jsonify(result)


@app.post("/api/run/<run_id>/arena-npc-chat")
def ai_arena_npc_chat(run_id):
    """Chat with a game-specific NPC (scoped to current AI Arena run).
    Body: {"npc_id": "...", "message": "...", "history": [...]}
    Returns: {"response": str, "hint": str|null, "mood": str}
    """
    from ai_arena_engine import generate_npc_dialogue

    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    payload = request.get_json(silent=True) or {}
    npc_id = payload.get("npc_id", "")
    message = payload.get("message", "").strip()
    history = payload.get("history", [])

    if not message:
        return jsonify({"error": "Message cannot be empty"}), 400

    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err

    active_game = r.get("initialized_game", game)

    # Find NPC config
    npc_config = None
    for npc in active_game.get("npcs", []):
        if npc.get("id") == npc_id:
            npc_config = npc
            break

    if not npc_config:
        return jsonify({"error": f"NPC not found: {npc_id}"}), 404

    config = active_game.get("ai_arena_config", {})
