    # Build username lookup for display names
    try:
        from auth import _load_users
        _users_list = _load_users()
        users_by_id = {str(u.get("id", u.get("user_id", ""))): u.get("username", "") for u in _users_list}
    except Exception:
        users_by_id = {}

    # Enrich with per-student details
    profiles = learning_analytics._load_profiles()
    students = []
    for uid, p in profiles.items():
        if not isinstance(p, dict):
            continue
        history = p.get("history", [])
        recent_games = history[-5:] if history else []
        avg_score = 0
        if history:
            scores = [h.get("score", 0) for h in history if isinstance(h.get("score"), (int, float))]
            avg_score = round(sum(scores) / max(len(scores), 1)) if scores else 0

        # Psychological scores for skill radar
        psych = p.get("psychological_scores", {})
        # Soft skill dimension scores (6 standard dimensions)
        dim_scores = p.get("dimension_scores", {})

        display_name = users_by_id.get(str(uid), "")
        if not display_name:
            display_name = uid[:8] + "..."

        students.append({
            "user_id": uid,
            "display_name": display_name,
            "xp": p.get("xp", 0),
            "level": p.get("level", 1),
            "games_completed": p.get("games_completed", 0),
            "badges_count": len(p.get("badges_earned", [])),
            "avg_score": avg_score,
            "game_types_played": list(p.get("game_type_counts", {}).keys()),
            "recent_games": [{"game": g.get("game_title", ""), "score": g.get("score", 0), "ts": g.get("timestamp", "")} for g in recent_games],
            "skills": {k: round(v, 1) for k, v in psych.items()} if psych else {},
            "dimension_scores": dim_scores,
        })

    students.sort(key=lambda x: x["xp"], reverse=True)

    load_bundle()
    # Recommended next games for students who are struggling
    recommended = []
    for s in class_data.get("top_struggles", [])[:3]:
        gid = s["game_id"]
        gdata = GAMES.get(gid, {})
        recommended.append({
            "game_id": gid,
            "title": gdata.get("title", gid),
            "icon": gdata.get("icon", ""),
            "reason": f"{s['low_score_count']} students scored below 40",
        })

    return jsonify({
        "class_overview": class_data,
        "students": students,
        "recommendations": recommended,
    })


