@app.post("/api/run/<run_id>/rate")
def api_rate_game(run_id):
    """Rate a completed game run (1-5 stars + optional feedback)."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401
    data = request.get_json(silent=True) or {}
    rating = data.get("rating")
    feedback = data.get("feedback", "")
    if not rating or not isinstance(rating, int) or not 1 <= rating <= 5:
        return jsonify({"error": "Rating must be integer 1-5"}), 400
    try:
        r = get_run(run_id)
    except Exception:
        return jsonify({"error": "Run not found"}), 404
    entry = game_ratings.rate_game(
        game_id=r["game_id"],
        user_id=user_payload["user_id"],
        run_id=run_id,
        rating=rating,
        feedback=feedback,
    )
    return jsonify({"status": "ok", "rating": entry})


