@app.post("/api/run/<run_id>/generate-quiz")
@limiter.limit("10 per minute")
def api_generate_quiz(run_id):
    """Generate a post-game quiz based on the completed game."""
    try:
        r = get_run(run_id)
    except Exception:
        return jsonify({"error": "Run not found"}), 404
    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    st_obj = r["state"]
    final_state = state_to_dict(st_obj)
    choices = [{"round_id": x["round_id"], "choice": x["choice"]["label"]} for x in r.get("log", [])]
    psych_skills = []
    for s in (game.get("psychological_framework") or {}).get("core_skills", []):
        if isinstance(s, dict) and s.get("id"):
            psych_skills.append({"id": s["id"], "name": s.get("name", s["id"])})
    context = {
        "game_title": game.get("title", ""),
        "theme": game.get("theme", ""),
        "choices_made": choices[:10],
        "psychological_skills": psych_skills[:5],
        "final_state": {k: v for k, v in final_state.items() if isinstance(v, (int, float, str))},
    }
    quiz = generate_post_game_quiz(context)
    return jsonify(quiz)


@app.post("/api/run/<run_id>/submit-quiz")
def api_submit_quiz(run_id):
    """Submit quiz answers and get scoring."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    data = request.get_json(silent=True) or {}
    answers = data.get("answers", [])
    questions = data.get("questions", [])
    if not answers or not questions:
        return jsonify({"error": "answers and questions required"}), 400
    correct = 0
    results = []
    for ans in answers:
        q = next((q for q in questions if q.get("id") == ans.get("question_id")), None)
        if q:
            is_correct = ans.get("selected_index") == q.get("correct_index")
            if is_correct:
                correct += 1
            results.append({
                "question_id": ans.get("question_id"),
                "selected_index": ans.get("selected_index"),
                "correct_index": q.get("correct_index"),
                "is_correct": is_correct,
                "explanation": q.get("explanation", ""),
            })
    score = round((correct / max(len(questions), 1)) * 100)
    bonus_xp = 0
    if user_payload and score >= 60:
        bonus_xp = 10 + (score // 20) * 5
        player_profile.award_xp(
            user_id=user_payload["user_id"],
            xp_amount=bonus_xp,
            reason="quiz_completion",
            game_type="quiz",
            game_title=f"Quiz",
            score=score,
        )
    return jsonify({
        "correct": correct,
        "total": len(questions),
        "score": score,
        "results": results,
        "xp_bonus": bonus_xp,
    })


