@app.get("/api/profile/progress")
def api_get_progress():
    """Get structured progress data for dashboard visualizations."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401
    from datetime import datetime, timedelta
    profiles = player_profile._load_profiles()
    p = player_profile._ensure_profile(profiles, user_payload["user_id"])
    history = p.get("history", [])
    daily_completions = p.get("daily_completions", {})
    today = datetime.now().date()

    daily_activity = []
    for i in range(30):
        date = today - timedelta(days=29 - i)
        date_str = date.strftime("%Y-%m-%d")
        day_games = [h for h in history if h.get("timestamp", "").startswith(date_str)]
        scores = [h.get("score", 0) for h in day_games if h.get("score")]
        daily_activity.append({
            "date": date_str,
            "games_played": daily_completions.get(date_str, 0),
            "avg_score": round(sum(scores) / max(len(scores), 1)) if scores else 0,
            "xp_earned": sum(h.get("xp_earned", 0) for h in day_games),
        })

    # Streak
    streak = 0
    for i in range(len(daily_activity) - 1, -1, -1):
        if daily_activity[i]["games_played"] > 0:
            streak += 1
        else:
            break

    # Game type distribution
    type_counts = {}
    for h in history:
        gt = h.get("game_type", "unknown")
        type_counts[gt] = type_counts.get(gt, 0) + 1
    game_type_distribution = [{"type": k, "count": v} for k, v in type_counts.items()]

    # Monthly summary
    month_str = today.strftime("%Y-%m")
    month_games = [h for h in history if h.get("timestamp", "").startswith(month_str)]
    month_scores = [h.get("score", 0) for h in month_games if h.get("score")]

    return jsonify({
        "daily_activity": daily_activity,
        "streak": streak,
        "game_type_distribution": game_type_distribution,
        "monthly_summary": {
            "total_games": len(month_games),
            "avg_score": round(sum(month_scores) / max(len(month_scores), 1)) if month_scores else 0,
            "total_xp": sum(h.get("xp_earned", 0) for h in month_games),
            "best_score": max(month_scores) if month_scores else 0,
        },
    })


