@app.get("/api/profile/skill-tree")
def api_get_skill_tree():
    """Get skill tree with progression data for the authenticated user."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    # Load skill tree config
    import json as _json
    config_path = os.path.join(os.path.dirname(__file__), "config", "skill_tree_config.json")
    try:
        with open(config_path, "r") as f:
            tree_config = _json.load(f)
    except Exception:
        return jsonify({"error": "Skill tree config not found"}), 500

    # Load player data
    profiles = player_profile._load_profiles()
    p = player_profile._ensure_profile(profiles, user_payload["user_id"])
    psych_scores = p.get("psychological_scores", {})
    games_completed = p.get("games_completed", 0)
    game_types_played = set(p.get("game_types_played", []))

    # Load wallet for completed_games list
    from wallet import _load_wallets, _ensure_wallet
    wallets = _load_wallets()
    w = _ensure_wallet(wallets, user_payload["user_id"])
    completed_game_ids = set(w.get("completed_games", []))

    # Build skill nodes with XP calculations
    skill_nodes = []
    skill_levels = {}  # id -> level for prerequisite checking

    # First pass: compute XP and level for each skill
    for skill in tree_config.get("skills", []):
        sid = skill["id"]
        # XP comes from avg psychological score * games contributing
        score_data = psych_scores.get(sid, {})
        avg_score = round(score_data.get("total", 0) / max(score_data.get("count", 0), 1)) if score_data.get("count", 0) > 0 else 0
        contributing_games = score_data.get("count", 0)

        # Also count related game type plays
        related_types = set(skill.get("game_types", []))
        type_overlap = len(related_types & game_types_played)

        # XP formula: avg_score * contributing_games + type_diversity bonus
        xp = (avg_score * contributing_games) + (type_overlap * 20)

        # Determine level
        xp_thresholds = skill.get("xp_per_level", [0, 100, 250, 500, 800])
        level = 0
        for i, threshold in enumerate(xp_thresholds):
            if xp >= threshold:
                level = i
            else:
                break

        skill_levels[sid] = level

    # Second pass: build full nodes with prerequisite checking
    for skill in tree_config.get("skills", []):
        sid = skill["id"]
        score_data = psych_scores.get(sid, {})
        avg_score = round(score_data.get("total", 0) / max(score_data.get("count", 0), 1)) if score_data.get("count", 0) > 0 else 0
        contributing_games = score_data.get("count", 0)

        related_types = set(skill.get("game_types", []))
        type_overlap = len(related_types & game_types_played)
        xp = (avg_score * contributing_games) + (type_overlap * 20)

        xp_thresholds = skill.get("xp_per_level", [0, 100, 250, 500, 800])
        level = skill_levels[sid]
        max_level = skill.get("max_level", 5)
        xp_to_next = xp_thresholds[level + 1] if level < len(xp_thresholds) - 1 else xp_thresholds[-1]
        xp_in_level = xp - xp_thresholds[level] if level < len(xp_thresholds) else 0
        xp_for_next = xp_to_next - xp_thresholds[level] if level < len(xp_thresholds) - 1 else 1

        # Check prerequisites
        prereqs = skill.get("prerequisites", [])
        prereqs_met = all(skill_levels.get(p, 0) >= 1 for p in prereqs)
        unlocked = prereqs_met and (contributing_games > 0 or type_overlap > 0)

        skill_nodes.append({
            "id": sid,
            "label": skill["label"],
            "icon": skill["icon"],
            "description": skill["description"],
            "category": skill.get("category", "core"),
            "color": skill.get("color", "#6366F1"),
            "level": level,
            "max_level": max_level,
            "xp": xp,
            "xp_to_next": xp_to_next,
            "xp_in_level": max(xp_in_level, 0),
            "xp_for_next": max(xp_for_next, 1),
            "progress_pct": round(min(max(xp_in_level, 0) / max(xp_for_next, 1) * 100, 100)),
            "avg_score": avg_score,
            "games_contributing": contributing_games,
            "prerequisites": prereqs,
            "prerequisites_met": prereqs_met,
            "unlocked": unlocked,
            "game_types": skill.get("game_types", []),
        })

    return jsonify({
        "skills": skill_nodes,
        "connections": tree_config.get("connections", []),
        "categories": tree_config.get("categories", {}),
        "player_stats": {
            "games_completed": games_completed,
            "game_types_played": list(game_types_played),
            "total_skills_unlocked": sum(1 for s in skill_nodes if s["unlocked"]),
            "total_skills": len(skill_nodes),
        }
    })


