@app.get("/api/run/<run_id>/behavioral-prediction")
def api_behavioral_prediction(run_id):
    """Real-time behavioral prediction from early choices during gameplay."""
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Run not found"}), 404

    try:
        from engines.behavioral_analytics import extract_early_features, predict_final_scores
        state_obj = r["state"]
        choice_history = state_obj.choice_history if hasattr(state_obj, 'choice_history') else []
        resource_trajectory = state_obj.resource_trajectory if hasattr(state_obj, 'resource_trajectory') else []

        features = extract_early_features(choice_history, resource_trajectory, n=3)
        if features is None:
            return jsonify({"status": "insufficient_data", "message": "Need at least 3 choices"})

        prediction = predict_final_scores(features)
        return jsonify({"status": "ok", "prediction": prediction, "features": features})
    except Exception as e:
        logger.error(f"Behavioral prediction failed: {e}")
        return jsonify({"error": "Failed to generate prediction"}), 500


