_GLOSSARY_CACHE = None
_GLOSSARY_CACHE_TIME = 0

@app.get("/api/glossary")
def api_global_glossary():
    """
    Aggregate all glossary_terms from all games into one searchable list.
    Optional query param: ?search=xyz to filter by term name or definition.
    Returns {terms: [{term, definition, game_id, game_title, category}], total: int}
    """
    global _GLOSSARY_CACHE, _GLOSSARY_CACHE_TIME
    import time as _time
    search = request.args.get("search", "").strip().lower()
    seen_terms = {}  # term_lower -> entry (deduplicate, keep first occurrence)
    # Use cache for non-search requests (cache valid for 5 minutes)
    if not search and _GLOSSARY_CACHE and (_time.time() - _GLOSSARY_CACHE_TIME) < 300:
        return jsonify({"terms": _GLOSSARY_CACHE, "total": len(_GLOSSARY_CACHE)})

    try:
        games_dir = os.path.join(os.path.dirname(__file__), "games")
        for fname in sorted(os.listdir(games_dir)):
            if not fname.endswith(".json"):
                continue
            game_id = fname[:-5]
            fpath = os.path.join(games_dir, fname)
            try:
                with open(fpath, "r", encoding="utf-8") as f:
                    game_data = json.load(f)
            except Exception:
                continue

            game_title = game_data.get("title", game_id)
            category = game_data.get("category", "")
            raw_terms = game_data.get("glossary_terms", [])

            # Normalize: can be a list of dicts or a plain dict {term: definition}
            if isinstance(raw_terms, dict):
                items = [{"term": k, "definition": v} for k, v in raw_terms.items()]
            elif isinstance(raw_terms, list):
                items = raw_terms
            else:
                items = []

            for item in items:
                if not isinstance(item, dict):
                    continue
                term_name = (item.get("term") or "").strip()
                definition = (item.get("definition") or "").strip()
                if not term_name:
                    continue
                key = term_name.lower()
                if key not in seen_terms:
                    seen_terms[key] = {
                        "term": term_name,
                        "definition": definition,
                        "game_id": game_id,
                        "game_title": game_title,
                        "category": category,
                    }

        # Sort alphabetically by term
        all_terms = sorted(seen_terms.values(), key=lambda x: x["term"].lower())

        # Apply search filter if provided
        if search:
            all_terms = [
                t for t in all_terms
                if search in t["term"].lower() or search in t["definition"].lower()
            ]

        if not search:
            _GLOSSARY_CACHE = all_terms
            _GLOSSARY_CACHE_TIME = _time.time()
        return jsonify({"terms": all_terms, "total": len(all_terms)})

    except Exception as e:
        logger.error(f"Global glossary failed: {e}")
        return jsonify({"error": "Failed to load glossary"}), 500


