    user_id = request.current_user["user_id"]
    prof = _pp_mc.get_profile(user_id)
    cal = prof.get("metacognition_calibration", [])
    if not cal:
        return jsonify({"calibration_history": [], "avg_delta": 0, "trend": "no_data"})
    avg_delta = sum(c["delta"] for c in cal) / len(cal)
    recent = cal[-5:]
    if len(recent) >= 3:
        trend = "improving" if recent[-1]["delta"] > recent[0]["delta"] else "declining" if recent[-1]["delta"] < recent[0]["delta"] else "stable"
    else:
        trend = "insufficient_data"
    return jsonify({"calibration_history": cal[-10:], "avg_delta": round(avg_delta, 1), "trend": trend})


