@app.get("/api/career/recommendations")
@require_auth
def career_recommendations():
    """Return top career matches based on the player's dimension scores."""
    import math as _math
    user_id = request.current_user["user_id"]
    prof = player_profile.get_profile(user_id)
    dim_scores = prof.get("dimension_scores", {})
    # Normalize to 0-1 scale (scores are 0-100)
    player = {k: v / 100.0 for k, v in dim_scores.items() if isinstance(v, (int, float))}
    if len(player) < 1:
        return jsonify({"recommendations": [], "note": "Complete more games to get career recommendations"})

    career_file = os.path.join(os.path.dirname(__file__), "data", "career_mapping.json")
    try:
        with open(career_file) as _cf:
            careers = json.load(_cf)
    except (FileNotFoundError, json.JSONDecodeError):
        return jsonify({"recommendations": [], "error": "Career mapping data unavailable"}), 500

    results = []
    for career in careers:
        req = career.get("required_dimensions", {})
        if not req:
            continue
        total_weight = sum(req.values())
        score_sum = sum(
            min(player.get(dim, 0) / max(req_val, 0.01), 1.0) * req_val
            for dim, req_val in req.items()
        )
        match_score = score_sum / max(total_weight, 0.01)
        # Identify strong dims (player meets or exceeds requirement)
        strong = [d for d, rv in req.items() if player.get(d, 0) >= rv * 0.9]
        # Identify gap dims (player significantly below requirement)
        gaps = [d for d, rv in req.items() if player.get(d, 0) < rv * 0.7]
        results.append({
            "career": career["career"],
            "description": career.get("description", ""),
            "match_score": round(match_score, 3),
            "strong_dims": strong,
            "gap_dims": gaps,
        })

    results.sort(key=lambda x: x["match_score"], reverse=True)
    return jsonify({"recommendations": results[:5], "total_careers": len(results)})


@app.post("/api/admin/game/<game_id>/version/bump")
@require_admin
def game_version_bump(game_id):
    """Bump the semantic version of a game (major/minor/patch) with a changelog entry."""
    from datetime import datetime
    body = request.get_json(force=True) or {}
    bump_type = body.get("bump_type", "patch")
    changelog = body.get("changelog", "")
    if bump_type not in ("major", "minor", "patch"):
        return jsonify({"error": "bump_type must be major, minor, or patch"}), 400

    game_data, err = get_game_or_400(game_id)
    if err:
        return err

    # Parse/increment semver
    current = game_data.get("game_version", "1.0.0")
    try:
        parts = [int(x) for x in str(current).split(".")]
        while len(parts) < 3:
            parts.append(0)
        major, minor, patch = parts[0], parts[1], parts[2]
    except (ValueError, AttributeError):
        major, minor, patch = 1, 0, 0

    if bump_type == "major":
        major += 1; minor = 0; patch = 0
    elif bump_type == "minor":
        minor += 1; patch = 0
    else:
        patch += 1

    new_version = f"{major}.{minor}.{patch}"
    game_data["game_version"] = new_version
    history = game_data.get("version_history", [])
    history.append({
        "version": new_version,
        "date": datetime.now().isoformat(),
        "changelog": changelog,
        "bump_type": bump_type,
    })
    game_data["version_history"] = history

    from game_storage import save_game as _save_g
    _save_g(game_data)
    return jsonify({"game_id": game_id, "game_version": new_version, "version_history": history})


