@app.get("/api/teacher/student/<user_id>/accessibility-profile")
@require_auth
def student_accessibility_profile(user_id):
    """Return ASD cognitive style accommodation signals for a student (teacher-only, NOT clinical)."""
    # Only teachers, admins, and school admins can access this
    current_role = request.current_user.get("role", "student")
    if current_role not in ("teacher", "school_admin", "admin"):
        return jsonify({"error": "Teacher access required"}), 403

    prof = player_profile.get_profile(user_id)
    dim_scores = prof.get("dimension_scores", {})

    # Derive preferred game types from top dimensions
    preferred_types = []
    top_dims = sorted(dim_scores.items(), key=lambda x: x[1], reverse=True)[:2] if dim_scores else []
    for dim, _ in top_dims:
        if dim in ("strategic_thinking", "risk_tolerance"):
            preferred_types.extend(["chess_strategy", "strategy_grid"])
        elif dim in ("empathy", "ethical_reasoning"):
            preferred_types.extend(["rounds", "story_branching"])
        elif dim in ("adaptability", "resilience"):
            preferred_types.extend(["debate", "negotiation"])

    # Simple accommodation hints based on game history patterns
    history = prof.get("game_history", [])
    completed_types = [h.get("game_type") for h in history if h.get("completed")]
    high_sensory_played = sum(1 for t in completed_types if t in ("card_board", "board", "ai_arena"))
    low_sensory_played = sum(1 for t in completed_types if t in ("rounds", "story_branching", "debate"))

    accommodation_hints = []
    if low_sensory_played > high_sensory_played * 2:
        accommodation_hints.append("Student shows preference for low-sensory game types")
    if prof.get("avg_decision_speed_ms", 0) > 8000:
        accommodation_hints.append("Extended response time may be beneficial")

    try:
        import behavioral_indicators as _bi
        asd_result = _bi.detect_asd_cognitive_style(
            [c for h in history for c in h.get("choice_history", [])]
        )
    except Exception:
        asd_result = {"signal_strength": 0, "signals": [], "accommodation_hints": []}

    return jsonify({
        "user_id": user_id,
        "preferred_game_types": list(set(preferred_types))[:4],
        "accommodation_hints": accommodation_hints + asd_result.get("accommodation_hints", []),
        "asd_cognitive_style": asd_result,
        "note": "This is NOT a clinical assessment. For informational use by educators only.",
    })


