@app.get("/api/learning-paths/<path_id>/progress")
def api_learning_path_progress(path_id):
    """Item 33: Get user progress on a specific learning path."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    paths_file = os.path.join(os.path.dirname(__file__), "data", "learning_paths.json")
    try:
        with open(paths_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except FileNotFoundError:
        return jsonify({"error": "No learning paths configured"}), 404

    path = None
    for p in data.get("paths", []):
        if p.get("id") == path_id:
            path = p
            break
    if not path:
        return jsonify({"error": "Path not found"}), 404

    # Check which games the user has completed
    try:
        from services.skill_portfolio import get_player_portfolio
        portfolio = get_player_portfolio(user_payload["user_id"])
        played_ids = {e["game_id"] for e in portfolio.get("recent_activity", [])}
    except Exception:
        played_ids = set()

    games = path.get("games", [])
    completed = []
    remaining = []
    for g in games:
        gid = g.get("game_id", "")
        if gid in played_ids:
            completed.append(g)
        else:
            remaining.append(g)

    total = len(games)
    done_count = len(completed)
    progress_pct = round((done_count / total) * 100) if total > 0 else 0

    return jsonify({
        "path_id": path_id,
        "title": path.get("title", ""),
        "total_games": total,
        "completed_count": done_count,
        "progress_pct": progress_pct,
        "completed_games": completed,
        "remaining_games": remaining,
    })


