@app.get("/api/profile/goals/recommendations")
def api_goals_recommendations():
    """Return top 5 recommended games based on user's skill goals and current scores."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401
    try:
        user_id = user_payload["user_id"]
        goals_data = player_profile.get_skill_goals(user_id)
        goals = goals_data.get("goals", {})
        if not goals:
            return jsonify({"recommendations": [], "reason": "no_goals_set"})

        # Get current dimension scores from profile
        profile = player_profile.get_profile(user_id)
        psych_scores = profile.get("psychological_scores", {})
        current_scores = {
            dim: psych_scores[dim]["latest"] if dim in psych_scores else 50
            for dim in goals
        }

        # Find top 2 dimensions with biggest gap (goal - current)
        gaps = {dim: (goals[dim].get("target", 80) if isinstance(goals[dim], dict) else goals[dim]) - current_scores.get(dim, 50) for dim in goals}
        top_dims = sorted(gaps, key=lambda d: gaps[d], reverse=True)[:2]

        # Load games and score by skill_tags matching
        load_bundle()
        all_games = list(GAMES.values()) if GAMES else []
        recent_played = {e["game_id"] for e in profile.get("recent_activity", [])}

        scored = []
        for g in all_games:
            if g.get("game_type") in ("negotiation", "debate", "interview", "group_discussion", "pitch", "public_speaking"):
                continue  # Live AI sessions handled separately
            tags = []
            for r_obj in g.get("rounds", g.get("story_intro", {}).get("scenes", [])):
                for choice in r_obj.get("choices", []):
                    tags.extend(choice.get("skill_tags", []))
            tags_set = set(tags)
            match_score = sum(1 for d in top_dims if d in tags_set)
            if match_score > 0:
                not_played_bonus = 1 if g.get("game_id") not in recent_played else 0
                scored.append((g, match_score + not_played_bonus))

        scored.sort(key=lambda x: x[1], reverse=True)
        recs = []
        for g, _ in scored[:5]:
            recs.append({
                "game_id": g.get("game_id"),
                "title": g.get("title"),
                "icon": g.get("icon", "🎮"),
                "description": g.get("description", ""),
                "target_dimensions": [d for d in top_dims if d in str(g)],
            })
        return jsonify({"recommendations": recs, "targeting_dimensions": top_dims})
    except Exception as e:
        logger.error(f"Goals recommendations failed: {e}")
        return jsonify({"recommendations": [], "error": str(e)})


