@app.get("/api/profile/next-game")
def api_next_game_recommendation():
    """Recommend the next game based on weakest skill dimension."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"recommendations": []})
    try:
        history_data = player_profile.get_skill_history(user_payload["user_id"])
        dim_scores = history_data.get("latest_scores", {})
        if not dim_scores:
            # No scores yet — recommend starter games
            games_list = []
            try:
                for gid, g in GAMES.items():
                    if g.get("visible") is False or g.get("game_type") not in _PUBLIC_GAME_TYPES:
                        continue
                    if g.get("game_type") in ("rounds", "story_branching"):
                        games_list.append({"game_id": gid, "title": g.get("title", ""), "reason": "Great for beginners"})
                    if len(games_list) >= 3:
                        break
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            return jsonify({"recommendations": games_list[:3], "based_on": "starter"})

        # Find weakest and second-weakest dimensions
        sorted_dims = sorted(dim_scores.items(), key=lambda x: x[1])
        weak_dims = [d[0] for d in sorted_dims[:2]]

        # Find games that target these skills
        _dim_to_skill_words = {
            "strategic_thinking": ["strategy", "planning", "strategic", "chess", "resource"],
            "risk_tolerance": ["risk", "bold", "startup", "entrepreneur", "invest"],
            "delayed_gratification": ["patience", "longterm", "savings", "sustainability", "growth"],
            "adaptability": ["adaptability", "flexible", "pivot", "change", "agile"],
            "resilience": ["resilience", "leadership", "challenge", "crisis", "pressure"],
            "empathy": ["empathy", "team", "social", "leadership", "negotiation", "ethics"],
        }

        recs = []
        try:
            for gid, g in GAMES.items():
                if len(recs) >= 5:
                    break
                if g.get("visible") is False or g.get("game_type") not in _PUBLIC_GAME_TYPES:
                    continue
                try:
                    concept = (g.get("learning_concept", "") + " " + g.get("description", "")).lower()
                    for dim in weak_dims:
                        words = _dim_to_skill_words.get(dim, [])
                        if any(w in concept for w in words):
                            recs.append({
                                "game_id": gid,
                                "title": g.get("title", ""),
                                "game_type": g.get("game_type", ""),
                                "learning_concept": g.get("learning_concept", ""),
                                "reason": f"Builds {dim.replace('_', ' ').title()} — your area to grow",
                                "target_dimension": dim,
                                "current_score": dim_scores.get(dim, 0),
                            })
                            break
                except Exception as _e:
                    logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        return jsonify({"recommendations": recs[:3], "based_on": "weakest_skills", "weak_dims": weak_dims})
    except Exception as e:
        return jsonify({"recommendations": [], "error": str(e)})


@app.get("/api/admin/analytics/game-health")
@require_admin
def api_game_health():
    """Per-game completion rate from persistent game_starts.json tracker."""
    try:
        _gs_file = os.path.join(os.path.dirname(__file__), "data", "game_starts.json")
        try:
            with open(_gs_file) as _f:
                _game_starts = json.load(_f)
        except (FileNotFoundError, json.JSONDecodeError):
            _game_starts = {}
        agg = {}
        for run_id, entry in _game_starts.items():
            if not isinstance(entry, dict):
                continue
            gid = entry.get("game_id", "unknown")
            if gid not in agg:
                agg[gid] = {"game_id": gid, "game_type": entry.get("game_type", ""), "started": 0, "completed": 0, "total_rounds_completed": 0}
            agg[gid]["started"] += 1
            if entry.get("completed"):
                agg[gid]["completed"] += 1
            agg[gid]["total_rounds_completed"] += entry.get("rounds_completed", 0)
        result = []
        for gid, s in agg.items():
            s["completion_rate"] = round(s["completed"] / max(1, s["started"]) * 100, 1)
            s["avg_rounds_completed"] = round(s["total_rounds_completed"] / max(1, s["started"]), 1)
            result.append(s)
        result.sort(key=lambda x: x["started"], reverse=True)
        return jsonify({"games": result})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.get("/api/admin/analytics/content-signals")
@require_admin
def api_content_signals():
    """Rounds where one choice is picked >75% of the time (flag for redesign)."""
    try:
        _cstats_file = os.path.join(os.path.dirname(__file__), "data", "choice_stats.json")
        try:
            with open(_cstats_file) as _f:
                _cstats = json.load(_f)
        except (FileNotFoundError, json.JSONDecodeError):
            _cstats = {}
        flags = []
        for game_id, rounds in _cstats.items():
            if not isinstance(rounds, dict):
                continue
            for round_id, choices in rounds.items():
                if not isinstance(choices, dict):
                    continue
                total = sum(choices.values())
                if total < 5:
                    continue  # not enough data
                for cid, count in choices.items():
                    pct = count / total * 100
                    if pct >= 75:
                        flags.append({
                            "game_id": game_id, "round_id": round_id,
                            "dominant_choice": cid, "pick_rate_pct": round(pct, 1),
                            "total_picks": total,
                        })
        flags.sort(key=lambda x: x["pick_rate_pct"], reverse=True)
        return jsonify({"flagged_rounds": flags})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


