@app.get("/api/adaptive/variant/<game_id>")
def adaptive_variant(game_id):
    """Generate a game variant tailored to the player.

    Improvements over the stub:
    - Loads the game JSON and applies real structural variation.
    - If a round has a ``variants`` array ({story, choices}), randomly pick one.
    - Otherwise shuffle round choices so replay sees a different order.
    - Also prepends a random alternative opening phrase to the story text
      (rephrase variant) when neither of the above applies.
    - Marks the run metadata with ``variant_mode: true`` so the round-fetch
      route can shuffle choices on the fly.
    """
    import copy, random as _rnd
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    user_payload = verify_token(token)
    if not user_payload:
        return jsonify({"error": "Invalid token"}), 401

    load_bundle()
    game = GAMES.get(game_id)
    if not game:
        return jsonify({"error": "Game not found"}), 404

    _REPHRASE_OPENERS = [
        "This time, ",
        "In a different scenario, ",
        "Facing the same challenge, ",
    ]

    variant_type = "none"
    rounds_modified = 0
    game_copy = copy.deepcopy(game)

    for rnd in game_copy.get("rounds", []):
        # Option 1: round has explicit variants array
        variants_list = rnd.get("variants")
        if isinstance(variants_list, list) and variants_list:
            chosen = _rnd.choice(variants_list)
            if chosen.get("story"):
                rnd["story"] = chosen["story"]
            if chosen.get("choices"):
                rnd["choices"] = chosen["choices"]
            variant_type = "reorder"
            rounds_modified += 1
            continue

        # Option 2: shuffle choices within the round
        choices = rnd.get("choices", [])
        if len(choices) > 1:
            _rnd.shuffle(choices)
            rnd["choices"] = choices
            variant_type = "shuffle"
            rounds_modified += 1
            continue

        # Option 3: rephrase story opening
        story = rnd.get("story", "")
        if story:
            opener = _rnd.choice(_REPHRASE_OPENERS)
            # Lower-case the first letter of the original story for natural flow
            rnd["story"] = opener + story[0].lower() + story[1:] if len(story) > 1 else opener + story
            variant_type = "rephrase"
            rounds_modified += 1

    return jsonify({
        "game_id": game_id,
        "variant_applied": rounds_modified > 0,
        "variant_type": variant_type,
        "rounds_modified": rounds_modified,
        "game_title": game.get("title", ""),
        "variant_game": game_copy,
    })


