@app.get("/api/spaced-repetition/due")
def api_spaced_repetition_due():
    """Return all spaced-repetition reviews that are due today or overdue for the current user."""
    token = get_token_from_request()
    if not token:
        return jsonify({"error": "Authentication required"}), 401
    user_payload = verify_token(token)
    if not user_payload:
        return jsonify({"error": "Invalid token"}), 401
    try:
        import spaced_repetition
        user_id = user_payload["user_id"]
        # Build dimension→games lookup for interleaving (different game type, same skill)
        load_bundle()
        games_by_dimension: dict = {}
        # R20 — track which games declare themselves as specialists for a dimension
        specialists_by_dim: dict = {}
        for gid, g in GAMES.items():
            for dim in g.get("dimension_scoring_weights", {}).keys():
                games_by_dimension.setdefault(dim, []).append(gid)
            for tag in g.get("skill_tags", []):
                games_by_dimension.setdefault(tag, []).append(gid)
            for sdim in g.get("specialist_for", []) or []:
                specialists_by_dim.setdefault(sdim, []).append(gid)
        # R20 — promote specialist games (Ethics Tribunal, CFO Q2) to the front of
        # their dimension's candidate list so weak performers get auto-routed to the
        # matching deep-practice game rather than a generic interleave.
        for dim, specialists in specialists_by_dim.items():
            if dim not in games_by_dimension:
                games_by_dimension[dim] = []
            cur = games_by_dimension[dim]
            kept = [g for g in cur if g not in specialists]
            games_by_dimension[dim] = specialists + kept
        reviews = spaced_repetition.get_due_reviews(user_id, games_by_dimension=games_by_dimension)
        # Enrich each review with game titles
        for rev in reviews:
            game = GAMES.get(rev["game_id"])
            rev["game_title"] = game.get("title", rev["game_id"]) if game else rev["game_id"]
            orig = GAMES.get(rev.get("original_game_id", ""))
            rev["original_game_title"] = orig.get("title", rev.get("original_game_id", "")) if orig else rev.get("original_game_id", "")
            # R20 — mark specialist re-teach routing so the UI can label "Deep practice on X"
            dim = rev.get("dimension", "")
            specialists_for_dim = specialists_by_dim.get(dim, [])
            if rev.get("game_id") in specialists_for_dim:
                rev["is_specialist_review"] = True
                rev["specialist_reason"] = f"Deep-practice round for {dim.replace('_', ' ')} — re-teach via the specialist game"
            elif rev.get("is_interleaved"):
                rev["interleave_reason"] = f"Practising {dim.replace('_', ' ')} in a new game context to strengthen transfer"
        return jsonify({"reviews": reviews, "count": len(reviews)})
    except Exception as e:
        logger.warning(f"spaced_repetition.get_due_reviews failed: {e}")
        return jsonify({"reviews": [], "count": 0})


