@app.route('/api/run/<run_id>/strategygrid/init', methods=['POST'])
def strategygrid_init(run_id):
    """Initialize a Strategy Grid game."""
    from engines.strategy_grid_engine import StrategyGridEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404
    game_data, err = get_game_or_400(run.get("game_id"))
    if err:
        return err
    config = game_data.get("strategy_grid_config", {})
    data = request.get_json(silent=True) or {}
    # Apply custom player types from frontend config screen
    custom_players = data.get("players")
    if custom_players and isinstance(custom_players, list) and config.get("players"):
        import copy
        config = copy.deepcopy(config)
        for cp in custom_players:
            slot = cp.get("slot")
            if slot is not None and slot < len(config["players"]):
                if cp.get("type") in ("human", "ai"):
                    config["players"][slot]["type"] = cp["type"]
    engine = StrategyGridEngine(config)
    state = engine.initialize_game()
    # Apply difficulty from request payload
    difficulty = data.get("difficulty", "medium")
    if difficulty in ("easy", "medium", "hard"):
        state["difficulty"] = difficulty
        # Also update per-player AI difficulty if multiplayer
        if state.get("multiplayer"):
            for slot, pdata in state.get("players", {}).items():
                if pdata.get("type") == "ai":
                    pdata["ai_difficulty"] = difficulty
    run["sg_state"] = state
    storage.update_run(run_id, run)
    return jsonify({"state": state})


