@app.route('/api/run/<run_id>/strategygrid/move', methods=['POST'])
def strategygrid_move(run_id):
    """Move a piece to a target position."""
    from engines.strategy_grid_engine import StrategyGridEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404
    game_data, err = get_game_or_400(run.get("game_id"))
    if err:
        return err
    sg_state = run.get("sg_state")
    if not sg_state:
        return jsonify({"error": "Game not initialized"}), 400
    data = request.json or {}
    piece_id = data.get("piece_id")
    target_pos = data.get("position")
    if not piece_id or not target_pos:
        return jsonify({"error": "piece_id and position required"}), 400
    config = game_data.get("strategy_grid_config", {})
    engine = StrategyGridEngine(config)
    result = engine.move_piece(sg_state, piece_id, target_pos)
    ai_results = []
    if result.get("success") and not sg_state.get("game_over"):
        end_result = engine.end_turn(sg_state)
        # In multiplayer: loop through all consecutive AI turns
        if sg_state.get("multiplayer"):
            max_ai_turns = 10  # safety limit
            while not sg_state.get("game_over") and max_ai_turns > 0:
                current_slot = sg_state["turn"]
                player_data = sg_state["players"].get(current_slot, {})
                if player_data.get("type") == "human":
                    break  # Next human player's turn
                # AI turn
                ai_result = engine.get_ai_move(sg_state, player_slot=current_slot)
                ai_result["player_slot"] = current_slot
                ai_result["player_name"] = player_data.get("name", f"AI {current_slot}")
                ai_results.append(ai_result)
                if not sg_state.get("game_over"):
                    engine.end_turn(sg_state)
                max_ai_turns -= 1
        else:
            # Legacy 2-player: single AI turn
            if not sg_state.get("game_over") and sg_state["turn"] == "ai":
                ai_result = engine.get_ai_move(sg_state)
                ai_results.append(ai_result)
                if not sg_state.get("game_over"):
                    engine.end_turn(sg_state)
    run["sg_state"] = sg_state
    storage.update_run(run_id, run)
    # Legacy compat: ai_result is first AI result or None
    ai_result = ai_results[0] if ai_results else None
    return jsonify({"result": result, "ai_result": ai_result, "ai_results": ai_results, "state": sg_state})


@app.route('/api/run/<run_id>/strategygrid/end-turn', methods=['POST'])
def strategygrid_end_turn(run_id):
    """Explicitly end the current player's turn (for multiplayer or skip-turn)."""
    from engines.strategy_grid_engine import StrategyGridEngine
    load_bundle()
    run = storage.get_run(run_id)
    if not run:
        return jsonify({"error": "Run not found"}), 404
    game_data, err = get_game_or_400(run.get("game_id"))
    if err:
        return err
    sg_state = run.get("sg_state")
    if not sg_state:
        return jsonify({"error": "Game not initialized"}), 400
    if sg_state.get("game_over"):
        return jsonify({"error": "Game is over"}), 400
    config = game_data.get("strategy_grid_config", {})
    engine = StrategyGridEngine(config)
    end_result = engine.end_turn(sg_state)
    ai_results = []
    # Auto-play consecutive AI turns
    if sg_state.get("multiplayer"):
        max_ai_turns = 10
        while not sg_state.get("game_over") and max_ai_turns > 0:
            current_slot = sg_state["turn"]
            player_data = sg_state["players"].get(current_slot, {})
            if player_data.get("type") == "human":
                break
            ai_result = engine.get_ai_move(sg_state, player_slot=current_slot)
            ai_result["player_slot"] = current_slot
            ai_result["player_name"] = player_data.get("name", f"AI {current_slot}")
            ai_results.append(ai_result)
            if not sg_state.get("game_over"):
                engine.end_turn(sg_state)
            max_ai_turns -= 1
    else:
        if not sg_state.get("game_over") and sg_state["turn"] == "ai":
            ai_result = engine.get_ai_move(sg_state)
            ai_results.append(ai_result)
            if not sg_state.get("game_over"):
                engine.end_turn(sg_state)
    run["sg_state"] = sg_state
    storage.update_run(run_id, run)
    ai_result = ai_results[0] if ai_results else None
    return jsonify({"result": end_result, "ai_result": ai_result, "ai_results": ai_results, "state": sg_state})


