CHALLENGES_FILE = os.path.join(os.path.dirname(__file__), "game_sessions", "challenges.json")

def _load_challenges():
    try:
        with open(CHALLENGES_FILE, "r") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def _save_challenges(data):
    os.makedirs(os.path.dirname(CHALLENGES_FILE), exist_ok=True)
    with open(CHALLENGES_FILE, "w") as f:
        json.dump(data, f, indent=2, default=str)

@app.post("/api/challenge/create")
def create_challenge():
        """Create a challenge from a completed game run."""
        token = get_token_from_request()
        user_payload = verify_token(token) if token else None
        if not user_payload:
            return jsonify({"error": "Authentication required"}), 401

        data = request.get_json(silent=True) or {}
        run_id = data.get("run_id")
        message = data.get("message", "")

        if not run_id:
            return jsonify({"error": "run_id required"}), 400

        run = storage.get_run(run_id)
        if not run:
            return jsonify({"error": "Run not found"}), 404

        game_id = run.get("game_id")
        game_data_c, err = get_game_or_400(game_id)
        if err:
            return err

        # Get challenger's score
        challenger_score = 0
        sg_state = run.get("sg_state")
        if sg_state and sg_state.get("game_over"):
            summary = sg_state.get("summary", {})
            challenger_score = summary.get("player_score", 0)
        else:
            state = run.get("state")
            if state:
                sd = state.to_dict() if hasattr(state, "to_dict") else state
                challenger_score = sd.get("mento_score", 0) or sd.get("score", 0)

        challenge_id = str(uuid.uuid4())[:8]
        challenges = _load_challenges()
        challenges[challenge_id] = {
            "id": challenge_id,
            "challenger_id": user_payload["user_id"],
            "challenger_score": challenger_score,
            "game_id": game_id,
            "game_title": game_data_c.get("title", game_id),
            "game_type": game_data_c.get("game_type", "rounds"),
            "icon": game_data_c.get("icon", "🎮"),
            "message": str(message)[:200],
            "status": "open",
            "created_at": datetime.now().isoformat(),
            "expires_at": (datetime.now() + timedelta(hours=int(data.get("expiry_hours", 48)))).isoformat(),
            "acceptances": [],
        }
        _save_challenges(challenges)

        return jsonify({"challenge_id": challenge_id, "challenge": challenges[challenge_id]})

@app.get("/api/challenge/<challenge_id>")
def get_challenge(challenge_id):
    """Get challenge details."""
    challenges = _load_challenges()
    c = challenges.get(challenge_id)
    if not c:
        return jsonify({"error": "Challenge not found"}), 404
    return jsonify(c)

@app.post("/api/challenge/<challenge_id>/accept")
def accept_challenge(challenge_id):
    """Accept a challenge — record the acceptor's run_id and score."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    data = request.get_json(silent=True) or {}
    run_id = data.get("run_id")

    challenges = _load_challenges()
    c = challenges.get(challenge_id)
    if not c:
        return jsonify({"error": "Challenge not found"}), 404

    if c["status"] == "expired":
        return jsonify({"error": "Challenge has expired"}), 400

    # Check expiry
    if datetime.now().isoformat() > c.get("expires_at", ""):
        c["status"] = "expired"
        _save_challenges(challenges)
        return jsonify({"error": "Challenge has expired"}), 400

    user_id = user_payload["user_id"]
    if user_id == c["challenger_id"]:
        return jsonify({"error": "Cannot accept your own challenge"}), 400

    # Get acceptor's score
    acceptor_score = 0
    if run_id:
        run = storage.get_run(run_id)
        if run:
            sg_state = run.get("sg_state")
            if sg_state and sg_state.get("game_over"):
                summary = sg_state.get("summary", {})
                acceptor_score = summary.get("player_score", 0)
            else:
                state = run.get("state")
                if state:
                    sd = state.to_dict() if hasattr(state, "to_dict") else state
                    acceptor_score = sd.get("mento_score", 0) or sd.get("score", 0)

    acceptance = {
        "user_id": user_id,
        "run_id": run_id,
        "score": acceptor_score,
        "accepted_at": datetime.now().isoformat(),
        "won": acceptor_score > c["challenger_score"],
    }
    c.setdefault("acceptances", []).append(acceptance)
    _save_challenges(challenges)

    return jsonify({
        "result": acceptance,
        "challenger_score": c["challenger_score"],
        "you_won": acceptance["won"],
    })

@app.post("/api/challenge/<challenge_id>/result")
def submit_challenge_result(challenge_id):
    """Submit result for a challenge after completing the game."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    data = request.get_json(silent=True) or {}
    score = data.get("score", 0)

    challenges = _load_challenges()
    c = challenges.get(challenge_id)
    if not c:
        return jsonify({"error": "Challenge not found"}), 404

    user_id = user_payload["user_id"]
    won = score > c["challenger_score"]

    result_entry = {
        "user_id": user_id,
        "score": score,
        "completed_at": datetime.now().isoformat(),
        "won": won,
    }
    c.setdefault("acceptances", []).append(result_entry)
    _save_challenges(challenges)

    return jsonify({
        "result": result_entry,
        "challenger_score": c["challenger_score"],
        "you_won": won,
    })

@app.get("/api/challenges")
def list_challenges():
    """List open challenges for the current user."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    user_id = user_payload["user_id"]
    challenges = _load_challenges()
    now = datetime.now().isoformat()

    my_challenges = []
    open_challenges = []
    completed = []

    for cid, c in challenges.items():
        if c.get("status") == "open" and now > c.get("expires_at", ""):
            c["status"] = "expired"

        accepted_by_me = any(a["user_id"] == user_id for a in c.get("acceptances", []))

        if c["challenger_id"] == user_id:
            my_challenges.append(c)
        elif c["status"] == "open" and not accepted_by_me:
            open_challenges.append(c)
        elif accepted_by_me:
            completed.append(c)

    _save_challenges(challenges)

    return jsonify({
        "my_challenges": sorted(my_challenges, key=lambda x: x["created_at"], reverse=True)[:20],
        "open_challenges": sorted(open_challenges, key=lambda x: x["created_at"], reverse=True)[:20],
        "completed": sorted(completed, key=lambda x: x["created_at"], reverse=True)[:20],
    })


# ── Campaign Mode Endpoints ──────────────────────────────────────────

CAMPAIGNS_DIR = os.path.join(os.path.dirname(__file__), "campaigns")
CAMPAIGN_PROGRESS_FILE = os.path.join(os.path.dirname(__file__), "game_sessions", "campaign_progress.json")

def _load_all_campaigns():
    """Load all campaign JSON files from the campaigns directory."""
    campaigns = []
    if not os.path.isdir(CAMPAIGNS_DIR):
        return campaigns
    for fname in os.listdir(CAMPAIGNS_DIR):
        if fname.endswith(".json"):
            try:
                with open(os.path.join(CAMPAIGNS_DIR, fname), "r") as f:
                    campaigns.append(json.load(f))
            except (json.JSONDecodeError, IOError):
                continue
    return campaigns

def _load_campaign_progress():
    try:
        with open(CAMPAIGN_PROGRESS_FILE, "r") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def _save_campaign_progress(data):
    os.makedirs(os.path.dirname(CAMPAIGN_PROGRESS_FILE), exist_ok=True)
    with open(CAMPAIGN_PROGRESS_FILE, "w") as f:
        json.dump(data, f, indent=2, default=str)

def _get_user_campaign_progress(user_id, campaign_id):
    """Get a user's progress for a specific campaign."""
    all_progress = _load_campaign_progress()
    user_prog = all_progress.get(user_id, {})
    return user_prog.get(campaign_id, {"completed_games": [], "completed_chapters": [], "rewards_claimed": []})

def _is_chapter_unlocked(chapter, user_progress):
    """Check if a chapter is unlocked based on its unlock_condition and user progress."""
    cond = chapter.get("unlock_condition")
    if not cond:
        return True
    req_chapter = cond.get("chapter")
    req_games = cond.get("games_completed", 1)
    if not req_chapter:
        return True
    completed_games = user_progress.get("completed_games", [])
    # Count how many games from the prerequisite chapter have been completed
    # We need the campaign data to check this properly, so we use a simple approach:
    # check if the prerequisite chapter is in completed_chapters
    return req_chapter in user_progress.get("completed_chapters", [])

@app.get("/api/campaigns")
def list_campaigns():
    """List all campaigns with user progress."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    user_id = user_payload["user_id"] if user_payload else None

    campaigns = _load_all_campaigns()
    result = []
    for camp in campaigns:
        camp_data = {
            "id": camp["id"],
            "title": camp["title"],
            "description": camp["description"],
            "icon": camp.get("icon", "🗺️"),
            "theme_color": camp.get("theme_color", "#6366F1"),
            "chapter_count": len(camp.get("chapters", [])),
        }
        if user_id:
            progress = _get_user_campaign_progress(user_id, camp["id"])
            camp_data["completed_chapters"] = len(progress.get("completed_chapters", []))
            camp_data["completed_games"] = len(progress.get("completed_games", []))
        result.append(camp_data)
    return jsonify({"campaigns": result})

@app.get("/api/campaigns/<campaign_id>")
def get_campaign(campaign_id):
    """Get full campaign details with chapter progress."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    user_id = user_payload["user_id"] if user_payload else None

    campaigns = _load_all_campaigns()
    campaign = next((c for c in campaigns if c["id"] == campaign_id), None)
    if not campaign:
        return jsonify({"error": "Campaign not found"}), 404

    progress = _get_user_campaign_progress(user_id, campaign_id) if user_id else {}
    completed_games = progress.get("completed_games", [])
    completed_chapters = progress.get("completed_chapters", [])
    rewards_claimed = progress.get("rewards_claimed", [])

    # Enrich chapters with progress and game info
    load_bundle()
    enriched_chapters = []
    for chapter in campaign.get("chapters", []):
        ch_games = []
        ch_completed_count = 0
        for g in chapter.get("games", []):
            game_id = g["game_id"]
            game_data = GAMES.get(game_id, {})
            game_completed = game_id in completed_games
            if game_completed:
                ch_completed_count += 1
            ch_games.append({
                "game_id": game_id,
                "title": game_data.get("title", game_id),
                "icon": game_data.get("icon", "🎮"),
                "game_type": game_data.get("game_type", "rounds"),
                "required": g.get("required", False),
                "min_score": g.get("min_score", 0),
                "completed": game_completed,
            })

        unlocked = _is_chapter_unlocked(chapter, progress)
        ch_is_completed = chapter["id"] in completed_chapters

        # Check if all required games are done
        required_games = [g for g in chapter.get("games", []) if g.get("required")]
        all_required_done = all(g["game_id"] in completed_games for g in required_games) if required_games else ch_completed_count > 0

        enriched_chapters.append({
            "id": chapter["id"],
            "title": chapter["title"],
            "description": chapter.get("description", ""),
            "icon": chapter.get("icon", "📖"),
            "unlocked": unlocked,
            "completed": ch_is_completed,
            "all_required_done": all_required_done,
            "rewards": chapter.get("rewards", {}),
            "rewards_claimed": chapter["id"] in rewards_claimed,
            "games": ch_games,
            "completed_count": ch_completed_count,
            "total_count": len(ch_games),
        })

    return jsonify({
        "campaign": {
            "id": campaign["id"],
            "title": campaign["title"],
            "description": campaign["description"],
            "icon": campaign.get("icon", "🗺️"),
            "theme_color": campaign.get("theme_color", "#6366F1"),
            "chapters": enriched_chapters,
        }
    })

@app.post("/api/campaigns/<campaign_id>/complete-game")
def campaign_complete_game(campaign_id):
    """Mark a game as completed within a campaign and check chapter completion."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    user_id = user_payload["user_id"]
    data = request.get_json(silent=True) or {}
    game_id = data.get("game_id")
    score = data.get("score", 0)

    if not game_id:
        return jsonify({"error": "game_id required"}), 400

    campaigns = _load_all_campaigns()
    campaign = next((c for c in campaigns if c["id"] == campaign_id), None)
    if not campaign:
        return jsonify({"error": "Campaign not found"}), 404

    all_progress = _load_campaign_progress()
    user_prog = all_progress.setdefault(user_id, {})
    camp_prog = user_prog.setdefault(campaign_id, {"completed_games": [], "completed_chapters": [], "rewards_claimed": []})

    # Check min_score requirement
    for chapter in campaign.get("chapters", []):
        for g in chapter.get("games", []):
            if g["game_id"] == game_id:
                if score < g.get("min_score", 0):
                    return jsonify({"error": f"Score {score} below minimum {g['min_score']}", "success": False}), 400

    # Mark game as completed
    if game_id not in camp_prog["completed_games"]:
        camp_prog["completed_games"].append(game_id)

    # Check for chapter completions
    newly_completed_chapters = []
    rewards_earned = {}
    for chapter in campaign.get("chapters", []):
        if chapter["id"] in camp_prog["completed_chapters"]:
            continue
        required_games = [g for g in chapter.get("games", []) if g.get("required")]
        if required_games:
            all_done = all(g["game_id"] in camp_prog["completed_games"] for g in required_games)
        else:
            all_done = any(g["game_id"] in camp_prog["completed_games"] for g in chapter.get("games", []))

        if all_done:
            camp_prog["completed_chapters"].append(chapter["id"])
            newly_completed_chapters.append(chapter["id"])
            rewards = chapter.get("rewards", {})
            if rewards and chapter["id"] not in camp_prog["rewards_claimed"]:
                camp_prog["rewards_claimed"].append(chapter["id"])
                rewards_earned[chapter["id"]] = rewards
                # Award XP and coins
                import player_profile
                if rewards.get("xp"):
                    player_profile.award_xp(user_id, rewards["xp"])
                if rewards.get("coins"):
                    from wallet_engine import WalletEngine
                    we = WalletEngine()
                    we.credit(user_id, rewards["coins"], f"Campaign reward: {chapter['title']}")

    _save_campaign_progress(all_progress)

    return jsonify({
        "success": True,
        "game_id": game_id,
        "newly_completed_chapters": newly_completed_chapters,
        "rewards_earned": rewards_earned,
    })


