@app.post("/api/admin/learning-paths")
@require_admin
def admin_create_learning_path():
    """Create a new learning path."""
    paths_file = os.path.join(os.path.dirname(__file__), "data", "learning_paths.json")
    body = request.get_json(silent=True) or {}
    if not body.get("title"):
        return jsonify({"error": "title is required"}), 400
    try:
        with open(paths_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except FileNotFoundError:
        data = {"paths": []}
    import uuid as _uuid
    new_path = {
        "id": body.get("id") or _uuid.uuid4().hex[:8],
        "title": body["title"],
        "description": body.get("description", ""),
        "target_skills": body.get("target_skills", []),
        "games": body.get("games", []),
        "difficulty": body.get("difficulty", "intermediate"),
        "duration_weeks": body.get("duration_weeks", 4),
    }
    data.setdefault("paths", []).append(new_path)
    with open(paths_file, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    return jsonify(new_path), 201


@app.put("/api/admin/learning-paths/<path_id>")
@require_admin
def admin_update_learning_path(path_id):
    """Update an existing learning path."""
    paths_file = os.path.join(os.path.dirname(__file__), "data", "learning_paths.json")
    body = request.get_json(silent=True) or {}
    try:
        with open(paths_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except FileNotFoundError:
        return jsonify({"error": "No learning paths configured"}), 404
    for i, p in enumerate(data.get("paths", [])):
        if p.get("id") == path_id:
            data["paths"][i].update(body)
            data["paths"][i]["id"] = path_id
            with open(paths_file, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            return jsonify(data["paths"][i])
    return jsonify({"error": "Path not found"}), 404


@app.delete("/api/admin/learning-paths/<path_id>")
@require_admin
def admin_delete_learning_path(path_id):
    """Delete a learning path."""
    paths_file = os.path.join(os.path.dirname(__file__), "data", "learning_paths.json")
    try:
        with open(paths_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except FileNotFoundError:
        return jsonify({"error": "No learning paths configured"}), 404
    original_count = len(data.get("paths", []))
    data["paths"] = [p for p in data.get("paths", []) if p.get("id") != path_id]
    if len(data["paths"]) == original_count:
        return jsonify({"error": "Path not found"}), 404
    with open(paths_file, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    return jsonify({"deleted": path_id})


