# ============================================================
# ADMIN: Cohort / Class Management
# ============================================================

def _load_cohorts():
    cohorts_file = os.path.join(os.path.dirname(__file__), "data", "cohorts.json")
    try:
        with open(cohorts_file, "r", encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        return {"cohorts": []}


def _save_cohorts(data):
    cohorts_file = os.path.join(os.path.dirname(__file__), "data", "cohorts.json")
    with open(cohorts_file, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)


def _caller_org_id():
    """Return org_id from the current request's JWT, or None if admin (no filter)."""
    caller = getattr(request, "current_user", {})
    if caller.get("role") == "school_admin":
        return caller.get("org_id", "default")
    return None  # admin sees all


def _cohort_belongs_to_caller(cohort):
    """True if caller is admin OR cohort's org_id matches caller's org."""
    oid = _caller_org_id()
    if oid is None:
        return True
    return cohort.get("org_id", "default") == oid


@app.get("/api/admin/cohorts")
@require_admin_or_school_admin
def admin_list_cohorts():
    data = _load_cohorts()
    cohorts = data.get("cohorts", [])
    oid = _caller_org_id()
    if oid:
        cohorts = [c for c in cohorts if c.get("org_id", "default") == oid]
    return jsonify({"cohorts": cohorts})


@app.post("/api/admin/cohorts")
@require_admin_or_school_admin
def admin_create_cohort():
    body = request.get_json(silent=True) or {}
    if not body.get("name"):
        return jsonify({"error": "name is required"}), 400
    import uuid as _uuid
    data = _load_cohorts()
    caller_oid = _caller_org_id() or body.get("org_id", "default")
    cohort = {
        "id": _uuid.uuid4().hex[:8],
        "name": body["name"],
        "description": body.get("description", ""),
        "students": [],
        "assigned_paths": [],
        "org_id": caller_oid,
        "created_at": __import__("datetime").datetime.utcnow().isoformat(),
    }
    data.setdefault("cohorts", []).append(cohort)
    _save_cohorts(data)
    return jsonify(cohort), 201


@app.put("/api/admin/cohorts/<cohort_id>")
@require_admin_or_school_admin
def admin_update_cohort(cohort_id):
    body = request.get_json(silent=True) or {}
    data = _load_cohorts()
    for i, c in enumerate(data.get("cohorts", [])):
        if c.get("id") == cohort_id:
            if not _cohort_belongs_to_caller(c):
                return jsonify({"error": "Access denied"}), 403
            data["cohorts"][i].update({k: v for k, v in body.items() if k not in ("id", "students", "assigned_paths", "org_id")})
            _save_cohorts(data)
            return jsonify(data["cohorts"][i])
    return jsonify({"error": "Cohort not found"}), 404


@app.delete("/api/admin/cohorts/<cohort_id>")
@require_admin_or_school_admin
def admin_delete_cohort(cohort_id):
    data = _load_cohorts()
    cohort = next((c for c in data.get("cohorts", []) if c.get("id") == cohort_id), None)
    if not cohort:
        return jsonify({"error": "Cohort not found"}), 404
    if not _cohort_belongs_to_caller(cohort):
        return jsonify({"error": "Access denied"}), 403
    data["cohorts"] = [c for c in data["cohorts"] if c.get("id") != cohort_id]
    _save_cohorts(data)
    return jsonify({"deleted": cohort_id})


@app.post("/api/admin/cohorts/<cohort_id>/students")
@require_admin_or_school_admin
def admin_add_student_to_cohort(cohort_id):
    body = request.get_json(silent=True) or {}
    user_id = body.get("user_id") or body.get("uid")
    if not user_id:
        return jsonify({"error": "user_id required"}), 400
    data = _load_cohorts()
    for i, c in enumerate(data.get("cohorts", [])):
        if c.get("id") == cohort_id:
            if not _cohort_belongs_to_caller(c):
                return jsonify({"error": "Access denied"}), 403
            students = data["cohorts"][i].setdefault("students", [])
            if user_id not in students:
                students.append(user_id)
            _save_cohorts(data)
            return jsonify(data["cohorts"][i])
    return jsonify({"error": "Cohort not found"}), 404


@app.delete("/api/admin/cohorts/<cohort_id>/students/<uid>")
@require_admin_or_school_admin
def admin_remove_student_from_cohort(cohort_id, uid):
    data = _load_cohorts()
    for i, c in enumerate(data.get("cohorts", [])):
        if c.get("id") == cohort_id:
            if not _cohort_belongs_to_caller(c):
                return jsonify({"error": "Access denied"}), 403
            data["cohorts"][i]["students"] = [s for s in c.get("students", []) if s != uid]
            _save_cohorts(data)
            return jsonify(data["cohorts"][i])
    return jsonify({"error": "Cohort not found"}), 404


@app.post("/api/admin/cohorts/<cohort_id>/assign-path")
@require_admin_or_school_admin
def admin_assign_path_to_cohort(cohort_id):
    body = request.get_json(silent=True) or {}
    path_id = body.get("path_id")
    if not path_id:
        return jsonify({"error": "path_id required"}), 400
    data = _load_cohorts()
    for i, c in enumerate(data.get("cohorts", [])):
        if c.get("id") == cohort_id:
            if not _cohort_belongs_to_caller(c):
                return jsonify({"error": "Access denied"}), 403
            assigned = data["cohorts"][i].setdefault("assigned_paths", [])
            entry = {"path_id": path_id, "deadline": body.get("deadline"), "assigned_at": __import__("datetime").datetime.utcnow().isoformat()}
            existing_ids = [x.get("path_id") for x in assigned]
            if path_id not in existing_ids:
                assigned.append(entry)
            _save_cohorts(data)
            return jsonify(data["cohorts"][i])
    return jsonify({"error": "Cohort not found"}), 404


@app.get("/api/admin/cohorts/<cohort_id>/progress")
@require_admin_or_school_admin
def admin_cohort_progress(cohort_id):
    data = _load_cohorts()
    cohort = next((c for c in data.get("cohorts", []) if c.get("id") == cohort_id), None)
    if not cohort:
        return jsonify({"error": "Cohort not found"}), 404
    if not _cohort_belongs_to_caller(cohort):
        return jsonify({"error": "Access denied"}), 403
    students = cohort.get("students", [])
    progress_list = []
    users_file = os.path.join(os.path.dirname(__file__), "data", "users.json")
    try:
        with open(users_file, "r", encoding="utf-8") as f:
            users_data = json.load(f)
        all_users = {u.get("id"): u for u in users_data.get("users", [])}
    except Exception:
        all_users = {}
    for uid in students:
        user = all_users.get(uid, {})
        progress_list.append({
            "user_id": uid,
            "name": user.get("name", uid),
            "email": user.get("email", ""),
            "games_played": user.get("games_played", 0),
            "xp": user.get("xp", 0),
        })
    return jsonify({"cohort_id": cohort_id, "students": progress_list, "total": len(students)})


@app.get("/api/admin/cohorts/<cohort_id>/export-csv")
@require_admin_or_school_admin
def admin_cohort_export_csv(cohort_id):
    """Export cohort student data as CSV with dynamic dimension columns."""
    import csv
    import io
    data = _load_cohorts()
    cohort = next((c for c in data.get("cohorts", []) if c.get("id") == cohort_id), None)
    if not cohort:
        return jsonify({"error": "Cohort not found"}), 404
    if not _cohort_belongs_to_caller(cohort):
        return jsonify({"error": "Access denied"}), 403
    students = cohort.get("students", [])

    # Collect all profiles + union of all dimension keys
    profiles = []
    all_dim_keys: set = set()
    for uid in students:
        try:
            p = player_profile.get_profile(uid)
            dim_scores = p.get("dimension_scores", {})
            all_dim_keys.update(dim_scores.keys())
            profiles.append((uid, p))
        except Exception:
            profiles.append((uid, {}))

    dim_keys = sorted(all_dim_keys)
    base_fields = ["username", "games_completed", "xp", "streak_days"]
    fieldnames = base_fields + dim_keys

    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames)
    writer.writeheader()
    for uid, p in profiles:
        dim_scores = p.get("dimension_scores", {})
        row = {
            "username": uid,
            "games_completed": p.get("games_completed", 0),
            "xp": p.get("xp", 0),
            "streak_days": p.get("streak_days", 0),
        }
        for dk in dim_keys:
            row[dk] = dim_scores.get(dk, "")
        writer.writerow(row)

    csv_bytes = output.getvalue().encode("utf-8")
    from flask import Response
    filename = f"cohort_{cohort_id}_{cohort.get('name', 'export').replace(' ', '_')}.csv"
    return Response(
        csv_bytes,
        mimetype="text/csv",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )


@app.get("/api/admin/cohorts/<cohort_id>/efficacy")
@require_admin_or_school_admin
def admin_cohort_efficacy(cohort_id):
    """Return longitudinal dimension score data for a cohort (used for efficacy chart)."""
    data = _load_cohorts()
    cohort = next((c for c in data.get("cohorts", []) if c.get("id") == cohort_id), None)
    if not cohort:
        return jsonify({"error": "Cohort not found"}), 404
    if not _cohort_belongs_to_caller(cohort):
        return jsonify({"error": "Access denied"}), 403

    students = cohort.get("students", [])
    # Collect all skill_history entries across students
    all_entries = []  # list of {timestamp, scores: {dim: val}}
    baseline_totals = {}  # dim -> [val]
    current_totals = {}   # dim -> [val]
    has_baseline_count = 0

    for uid in students:
        try:
            p = player_profile.get_profile(uid)
            hist = player_profile.get_skill_history(uid).get("skill_history", [])
            baseline = p.get("baseline_scores")
            current = p.get("dimension_scores", {})
            if baseline:
                has_baseline_count += 1
                for dim, val in baseline.items():
                    baseline_totals.setdefault(dim, []).append(val)
            for dim, val in current.items():
                current_totals.setdefault(dim, []).append(val)
            for entry in hist:
                all_entries.append(entry)
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    # Aggregate by week (ISO week string)
    from collections import defaultdict
    week_data = defaultdict(lambda: defaultdict(list))
    for entry in all_entries:
        ts = entry.get("timestamp", "")
        try:
            from datetime import datetime as dt
            d = dt.fromisoformat(ts[:10])
            week_key = d.strftime("%Y-W%V")
        except Exception:
            continue
        for dim, val in entry.get("scores", {}).items():
            if isinstance(val, (int, float)):
                week_data[week_key][dim].append(val)

    # Build sorted weekly trend
    trend = []
    for week in sorted(week_data.keys()):
        point = {"week": week}
        for dim, vals in week_data[week].items():
            point[dim] = round(sum(vals) / len(vals), 1)
        trend.append(point)

    # Build avg baseline and current
    avg_baseline = {dim: round(sum(v) / len(v), 1) for dim, v in baseline_totals.items() if v}
    avg_current = {dim: round(sum(v) / len(v), 1) for dim, v in current_totals.items() if v}
    improvement = {}
    for dim in avg_current:
        if dim in avg_baseline:
            improvement[dim] = round(avg_current[dim] - avg_baseline[dim], 1)

    return jsonify({
        "cohort_id": cohort_id,
        "cohort_name": cohort.get("name", ""),
        "student_count": len(students),
        "has_baseline_count": has_baseline_count,
        "trend": trend,
        "avg_baseline": avg_baseline,
        "avg_current": avg_current,
        "improvement": improvement,
    }), 200


