@require_admin
def api_get_prompt_config():
    """Get custom extra-rules for each AI agent type."""
    import os as _os, json as _json
    cfg_path = _os.path.join(_os.path.dirname(__file__), "data", "prompt_config.json")
    default = {
        "mento_coach": {"extra_rules": ""},
        "story_narrator": {"extra_rules": ""},
        "debate_coach": {"extra_rules": ""},
        "coaching_tips": {"extra_rules": ""},
    }
    if _os.path.exists(cfg_path):
        try:
            with open(cfg_path) as f:
                saved = _json.load(f)
            # Merge with defaults so new keys always present
            for k, v in default.items():
                if k not in saved:
                    saved[k] = v
            return jsonify(saved), 200
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    return jsonify(default), 200


