def _require_teacher_or_admin(f):
    """Decorator: allow teacher or admin roles."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        token = get_token_from_request()
        if not token:
            return jsonify({"error": "Authentication required"}), 401
        payload = verify_token(token)
        if not payload:
            return jsonify({"error": "Invalid or expired token"}), 401
        if payload.get("role") not in ("admin", "teacher"):
            return jsonify({"error": "Teacher access required"}), 403
        request.current_user = payload
        return f(*args, **kwargs)
    return decorated


def _require_trainer_or_admin(f):
    """Decorator: allow trainer or admin roles (designer tools)."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        token = get_token_from_request()
        payload = verify_token(token) if token else None
        if not payload:
            return jsonify({"error": "Authentication required"}), 401
        if payload.get("role") not in ("admin", "trainer"):
            return jsonify({"error": "Trainer access required"}), 403
        request.current_user = payload
        return f(*args, **kwargs)
    return decorated


def _require_assessor(f):
    """Decorator: allow hr, trainer, or admin roles (assessment manager tools)."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        token = get_token_from_request()
        payload = verify_token(token) if token else None
        if not payload:
            return jsonify({"error": "Authentication required"}), 401
        if payload.get("role") not in ("admin", "trainer", "hr"):
            return jsonify({"error": "Assessment manager access required"}), 403
        request.current_user = payload
        return f(*args, **kwargs)
    return decorated


def _require_school_admin_or_admin(f):
    """Decorator: allow school_admin (own org) or admin (all)."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        token = get_token_from_request()
        payload = verify_token(token) if token else None
        if not payload:
            return jsonify({"error": "Authentication required"}), 401
        if payload.get("role") not in ("admin", "school_admin"):
            return jsonify({"error": "School admin access required"}), 403
        request.current_user = payload
        return f(*args, **kwargs)
    return decorated


_ASSIGNMENTS_FILE = os.path.join(os.path.dirname(__file__), "data", "assignments.json")


def _load_assignments():
    if os.path.exists(_ASSIGNMENTS_FILE):
        try:
            with open(_ASSIGNMENTS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            # Handle both list format and {"assignments": [...]} dict format
            if isinstance(data, list):
                return data
            if isinstance(data, dict):
                return data.get("assignments", [])
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    return []


def _save_assignments(data):
    os.makedirs(os.path.dirname(_ASSIGNMENTS_FILE), exist_ok=True)
    with open(_ASSIGNMENTS_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)


