@app.post("/api/teacher/assignments")
@_require_teacher_or_admin
def teacher_create_assignment():
    """Assign a game to a cohort with an optional due date."""
    data = request.get_json(silent=True) or {}
    cohort_id = data.get("cohort_id")
    game_id = data.get("game_id")
    title = data.get("title", game_id)
    due_date = data.get("due_date")
    user = request.current_user
    if not cohort_id or not game_id:
        return jsonify({"error": "cohort_id and game_id required"}), 400
    import uuid, time
    assignments = _load_assignments()
    new_assignment = {
        "id": str(uuid.uuid4())[:8],
        "cohort_id": cohort_id,
        "game_id": game_id,
        "title": title,
        "due_date": due_date,
        "teacher_id": user.get("user_id"),
        "created_at": int(time.time()),
        "is_weekly_challenge": data.get("is_weekly_challenge", False),
        "mode": data.get("mode", "solo"),  # "solo" | "paired" | "squad"
    }
    assignments.append(new_assignment)
    _save_assignments(assignments)
    return jsonify({"assignment": new_assignment, "created": True})


