@app.post("/api/admin/cohorts/<cohort_id>/pair-students")
@_require_teacher_or_admin
def cohort_pair_students(cohort_id):
    """Auto-create multiplayer matches between student pairs in a cohort."""
    try:
        from engines.multiplayer_engine import MultiplayerEngine
        mp_engine = MultiplayerEngine()
    except Exception:
        return jsonify({"error": "Multiplayer engine not available"}), 500

    data = request.get_json(silent=True) or {}
    game_id = data.get("game_id", "")
    mode = data.get("mode", "paired")  # "paired" = groups of 2, "squad" = groups of 3-4
    if not game_id:
        return jsonify({"error": "game_id required"}), 400

    cohort_data = _load_cohorts()
    cohort = next((c for c in cohort_data.get("cohorts", []) if c.get("id") == cohort_id), None)
    if not cohort:
        return jsonify({"error": "Cohort not found"}), 404

    students = cohort.get("students", [])
    if len(students) < 2:
        return jsonify({"error": "At least 2 students required for paired play"}), 400

    group_size = 2 if mode == "paired" else 3
    pairs = []
    import uuid as _uuid
    try:
        for i in range(0, len(students) - 1, group_size):
            group = students[i:i + group_size]
            if len(group) < 2:
                continue
            creator_id = str(group[0])
            match_result = mp_engine.create_match(game_id, creator_id)
            match_id = match_result.get("match_id")
            if not match_id:
                continue
            for student_id in group[1:]:
                try:
                    mp_engine.join_match(match_id, str(student_id))
                except Exception as _e:
                    logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
            pairs.append({"match_id": match_id, "players": [str(s) for s in group]})
    except Exception as e:
        logger.error(f"Pair students error: {e}")
        return jsonify({"error": str(e)}), 500

    return jsonify({"pairs": pairs, "cohort_id": cohort_id, "game_id": game_id})


@app.get("/api/student/cohort-matches")
@require_auth
def student_cohort_matches():
    """Return multiplayer matches created for the student's cohort games."""
    try:
        from engines.multiplayer_engine import MultiplayerEngine
        mp_engine = MultiplayerEngine()
    except Exception:
        return jsonify({"matches": []})

    user = request.current_user
    user_id = str(user.get("user_id", ""))

    try:
        # Get all matches and filter to ones the user is a player in
        all_matches = mp_engine.list_available_matches()
        if isinstance(all_matches, dict):
            all_matches = all_matches.get("matches", [])
        my_matches = [
            m for m in all_matches
            if user_id in [str(p) for p in m.get("players", [])]
            and m.get("status") in ("waiting", "in_progress")
        ]
        return jsonify({"matches": my_matches})
    except Exception as e:
        return jsonify({"matches": [], "error": str(e)})


