# ADMIN: Automated Playtesting
# ============================================================

_playtest_jobs = {}

@app.post("/api/admin/playtesting/run")
@require_admin
def admin_playtesting_run():
    """Start a playtesting simulation."""
    body = request.get_json(silent=True) or {}
    game_id = body.get("game_id")
    num_runs = min(int(body.get("num_runs", 5)), 20)
    if not game_id:
        return jsonify({"error": "game_id required"}), 400
    import uuid as _uuid, threading
    job_id = _uuid.uuid4().hex[:8]
    _playtest_jobs[job_id] = {"status": "running", "game_id": game_id, "started_at": __import__("datetime").datetime.utcnow().isoformat()}
    def _run():
        try:
            game = next((g for g in GAMES if g.get("id") == game_id), None)
            if not game:
                _playtest_jobs[job_id] = {"status": "error", "error": "Game not found"}
                return
            from ai.automated_playtesting import AutomatedPlaytester
            tester = AutomatedPlaytester()
            result = tester.run_full_playtest(game, num_runs=num_runs)
            _playtest_jobs[job_id] = {"status": "complete", "result": result, "game_id": game_id}
        except Exception as e:
            _playtest_jobs[job_id] = {"status": "error", "error": str(e)}
    threading.Thread(target=_run, daemon=True).start()
    return jsonify({"job_id": job_id, "status": "running"})


@app.get("/api/admin/playtesting/report/<job_id>")
@require_admin
def admin_playtesting_report(job_id):
    """Get playtesting simulation results."""
    job = _playtest_jobs.get(job_id)
    if not job:
        return jsonify({"error": "Job not found"}), 404
    return jsonify(job)


