@app.get("/api/admin/assets")
@require_admin
def admin_list_assets():
    """List uploaded assets."""
    uploads_dir = os.path.join(os.path.dirname(__file__), "uploads")
    assets = []
    if os.path.exists(uploads_dir):
        for root, dirs, files in os.walk(uploads_dir):
            for fname in files:
                fpath = os.path.join(root, fname)
                rel = os.path.relpath(fpath, uploads_dir)
                stat = os.stat(fpath)
                assets.append({
                    "filename": fname,
                    "path": rel.replace("\\", "/"),
                    "size": stat.st_size,
                    "modified": __import__("datetime").datetime.fromtimestamp(stat.st_mtime).isoformat(),
                    "category": os.path.dirname(rel).replace("\\", "/") or "root",
                })
    return jsonify({"assets": assets, "total": len(assets)})


@app.get("/api/admin/assets/stats")
@require_admin
def admin_assets_stats():
    """Get asset stats by category."""
    uploads_dir = os.path.join(os.path.dirname(__file__), "uploads")
    stats = {}
    if os.path.exists(uploads_dir):
        for root, dirs, files in os.walk(uploads_dir):
            for fname in files:
                fpath = os.path.join(root, fname)
                rel = os.path.relpath(fpath, uploads_dir)
                cat = os.path.dirname(rel).replace("\\", "/") or "root"
                s = stats.setdefault(cat, {"count": 0, "total_size": 0})
                s["count"] += 1
                s["total_size"] += os.path.getsize(fpath)
    return jsonify({"stats": stats})


@app.delete("/api/admin/assets/<path:filename>")
@require_admin
def admin_delete_asset(filename):
    """Delete an uploaded asset."""
    uploads_dir = os.path.join(os.path.dirname(__file__), "uploads")
    safe_path = os.path.normpath(os.path.join(uploads_dir, filename))
    if not safe_path.startswith(os.path.abspath(uploads_dir)):
        return jsonify({"error": "Invalid path"}), 400
    if not os.path.exists(safe_path):
        return jsonify({"error": "File not found"}), 404
    os.remove(safe_path)
    return jsonify({"deleted": filename})


@app.post("/api/admin/assets/generate-visual")
@require_admin
def admin_generate_visual():
    """Generate a visual asset using DALL-E 3."""
    body = request.get_json(silent=True) or {}
    prompt = body.get("prompt", "")
    if not prompt:
        return jsonify({"error": "prompt required"}), 400
    try:
        from llm import _client, llm_enabled, MODEL
        if not llm_enabled():
            return jsonify({"error": "LLM not enabled"}), 503
        client = _client()
        resp = client.images.generate(
            model="dall-e-3",
            prompt=prompt[:1000],
            size="1024x1024",
            quality="standard",
            n=1,
        )
        url = resp.data[0].url
        return jsonify({"url": url, "prompt": prompt})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.post("/api/admin/assets/optimize")
@require_admin
def admin_assets_optimize():
    """Scan and report unused assets."""
    uploads_dir = os.path.join(os.path.dirname(__file__), "uploads")
    all_files = []
    if os.path.exists(uploads_dir):
        for root, dirs, files in os.walk(uploads_dir):
            for fname in files:
                fpath = os.path.join(root, fname)
                rel = os.path.relpath(fpath, uploads_dir).replace("\\", "/")
                all_files.append(rel)
    return jsonify({"total_files": len(all_files), "files": all_files, "message": "Manual review recommended before deletion"})


