_BUILDER_DATA_FILE = os.path.join(os.path.dirname(__file__), "data", "builder_sessions.json")
_BUILDER_UPLOAD_DIR = os.path.join(os.path.dirname(__file__), "uploads", "builder")
os.makedirs(_BUILDER_UPLOAD_DIR, exist_ok=True)

BUILDER_ALLOWED_EXTENSIONS = {".pdf", ".docx", ".doc", ".txt", ".md"}
BUILDER_MAX_FILE_SIZE = 10 * 1024 * 1024  # 10 MB


def _load_builder_sessions():
    try:
        with open(_BUILDER_DATA_FILE) as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def _save_builder_sessions(data):
    with open(_BUILDER_DATA_FILE, "w") as f:
        json.dump(data, f, indent=2, default=str)


def _builder_quality_score(game: dict) -> int:
    """0-100 heuristic quality score for a generated game."""
    score = 0
    SKILL_DIMS = {"strategic_thinking", "risk_tolerance", "delayed_gratification", "adaptability", "resilience", "empathy"}
    dims_seen = set()
    rounds = game.get("rounds", [])
    for rnd in rounds:
        for ch in rnd.get("choices", []):
            delta = ch.get("delta", ch.get("deltas", {}))
            for k in delta:
                if k in SKILL_DIMS:
                    dims_seen.add(k)
    if len(dims_seen) >= 6:
        score += 20
    if len(rounds) >= 7:
        score += 20
    if all(r.get("coaching_moment") for r in rounds):
        score += 20
    if len(game.get("glossary_terms", [])) >= 3:
        score += 20
    if len(game.get("learning_objectives", [])) >= 4:
        score += 20
    return score


@app.post("/api/admin/builder/upload-doc")
@_require_trainer_or_admin
def api_builder_upload_doc():
    """Upload a document (PDF/DOCX/TXT) for the AI Game Builder context."""
    from ai.document_parser import parse_document
    import uuid

    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400

    f = request.files["file"]
    filename = f.filename or "upload"
    ext = os.path.splitext(filename)[1].lower()
    if ext not in BUILDER_ALLOWED_EXTENSIONS:
        return jsonify({"error": f"Unsupported file type: {ext}. Use PDF, DOCX, TXT, or MD."}), 400

    doc_id = str(uuid.uuid4())[:8]
    safe_name = f"{doc_id}_{filename}"
    save_path = os.path.join(_BUILDER_UPLOAD_DIR, safe_name)

    # Check size
    f.seek(0, 2)
    size = f.tell()
    f.seek(0)
    if size > BUILDER_MAX_FILE_SIZE:
        return jsonify({"error": "File too large (max 10 MB)"}), 400

    f.save(save_path)

    parsed = parse_document(save_path)
    user_id = user_payload["user_id"]
    sessions = _load_builder_sessions()
    sessions.setdefault(user_id, {}).setdefault("docs", {})[doc_id] = {
        "doc_id": doc_id,
        "filename": filename,
        "saved_as": safe_name,
        "word_count": parsed["word_count"],
        "preview": parsed["preview"],
        "uploaded_at": datetime.now().isoformat(),
    }
    _save_builder_sessions(sessions)

    return jsonify({
        "doc_id": doc_id,
        "filename": filename,
        "word_count": parsed["word_count"],
        "preview": parsed["preview"],
    })


