@app.delete("/api/admin/builder/doc/<doc_id>")
@_require_trainer_or_admin
def api_builder_delete_doc(doc_id):
    """Delete an uploaded document."""
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401
    sessions = _load_builder_sessions()
    user_docs = sessions.get(user_payload["user_id"], {}).get("docs", {})
    doc = user_docs.pop(doc_id, None)
    if not doc:
        return jsonify({"error": "Document not found"}), 404
    # Remove file
    try:
        os.remove(os.path.join(_BUILDER_UPLOAD_DIR, doc["saved_as"]))
    except FileNotFoundError as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    _save_builder_sessions(sessions)
    return jsonify({"ok": True})


@app.post("/api/admin/builder/generate")
@_require_trainer_or_admin
def api_builder_generate():
    """Generate a full game JSON from prompt + uploaded documents."""
    import uuid
    from llm import generate_full_game_json
    from ai.document_parser import parse_document, pick_relevant_chunks

    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    body = request.json or {}
    prompt = (body.get("prompt") or "").strip()
    if not prompt:
        return jsonify({"error": "prompt is required"}), 400

    game_type = body.get("game_type", "rounds")
    age_group = body.get("age_group", "all")
    difficulty = body.get("difficulty", "medium")
    doc_ids = body.get("doc_ids", [])
    reference_questions = body.get("reference_questions", "")
    learning_goals = body.get("learning_goals", [])
    tone = body.get("tone", "professional")
    card_board_config = body.get("card_board_config", None)

    # Build enriched prompt from documents
    sessions = _load_builder_sessions()
    user_docs = sessions.get(user_payload["user_id"], {}).get("docs", {})
    doc_context_used = []
    context_snippets = []

    for did in doc_ids:
        doc_meta = user_docs.get(did)
        if not doc_meta:
            continue
        saved_path = os.path.join(_BUILDER_UPLOAD_DIR, doc_meta["saved_as"])
        try:
            parsed = parse_document(saved_path)
            top_chunks = pick_relevant_chunks(parsed["chunks"], prompt, max_chunks=5)
            context_snippets.extend(top_chunks)
            doc_context_used.append(doc_meta["filename"])
        except Exception as _e:
            logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

    enriched_prompt = prompt
    if context_snippets:
        context_text = "\n---\n".join(context_snippets[:5])
        enriched_prompt = (
            f"{prompt}\n\n"
            f"Reference material from uploaded documents:\n{context_text}"
        )
    if learning_goals:
        enriched_prompt += f"\n\nLearning goals: {', '.join(learning_goals)}"
    if tone:
        enriched_prompt += f"\n\nTone: {tone}"

    # Generate the game
    game = generate_full_game_json(enriched_prompt, game_type, age_group, difficulty,
                                   card_board_config=card_board_config)

    # Inject reference_questions as reflection_prompt on rounds 3, 6, 9
    if reference_questions:
        rounds = game.get("rounds", [])
        for idx in (2, 5, 8):  # 0-based for rounds 3, 6, 9
            if idx < len(rounds):
                rounds[idx]["reflection_prompt"] = reference_questions

    quality_score = _builder_quality_score(game)

    session_id = str(uuid.uuid4())[:12]
    sessions.setdefault(user_payload["user_id"], {}).setdefault("build_sessions", {})[session_id] = {
        "session_id": session_id,
        "prompt": prompt,
        "game_type": game_type,
        "game": game,
        "quality_score": quality_score,
        "doc_context_used": doc_context_used,
        "created_at": datetime.now().isoformat(),
    }
    _save_builder_sessions(sessions)

    return jsonify({
        "session_id": session_id,
        "game": game,
        "quality_score": quality_score,
        "doc_context_used": doc_context_used,
    })


@app.post("/api/admin/builder/regenerate-round")
@_require_trainer_or_admin
def api_builder_regenerate_round():
    """Regenerate a single round in a builder session."""
    from llm import generate_full_game_json

    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401

    body = request.json or {}
    session_id = body.get("session_id", "")
    round_index = body.get("round_index", 0)
    instruction = (body.get("instruction") or "").strip()

    sessions = _load_builder_sessions()
    build_sessions = sessions.get(user_payload["user_id"], {}).get("build_sessions", {})
    session = build_sessions.get(session_id)
    if not session:
        return jsonify({"error": "Session not found"}), 404

    game = session["game"]
    rounds = game.get("rounds", [])
    if round_index < 0 or round_index >= len(rounds):
        return jsonify({"error": "Invalid round_index"}), 400

    original_round = rounds[round_index]
    regen_prompt = (
        f"Rewrite round {round_index + 1} of a game called '{game.get('title', '')}'. "
        f"Original title: {original_round.get('title', '')}. "
        f"Instruction: {instruction or 'Make it more engaging and realistic'}. "
        f"Keep the same 3-choice structure with skill_tags and delta values. "
        f"Return ONLY the round JSON object."
    )

    try:
        mini_game = generate_full_game_json(regen_prompt, game.get("game_type", "rounds"), num_rounds=1)
        new_rounds = mini_game.get("rounds", [])
        if new_rounds:
            new_round = new_rounds[0]
            new_round["id"] = original_round.get("id", f"round_{round_index + 1}")
            rounds[round_index] = new_round
            game["rounds"] = rounds
            session["game"] = game
            session["quality_score"] = _builder_quality_score(game)
            _save_builder_sessions(sessions)
            return jsonify({"round": new_round, "quality_score": session["quality_score"]})
    except Exception as e:
        logger.debug("Suppressed %s: %s", type(e).__name__, e)

    return jsonify({"error": "Failed to regenerate round"}), 500


