@app.get("/api/admin/voice-games")
@require_admin
def api_get_voice_games():
    """List all games with voice_enabled status for the Audio admin section."""
    load_bundle()
    games = []
    for g in BUNDLE.get("games", []):
        features = g.get("features", {})
        games.append({
            "game_id": g["game_id"],
            "title": g.get("title", ""),
            "game_type": g.get("game_type", ""),
            "description": g.get("description", ""),
            "emoji": g.get("icon", "🎮"),
            "voice_enabled": bool(features.get("voice_enabled")),
            "has_storybook": bool(g.get("storybook_pages")),
            "features": features,
        })
    # Sort: voice-enabled first, then alphabetical
    games.sort(key=lambda g: (not g["voice_enabled"], g["title"].lower()))
    return jsonify({"games": games, "voice_count": sum(1 for g in games if g["voice_enabled"])})


@app.put("/api/admin/voice-games/<game_id>")
@require_admin
def api_toggle_voice_game(game_id):
    """Enable or disable voice narration for a game."""
    body = request.json or {}
    enabled = bool(body.get("voice_enabled", False))
    game_path = os.path.join(GAMES_DIR, f"{game_id}.json")
    if not os.path.exists(game_path):
        return jsonify({"error": f"Game '{game_id}' not found"}), 404
    try:
        with open(game_path, "r", encoding="utf-8") as f:
            game_data = json.load(f)
        game_data.setdefault("features", {})["voice_enabled"] = enabled
        with open(game_path, "w", encoding="utf-8") as f:
            json.dump(game_data, f, indent=2)
        # Invalidate bundle so next load picks up the change
        global BUNDLE
        BUNDLE = {}
        # Validate formulas in game choices
        formula_warnings = []
        try:
            from formula_engine import validate_formula as _vf
            for i, rnd in enumerate(game_data.get("rounds", [])):
                for j, ch in enumerate(rnd.get("choices", [])):
                    for ckey, cval in ch.get("calc", {}).items():
                        if isinstance(cval, str) and any(op in cval for op in ["+", "-", "*", "/", "{"]):
                            vresult = _vf(cval)
                            if not vresult.get("valid"):
                                formula_warnings.append(
                                    f"Round {i+1} choice {j+1} calc.{ckey}: {vresult.get('error')}"
                                )
        except Exception as _fv_err:
            logger.debug("Formula validation skipped: %s", _fv_err)
        response_data = {"game_id": game_id, "voice_enabled": enabled, "updated": True}
        if formula_warnings:
            response_data["formula_warnings"] = formula_warnings
        return jsonify(response_data)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


