@app.get("/api/run/<run_id>/assessment")
@require_auth
def run_assessment(run_id):
    """Generate or retrieve a competency assessment report for a completed run."""
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Resource not found"}), 404
    if r.get("assessment_report"):
        return jsonify(r["assessment_report"])
    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    game = get_effective_game(r, game)
    st_obj = r["state"]
    final_state = state_to_dict(st_obj)
    dimension_scores = final_state.get("dimension_scores", {})
    choices = [
        {"round_id": x.get("round_id", ""), "choice": x.get("choice", {}).get("label", "")}
        for x in r.get("log", [])
    ]
    round_history = r.get("log", [])
    rubric = request.args.get("rubric")
    try:
        from llm import generate_assessment_report as _gen_assessment
        report = _gen_assessment(
            game_title=game.get("title", game_id),
            game_type=game.get("game_type", "rounds"),
            dimension_scores=dimension_scores,
            choices=choices,
            round_history=round_history,
            rubric=rubric,
        )
        r["assessment_report"] = report
        update_run(run_id, r)
        return jsonify(report)
    except Exception as e:
        logger.error(f"Assessment report generation failed: {e}")
        return jsonify({"error": "Assessment generation failed"}), 500


