@app.post("/api/run/<run_id>/generate-round")
@require_auth
def run_generate_round(run_id):
    """Generate a dynamic round when player exhausts all standard rounds."""
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Resource not found"}), 404
    game_id = r["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err
    if not game.get("dynamic_rounds"):
        return jsonify({"error": "dynamic_rounds not enabled for this game"}), 400
    game = get_effective_game(r, game)
    st_obj = r["state"]
    current_state = state_to_dict(st_obj)
    state_keys = list((game.get("initial_state") or {}).keys())
    round_number = len(r.get("log", [])) + 1
    player_summary = None
    try:
        import player_profile as _pp_gr
        tok_gr = get_token_from_request()
        usr_gr = verify_token(tok_gr) if tok_gr else None
        if usr_gr:
            player_summary = _pp_gr.get_adaptive_summary(usr_gr["user_id"])
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)
    try:
        from llm import generate_dynamic_round as _gen_round
        new_round = _gen_round(
            game_title=game.get("title", game_id),
            game_type=game.get("game_type", "rounds"),
            state_keys=state_keys,
            current_state=current_state,
            round_number=round_number,
            player_summary=player_summary,
            difficulty="medium",
        )
        if not new_round or not new_round.get("choices"):
            return jsonify({"error": "generation_failed"}), 200
        game["rounds"].append(new_round)
        if "initialized_game" in r:
            r["initialized_game"]["rounds"] = list(game["rounds"])
        st_obj.game_over = False
        update_run(run_id, r)
        try:
            next_payload = build_round_payload(game, st_obj)
        except Exception:
            next_payload = new_round
        return jsonify({
            "success": True,
            "round": next_payload,
            "round_index": int(st_obj.round_index),
        })
    except Exception as e:
        logger.error(f"Dynamic round generation failed: {e}")
        return jsonify({"error": "generation_failed"}), 200


@app.get("/api/admin/cohorts/<cohort_id>/live-sessions")
@require_auth
def admin_cohort_live_sessions(cohort_id):
    """Return currently active game sessions for students in a cohort."""
    token = get_token_from_request()
    user = verify_token(token) if token else None
    if not user or user.get("role") not in ("admin", "teacher", "school_admin", "hr"):
        return jsonify({"error": "Forbidden"}), 403
    try:
        cohorts_file = os.path.join(os.path.dirname(__file__), "data", "cohorts.json")
        try:
            with open(cohorts_file) as _cf:
                _raw = json.load(_cf)
                cohorts_data = _raw.get("cohorts", _raw) if isinstance(_raw, dict) else _raw
        except (FileNotFoundError, json.JSONDecodeError):
            return jsonify({"sessions": [], "cohort_id": cohort_id})
        cohort = next((c for c in cohorts_data if isinstance(c, dict) and c.get("id") == cohort_id), None)
        if not cohort:
            return jsonify({"error": "Cohort not found"}), 404
        student_ids = set(cohort.get("students", []) or cohort.get("student_ids") or [])
        act_file = os.path.join(os.path.dirname(__file__), "data", "active_sessions.json")
        try:
            with open(act_file) as _af2:
                active_sessions = json.load(_af2)
        except (FileNotFoundError, json.JSONDecodeError):
            active_sessions = {}
        try:
            all_profiles = player_profile._load_profiles()
        except Exception:
            all_profiles = {}
        now = datetime.now()
        sessions_out = []
        for run_id_s, sess in active_sessions.items():
            if sess.get("user_id") not in student_ids:
                continue
            try:
                started = datetime.fromisoformat(sess["started_at"])
                duration_min = int((now - started).total_seconds() / 60)
            except Exception:
                duration_min = 0
            prof = all_profiles.get(sess.get("user_id"), {})
            sessions_out.append({
                "run_id": run_id_s,
                "user_id": sess.get("user_id"),
                "username": prof.get("username") or sess.get("user_id"),
                "display_name": prof.get("display_name") or prof.get("username") or sess.get("user_id"),
                "game_id": sess.get("game_id"),
                "game_title": sess.get("game_title"),
                "started_at": sess.get("started_at"),
                "duration_min": duration_min,
            })
        sessions_out.sort(key=lambda s: s.get("started_at", ""), reverse=True)
        return jsonify({"sessions": sessions_out, "cohort_id": cohort_id, "count": len(sessions_out)})
    except Exception as e:
        logger.error(f"admin_cohort_live_sessions error: {e}")
        return jsonify({"error": str(e)}), 500


# ─── Background Scheduler (streak reminders, cleanup) ─────────────────────────
def _run_scheduler():
    """Background scheduler for periodic tasks."""
    try:
        from apscheduler.schedulers.background import BackgroundScheduler
        import datetime as _dt

        def _daily_streak_check():
            """Check for users at streak risk and send reminders."""
            try:
                import notifications as _notif
                profiles_path = os.path.join(os.path.dirname(__file__), "game_sessions", "profiles.json")
                if not os.path.exists(profiles_path):
                    return
                with open(profiles_path, "r") as f:
                    profiles = json.load(f)
                today = _dt.date.today().isoformat()
                yesterday = (_dt.date.today() - _dt.timedelta(days=1)).isoformat()
                for uid, profile in profiles.items():
                    if not uid or uid.startswith("_"):
                        continue
                    streak = profile.get("streak_days", 0)
                    last_active = profile.get("last_active_date", "")
                    # At risk: streak >= 2, last active was yesterday (not today)
                    if streak >= 2 and last_active == yesterday:
                        _notif.trigger_streak_reminder(uid, streak)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        def _daily_cleanup():
            """Clean up old notifications."""
            try:
                import notifications as _notif
                _notif.cleanup_old(days=30)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        def _check_cohort_sessions():
            """Check for students stuck in games >20 min and notify their teachers."""
            try:
                import notifications as _notif_cs
                import datetime as _dt_cs
                data_dir = os.path.join(os.path.dirname(__file__), "data")
                act_file = os.path.join(data_dir, "active_sessions.json")
                cohorts_file = os.path.join(data_dir, "cohorts.json")
                if not os.path.exists(act_file):
                    return
                with open(act_file) as _f_cs:
                    active_sessions_cs = json.load(_f_cs)
                cohorts_cs = []
                if os.path.exists(cohorts_file):
                    with open(cohorts_file) as _f_cs2:
                        cohorts_cs = json.load(_f_cs2)
                profiles_cs = {}
                profiles_path_cs = os.path.join(os.path.dirname(__file__), "game_sessions", "profiles.json")
                if os.path.exists(profiles_path_cs):
                    with open(profiles_path_cs) as _f_cs3:
                        profiles_cs = json.load(_f_cs3)
                now_cs = _dt_cs.datetime.now()
                student_teachers_cs = {}
                for cohort_cs in cohorts_cs:
                    teacher_id_cs = cohort_cs.get("teacher_id") or cohort_cs.get("owner_id") or cohort_cs.get("created_by")
                    if not teacher_id_cs:
                        continue
                    for sid_cs in (cohort_cs.get("students") or cohort_cs.get("student_ids") or []):
                        student_teachers_cs.setdefault(sid_cs, set()).add(teacher_id_cs)
                for run_id_cs, sess_cs in active_sessions_cs.items():
                    uid_cs = sess_cs.get("user_id")
                    teachers_cs = student_teachers_cs.get(uid_cs)
                    if not teachers_cs:
                        continue
                    try:
                        started_cs = _dt_cs.datetime.fromisoformat(sess_cs["started_at"])
                        dur_min_cs = int((now_cs - started_cs).total_seconds() / 60)
                    except Exception:
                        continue
                    if dur_min_cs >= 20:
                        prof_cs = profiles_cs.get(uid_cs, {})
                        sname_cs = prof_cs.get("display_name") or prof_cs.get("username") or uid_cs
                        gtitle_cs = sess_cs.get("game_title", "Unknown Game")
                        for tid_cs in teachers_cs:
                            _notif_cs.trigger_student_stuck(tid_cs, sname_cs, gtitle_cs, dur_min_cs)
            except Exception as _e:
                logger.debug("Suppressed %s: %s", type(_e).__name__, _e)

        def _recompute_leaderboard_pop_stats():
            """Daily 3am: recompute per-game-type dimension mean/std across all
            leaderboard entries. Skips game_types with n<5 (insufficient pop).
            Writes to data/leaderboard_pop_stats.json. Defensive: never crashes
            the scheduler.
            """
            try:
                import math as _math_lb
                import glob as _glob_lb
                lb_dir = os.path.join(os.path.dirname(__file__), "game_sessions")
                pattern = os.path.join(lb_dir, "leaderboard_*.json")
                # accumulator: per_gt[game_type][dim] -> list of values
                per_gt = {}
                for fp in _glob_lb.glob(pattern):
                    try:
                        with open(fp, "r") as _flb:
                            lb = json.load(_flb)
                    except Exception:
                        continue
                    for ent in (lb or {}).get("entries", []) or []:
                        if not isinstance(ent, dict):
                            continue
                        gt = ent.get("game_type") or "unknown"
                        dims = None
                        fm = ent.get("final_metrics") or {}
                        if isinstance(fm, dict) and isinstance(fm.get("dimension_scores"), dict):
                            dims = fm["dimension_scores"]
                        elif isinstance(ent.get("dimension_scores"), dict):
                            dims = ent["dimension_scores"]
                        if not dims:
                            continue
                        gt_bucket = per_gt.setdefault(gt, {})
                        for d, v in dims.items():
                            if isinstance(v, (int, float)):
                                gt_bucket.setdefault(d, []).append(float(v))
                out = {}
                for gt, dims_map in per_gt.items():
                    gt_out = {}
                    for d, vals in dims_map.items():
                        n = len(vals)
                        if n < 5:
                            continue  # insufficient sample → fall back to raw
                        mean = sum(vals) / n
                        var = sum((x - mean) ** 2 for x in vals) / n
                        std = _math_lb.sqrt(var)
                        gt_out[d] = {"mean": mean, "std": std, "n": n}
                    if gt_out:
                        out[gt] = gt_out
                pop_path = os.path.join(os.path.dirname(__file__), "data", "leaderboard_pop_stats.json")
                os.makedirs(os.path.dirname(pop_path), exist_ok=True)
                with open(pop_path, "w") as _fout:
                    json.dump(out, _fout, indent=2)
                logger.info(f"Recomputed leaderboard pop stats for {len(out)} game_types")
            except Exception as _e:
                logger.warning(f"Leaderboard pop stats recompute failed: {_e}")

        _scheduler = BackgroundScheduler()
        _scheduler.add_job(_daily_streak_check, 'cron', hour=9, minute=0, id='streak_check')
        _scheduler.add_job(_daily_cleanup, 'cron', hour=2, minute=0, id='cleanup')
        _scheduler.add_job(_check_cohort_sessions, 'interval', minutes=10, id='cohort_sessions')
        _scheduler.add_job(_MULTIPLAYER_ENGINE.cleanup_stale_sessions, 'interval', minutes=5, id='multiplayer_cleanup', replace_existing=True)
        _scheduler.add_job(_recompute_leaderboard_pop_stats, 'cron', hour=3, minute=0, id='leaderboard_pop_stats', replace_existing=True)
        _scheduler.start()
    except ImportError:
        pass  # APScheduler not installed, skip
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)


