import random
import string as _string

def _generate_join_code():
    return ''.join(random.choices(_string.ascii_uppercase + _string.digits, k=6))


@app.post("/api/teacher/cohorts")
@_require_teacher_or_admin
def teacher_create_cohort():
    """Teacher creates a new cohort with auto-generated join code."""
    import uuid
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"error": "name required"}), 400
    user = request.current_user
    cohort_data = _load_cohorts()
    from datetime import datetime, timezone
    new_cohort = {
        "id": str(uuid.uuid4())[:8],
        "name": name,
        "description": data.get("description", ""),
        "students": [],
        "assigned_paths": [],
        "teacher_id": user.get("user_id"),
        "org_id": user.get("org_id", "default"),
        "join_code": _generate_join_code(),
        "weekly_challenge": None,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    cohort_data.setdefault("cohorts", []).append(new_cohort)
    _save_cohorts(cohort_data)
    return jsonify({"cohort": new_cohort, "created": True}), 201


