# ---------- HR Assessment Batches ----------

_ASSESSMENTS_FILE = os.path.join(os.path.dirname(__file__), "data", "assessments.json")


def _load_assessments():
    try:
        with open(_ASSESSMENTS_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {"batches": {}}


def _save_assessments(data):
    os.makedirs(os.path.dirname(_ASSESSMENTS_FILE), exist_ok=True)
    with open(_ASSESSMENTS_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)


def _record_assessment_run(batch_id, run_id, dimension_scores, final_score):
    """Record a completed game run into an assessment batch."""
    try:
        data = _load_assessments()
        batch = data["batches"].get(batch_id)
        if not batch:
            return
        runs = batch.setdefault("runs", [])
        if any(r.get("run_id") == run_id for r in runs):
            return  # already recorded
        from datetime import datetime, timezone
        label = f"Candidate {len(runs) + 1}"
        runs.append({
            "run_id": run_id,
            "completed_at": datetime.now(timezone.utc).isoformat(),
            "dimension_scores": dimension_scores,
            "final_score": final_score,
            "candidate_label": label,
        })
        _save_assessments(data)
    except Exception as _e:
        logger.debug("Suppressed %s: %s", type(_e).__name__, _e)


@app.post("/api/assessments/batches")
@_require_assessor
def create_assessment_batch():
    """Create a new assessment batch (HR creates a shareable game link)."""
    import uuid
    user = request.current_user
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    # Support multi-select: game_ids (array) or legacy game_id (string)
    game_ids = data.get("game_ids") or []
    if not game_ids and data.get("game_id"):
        game_ids = [data["game_id"].strip()]
    game_ids = [g for g in game_ids if g]
    if not name or not game_ids:
        return jsonify({"error": "name and at least one game_id required"}), 400
    from datetime import datetime, timezone
    batch_id = str(uuid.uuid4())[:8]
    assessments = _load_assessments()
    assessments["batches"][batch_id] = {
        "batch_id": batch_id,
        "name": name,
        "game_id": game_ids[0],   # backward-compat: first game
        "game_ids": game_ids,
        "description": data.get("description", ""),
        "created_by": user.get("user_id"),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "runs": []
    }
    _save_assessments(assessments)
    return jsonify({"batch_id": batch_id, "name": name, "game_id": game_ids[0], "game_ids": game_ids}), 201


@app.get("/api/assessments/batches")
@require_auth
def list_assessment_batches():
    """List all assessment batches created by the current user."""
    uid = request.current_user.get("user_id")
    data = _load_assessments()
    batches = [b for b in data.get("batches", {}).values() if b.get("created_by") == uid]
    batches.sort(key=lambda b: b.get("created_at", ""), reverse=True)
    # Add summary stats
    for b in batches:
        runs = b.get("runs", [])
        b["candidate_count"] = len(runs)
        b["avg_score"] = round(sum(r.get("final_score", 0) for r in runs) / max(1, len(runs))) if runs else 0
    return jsonify({"batches": batches})


@app.get("/api/assessments/batches/<batch_id>")
@require_auth
def get_assessment_batch(batch_id):
    """Get batch detail with all results and benchmarks."""
    uid = request.current_user.get("user_id")
    data = _load_assessments()
    batch = data.get("batches", {}).get(batch_id)
    if not batch:
        return jsonify({"error": "Batch not found"}), 404
    if batch.get("created_by") != uid and request.current_user.get("role") != "admin":
        return jsonify({"error": "Access denied"}), 403
    # Compute benchmark (mean per dimension)
    runs = batch.get("runs", [])
    benchmark = {}
    _BATCH_DIMS = ["strategic_thinking", "risk_tolerance", "delayed_gratification", "adaptability", "resilience", "empathy", "ethical_reasoning", "creativity"]
    for dim in _BATCH_DIMS:
        vals = [r["dimension_scores"].get(dim, 0) for r in runs if r.get("dimension_scores")]
        benchmark[dim] = round(sum(vals) / max(1, len(vals))) if vals else 0
    # avg_score for benchmark row
    benchmark["avg_score"] = round(sum(r.get("final_score", 0) for r in runs) / max(1, len(runs))) if runs else 0
    # Add percentile_rank per candidate (within batch) — use rank-based to handle ties correctly
    if len(runs) > 1:
        scores = [r.get("final_score", 0) for r in runs]
        scores_sorted = sorted(scores)
        n = len(scores_sorted)
        for r in runs:
            s = r.get("final_score", 0)
            # Count how many candidates scored strictly less (rank from bottom)
            rank_from_bottom = sum(1 for x in scores_sorted if x < s)
            r["percentile_rank"] = int(100 * rank_from_bottom / max(1, n - 1))
    else:
        for r in runs:
            r["percentile_rank"] = 50
    return jsonify({"batch": batch, "benchmark": benchmark})


@app.delete("/api/assessments/batches/<batch_id>")
@require_auth
def delete_assessment_batch(batch_id):
    """Delete an assessment batch."""
    uid = request.current_user.get("user_id")
    data = _load_assessments()
    batch = data.get("batches", {}).get(batch_id)
    if not batch:
        return jsonify({"error": "Not found"}), 404
    if batch.get("created_by") != uid and request.current_user.get("role") != "admin":
        return jsonify({"error": "Access denied"}), 403
    del data["batches"][batch_id]
    _save_assessments(data)
    return jsonify({"deleted": True})


