@app.post("/api/org/create")
@require_auth
def create_my_org():
    """Any authenticated user creates an org and becomes school_admin of it."""
    user = request.current_user
    data = request.get_json(silent=True) or {}
    org_name = (data.get("name") or "").strip()
    if not org_name:
        return jsonify({"error": "org name required"}), 400
    new_org = org_module.create_org({
        "name": org_name,
        "type": data.get("type", "school"),
        "primary_color": data.get("primary_color", "#6C5CE7"),
        "accent_color": data.get("accent_color", "#00B894"),
        "logo_url": data.get("logo_url", ""),
    })
    # Promote user to school_admin and update their org_id
    from auth import _load_users, _save_users, generate_token
    users = _load_users()
    updated_user = None
    for u in users:
        if u.get("id") == user.get("user_id"):
            u["role"] = "school_admin"
            u["org_id"] = new_org["id"]
            updated_user = u
            break
    _save_users(users)
    # Issue a new JWT so the client immediately has school_admin role without re-login
    new_token = None
    if updated_user:
        new_token = generate_token(updated_user["id"], updated_user["username"], "school_admin", new_org["id"])
    return jsonify({"org": new_org, "role": "school_admin", "token": new_token}), 201


