@app.post("/api/multiplayer/create")
@require_auth
def multiplayer_create():
    """Create a new multiplayer match."""
    user = request.current_user
    payload = request.get_json(silent=True) or {}
    game_id = payload.get("game_id", "")
    if not game_id:
        return jsonify({"error": "game_id required"}), 400
    # Enforce multiplayer.enabled flag on the game JSON
    try:
        _mp_game, _mp_err = get_game_or_400(game_id)
        if _mp_err:
            return _mp_err
        _mp_cfg = (_mp_game or {}).get("multiplayer") or {}
        if isinstance(_mp_cfg, dict) and _mp_cfg.get("enabled") is False:
            return jsonify({"error": "Multiplayer is disabled for this game."}), 400
    except Exception as _mp_check_err:
        logger.debug("multiplayer gate check failed: %s", _mp_check_err)
    match_settings = payload.get("match_settings")
    match = _MULTIPLAYER_ENGINE.create_match(game_id, user["user_id"], match_settings)
    return jsonify({"match": match}), 201


