@app.post("/api/run/<run_id>/pvp/launch")
@require_auth
def pvp_launch(run_id):
    """R13 — Launch a PvP live session from inside a single-player run.

    For Series A q5_term_sheet (and any round with `pvp_mode.enabled`), the
    player can choose to step out of the AI-driven LiveInvestor flow into a
    real-time PvP negotiation against another player. We create or join a
    realtime session and return its id, then the frontend takes over.

    POST body: { "round_id": str, "mode": "create"|"join"|"random",
                 "session_id"?: str, "role"?: str }
    """
    user = request.current_user
    try:
        r = get_run(run_id)
    except (KeyError, Exception):
        return jsonify({"error": f"Run not found: {run_id}"}), 404

    if r.get("user_id") and r.get("user_id") != user.get("user_id"):
        return jsonify({"error": "Run does not belong to current user"}), 403

    payload = request.get_json(silent=True) or {}
    round_id = (payload.get("round_id") or "").strip()
    mode = (payload.get("mode") or "create").strip()
    requested_session_id = (payload.get("session_id") or "").strip()
    role = (payload.get("role") or "").strip()

    if not round_id:
        return jsonify({"error": "round_id required"}), 400

    game_id = r.get("game_id")
    game, err = get_game_or_400(game_id)
    if err:
        return err

    rounds = game.get("rounds") or []
    rd = next((x for x in rounds if (x.get("id") or x.get("round_id")) == round_id), None)
    if not rd:
        return jsonify({"error": f"Round not found: {round_id}"}), 404

    pvp = rd.get("pvp_mode") or {}
    if not pvp.get("enabled"):
        return jsonify({"error": "PvP mode not enabled for this round"}), 400

    config = {
        "round_id": round_id,
        "session_kind": pvp.get("session_kind", "negotiation"),
        "roles": pvp.get("roles") or [],
        "max_turns": pvp.get("max_turns", 6),
        "turn_time_limit": pvp.get("turn_time_limit_seconds", 90),
        "scoring_rubric": pvp.get("scoring_rubric") or {},
        "preferred_role": role,
    }

    try:
        if mode == "join" and requested_session_id:
            s = rt_get(requested_session_id)
            if not s:
                return jsonify({"error": "Session not found"}), 404
            ok, msg = s.join(user["user_id"])
            if not ok:
                return jsonify({"error": msg}), 400
            return jsonify({
                "session_id": s.id,
                "state": s.get_state(user["user_id"]),
                "joined": True,
            })

        if mode == "random":
            sessions = rt_list(game_id) or []
            for sess_meta in sessions:
                sid = sess_meta.get("id") or sess_meta.get("session_id")
                if not sid:
                    continue
                s = rt_get(sid)
                if not s:
                    continue
                ok, _msg = s.join(user["user_id"])
                if ok:
                    return jsonify({
                        "session_id": s.id,
                        "state": s.get_state(user["user_id"]),
                        "joined": True,
                    })
            mode = "create"

        s = rt_create(game_id, user["user_id"], config)
        return jsonify({
            "session_id": s.id,
            "state": s.get_state(user["user_id"]),
            "joined": False,
            "created": True,
        })
    except Exception as _pvp_err:
        logger.warning(f"R13 pvp_launch failed: {_pvp_err}")
        return jsonify({"error": "Could not start PvP session"}), 500


