@app.post("/api/realtime/create")
@require_auth
def realtime_create():
    """Create a new real-time multiplayer session."""
    body = request.get_json(silent=True) or {}
    game_id = body.get("game_id")
    if not game_id:
        return _api_error("game_id required")
    user = request.current_user
    config = body.get("config", {})
    s = rt_create(game_id, user["user_id"], config)
