@app.patch("/api/profile/wellbeing-consent")
@require_auth
def update_wellbeing_consent_endpoint():
    """Grant or withdraw wellbeing monitoring consent (DPDP compliant)."""
    user = request.current_user
    body = request.get_json(force=True) or {}
    action = body.get("consent")
    child_id = body.get("child_id")
    if action not in ("given", "withdrawn"):
        return jsonify({"error": "consent must be 'given' or 'withdrawn'"}), 400
    target_uid = child_id if child_id else user["user_id"]
    if child_id:
        fl = _load_family_links()
        linked = any(
            lnk.get("child_id") == child_id and lnk.get("parent_id") == user["user_id"]
            for lnk in fl.get("links", [])
        )
        if not linked:
            return jsonify({"error": "Not authorized for this child"}), 403
    minor = bool(child_id)
    try:
        player_profile.update_wellbeing_consent(target_uid, action, minor=minor)
        # Append-only audit log
        import hashlib
        from datetime import datetime
        _audit_file = os.path.join(os.path.dirname(__file__), "data", "consent_audit.json")
        try:
            with open(_audit_file) as _af:
                _audit = json.load(_af)
        except (FileNotFoundError, json.JSONDecodeError):
            _audit = {"log": []}
        _audit["log"].append({
            "user_id_hash": hashlib.sha256(target_uid.encode()).hexdigest()[:16],
            "action": action,
            "timestamp": datetime.now().isoformat(),
            "version": "1.0",
            "minor": minor,
        })
        with open(_audit_file, "w") as _af:
            json.dump(_audit, _af)
    except Exception as _ce:
        logger.warning("wellbeing consent update failed: %s", _ce)
        return jsonify({"error": "Consent update failed"}), 500
    return jsonify({"wellbeing_consent": action, "target_user_id": target_uid})


