@app.delete("/api/profile/wellbeing-data")
@require_auth
def delete_wellbeing_data():
    """Right to erasure: delete all wellbeing data for the user (DPDP Article 12)."""
    user = request.current_user
    try:
        player_profile.delete_wellbeing_data(user["user_id"])
        # Audit log
        import hashlib
        _audit_file = os.path.join(os.path.dirname(__file__), "data", "consent_audit.json")
        try:
            with open(_audit_file) as _af:
                _audit = json.load(_af)
        except (FileNotFoundError, json.JSONDecodeError):
            _audit = {"log": []}
        _audit["log"].append({
            "user_id_hash": hashlib.sha256(user["user_id"].encode()).hexdigest()[:16],
            "action": "erased",
            "timestamp": datetime.now().isoformat(),
            "version": "1.0",
        })
        with open(_audit_file, "w") as _af:
            json.dump(_audit, _af)
    except Exception as _de_err:
        logger.warning("delete_wellbeing_data failed: %s", _de_err)
        return jsonify({"error": "Deletion failed"}), 500
    # Also clear behavioral analytics files
    import glob as _glob
    from datetime import datetime as _dt_erasure
    _data_dir = os.path.join(os.path.dirname(__file__), "data")
    _user_id_erasure = user["user_id"]
    for _pattern in [
        f"behavioral_analytics/{_user_id_erasure}*",
        f"models/{_user_id_erasure}*",
    ]:
        for _f in _glob.glob(os.path.join(_data_dir, _pattern)):
            try:
                os.remove(_f)
            except Exception:
                pass
    # Clear from wellbeing_data.json
    _wb_file = os.path.join(_data_dir, "wellbeing_data.json")
    try:
        with open(_wb_file) as _wbf:
            _wb = json.load(_wbf)
        _wb.pop(_user_id_erasure, None)
        with open(_wb_file, "w") as _wbf:
            json.dump(_wb, _wbf)
    except Exception:
        pass
    # Log erasure in consent_audit
    _audit_file2 = os.path.join(_data_dir, "consent_audit.json")
    try:
        import hashlib as _hl
        _uid_hash = _hl.sha256(_user_id_erasure.encode()).hexdigest()[:16]
        try:
            with open(_audit_file2) as _af2:
                _audit2 = json.load(_af2)
        except (FileNotFoundError, json.JSONDecodeError):
            _audit2 = {"log": []}
        _audit2.setdefault("log", []).append({"user_id_hash": _uid_hash, "action": "erased_all", "timestamp": _dt_erasure.now().isoformat()})
        with open(_audit_file2, "w") as _af2:
            json.dump(_audit2, _af2)
    except Exception:
        pass
    return jsonify({"deleted": True, "deleted_at": _dt_erasure.now().isoformat()})


@app.get("/api/teacher/wellbeing-alerts")
@_require_teacher_or_admin
def teacher_wellbeing_alerts():
    """Return wellbeing alert summary for students who have consented."""
    user = request.current_user
    cohort_data = _load_cohorts()
    user_cohorts = [
        c["id"] for c in cohort_data.get("cohorts", [])
        if user["user_id"] in [str(s) for s in c.get("teachers", [])]
        or user.get("role") in ("admin", "school_admin")
    ]
    # Collect all student IDs
    student_ids = set()
    for cohort in cohort_data.get("cohorts", []):
        if cohort["id"] in user_cohorts or user.get("role") in ("admin", "school_admin"):
            for s in cohort.get("students", []):
                student_ids.add(str(s))

    try:
        import behavioral_indicators as _bi
    except ImportError:
        return jsonify({"alerts": [], "error": "Behavioral indicators not available"}), 200

    alerts = []
    for sid in student_ids:
        try:
            prof = player_profile.get_profile(sid)
            if prof.get("wellbeing_consent") != "given":
                continue
            skill_history = player_profile.get_skill_history(sid).get("history", [])
            quit_history = prof.get("quit_history", [])
            # Build choice_histories and run_logs from stored history
            choice_histories = [
                s.get("choice_history", []) for s in skill_history[-10:] if s.get("choice_history")
            ]
            wellbeing_data = prof.get("wellbeing_responses", {}) or {}
            game_history_list = prof.get("recent_activity", []) or []
            indicators = _bi.compute_all_indicators(
                sid, skill_history, [], choice_histories, quit_history,
                wellbeing_data=wellbeing_data,
                game_history=game_history_list,
                include_escapism=True,
            )
            alert_level = indicators.get("alert_level", "green")
            escapism = indicators.get("escapism_risk", {})
            # Show alert if alert level is not green OR escapism risk is flagged
            if alert_level == "green" and not escapism.get("risk_flag"):
                continue
            detected = [k for k, v in indicators.get("indicators", {}).items()
                        if isinstance(v, dict) and v.get("detected")]
            _indicators_detail = []
            for _ind_name, _ind_data in indicators.get("indicators", {}).items():
                if isinstance(_ind_data, dict) and _ind_data.get("detected"):
                    _signals = _ind_data.get("signals", [])
                    _score = _ind_data.get("score", 0)
                    _evidence = _signals[0] if _signals else f"{_ind_name.replace('_', ' ').title()} pattern detected"
                    _indicators_detail.append({
                        "name": _ind_name.replace("_", " ").title(),
                        "score": _score,
                        "signals": _signals[:3],
                        "evidence_summary": _evidence
                    })
            alerts.append({
                "student_id": sid,
                "student_name": prof.get("display_name") or sid,
                "alert_level": alert_level,
                "indicators_detected": detected,
                "behavioral_summary": indicators.get("behavioral_summary", ""),
                "last_active": prof.get("last_active"),
                "checked_in": prof.get("wellbeing_alert_checked", False),
                "indicators_detail": _indicators_detail,
                "escapism_risk": escapism,
            })
        except Exception as _ae:
            logger.debug("Suppressed wellbeing alert for %s: %s", sid, _ae)
    return jsonify({"alerts": alerts, "total_students": len(student_ids)})


