@app.get("/api/leaderboard/percentile")
def leaderboard_percentile():
    """Return the requesting user's percentile rank for a given skill dimension."""
    dimension = request.args.get("dimension", "strategic_thinking")
    period = request.args.get("period", "all")  # week|month|all
    token = get_token_from_request()
    user_payload = verify_token(token) if token else None
    if not user_payload:
        return jsonify({"error": "Authentication required"}), 401
    uid = user_payload["user_id"]
    try:
        prof = player_profile.get_profile(uid)
        user_score = (prof.get("dimension_scores") or {}).get(dimension, 0)
        # Gather all player scores for the dimension
        all_scores = []
        profs = player_profile._load_profiles()
        for pid, p in profs.items():
            ds = p.get("dimension_scores") or {}
            val = ds.get(dimension)
            if isinstance(val, (int, float)):
                all_scores.append(val)
        if not all_scores:
            return jsonify({"user_score": user_score, "percentile": 50, "total_players": 0})
        below = sum(1 for s in all_scores if s < user_score)
        percentile = round(below / len(all_scores) * 100)
        from statistics import mean as _smean
        return jsonify({
            "dimension": dimension,
            "user_score": round(user_score),
            "percentile": percentile,
            "total_players": len(all_scores),
            "avg_score": round(_smean(all_scores)),
        })
    except Exception as _lp_err:
        logger.warning("leaderboard percentile failed: %s", _lp_err)
        return jsonify({"error": "Could not compute percentile"}), 500


