# LMS MODULE BUILDER
# ═══════════════════════════════════════════════════════════════════════════
_MODULES_FILE = os.path.join(os.path.dirname(__file__), "data", "modules.json")


def _load_modules() -> list:
    try:
        if os.path.exists(_MODULES_FILE):
            data = json.load(open(_MODULES_FILE, encoding="utf-8"))
            return data if isinstance(data, list) else data.get("modules", [])
    except Exception:
        pass
    return []


def _save_modules(modules: list):
    os.makedirs(os.path.dirname(_MODULES_FILE), exist_ok=True)
    json.dump(modules, open(_MODULES_FILE, "w", encoding="utf-8"), indent=2)


@app.get("/api/teacher/modules")
@_require_teacher_or_admin
def teacher_list_modules():
    user = request.current_user
    modules = _load_modules()
    if user.get("role") == "teacher":
        modules = [m for m in modules if m.get("teacher_id") == user["user_id"] or not m.get("teacher_id")]
    return jsonify({"modules": modules})


@app.post("/api/teacher/modules")
@_require_teacher_or_admin
def teacher_create_module():
    user = request.current_user
    data = request.get_json(silent=True) or {}
    if not data.get("name"):
        return _api_error("name required", 400)
    import uuid as _uuid_mod
    from datetime import datetime as _dt_mod
    module = {
        "id": "mod_" + str(_uuid_mod.uuid4())[:8],
        "name": data["name"],
        "description": data.get("description", ""),
        "game_ids": data.get("game_ids", []),
        "cohort_ids": data.get("cohort_ids", []),
        "due_date": data.get("due_date"),
        "min_score_threshold": data.get("min_score_threshold", 60),
        "teacher_id": user["user_id"],
        "org_id": user.get("org_id", "default"),
        "created_at": _dt_mod.utcnow().isoformat(),
    }
    modules = _load_modules()
    modules.append(module)
    _save_modules(modules)
    return jsonify({"module": module, "created": True}), 201


@app.put("/api/teacher/modules/<module_id>")
@_require_teacher_or_admin
def teacher_update_module(module_id):
    user = request.current_user
    data = request.get_json(silent=True) or {}
    modules = _load_modules()
    for m in modules:
        if m["id"] == module_id:
            if user.get("role") == "teacher" and m.get("teacher_id") != user["user_id"]:
                return _api_error("Forbidden", 403)
            for field in ("name", "description", "game_ids", "cohort_ids", "due_date", "min_score_threshold"):
                if field in data:
                    m[field] = data[field]
            _save_modules(modules)
            return jsonify({"module": m})
    return _api_error("Module not found", 404)


@app.delete("/api/teacher/modules/<module_id>")
@_require_teacher_or_admin
def teacher_delete_module(module_id):
    user = request.current_user
    modules = _load_modules()
    before = len(modules)
    modules = [m for m in modules if not (m["id"] == module_id and (user.get("role") != "teacher" or m.get("teacher_id") == user["user_id"]))]
    if len(modules) == before:
        return _api_error("Not found or forbidden", 404)
    _save_modules(modules)
    return jsonify({"deleted": True})


@app.get("/api/teacher/modules/<module_id>/progress")
@_require_teacher_or_admin
def teacher_module_progress(module_id):
    """Per-student completion progress for each game in a module."""
    modules = _load_modules()
    module = next((m for m in modules if m["id"] == module_id), None)
    if not module:
        return _api_error("Not found", 404)
    cohort_data = _load_cohorts()
    all_students = []
    for cid in (module.get("cohort_ids") or []):
        cohort = next((c for c in cohort_data.get("cohorts", []) if c["id"] == cid), None)
        if cohort:
            for s in cohort.get("students", []):
                if s not in all_students:
                    all_students.append(s)
    progress = []
    for uid in all_students:
        try:
            p = player_profile.get_profile(uid)
            completed_games = [r.get("game_id") for r in (p.get("recent_activity") or []) if r.get("completed")]
            game_status = {gid: gid in completed_games for gid in module["game_ids"]}
            pct = round(100 * sum(game_status.values()) / max(len(module["game_ids"]), 1))
            progress.append({"user_id": uid, "display_name": p.get("display_name", uid), "game_status": game_status, "pct": pct})
        except Exception:
            progress.append({"user_id": uid, "display_name": uid, "game_status": {}, "pct": 0})
    return jsonify({"module": module, "students": progress})


