# ═══════════════════════════════════════════════════════════════════════════
# CURRICULUM SCHEDULING — Teacher assigns a full curriculum with dates
# ═══════════════════════════════════════════════════════════════════════════

@app.post("/api/teacher/curriculum/schedule")
@_require_teacher_or_admin
def teacher_schedule_curriculum():
    """Schedule a curriculum template as a series of dated assignments.

    Body JSON:
      template_id: str          — curriculum template to schedule
      cohort_id: str            — target cohort
      schedule: [               — per-month schedule (array of 9 objects)
        { month: 1, game_id: "g6-budget-bazaar", start_date: "2026-06-01", due_date: "2026-06-30" },
        ...
      ]
      title: str (optional)     — custom schedule name
    """
    from datetime import datetime as _dt_sched
    import uuid as _uuid_sched

    user = request.current_user
    data = request.get_json(silent=True) or {}
    template_id = data.get("template_id")
    cohort_id = data.get("cohort_id")
    schedule = data.get("schedule", [])
    custom_title = data.get("title", "")

    if not template_id or not cohort_id or not schedule:
        return _api_error("template_id, cohort_id, and schedule required", 400)

    # Validate cohort exists
    cohort_data = _load_cohorts()
    cohort = next((c for c in cohort_data.get("cohorts", []) if c["id"] == cohort_id), None)
    if not cohort:
        return _api_error("Cohort not found", 404)

    # Load template for game titles
    templates = _load_curriculum_templates()
    tpl = next((t for t in templates if t["id"] == template_id), None)
    if not tpl:
        return _api_error("Template not found", 404)

    load_bundle()
    games_map = {m["game_id"]: m for m in tpl.get("months", [])}

    # Generate a schedule_id to group these assignments
    schedule_id = "sched_" + str(_uuid_sched.uuid4())[:8]

    assignments = _load_assignments()
    created = []
    for idx, entry in enumerate(schedule):
        game_id = entry.get("game_id")
        if not game_id:
            continue
        month_info = games_map.get(game_id, {})
        game = GAMES.get(game_id)
        new_a = {
            "id": "asgn_" + str(_uuid_sched.uuid4())[:8],
            "schedule_id": schedule_id,
            "cohort_id": cohort_id,
            "game_id": game_id,
            "title": game.get("title", game_id) if game else (month_info.get("title") or game_id),
            "theme": month_info.get("theme", ""),
            "start_date": entry.get("start_date", ""),
            "due_date": entry.get("due_date", ""),
            "sequence_order": entry.get("month", idx + 1),
            "created_by": user["user_id"],
            "created_at": _dt_sched.utcnow().isoformat(),
            "curriculum_template_id": template_id,
            "is_weekly_challenge": False,
            "mode": "solo",
        }
        assignments.append(new_a)
        created.append(new_a)

    _save_assignments(assignments)

    # Store schedule metadata
    try:
        _sched_file = os.path.join(os.path.dirname(__file__), "data", "curriculum_schedules.json")
        schedules = []
        if os.path.exists(_sched_file):
            with open(_sched_file) as _sf:
                schedules = json.load(_sf)
        schedules.append({
            "id": schedule_id,
            "template_id": template_id,
            "title": custom_title or tpl.get("title", ""),
            "template_title": custom_title or tpl.get("title", ""),
            "cohort_id": cohort_id,
            "cohort_name": cohort.get("name", ""),
            "teacher_id": user["user_id"],
            "created_at": _dt_sched.utcnow().isoformat(),
            "assignment_count": len(created),
            "student_count": len(cohort.get("students", [])),
        })
        with open(_sched_file, "w") as _sf:
            json.dump(schedules, _sf, indent=2)
    except Exception as _e:
        logger.debug("Schedule metadata save: %s", _e)

    return jsonify({
        "schedule_id": schedule_id,
        "assignments": created,
        "student_count": len(cohort.get("students", [])),
    }), 201


