@app.get("/api/student/schedule")
@require_auth
def student_get_schedule():
    """Get the student's assigned game schedule with dates and completion status.

    Returns assignments grouped by status: upcoming, active (started), overdue, completed.
    Only returns curriculum-scheduled assignments (those with start_date).
    """
    from datetime import datetime as _dt_stu, date as _date_stu
    user = request.current_user
    user_id = user.get("user_id")

    # Find student's cohorts
    cohort_data = _load_cohorts()
    user_cohorts = [c.get("id") for c in cohort_data.get("cohorts", []) if str(user_id) in [str(s) for s in c.get("students", [])]]
    if not user_cohorts:
        return jsonify({"schedule": [], "summary": {"total": 0, "active": 0, "upcoming": 0, "completed": 0, "overdue": 0}})

    # Load assignments for student's cohorts — only scheduled ones (with start_date)
    all_assignments = _load_assignments()
    my_assignments = [a for a in all_assignments if a.get("cohort_id") in user_cohorts and a.get("start_date")]

    # Check completion status from profile
    try:
        profile = player_profile.get_profile(user_id)
        completed_games = {r.get("game_id") for r in (profile.get("recent_activity") or profile.get("game_history") or []) if r.get("completed") or r.get("game_id")}
    except Exception:
        completed_games = set()

    today = _date_stu.today().isoformat()
    result = []
    counts = {"total": 0, "active": 0, "upcoming": 0, "completed": 0, "overdue": 0}

    for a in sorted(my_assignments, key=lambda x: (x.get("sequence_order", 99), x.get("start_date", ""))):
        start = a.get("start_date", "")
        due = a.get("due_date", "")
        game_id = a.get("game_id", "")

        is_completed = game_id in completed_games
        if is_completed:
            status = "completed"
        elif start and start > today:
            status = "upcoming"
        elif due and due < today:
            status = "overdue"
        else:
            status = "active"

        entry = {
            "id": a.get("id"),
            "game_id": game_id,
            "title": a.get("title", game_id),
            "theme": a.get("theme", ""),
            "start_date": start,
            "due_date": due,
            "sequence_order": a.get("sequence_order", 0),
            "status": status,
            "schedule_id": a.get("schedule_id", ""),
            "curriculum_template_id": a.get("curriculum_template_id", ""),
        }
        result.append(entry)
        counts["total"] += 1
        counts[status] += 1

    return jsonify({"schedule": result, "summary": counts})


