# DETAILED CHILD REPORT (for parents)
# ═══════════════════════════════════════════════════════════════════════════
_WEAK_RECS = {
    "strategic_thinking": ["Play Chess Strategy or Strategy Grid games", "Try multi-round board simulations", "Focus on planning ahead in decision games"],
    "risk_tolerance":     ["Try AI Arena competitive games", "Explore negotiation simulations", "Play games with variable outcomes"],
    "delayed_gratification": ["Practice spaced repetition reviews", "Complete full game series without skipping", "Try resource management board games"],
    "adaptability":       ["Play story branching games with unexpected events", "Try different game formats each session", "Explore debate and negotiation scenarios"],
    "resilience":         ["Retry games you found difficult", "Play comeback-themed simulation games", "Track your improvement over multiple sessions"],
    "empathy":            ["Play group discussion and conflict mediation games", "Try story games with multiple perspectives", "Explore ethics-themed simulations"],
    "ethical_reasoning":  ["Play Ethics Tribunal or values-based games", "Explore dilemma scenarios in story games", "Discuss choices with peers after game sessions"],
    "creativity":         ["Try AI Arena creation challenges", "Explore open-ended strategy games", "Build custom game scenarios in the designer"],
}


@app.get("/api/family/children/<child_id>/detailed-report")
@require_auth
def family_child_detailed_report(child_id):
    """Full skill report with history, per-game scores, and recommendations for a linked child."""
    user = request.current_user
    links = _load_family_links()
    link = next((l for l in links.get("links", []) if l["parent_id"] == user["user_id"] and l["child_id"] == child_id), None)
    # Allow teachers/admins to view any student's report
    if not link and user.get("role") not in ("teacher", "admin", "school_admin", "hr"):
        return _api_error("Not linked to this child", 403)
    try:
        p = player_profile.get_profile(child_id)
    except Exception:
        return _api_error("Child profile not found", 404)
    dim_scores = p.get("dimension_scores") or {}
    baseline = p.get("baseline_scores") or {}
    recent = p.get("recent_activity") or []
    # Build per-game score history
    game_history = []
    for r in recent[:20]:
        if not isinstance(r, dict):
            continue
        game_history.append({
            "game_id": r.get("game_id"),
            "game_title": r.get("game_title", r.get("game_id", "")),
            "completed": r.get("completed", False),
            "xp_earned": r.get("xp_earned", 0),
            "timestamp": r.get("timestamp"),
            "dimension_scores": r.get("dimension_scores") or {},
        })
    # Improvement vs baseline
    improvement = {}
    for dim, score in dim_scores.items():
        base = baseline.get(dim)
        if base is not None:
            improvement[dim] = round(score - base, 1)
    # Recommendations for weak dimensions (score < 60)
    weak_dims = [(dim, score) for dim, score in dim_scores.items() if score < 60]
    weak_dims.sort(key=lambda x: x[1])
    recommendations = []
    for dim, score in weak_dims[:3]:
        recs = _WEAK_RECS.get(dim, [])
        recommendations.append({
            "dimension": dim,
            "score": score,
            "label": dim.replace("_", " ").title(),
            "tips": recs,
        })
    # Strengths (top 3 dimensions)
    strong_dims = sorted([(dim, score) for dim, score in dim_scores.items() if score >= 70], key=lambda x: -x[1])[:3]
    strengths = [{"dimension": d, "score": s, "label": d.replace("_", " ").title()} for d, s in strong_dims]
    return jsonify({
        "child_id": child_id,
        "display_name": p.get("display_name", child_id),
        "level": p.get("level", 1),
        "xp": p.get("xp", 0),
        "games_completed": p.get("games_completed", 0),
        "streak_days": p.get("streak_days", 0),
        "dimension_scores": dim_scores,
        "baseline_scores": baseline,
        "improvement": improvement,
        "game_history": game_history,
        "recommendations": recommendations,
        "strengths": strengths,
    })


