@app.patch("/api/family/parental-controls/<child_id>")
@require_auth
def set_parental_controls(child_id):
    """Set parental control settings for a specific linked child."""
    user = request.current_user
    if user.get("role") not in ("parent", "admin", "school_admin"):
        return _api_error("Forbidden", 403)
    links = _load_family_links()
    children = [l["child_id"] for l in links.get("links", []) if l.get("parent_id") == user["user_id"]]
    if child_id not in children and user.get("role") not in ("admin", "school_admin"):
        return _api_error("Not your child", 403)
    cp = player_profile.get_profile(child_id)
    if not cp:
        return _api_error("Child not found", 404)
    data = request.get_json() or {}
    controls = cp.get("parental_controls") or {}
    if "daily_time_limit_minutes" in data:
        val = data["daily_time_limit_minutes"]
        controls["daily_time_limit_minutes"] = int(val) if val is not None else None
    if "restricted_game_types" in data:
        controls["restricted_game_types"] = list(data["restricted_game_types"])
    if "notifications_enabled" in data:
        controls["notifications_enabled"] = bool(data["notifications_enabled"])
    if "bedtime_hour" in data:
        val = data["bedtime_hour"]
        controls["bedtime_hour"] = int(val) if val is not None else None
    cp["parental_controls"] = controls
    player_profile.save_profile(child_id, cp)
    return jsonify({"ok": True, "controls": controls})


