# PARENT WEEKLY DIGEST
# ═══════════════════════════════════════════════════════════════════════════

@app.get("/api/family/weekly-digest/<child_id>")
def api_weekly_digest(child_id):
    """Generate a weekly digest HTML for a parent about their child's progress.
    Can be sent via email later — for now returns viewable HTML."""
    token = get_token_from_request() or request.args.get("token")
    payload = verify_token(token) if token else None
    if not payload:
        return jsonify({"error": "Authentication required"}), 401

    child_profile = player_profile.get_profile(child_id)
    if not child_profile:
        return jsonify({"error": "Child not found"}), 404

    # Get child's display name
    child_name = child_profile.get("display_name") or child_profile.get("bio", {}).get("name") or child_id

    # This week's activity
    from datetime import datetime, timedelta
    week_ago = (datetime.now() - timedelta(days=7)).isoformat()
    recent_games = [h for h in child_profile.get("history", []) if h.get("timestamp", "") >= week_ago]

    games_this_week = len(recent_games)

    # Dimension averages
    ps = child_profile.get("psychological_scores", {})
    dims = {}
    for dim, data in ps.items():
        if isinstance(data, dict) and data.get("count", 0) > 0:
            dims[dim] = round(data["total"] / data["count"], 1)

    # Find strongest and weakest
    sorted_dims = sorted(dims.items(), key=lambda x: x[1], reverse=True)
    strongest = sorted_dims[0] if sorted_dims else ("strategic_thinking", 50)
    weakest = sorted_dims[-1] if sorted_dims else ("empathy", 50)

    DIM_LABELS = {
        'strategic_thinking': 'Strategic Thinking', 'risk_tolerance': 'Risk Tolerance',
        'delayed_gratification': 'Patience', 'adaptability': 'Adaptability',
        'resilience': 'Resilience', 'empathy': 'Empathy',
        'ethical_reasoning': 'Ethics', 'creativity': 'Creativity',
    }

    from datetime import datetime as _dt
    today = _dt.now().strftime("%B %d, %Y")

    # Build game rows
    game_list = ''
    for h in recent_games[-5:]:
        gid = h.get("game_id", "")
        game_obj = GAMES.get(gid, {})
        title = game_obj.get("title", gid)
        score = h.get("score", "—")
        game_list += f'<li style="padding:4px 0;font-size:13px;color:#2D3047">{title} — Score: {score}</li>'

    # Recommended next game
    rec_game = None
    for gid, g in GAMES.items():
        if g.get("visible") is False or g.get("game_type") not in _PUBLIC_GAME_TYPES:
            continue
        wts = g.get("dimension_scoring_weights", {})
        if wts.get(weakest[0], 0) >= 0.2:
            rec_game = g.get("title", gid)
            break

    html = f'''<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Weekly Progress — {child_name}</title></head>
<body style="font-family:'Segoe UI',system-ui,sans-serif;margin:0;padding:0;background:#FFFDF7">
<div style="max-width:500px;margin:0 auto;padding:32px 20px">
    <div style="text-align:center;margin-bottom:24px">
        <div style="font-size:10px;color:#64748B;text-transform:uppercase;letter-spacing:2px">MentoMap Weekly Digest</div>
        <h1 style="font-size:22px;color:#2D3047;margin:8px 0 4px">{child_name}'s Week</h1>
        <p style="font-size:12px;color:#64748B">{today}</p>
    </div>

    <div style="background:white;border-radius:16px;padding:20px;border:1px solid #E2E8F0;margin-bottom:16px">
        <div style="display:flex;justify-content:space-around;text-align:center">
            <div>
                <div style="font-size:28px;font-weight:900;color:#FFB300">{games_this_week}</div>
                <div style="font-size:10px;color:#64748B;font-weight:600">Games This Week</div>
            </div>
            <div>
                <div style="font-size:28px;font-weight:900;color:#10B981">{strongest[1]:.0f}</div>
                <div style="font-size:10px;color:#64748B;font-weight:600">Top Skill ({DIM_LABELS.get(strongest[0], strongest[0])})</div>
            </div>
            <div>
                <div style="font-size:28px;font-weight:900;color:#EF4444">{weakest[1]:.0f}</div>
                <div style="font-size:10px;color:#64748B;font-weight:600">Growth Area ({DIM_LABELS.get(weakest[0], weakest[0])})</div>
            </div>
        </div>
    </div>

    {'<div style="background:white;border-radius:16px;padding:16px 20px;border:1px solid #E2E8F0;margin-bottom:16px"><h3 style="font-size:13px;font-weight:700;color:#2D3047;margin:0 0 8px">Games Played</h3><ul style="margin:0;padding:0 0 0 16px">' + game_list + '</ul></div>' if game_list else ''}

    {f'<div style="background:#FFF8E7;border-radius:16px;padding:16px 20px;border:1px solid #FFD166;margin-bottom:16px"><h3 style="font-size:13px;font-weight:700;color:#92400E;margin:0 0 4px">Recommended Next</h3><p style="font-size:13px;color:#92400E;margin:0">{rec_game} — targets {DIM_LABELS.get(weakest[0], weakest[0])}</p></div>' if rec_game else ''}

    <div style="text-align:center;padding:16px 0">
        <a href="https://simulations.mentomap.com/parent-dashboard" style="display:inline-block;padding:12px 24px;background:#FFD166;color:#2D3047;border-radius:10px;font-weight:700;text-decoration:none;font-size:14px">View Full Dashboard</a>
    </div>

    <p style="text-align:center;font-size:10px;color:#CBD5E1;margin-top:16px">
        This report was generated by MentoMap &middot; simulations.mentomap.com<br>
        Email integration coming soon — this is a preview template
    </p>
</div>
</body></html>'''

    response = make_response(html)
    response.headers['Content-Type'] = 'text/html; charset=utf-8'
    return response


