@app.route("/api/teacher/student/<student_id>/accommodations", methods=["GET", "PATCH"])
@_require_teacher_or_admin
def teacher_student_accommodations(student_id):
    """Get or set learning accommodations for a student (teacher/admin only)."""
    sp = player_profile.get_profile(student_id)
    if not sp:
        return _api_error("Student not found", 404)
    if request.method == "GET":
        return jsonify(sp.get("accommodations") or {
            "extended_time": False,
            "reduced_animations": False,
            "focus_mode": False,
            "high_contrast": False,
            "notes": "",
        })
    data = request.get_json() or {}
    accommodations = sp.get("accommodations") or {}
    for key in ("extended_time", "reduced_animations", "focus_mode", "high_contrast"):
        if key in data:
            accommodations[key] = bool(data[key])
    if "notes" in data:
        accommodations["notes"] = str(data["notes"])[:500]
    sp["accommodations"] = accommodations
    player_profile.save_profile(student_id, sp)
    return jsonify({"ok": True, "accommodations": accommodations})


