@app.post("/api/profile/transfer-prompt")
@require_auth
def save_transfer_prompt():
    """Save a student's transfer prompt response after a game."""
    uid = request.current_user["user_id"]
    data = request.get_json() or {}
    game_id = str(data.get("game_id", "unknown"))
    response_text = str(data.get("response", ""))[:1000].strip()
    if not response_text:
        return jsonify({"ok": True})
    p = player_profile.get_profile(uid)
    transfers = p.get("transfer_prompts") or []
    transfers.append({
        "game_id": game_id,
        "response": response_text,
        "timestamp": datetime.now().isoformat(),
    })
    p["transfer_prompts"] = transfers[-50:]
    player_profile.save_profile(uid, p)
    return jsonify({"ok": True})


