@app.get("/api/org/members")
@require_auth
def org_list_members():
    """List teachers/HR in the caller's org."""
    user = request.current_user
    org_id = user.get("org_id", "default")
    from auth import _load_users as _get_users
    try:
        all_users = _get_users()
    except Exception:
        return jsonify({"members": []})
    members = [
        {"user_id": u.get("id", u.get("username")), "username": u.get("username"), "display_name": u.get("display_name", u.get("username")), "role": u.get("role")}
        for u in all_users
        if u.get("org_id") == org_id and u.get("role") in ("teacher", "hr", "school_admin", "trainer")
    ]
    return jsonify({"members": members, "org_id": org_id})


@app.post("/api/teacher/cohorts/<cohort_id>/invite-parent")
@_require_teacher_or_admin
def teacher_invite_parent(cohort_id):
    """Teacher adds a parent account for a student in their cohort."""
    from auth import get_user_by_username as _get_by_uname
    data = request.get_json(silent=True) or {}
    parent_username = data.get("parent_username", "").strip()
    student_id = data.get("student_id", "").strip()
    if not parent_username or not student_id:
        return _api_error("parent_username and student_id required", 400)
    parent = _get_by_uname(parent_username)
    if not parent:
        return _api_error("Parent account not found. They must register first.", 404)
    if parent.get("role") != "parent":
        return _api_error("That account is not a parent role", 400)
    # Add the family link on behalf of the parent
    links = _load_family_links()
    existing = next((l for l in links.get("links", []) if l["parent_id"] == parent["user_id"] and l["child_id"] == student_id), None)
    if existing:
        return jsonify({"ok": True, "already_linked": True})
    from datetime import datetime as _dt_inv
    links.setdefault("links", []).append({
        "parent_id": parent["user_id"],
        "child_id": student_id,
        "child_display_name": student_id,
        "linked_at": _dt_inv.utcnow().isoformat(),
        "invited_by_teacher": True,
    })
    _save_family_links(links)
    return jsonify({"ok": True, "linked": True})


