# ── Teacher: Simulation Orchestration ─────────────────────────────────────
# Teachers can launch simulation sessions, track student progress, and control pacing.

_SIM_SESSIONS_FILE = os.path.join(os.path.dirname(__file__), "data", "simulation_sessions.json")


def _load_sim_sessions():
    try:
        with open(_SIM_SESSIONS_FILE) as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def _save_sim_sessions(data):
    os.makedirs(os.path.dirname(_SIM_SESSIONS_FILE), exist_ok=True)
    with open(_SIM_SESSIONS_FILE, "w") as f:
        json.dump(data, f, indent=2)


@app.post("/api/teacher/simulation/launch")
@_require_teacher_or_admin
def teacher_launch_simulation():
    """Teacher launches a simulation session for a cohort/class.

    Body: { game_id, cohort_id?, title?, max_students? }
    Returns: { session_id, join_code }
    """
    data = request.get_json() or {}
    game_id = data.get("game_id")
    if not game_id:
        return jsonify({"error": "game_id is required"}), 400

    game, err = get_game_or_400(game_id)
    if err:
        return err

    if game.get("game_type") != "simulation":
        return jsonify({"error": "This game is not a simulation type"}), 400

    user = request.current_user
    import random, string
    session_id = ''.join(random.choices(string.ascii_uppercase + string.digits, k=6))
    join_code = ''.join(random.choices(string.digits, k=4))

    sim_session = {
        "session_id": session_id,
        "join_code": join_code,
        "game_id": game_id,
        "game_title": game.get("title", game_id),
        "teacher_id": user.get("user_id", ""),
        "teacher_name": user.get("username", ""),
        "cohort_id": data.get("cohort_id"),
        "title": data.get("title", f"{game.get('title', 'Simulation')} - Live Session"),
        "max_students": data.get("max_students", 40),
        "status": "waiting",  # waiting → active → paused → completed
        "students": {},  # { user_id: { run_id, name, current_round, status } }
        "created_at": datetime.now().isoformat(),
        "started_at": None,
        "completed_at": None,
    }

    sessions = _load_sim_sessions()
    sessions[session_id] = sim_session
    _save_sim_sessions(sessions)

    return jsonify({
        "session_id": session_id,
        "join_code": join_code,
        "title": sim_session["title"],
        "game_title": sim_session["game_title"],
    })


@app.post("/api/teacher/simulation/<session_id>/control")
@_require_teacher_or_admin
def teacher_control_simulation(session_id):
    """Teacher controls simulation: start, pause, resume, end.

    Body: { action: "start" | "pause" | "resume" | "end" }
    """
    data = request.get_json() or {}
    action = data.get("action")
    if action not in ("start", "pause", "resume", "end"):
        return jsonify({"error": "Invalid action"}), 400

    sessions = _load_sim_sessions()
    s = sessions.get(session_id)
    if not s:
        return jsonify({"error": "Session not found"}), 404

    if action == "start":
        s["status"] = "active"
        s["started_at"] = datetime.now().isoformat()
    elif action == "pause":
        s["status"] = "paused"
    elif action == "resume":
        s["status"] = "active"
    elif action == "end":
        s["status"] = "completed"
        s["completed_at"] = datetime.now().isoformat()

    sessions[session_id] = s
    _save_sim_sessions(sessions)
    return jsonify({"status": s["status"], "session_id": session_id})


@app.get("/api/teacher/simulation/<session_id>")
@_require_teacher_or_admin
def teacher_get_simulation(session_id):
    """Get simulation session details + all student progress."""
    sessions = _load_sim_sessions()
    s = sessions.get(session_id)
    if not s:
        return jsonify({"error": "Session not found"}), 404
    return jsonify(s)


@app.get("/api/teacher/simulations")
@_require_teacher_or_admin
def teacher_list_simulations():
    """List all simulation sessions for this teacher."""
    user = request.current_user
    sessions = _load_sim_sessions()
    teacher_sessions = [s for s in sessions.values() if s.get("teacher_id") == user.get("user_id")]
    # Sort by created_at desc
    teacher_sessions.sort(key=lambda x: x.get("created_at", ""), reverse=True)
    return jsonify({"sessions": teacher_sessions})


@app.post("/api/simulation/join")
@require_auth
def student_join_simulation():
    """Student joins a simulation session via join_code.

    Body: { join_code }
    Returns: { session_id, game_id, run_id }
    """
    data = request.get_json() or {}
    join_code = data.get("join_code", "").strip()
    if not join_code:
        return jsonify({"error": "join_code is required"}), 400

    sessions = _load_sim_sessions()
    target_session = None
    for s in sessions.values():
        if s.get("join_code") == join_code and s.get("status") in ("waiting", "active"):
            target_session = s
            break

    if not target_session:
        return jsonify({"error": "Invalid or expired join code"}), 404

    user = request.current_user
    user_id = user.get("user_id", "")
    session_id = target_session["session_id"]

    # Check if already joined
    if user_id in target_session.get("students", {}):
        existing = target_session["students"][user_id]
        return jsonify({
            "session_id": session_id,
            "game_id": target_session["game_id"],
            "run_id": existing.get("run_id"),
            "already_joined": True,
        })

    # Check max students
    if len(target_session.get("students", {})) >= target_session.get("max_students", 40):
        return jsonify({"error": "Session is full"}), 403

    # Create a game run for this student
    game_id = target_session["game_id"]
    game, err = get_game_or_400(game_id)
    if err:
        return err

    run_id = create_run(game_id, game["initial_state"], game)

    # Register student in session
    target_session.setdefault("students", {})[user_id] = {
        "run_id": run_id,
        "name": user.get("username", user_id),
        "current_round": 0,
        "status": "playing",
        "joined_at": datetime.now().isoformat(),
    }

    sessions[session_id] = target_session
    _save_sim_sessions(sessions)

    return jsonify({
        "session_id": session_id,
        "game_id": game_id,
        "run_id": run_id,
        "game_title": target_session.get("game_title", ""),
        "session_title": target_session.get("title", ""),
    })


