@app.get("/api/student/courses/<course_id>/certificate")
@require_auth
def student_get_certificate(course_id):
    user = request.current_user
    enrollment = _ce.get_enrollment(course_id, user["user_id"])
    if not enrollment:
        return _api_error("Not enrolled", 403)
    if not enrollment.get("completed"):
        return _api_error("Course not yet completed", 400)
    course = _ce.get_course(course_id)
    if not course:
        return _api_error("Course not found", 404)
    # Get student display name
    try:
        import player_profile as _pp
        p = _pp.get_profile(user["user_id"])
        student_name = p.get("display_name") or p.get("first_name") or user.get("username", "Student")
    except Exception:
        student_name = user.get("username", "Student")
    # Get org name
    try:
        from organizations import get_organization as _get_org
        org = _get_org(user.get("org_id", "default"))
        org_name = org.get("name", "Mento") if org else "Mento"
    except Exception:
        org_name = "Mento"
    try:
        pdf_bytes = _ce.generate_certificate_pdf(course_id, user["user_id"], student_name, org_name)
        from flask import Response
        return Response(
            pdf_bytes,
            mimetype="application/pdf",
            headers={"Content-Disposition": f'attachment; filename="certificate-{course_id}.pdf"'}
        )
    except ImportError as e:
        return _api_error(str(e), 500)
    except Exception as e:
        logger.error(f"Certificate generation error: {e}")
        return _api_error("Failed to generate certificate", 500)


