def _load_curriculum_templates():
    """Load curriculum templates from data/curriculum_templates.json."""
    try:
        import json as _json
        path = os.path.join(os.path.dirname(__file__), "data", "curriculum_templates.json")
        with open(path) as f:
            return _json.load(f).get("templates", [])
    except Exception as e:
        logger.error("Failed to load curriculum templates: %s", e)
        return []


@app.get("/api/curriculum/templates")
@require_auth
def curriculum_list_templates():
    """List all available curriculum templates (Grade 6, 7, 8)."""
    templates = _load_curriculum_templates()
    # Enrich with game availability — check which games actually exist
    load_bundle()
    existing_ids = {g["game_id"] for g in BUNDLE.get("games", [])}
    for tpl in templates:
        available = 0
        total = len(tpl.get("months", []))
        for m in tpl.get("months", []):
            if m.get("game_id") in existing_ids:
                available += 1
                m["available"] = True
            else:
                m["available"] = False
        tpl["games_available"] = available
        tpl["games_total"] = total
    return jsonify({"templates": templates})


@app.get("/api/curriculum/templates/<template_id>")
@require_auth
def curriculum_get_template(template_id):
    """Get a specific curriculum template by ID."""
    templates = _load_curriculum_templates()
    tpl = next((t for t in templates if t["id"] == template_id), None)
    if not tpl:
        return _api_error("Curriculum template not found", 404)
    # Enrich with game details
    load_bundle()
    games_map = {g["game_id"]: g for g in BUNDLE.get("games", [])}
    for m in tpl.get("months", []):
        gid = m.get("game_id")
        g = games_map.get(gid)
        if g:
            m["available"] = True
            m["game_title"] = g.get("title", "")
            m["game_description"] = g.get("description", "")
            m["game_icon"] = g.get("icon", "")
            m["game_type"] = g.get("game_type", "simulation")
            m["difficulty"] = g.get("difficulty", "")
            m["duration_minutes"] = g.get("duration_minutes", 0) or g.get("estimated_duration_minutes", 0)
            m["round_count"] = len(g.get("rounds", []))
        else:
            m["available"] = False
    return jsonify({"template": tpl})


@app.post("/api/teacher/curriculum/deploy")
@_require_teacher_or_admin
def teacher_deploy_curriculum():
    """Deploy a curriculum template as a course.

    Creates a course from the template with one section per month,
    each containing the monthly game as a course item.
    Optionally enrolls a cohort immediately.
    """
    user = request.current_user
    data = request.get_json(silent=True) or {}
    template_id = data.get("template_id")
    cohort_id = data.get("cohort_id")  # optional — enroll cohort immediately
    custom_title = data.get("title")  # optional override

    if not template_id:
        return _api_error("template_id required", 400)

    templates = _load_curriculum_templates()
    tpl = next((t for t in templates if t["id"] == template_id), None)
    if not tpl:
        return _api_error("Template not found", 404)

    # Build course sections from months
    import uuid as _uuid_mod
    sections = []
    for m in tpl.get("months", []):
        item_id = "item_" + str(_uuid_mod.uuid4())[:8]
        section = {
            "id": "sec_" + str(_uuid_mod.uuid4())[:8],
            "title": f"{m['label']}: {m['theme']}",
            "description": m.get("description", ""),
            "items": [
                {
                    "id": item_id,
                    "title": m.get("title", m.get("game_id", "")),
                    "type": "game",
                    "game_id": m.get("game_id"),
                    "required": True,
                    "estimated_minutes": 30,
                }
            ]
        }
        sections.append(section)

    course_data = {
        "title": custom_title or tpl.get("title", "Curriculum"),
        "subject": "Life Skills & Soft Skills",
        "grade_level": f"Grade {tpl.get('grade', '')}",
        "description": tpl.get("description", ""),
        "thumbnail_emoji": tpl.get("icon", "📚"),
        "learning_outcomes": tpl.get("learning_outcomes", []),
        "pass_threshold": 60,
        "sections": sections,
        "curriculum_template_id": template_id,
    }

    course = _ce.create_course(user["user_id"], user.get("org_id", "default"), course_data)
    if not course:
        return _api_error("Failed to create course", 500)

    # Auto-publish so students can see it immediately
    published_course = _ce.publish_course(course["id"], user["user_id"]) or course
    published_course["published"] = True

    # Optionally enroll a cohort
    enrollment_result = None
    if cohort_id:
        try:
            cohort_data = _load_cohorts()
            cohort = next((c for c in cohort_data.get("cohorts", []) if c["id"] == cohort_id), None)
            if cohort:
                student_ids = cohort.get("students", [])
                if student_ids:
                    enrollment_result = _ce.enroll_cohort(published_course["id"], student_ids, user["user_id"])
        except Exception as e:
            logger.error("Curriculum deploy enroll error: %s", e)

    return jsonify({
        "course": published_course,
        "deployed": True,
        "enrollment": enrollment_result,
    }), 201


