# ── Hook: mark course item complete when a game run finishes ──────────────

def _check_course_progress_on_game_complete(user_id: str, game_id: str, run_id: str, score: int):
    """Called from report endpoint — if game belongs to an active course, mark item complete."""
    try:
        enrollments = _ce.list_student_enrollments(user_id)
        for enr in enrollments:
            if enr.get("completed"):
                continue
            course = _ce.get_course(enr["course_id"])
            if not course:
                continue
            for section in course.get("sections", []):
                for item in section.get("items", []):
                    if item.get("game_id") == game_id and item.get("type") in ("game", "exam"):
                        # Check if already completed
                        prog = _ce.get_student_progress(enr["course_id"], user_id)
                        completions = prog.get("item_completions", {})
                        if not completions.get(item["id"], {}).get("completed"):
                            _ce.mark_item_complete(enr["course_id"], user_id, item["id"],
                                                   score=score, game_run_id=run_id)
                            return  # only match first
    except Exception as _e:
        pass  # never crash the report endpoint


