@app.post("/api/admin/research/assign-cohort")
@require_admin
def api_assign_research_cohort():
    """Assign students to a research cohort that includes pre/post TEIQue assessment."""
    data = request.get_json(silent=True) or {}
    student_ids = data.get("student_ids", [])
    cohort_name = data.get("cohort_name", "research_pilot")
    games_target = data.get("games_target", 5)

    if not student_ids:
        return jsonify({"error": "student_ids required"}), 400

    profiles = player_profile._load_profiles()
    assigned = 0
    for uid in student_ids:
        p = player_profile._ensure_profile(profiles, uid)
        p["research_cohort"] = cohort_name
        p["research_pre_test_complete"] = False
        p["research_post_test_complete"] = False
        p["research_games_target"] = games_target
        assigned += 1
    player_profile._save_profiles(profiles)

    return jsonify({"assigned": assigned, "cohort": cohort_name, "games_target": games_target})


@app.get("/api/research/status")
def api_research_status():
    """Check if current user is in a research cohort and needs pre/post assessment."""
    token = get_token_from_request()
    payload = verify_token(token) if token else None
    if not payload:
        return jsonify({"in_research": False})

    profile = player_profile.get_profile(payload["user_id"])
    cohort = profile.get("research_cohort")
    if not cohort:
        return jsonify({"in_research": False})

    pre_done = profile.get("research_pre_test_complete", False)
    post_done = profile.get("research_post_test_complete", False)
    games_since_pre = profile.get("games_completed", 0) - profile.get("research_pre_test_games", 0)
    games_target = profile.get("research_games_target", 5)

    needs_pre = not pre_done
    needs_post = pre_done and not post_done and games_since_pre >= games_target

    return jsonify({
        "in_research": True,
        "cohort": cohort,
        "pre_test_complete": pre_done,
        "post_test_complete": post_done,
        "needs_pre_test": needs_pre,
        "needs_post_test": needs_post,
        "games_since_pre": games_since_pre,
        "games_target": games_target,
        "survey_game_id": "teique-sf-survey",
    })


@app.get("/api/admin/research/export-csv")
@require_admin
def api_research_export_csv():
    """Export all student profiles with dimension scores + TEIQue pre/post as CSV for research."""
    import csv
    import io
    import math

    profiles = player_profile._load_profiles()
    users_file = os.path.join(os.path.dirname(__file__), "data", "users.json")
    try:
        with open(users_file) as f:
            users = json.load(f)
    except Exception:
        users = {}

    DIM_COLS = ["strategic_thinking", "risk_tolerance", "delayed_gratification",
                "adaptability", "resilience", "empathy", "ethical_reasoning", "creativity"]
    TEIQUE_COLS = ["wellbeing_score", "self_control_score", "emotionality_score",
                   "sociability_score", "global_ei_score"]

    output = io.StringIO()
    writer = csv.writer(output)

    header = ["user_id", "username", "role", "games_completed", "level", "xp", "streak_days",
              "research_cohort", "pre_test_complete", "post_test_complete"]
    header += [f"avg_{d}" for d in DIM_COLS]
    header += [f"pre_{t}" for t in TEIQUE_COLS]
    header += [f"post_{t}" for t in TEIQUE_COLS]
    header += ["pre_test_date", "post_test_date"]
    writer.writerow(header)

    for uid, p in profiles.items():
        user = users.get(uid, {})
        ps = p.get("psychological_scores", {})
        avg_dims = {}
        for d in DIM_COLS:
            data = ps.get(d, {})
            if isinstance(data, dict) and data.get("count", 0) > 0:
                avg_dims[d] = round(data["total"] / max(1, data["count"]), 1)
            else:
                avg_dims[d] = ""

        pre_scores = p.get("research_pre_test_scores", {})
        post_scores = p.get("research_post_test_scores", {})

        xp_val = p.get("xp", 0)
        level = math.floor(math.sqrt(xp_val / 50)) if xp_val >= 50 else 0

        row = [
            uid, user.get("username", ""), user.get("role", ""),
            p.get("games_completed", 0), level, xp_val,
            p.get("streak_days", 0),
            p.get("research_cohort", ""),
            p.get("research_pre_test_complete", False),
            p.get("research_post_test_complete", False),
        ]
        row += [avg_dims.get(d, "") for d in DIM_COLS]
        row += [pre_scores.get(t, "") for t in TEIQUE_COLS]
        row += [post_scores.get(t, "") for t in TEIQUE_COLS]
        row += [p.get("research_pre_test_date", ""), p.get("research_post_test_date", "")]
        writer.writerow(row)

    response = make_response(output.getvalue())
    response.headers["Content-Type"] = "text/csv"
    response.headers["Content-Disposition"] = "attachment; filename=mentoapp_research_export.csv"
    return response


