def _v2_get_user_id() -> str:
    """Pull user_id from JWT if present, else empty."""
    try:
        _tok = get_token_from_request()
        _u = verify_token(_tok) if _tok else None
        return (_u or {}).get("user_id", "") or ""
    except Exception:
        return ""


@app.post("/api/v2/run/<run_id>/init")
def v2_run_init(run_id):
    """
    Apply V2 mode/persona/legacy overrides to a just-started run.
    Payload: {"mode_id": "...", "persona_id": "...", "daily_challenge_id": "..."}
    Must be called BEFORE the first /api/run/.../choose.
    """
    try:
        from engines import v2_engine
    except Exception as e:
        return jsonify({"error": f"v2_engine unavailable: {e}"}), 500
    try:
        r = get_run(run_id)
    except Exception:
        return jsonify({"error": "Session not found"}), 404

    game = r.get("game") or get_game_or_400(r.get("game_id", ""))[0] or {}
    if not v2_engine.is_v2(game):
        return jsonify({"v2": False, "applied": []})

    body = request.get_json(silent=True) or {}
    mode_id = body.get("mode_id")
    persona_id = body.get("persona_id")
    daily_id = body.get("daily_challenge_id")
    user_id = _v2_get_user_id()

    state_obj = r.get("state")
    if state_obj is None:
        return jsonify({"error": "Run state missing"}), 500

    meta = v2_engine.apply_start_overrides(
        state_obj, game, mode_id=mode_id, persona_id=persona_id, user_id=user_id,
    )
    # Deterministic scoring profile
    prof = v2_engine.select_scoring_profile_seeded(game, run_id=run_id, mode_id=mode_id or "classic")
    if prof is not None:
        try:
            setattr(state_obj, "_sim_scoring_profile", prof)
        except Exception:
            pass

    # Store V2 run metadata
    r.setdefault("_v2", {})
    r["_v2"].update({
        "mode_id": mode_id,
        "persona_id": persona_id,
        "daily_challenge_id": daily_id,
        "meta": meta,
        "scoring_profile": prof,
        "rival_state": ((game.get("simulation_config") or {}).get("dynamic_rival") or {}).get("initial_state") or {},
    })
    update_run(run_id, r)

    return jsonify({
        "v2": True,
        "meta": meta,
        "scoring_profile": prof,
        "state": state_to_dict(state_obj),
    })


@app.get("/api/v2/run/<run_id>/post-tick")
def v2_run_post_tick(run_id):
    """
    Evaluate V2 achievements/mastery/rival/snapshots for the current tick.
    Frontend calls this after each /api/run/.../choose.
    """
    try:
        from engines import v2_engine
    except Exception as e:
        return jsonify({"error": f"v2_engine unavailable: {e}"}), 500
    try:
        r = get_run(run_id)
    except Exception:
        return jsonify({"error": "Session not found"}), 404

    game = r.get("game") or get_game_or_400(r.get("game_id", ""))[0] or {}
    if not v2_engine.is_v2(game):
        return jsonify({"v2": False})

    state_obj = r.get("state")
    if state_obj is None:
        return jsonify({"error": "Run state missing"}), 500

    round_index = getattr(state_obj, "round_index", 0)
    prev_rival = (r.get("_v2") or {}).get("rival_state") or {}
    user_id = _v2_get_user_id()

    result = v2_engine.evaluate_post_tick(
        state_obj, game, user_id=user_id, round_index=round_index, prev_rival_state=prev_rival,
    )
    # Persist rival state forward
    if result.get("rival"):
        r.setdefault("_v2", {})["rival_state"] = result["rival"].get("state") or prev_rival
        update_run(run_id, r)

    return jsonify({"v2": True, **result})


