@app.post("/api/run/<run_id>/apply-mid-round-reward")
@app.post("/api/v2/run/<run_id>/minigame-reward")
def v2_minigame_reward(run_id):
    """Apply a between-rounds minigame reward to the run's state.

    Persists resource deltas (reputation/players/money/etc.) so they survive
    refresh, and emits a chat entry into sim_news_feed so the player can see
    the connection between the minigame and the gameplay.
    Payload: {"minigame_id": "...", "label": "...", "reward": {"reputation": 5, ...}}
    """
    try:
        run = storage.get_run(run_id)
    except Exception:
        return jsonify({"error": "Session not found"}), 404
    if not run:
        return jsonify({"error": "Run not found"}), 404

    body = request.get_json(silent=True) or {}
    reward = body.get("reward") or {}
    label = (body.get("label") or "Minigame complete").strip()
    mg_id = body.get("minigame_id") or "minigame"
    if not isinstance(reward, dict):
        return jsonify({"error": "reward must be an object"}), 400

    state_obj = run.get("state")
    if state_obj is None:
        return jsonify({"error": "Run state missing"}), 500

    game = run.get("game") or get_game_or_400(run.get("game_id", ""))[0] or {}
    resource_meta = (game.get("resource_metadata") or {})

    applied = {}  # {resource: {"delta": d, "before": b, "after": a}}
    for k, v in reward.items():
        try:
            v = int(v)
        except (TypeError, ValueError):
            continue
        if v == 0:
            continue
        cur = int(getattr(state_obj, k, 0) or 0)
        meta = resource_meta.get(k) or {}
        lo = int(meta.get("min", 0))
        hi = int(meta.get("max", 10_000))
        new_val = max(lo, min(hi, cur + v))
        try:
            setattr(state_obj, k, new_val)
            applied[k] = {"delta": new_val - cur, "before": cur, "after": new_val}
        except Exception:
            continue

    # Spec #17 — chat entry shows before → after, not just delta.
    try:
        feed = list(getattr(state_obj, "sim_news_feed", []) or [])
        week = max(1, int(getattr(state_obj, "sim_tick", 0) or 0))
        if applied:
            parts = []
            for k, info in applied.items():
                d = info["delta"]
                lab = (resource_meta.get(k) or {}).get("label") or k.replace("_", " ").title()
                sign = "+" if d > 0 else ""
                parts.append(f"{lab} {info['before']} → {info['after']} ({sign}{d})")
            delta_str = "; ".join(parts)
        else:
            delta_str = "no resource change"
        feed.insert(0, {
            "type": "system",
            "icon": "🎯",
            "text": f"🎮 {label} — {delta_str}",
            "severity": "positive" if any(info["delta"] > 0 for info in applied.values()) else "info",
            "tick": int(getattr(state_obj, "sim_tick", 0) or 0),
            "week": week,
            "week_title": f"Week {week}",
        })
        state_obj.sim_news_feed = feed[:200]
    except Exception:
        pass

    try:
        # Track which minigames have fired so a refresh doesn't re-trigger them
        completed = list(getattr(state_obj, "minigames_completed", []) or [])
        if mg_id not in completed:
            completed.append(mg_id)
        state_obj.minigames_completed = completed
    except Exception:
        pass

    try:
        storage.update_run(run_id, run)
    except Exception:
        pass

    return jsonify({
        "applied": applied,
        "state": state_to_dict(state_obj) if 'state_to_dict' in globals() else None,
    })


# ─────────────────────────────────────────────────────────────────────
# Spec #5 — choice preview: project the post-tick state for each choice
#   so the UI can show players the EXPECTED net delta, not the choice's
#   intent (which can drift from reality once tick rules + decay fire).
# ─────────────────────────────────────────────────────────────────────
@app.get("/api/run/<run_id>/choice-preview")
def choice_preview(run_id):
    """Return per-choice projected money/players/reputation after tick rules
    fire. Pure read — does not mutate the run."""
    try:
        run = storage.get_run(run_id)
    except Exception:
        return jsonify({"error": "Session not found"}), 404
    if not run:
        return jsonify({"error": "Run not found"}), 404
    game = run.get("game") or get_game_or_400(run.get("game_id", ""))[0] or {}
    if not game.get("simulation_config"):
        return jsonify({"previews": []})

    state_obj = run.get("state")
    if state_obj is None:
        return jsonify({"previews": []})
    rounds = game.get("rounds") or []
    ri = int(getattr(state_obj, "round_index", 0) or 0)
    if ri >= len(rounds):
        return jsonify({"previews": []})
    cur_round = rounds[ri]
    choices = cur_round.get("choices") or []

    # Snapshot the resources we'll project on
    snap_keys = ["money", "players", "reputation", "expenses", "ethics_fairness"]
    base = {k: int(getattr(state_obj, k, 0) or 0) for k in snap_keys}

    previews = []
    for c in choices:
        # Authored delta (immediate)
        delta = c.get("delta") or {}
        proj = dict(base)
        for k, v in delta.items():
            if k in proj:
                try: proj[k] = proj[k] + int(v)
                except Exception: pass

        # Add weekly_dues_income tick-rule projection if applicable
        tick_rules = ((game.get("simulation_config") or {}).get("tick_rules") or [])
        for rule in tick_rules:
            if rule.get("id") == "weekly_dues_income" and proj.get("players", 0) > 0:
                # players * 50 income, minus expenses
                inc = proj["players"] * 50
                exp = proj.get("expenses", 0)
                proj["money"] = min(10000, proj.get("money", 0) + inc - exp)
            if rule.get("id") == "capacity_strain" and proj.get("players", 0) > 20:
                proj["reputation"] = max(0, proj.get("reputation", 0) - 2)

        previews.append({
            "id": c.get("id"),
            "projected": proj,
            "delta_from_now": {k: proj[k] - base[k] for k in snap_keys if k in proj},
        })

    return jsonify({"previews": previews, "current": base})


