# Framework authoring & grading (OKR / SWOT / Porter / BCG)
# Used by the executive UX widgets to let players actively *fill in*
# strategy artifacts during gameplay (vs the previous read-only view).
# ════════════════════════════════════════════════════════════════════

@app.get("/api/framework/<framework_type>/schema")
def framework_schema(framework_type):
    """Return the editor schema for a framework type (used by author modal)."""
    try:
        from framework_grader import get_framework_schema
        schema = get_framework_schema(framework_type)
        if not schema:
            return jsonify({"error": f"Unknown framework type: {framework_type}"}), 404
        return jsonify({"schema": schema})
    except Exception as e:
        logger.exception("framework_schema failed")
        return jsonify({"error": str(e)}), 500


@app.post("/api/run/<run_id>/framework/<fid>/save")
def save_framework_artifact_route(run_id, fid):
    """Save a framework artifact (no grading). Player can save drafts."""
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Resource not found"}), 404
    body = request.get_json(silent=True) or {}
    user_data = body.get("user_data") or {}
    if not isinstance(user_data, dict):
        return jsonify({"error": "user_data must be an object"}), 400

    state_obj = r["state"]
    try:
        from datetime import datetime as _dt_fw, timezone as _tz_fw
        from engines.executive_ux import save_framework_artifact
        # Preserve existing graded_score if present, but stamp new edit time
        existing = (getattr(state_obj, "artifacts", {}) or {}).get(fid) or {}
        merged = dict(existing)
        merged.update(user_data)
        merged.setdefault("type", body.get("type"))
        merged["last_saved_at"] = _dt_fw.now(_tz_fw.utc).isoformat()
        # Editing invalidates the previous grade
        merged.pop("graded_score", None)
        merged.pop("grade_detail", None)
        save_framework_artifact(state_obj, fid, merged)
        save_run(run_id, r)
        return jsonify({"saved": True, "artifact": merged})
    except Exception as e:
        logger.exception("save_framework_artifact failed")
        return jsonify({"error": str(e)}), 500


@app.post("/api/run/<run_id>/framework/<fid>/grade")
def grade_framework_artifact_route(run_id, fid):
    """Grade the current framework artifact via LLM (or heuristic fallback)."""
    try:
        r = get_run(run_id)
    except KeyError:
        return jsonify({"error": "Resource not found"}), 404
    body = request.get_json(silent=True) or {}
    framework_type = (body.get("type") or "").lower().strip()
    user_data = body.get("user_data")

    state_obj = r["state"]
    game_id = r.get("game_id")
    game = GAMES.get(game_id) or {}

    try:
        from framework_grader import grade_framework
        from engines.executive_ux import save_framework_artifact

        # Fall back to stored artifact if user_data not in body
        if not isinstance(user_data, dict):
            stored = (getattr(state_obj, "artifacts", {}) or {}).get(fid) or {}
            user_data = stored
        if not framework_type:
            # Look up from game's frameworks config
            fws = ((game.get("simulation_config") or {}).get("frameworks")) or []
            framework_type = next((f.get("type") for f in fws if f.get("id") == fid), "")

        # Build context for grader (game stage, ARR, runway, industry)
        ctx = {
            "game_title": game.get("title") or game.get("game_id"),
            "industry":   ((game.get("simulation_config") or {}).get("industry_benchmark_model")),
            "stage":      game.get("difficulty"),
        }
        try:
            ux_exec = _build_executive_payload(state_obj, game, None) or {}
            fin = (ux_exec.get("finance") or {})
            ctx["finance"] = {
                "arr": (fin.get("pnl") or {}).get("arr"),
                "runway_months": (fin.get("unit_economics") or {}).get("runway_months"),
            }
        except Exception:
            pass

        result = grade_framework(framework_type, user_data, ctx)

        # Persist grade onto the artifact
        existing = (getattr(state_obj, "artifacts", {}) or {}).get(fid) or {}
        merged = dict(existing)
        merged.update(user_data or {})
        merged["graded_score"] = result.get("score", 0)
        merged["grade_detail"] = result
        merged["type"] = framework_type
        save_framework_artifact(state_obj, fid, merged)
        save_run(run_id, r)
        return jsonify({"graded": True, "result": result, "artifact": merged})
    except Exception as e:
        logger.exception("grade_framework_artifact failed")
        return jsonify({"error": str(e)}), 500


@app.get("/api/exec/<game_id>/multiplayer/roles")
def exec_multiplayer_roles(game_id):
    """Return the configured multiplayer roles for an executive game (used by
    the multiplayer lobby to let a player pick CEO/CFO/etc.). Falls back to
    a sensible default set if the game doesn't declare roles."""
    try:
        game_path = os.path.join(GAMES_DIR, f"{game_id}.json")
        if not os.path.exists(game_path):
            return jsonify({"error": "game not found"}), 404
        with open(game_path) as f:
            game = json.load(f)
        from engines.executive_ux import get_multiplayer_roles
        roles = get_multiplayer_roles(game)
        if roles is None:
            # Fall back to a default 3-role set suitable for any exec sim
            roles = [
                {"id": "ceo", "label": "CEO", "description": "Vision, board, talent, capital"},
                {"id": "cfo", "label": "CFO", "description": "Cash, P&L, audit, covenants"},
                {"id": "vc",  "label": "Lead Investor", "description": "Board, follow-on, governance"},
            ]
        return jsonify({"game_id": game_id, "roles": roles})
    except Exception as e:
        logger.exception("exec_multiplayer_roles failed")
        return jsonify({"error": str(e)}), 500


