import modules_engine as _modules_engine  # noqa: E402


def _module_user_id() -> str:
    """Return the JWT user_id (username fallback) for the current request."""
    user = getattr(request, "current_user", None) or {}
    return str(user.get("user_id") or user.get("username") or "")


@app.get("/api/modules")
@require_auth
def api_modules_list():
    """List all available modules. Optional ?grade=7 filter."""
    user = request.current_user
    grade = request.args.get("grade")
    org_id = user.get("org_id")
    try:
        modules = _modules_engine.list_modules(org_id=org_id, grade=grade)

        # Attach lightweight user progress summary so the list view can show
        # "Continue" / "Start" / "Completed" badges without an extra round-trip.
        uid = _module_user_id()
        if uid:
            user_modules = _modules_engine.list_user_modules(uid)
            for m in modules:
                p = user_modules.get(m["module_id"])
                if p:
                    full = _modules_engine.get_module(m["module_id"])
                    if full:
                        m["my_progress"] = _modules_engine.compute_progress_summary(p, full)

        return jsonify({"modules": modules, "total": len(modules)})
    except Exception as e:
        logger.exception("api_modules_list failed")
        return jsonify({"error": str(e)}), 500


@app.get("/api/modules/<module_id>")
@require_auth
def api_module_get(module_id):
    """Return full module JSON + caller's progress."""
    module = _modules_engine.get_module(module_id)
    if not module:
        return jsonify({"error": "Module not found"}), 404
    uid = _module_user_id()
    progress = _modules_engine.get_user_progress(uid, module_id) if uid else None
    summary = _modules_engine.compute_progress_summary(progress, module) if progress else None
    return jsonify({"module": module, "progress": progress, "summary": summary})


