@app.post("/api/modules/<module_id>/lessons/<lesson_id>/complete")
@require_auth
def api_module_lesson_complete(module_id, lesson_id):
    """Mark a lesson complete and advance the pointer."""
    uid = _module_user_id()
    if not uid:
        return jsonify({"error": "Authentication required"}), 401
    body = request.get_json(silent=True) or {}
    payload = {
        "answers": body.get("answers"),
        "run_id": body.get("run_id"),
        "time_spent_seconds": body.get("time_spent_seconds"),
        # Quiz/assessment fields — backend validates against pass_threshold.
        "score": body.get("score"),
        "max_score": body.get("max_score"),
        "passed": body.get("passed"),
    }
    try:
        # Snapshot whether this lesson was already complete BEFORE we record it,
        # so we only award per-lesson XP on the *first* completion.
        prior_progress = _modules_engine.get_user_progress(uid, module_id) or {}
        prior_completed = set(prior_progress.get("completed_lesson_ids") or [])
        was_already_complete = lesson_id in prior_completed

        try:
            progress = _modules_engine.complete_lesson(uid, module_id, lesson_id, payload)
        except PermissionError as pe:
            return jsonify({"error": str(pe), "locked": True}), 403
        module = _modules_engine.get_module(module_id)
        summary = _modules_engine.compute_progress_summary(progress, module)

        # If the lesson is a quiz that didn't pass, surface that to the client.
        quiz_record = (progress.get("quizzes") or {}).get(lesson_id) or {}
        if quiz_record and not quiz_record.get("passed", True):
            return jsonify({
                "ok": False,
                "quiz_failed": True,
                "quiz": quiz_record,
                "summary": summary,
                "message": "You need to pass this checkpoint to unlock the next week.",
            }), 200

        # ── Per-lesson XP + Mento coaching ─────────────────────────────────
        # Find the lesson in the module so we can pick a sensible XP amount,
        # surface its coaching_moment, and report the skills it trains.
        active_lesson = None
        for w in (module or {}).get("weeks", []) or []:
            for l in (w.get("lessons") or []):
                if l.get("lesson_id") == lesson_id:
                    active_lesson = l
                    break
            if active_lesson:
                break

        # XP scale by lesson type (only awarded on the FIRST completion).
        XP_BY_TYPE = {
            "lesson":     15,
            "worksheet":  30,
            "reflection": 25,
            "quiz":       20,
            "game":       50,
            "assessment": 60,
            "field_mission": 40,
        }
        xp_awarded = 0
        if active_lesson and not was_already_complete:
            xp_awarded = int(active_lesson.get("xp")
                             or XP_BY_TYPE.get(active_lesson.get("type", "lesson"), 15))
            try:
                from player_profile import award_xp  # noqa: WPS433
                award_xp(
                    uid, xp_awarded,
                    reason=f"module_lesson:{module_id}:{lesson_id}",
                    game_type="module_lesson",
                    game_title=active_lesson.get("title", ""),
                    increment_game_count=False,
                )
            except Exception as _e:
                logger.debug("per-lesson award_xp suppressed: %s", _e)

        coaching_message = (active_lesson or {}).get("coaching_moment") or ""
        skill_gains = list((active_lesson or {}).get("skill_tags") or [])

        # ── AI feedback for worksheet/reflection submissions ────────────────
        # Generates personalized Mento-voice feedback based on what the
        # student actually wrote. Only runs on first completion to save tokens.
        ai_feedback = None
        if (
            active_lesson
            and active_lesson.get("type") in ("worksheet", "reflection")
            and not was_already_complete
            and isinstance(payload.get("answers"), dict)
            and payload.get("answers")
        ):
            try:
                from llm import evaluate_module_submission  # noqa: WPS433
                content = active_lesson.get("content") or {}
                ai_feedback = evaluate_module_submission(
                    lesson_title=active_lesson.get("title", ""),
                    lesson_type=active_lesson.get("type", "worksheet"),
                    lesson_intro=str(content.get("intro") or active_lesson.get("summary") or ""),
                    lesson_key_takeaway=str(content.get("key_takeaway") or ""),
                    skill_tags=skill_gains,
                    student_answers=payload["answers"],
                    coaching_moment=coaching_message,
                )
            except Exception as _e:
                logger.debug("evaluate_module_submission suppressed: %s", _e)

        # ── Worksheet rubric grading for textarea-heavy schema types ────────
        # Runs on first completion only for worksheet/reflection lessons whose
        # schema.type is one of the textarea-heavy discriminators.  Result is
        # persisted in prog["rubrics"][lesson_id] and returned as "rubric".
        _TEXTAREA_SCHEMA_TYPES = frozenset(
            ("reflection", "pitch_builder", "customer_profile", "idea_scorecard")
        )
        rubric_result = None
        if (
            active_lesson
            and active_lesson.get("type") in ("worksheet", "reflection")
            and not was_already_complete
            and isinstance(payload.get("answers"), dict)
            and payload.get("answers")
        ):
            schema = (active_lesson.get("schema") or {})
            schema_type = schema.get("type") or ""
            if schema_type in _TEXTAREA_SCHEMA_TYPES:
                try:
                    from llm import grade_worksheet_freetext  # noqa: WPS433
                    # Flatten all string answer values into a single text block.
                    text_parts = [
                        str(v) for v in payload["answers"].values()
                        if isinstance(v, str) and v.strip()
                    ]
                    combined_text = "\n\n".join(text_parts)
                    lesson_meta = {
                        "id": lesson_id,
                        "type": schema_type,
                    }
                    rubric_def = schema.get("rubric") or {}
                    rubric_result = grade_worksheet_freetext(
                        combined_text, lesson_meta, rubric_def
                    )
                    # Persist into progress file and update the in-memory dict.
                    if rubric_result:
                        try:
                            _modules_engine.persist_rubric(
                                uid, module_id, lesson_id, rubric_result
                            )
                        except Exception as _pe:
                            logger.debug("persist_rubric suppressed: %s", _pe)
                        # Always update the in-memory progress for the response.
                        progress.setdefault("rubrics", {})[lesson_id] = rubric_result
                except Exception as _e:
                    logger.debug("grade_worksheet_freetext suppressed: %s", _e)

        # ── Module-completion XP + badge (one-shot) ─────────────────────────
        new_badges = []
        if summary.get("completed"):
            try:
                from player_profile import mark_module_completed  # noqa: WPS433
                xp = int((module or {}).get("completion_award", {}).get("xp", 250))
                result = mark_module_completed(uid, module_id, xp_amount=xp)
                new_badges = result.get("new_badges", []) or []
            except Exception as _e:
                logger.debug("mark_module_completed suppressed: %s", _e)

        return jsonify({
            "ok": True,
            "progress": progress,
            "summary": summary,
            "new_badges": new_badges,
            "xp_awarded": xp_awarded,
            "coaching_message": coaching_message,
            "skill_gains": skill_gains,
            "ai_feedback": ai_feedback,
            "rubric": rubric_result,
            "already_completed": was_already_complete,
        })
    except ValueError as e:
        return jsonify({"error": str(e)}), 404
    except Exception as e:
        logger.exception("api_module_lesson_complete failed")
        return jsonify({"error": str(e)}), 500


@app.post("/api/modules/<module_id>/lessons/<lesson_id>/field-mission/entry")
@require_auth
def api_module_field_mission_add_entry(module_id, lesson_id):
    """Append one capture to a field_mission lesson.

    Body: {complaint, person, frequency, capture_type, photo_url|voice_url|note}
    Caps: max 200-char string fields, photo/voice URLs must be data: URIs (≤500KB)
    or HTTPS URLs from our own domain. Captures are stored per-user-per-lesson
    so the Week-4 detective game can pre-load them as case files.
    """
    uid = _module_user_id()
    if not uid:
        return jsonify({"error": "Authentication required"}), 401
    body = request.get_json(silent=True) or {}

    # Sanitize inbound entry to avoid storing arbitrary blobs.
    def _clip(v, n=400):
        if v is None:
            return ""
        s = str(v).strip()
        return s[:n]

    capture_type = _clip(body.get("capture_type") or "text", 16) or "text"
    if capture_type not in ("text", "photo", "voice"):
        capture_type = "text"

    entry = {
        "complaint": _clip(body.get("complaint"), 400),
        "person":    _clip(body.get("person"), 80),
        "frequency": _clip(body.get("frequency"), 64),
        "note":      _clip(body.get("note"), 500),
        "capture_type": capture_type,
    }
    # photo / voice payload — accept data: URIs or https URLs only.
    media = body.get("media_url") or body.get("photo_url") or body.get("voice_url") or ""
    media_str = str(media or "")
    if media_str.startswith("data:") and len(media_str) <= 700_000:
        entry["media_url"] = media_str
    elif media_str.startswith("https://"):
        entry["media_url"] = media_str[:1000]

    if not entry["complaint"] and not entry.get("media_url"):
        return jsonify({"error": "complaint text or media required"}), 400

    # ── Vision feedback for photo captures ────────────────────────────────
    # If a photo was uploaded, run Claude Vision to give the student
    # immediate "what I see" feedback tied to the mission brief.
    photo_feedback = None
    media_url = entry.get("media_url") or ""
    if (
        capture_type == "photo"
        and media_url.startswith("data:image/")
        and len(media_url) <= 700_000
    ):
        try:
            module_obj = _modules_engine.get_module(module_id) or {}
            target_lesson = None
            for w in module_obj.get("weeks", []) or []:
                for l in (w.get("lessons") or []):
                    if l.get("lesson_id") == lesson_id:
                        target_lesson = l
                        break
                if target_lesson:
                    break
            if target_lesson:
                from llm import evaluate_field_mission_photo  # noqa: WPS433
                schema_brief = ((target_lesson.get("schema") or {}).get("brief") or "")
                photo_feedback = evaluate_field_mission_photo(
                    lesson_title=target_lesson.get("title", ""),
                    mission_brief=schema_brief or target_lesson.get("summary", ""),
                    image_data_url=media_url,
                    note=entry.get("complaint") or entry.get("note") or "",
                    skill_tags=target_lesson.get("skill_tags") or [],
                )
        except Exception as _e:
            logger.debug("evaluate_field_mission_photo suppressed: %s", _e)
            photo_feedback = None

    try:
        rec = _modules_engine.add_field_mission_entry(uid, module_id, lesson_id, entry)
        return jsonify({"ok": True, "record": rec, "ai_feedback": photo_feedback})
    except Exception as e:
        logger.exception("api_module_field_mission_add_entry failed")
        return jsonify({"error": str(e)}), 500


