@app.post("/api/modules/<module_id>/lessons/<lesson_id>/voice-submit")
@require_auth
def api_module_voice_submit(module_id, lesson_id):
    """Transcribe + analyze a voice/speech submission for a public-speaking lesson.

    Multipart form: audio (file), duration_seconds (optional), format (optional)
    Returns: {ok, transcript, ai_feedback}
    """
    uid = _module_user_id()
    if not uid:
        return jsonify({"error": "Authentication required"}), 401

    # Accept either multipart (audio file field) OR JSON with a data URL.
    audio_bytes = b""
    audio_format = "webm"
    duration_seconds = 0.0

    if "audio" in (request.files or {}):
        audio_file = request.files["audio"]
        audio_format = request.form.get("format", "webm")
        audio_bytes = audio_file.read() or b""
        try:
            duration_seconds = float(request.form.get("duration_seconds") or 0)
        except (TypeError, ValueError):
            duration_seconds = 0.0
    else:
        body = request.get_json(silent=True) or {}
        data_url = body.get("audio_data_url") or ""
        try:
            duration_seconds = float(body.get("duration_seconds") or 0)
        except (TypeError, ValueError):
            duration_seconds = 0.0
        if not data_url.startswith("data:audio/"):
            return jsonify({"error": "No audio provided"}), 400
        try:
            header, b64 = data_url.split(",", 1)
            # header looks like "data:audio/webm;base64"
            mime = header.split(";")[0].split(":", 1)[1]
            audio_format = (mime.split("/", 1)[1] or "webm").split(";")[0]
            import base64 as _b64
            audio_bytes = _b64.b64decode(b64)
        except Exception:
            return jsonify({"error": "Could not decode audio"}), 400

    if not audio_bytes:
        return jsonify({"error": "Empty audio payload"}), 400

    # Cap to 3 minutes max
    if duration_seconds > 240:
        duration_seconds = 240.0

    # Step 1: Transcribe via Whisper
    api_key = os.environ.get("OPENAI_API_KEY", "")
    transcript = ""
    if api_key:
        try:
            from openai import OpenAI as _OpenAI
            client = _OpenAI(api_key=api_key)
            import io
            audio_buf = io.BytesIO(audio_bytes)
            audio_buf.name = f"recording.{audio_format}"
            result = client.audio.transcriptions.create(
                model="whisper-1",
                file=audio_buf,
                language="en",
            )
            transcript = (result.text or "").strip()
        except Exception as e:
            logger.warning(f"voice-submit transcription failed: {e}")
            transcript = ""

    if not transcript:
        return jsonify({
            "ok": False,
            "error": "Transcription failed or unavailable. Please try again.",
        }), 503

    # Step 2: Look up lesson context for evaluation
    module_obj = _modules_engine.get_module(module_id) or {}
    target_lesson = None
    for w in module_obj.get("weeks", []) or []:
        for l in (w.get("lessons") or []):
            if l.get("lesson_id") == lesson_id:
                target_lesson = l
                break
        if target_lesson:
            break

    speech_brief = ""
    skill_tags = []
    if target_lesson:
        schema = target_lesson.get("schema") or {}
        speech_brief = (
            schema.get("brief")
            or schema.get("prompt")
            or target_lesson.get("summary")
            or (target_lesson.get("content") or {}).get("intro")
            or ""
        )
        skill_tags = target_lesson.get("skill_tags") or []

    # Step 3: Analyze the transcript
    ai_feedback = None
    try:
        from llm import evaluate_voice_speech  # noqa: WPS433
        ai_feedback = evaluate_voice_speech(
            lesson_title=(target_lesson or {}).get("title", ""),
            speech_brief=speech_brief,
            transcript=transcript,
            duration_seconds=duration_seconds,
            skill_tags=skill_tags,
        )
    except Exception as _e:
        logger.debug("evaluate_voice_speech suppressed: %s", _e)

    # Step 4: Save the answer payload (transcript + analysis) so it persists
    try:
        _modules_engine.save_worksheet(uid, module_id, lesson_id, {
            "transcript": transcript,
            "duration_seconds": duration_seconds,
            "ai_feedback": ai_feedback,
        })
    except Exception as _e:
        logger.debug("voice-submit save_worksheet suppressed: %s", _e)

    return jsonify({
        "ok": True,
        "transcript": transcript,
        "duration_seconds": duration_seconds,
        "ai_feedback": ai_feedback,
    })


