@app.post("/api/cohorts/<cohort_id>/modules")
@require_admin_or_school_admin
def api_cohort_assign_module(cohort_id):
    """Assign a module to all students in a cohort (teacher/school_admin only)."""
    body = request.get_json(silent=True) or {}
    module_id = (body.get("module_id") or "").strip()
    if not module_id:
        return jsonify({"error": "module_id required"}), 400
    user = request.current_user
    try:
        record = _modules_engine.assign_module_to_cohort(
            cohort_id=cohort_id,
            module_id=module_id,
            assigned_by=str(user.get("user_id") or user.get("username")),
            start_date=body.get("start_date"),
            due_date=body.get("due_date"),
        )
        return jsonify({"ok": True, "assignment": record})
    except ValueError as e:
        return jsonify({"error": str(e)}), 404
    except Exception as e:
        logger.exception("api_cohort_assign_module failed")
        return jsonify({"error": str(e)}), 500


