@app.get("/api/cohorts/<cohort_id>/modules/<module_id>/progress")
@require_admin_or_school_admin
def api_cohort_module_progress(cohort_id, module_id):
    """Aggregate per-student progress for a teacher dashboard."""
    cohort_data = _load_cohorts()
    cohort = next(
        (c for c in cohort_data.get("cohorts", []) if str(c.get("id")) == str(cohort_id)),
        None,
    )
    if not cohort:
        return jsonify({"error": "Cohort not found"}), 404
    student_ids = [str(s) for s in cohort.get("students", [])]
    try:
        result = _modules_engine.get_cohort_progress(cohort_id, module_id, student_ids)

        # Resolve usernames so the teacher sees real names (best-effort).
        try:
            users_data = _safe_load_json(
                os.path.join(os.path.dirname(__file__), "data", "users.json"),
                {"users": []},
            )
            user_index = {}
            for u in users_data.get("users", []):
                user_index[str(u.get("id"))] = u.get("username") or u.get("name")
                user_index[str(u.get("username"))] = u.get("username")
            for row in result.get("rows", []):
                row["display_name"] = user_index.get(row["user_id"], row["user_id"])
        except Exception as _e:
            logger.debug("user-name resolution suppressed: %s", _e)

        return jsonify(result)
    except ValueError as e:
        return jsonify({"error": str(e)}), 404
    except Exception as e:
        logger.exception("api_cohort_module_progress failed")
        return jsonify({"error": str(e)}), 500


@app.get("/api/cohorts/<cohort_id>/modules/<module_id>/answers")
@require_admin_or_school_admin
def api_cohort_module_answers(cohort_id, module_id):
    """Per-student answer review for a teacher.

    Returns each student's worksheet answers, reflections, quiz scores,
    and field mission entry counts so a teacher can spot-check responses.
    """
    cohort_data = _load_cohorts()
    cohort = next(
        (c for c in cohort_data.get("cohorts", []) if str(c.get("id")) == str(cohort_id)),
        None,
    )
    if not cohort:
        return jsonify({"error": "Cohort not found"}), 404

    module = _modules_engine.get_module(module_id)
    if not module:
        return jsonify({"error": "Module not found"}), 404

    # Build a flat lesson index for the response.
    lessons_index = []
    for w in module.get("weeks", []) or []:
        for l in w.get("lessons", []) or []:
            lessons_index.append({
                "lesson_id": l.get("lesson_id"),
                "title": l.get("title"),
                "type": l.get("type"),
                "week_number": w.get("number"),
                "week_title": w.get("title"),
                "optional": bool(l.get("optional")),
            })

    student_ids = [str(s) for s in cohort.get("students", [])]
    try:
        users_data = _safe_load_json(
            os.path.join(os.path.dirname(__file__), "data", "users.json"),
            {"users": []},
        )
        user_index = {str(u.get("id")): (u.get("username") or u.get("name")) for u in users_data.get("users", [])}
    except Exception:
        user_index = {}

    rows = []
    for sid in student_ids:
        prog = _modules_engine.get_user_progress(sid, module_id) or {}
        worksheets = prog.get("worksheets") or {}
        reflections = prog.get("reflections") or {}
        quizzes = prog.get("quizzes") or {}
        fms = prog.get("field_missions") or {}
        completed = set(prog.get("completed_lesson_ids") or [])

        per_lesson = []
        for li in lessons_index:
            lid = li["lesson_id"]
            ltype = li["type"]
            row = {
                "lesson_id": lid,
                "title": li["title"],
                "type": ltype,
                "week_number": li["week_number"],
                "week_title": li["week_title"],
                "optional": li["optional"],
                "completed": lid in completed,
            }
            if ltype == "worksheet":
                row["answers"] = (worksheets.get(lid) or {}).get("answers") or {}
            elif ltype == "reflection":
                row["answers"] = (reflections.get(lid) or {}).get("answers") or {}
            elif ltype in ("quiz", "assessment"):
                q = quizzes.get(lid) or {}
                row["quiz"] = {
                    "score": q.get("score"),
                    "max_score": q.get("max_score"),
                    "ratio": q.get("ratio"),
                    "passed": q.get("passed"),
                    "attempts": q.get("attempts"),
                }
                row["answers"] = q.get("answers") or {}
            elif ltype == "field_mission":
                row["entries_count"] = len((fms.get(lid) or {}).get("entries") or [])
            per_lesson.append(row)

        summary = _modules_engine.compute_progress_summary(prog, module)
        rows.append({
            "user_id": sid,
            "display_name": user_index.get(sid, sid),
            "percent_complete": summary.get("percent_complete", 0),
            "completed": summary.get("completed", False),
            "lessons": per_lesson,
        })

    return jsonify({
        "cohort_id": cohort_id,
        "cohort_name": cohort.get("name"),
        "module_id": module_id,
        "module_title": module.get("title"),
        "lessons_index": lessons_index,
        "students": rows,
    })


@app.get("/api/modules/cohort-assigned")
@require_auth
def api_my_cohort_modules():
    """Modules assigned to the current student via any of their cohorts."""
    uid = _module_user_id()
    cohort_data = _load_cohorts()
    my_cohorts = [
        c for c in cohort_data.get("cohorts", [])
        if uid in [str(s) for s in c.get("students", [])]
    ]
    rows = _modules_engine.list_user_cohort_modules(uid, my_cohorts)

    # Enrich with module title + caller's progress
    out = []
    for r in rows:
        m = _modules_engine.get_module(r.get("module_id"))
        if not m:
            continue
        prog = _modules_engine.get_user_progress(uid, r.get("module_id"))
        out.append({
            **r,
            "title": m.get("title"),
            "icon": m.get("icon"),
            "cover_color": m.get("cover_color"),
            "summary": _modules_engine.compute_progress_summary(prog, m),
        })
    return jsonify({"modules": out})


# ---------- Helper alias ----------

